#define BUZZER_PIN 27
#define ADC_ADDR 0x48
#define ADC_CHANNEL 0
#define ADC_GAIN 4096
#define ADC_SPS 128
#define ADC_CONV_TIME 8500
#define TEMP_MIN 20
#define TEMP_MAX 80
#define TEMP_TRIGGER 60
#define BUZZER_TIME 2000
#define POLL_TIME 100
#define DEBOUNCE_TIME 50
#define LOG_FILE "fire_log.txt"

int running = 1;
int flame_detected = 0;
int temp_detected = 0;
int buzzer_on = 0;
int flame_debounce_count = 0;

void flame_detected_cb(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        flame_debounce_count++;
        if (flame_debounce_count >= DEBOUNCE_TIME / POLL_TIME) {
            flame_detected = 1;
            flame_debounce_count = 0;
        }
    } else {
        flame_debounce_count = 0;
    }
}

int main(void) {
    int adc_handle, log_fd;
    uint16_t adc_value;
    double temperature;
    char log_message[100];
    time_t current_time;
    struct tm *time_info;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO%d pull-up resistor\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(FLAME_SENSOR_PIN, flame_detected_cb) < 0) {
        fprintf(stderr, "Failed to set GPIO%d alert function\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if ((adc_handle = i2cOpen(1, ADC_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", ADC_ADDR);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteDevice(adc_handle, 0x01) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        i2cClose(adc_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteDevice(adc_handle, 0x80 | (ADC_CHANNEL << 4) | (ADC_GAIN >> 8)) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        i2cClose(adc_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteDevice(adc_handle, ADC_GAIN & 0xFF) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        i2cClose(adc_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteDevice(adc_handle, 0x03) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        i2cClose(adc_handle);
        gpioTerminate();
        return 1;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR)) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(adc_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (i2cReadDevice(adc_handle, (char *) &adc_value, 2) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
        } else {
            temperature = (double) adc_value * (TEMP_MAX - TEMP_MIN) / (65535 - 0) + TEMP_MIN;
            if (temperature > TEMP_TRIGGER) {
                temp_detected = 1;
            }
        }

        if (flame_detected && temp_detected) {
            current_time = time(NULL);
            time_info = localtime(&current_time);
            strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S: Fire detected!\n", time_info);
            write(log_fd, log_message, strlen(log_message));
            if (!buzzer_on) {
                gpioWrite(BUZZER_PIN, 1);
                buzzer_on = 1;
            }
        } else if (flame_detected) {
            current_time = time(NULL);
            time_info = localtime(&current_time);
            strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S: Flame detected!\n", time_info);
            write(log_fd, log_message, strlen(log_message));
        } else if (temp_detected) {
            current_time = time(NULL);
            time_info = localtime(&current_time);
            snprintf(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S: Temperature: %.1f\n", time_info, temperature);
            write(log_fd, log_message, strlen(log_message));
        }

        flame_detected = 0;
        temp_detected = 0;

        usleep(POLL_TIME * 1000);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFunc(FLAME_SENSOR_PIN, NULL);
    i2cClose(adc_handle);
    close(log_fd);
    gpioTerminate();

    return 0;
}

