#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>

#define FLAME_SENSOR_GPIO 4
#define MCP3008_CE0_GPIO 8
#define MCP3008_SCLK_GPIO 11
#define MCP3008_MOSI_GPIO 10
#define MCP3008_MISO_GPIO 9
#define MCP3008_CHANNEL 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_SPI_BITS 8
#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_DELAY 0
#define MCP3008_SPI_READ_CMD 0x01
#define MCP3008_SPI_READ_START_BIT 0x01
#define MCP3008_SPI_READ_SINGLE_BIT 0x80
#define MCP3008_SPI_READ_CHANNEL_BIT 0x40
#define MCP3008_SPI_READ_CHANNEL_MASK 0x04
#define MCP3008_SPI_READ_VALUE_MASK 0x03
#define MCP3008_SPI_READ_VALUE_SHIFT 2
#define MCP3008_SPI_READ_VALUE_MAX 1023
#define MCP3008_SPI_READ_VALUE_MIN 0
#define MCP3008_SPI_READ_VALUE_RANGE (MCP3008_SPI_READ_VALUE_MAX - MCP3008_SPI_READ_VALUE_MIN)
#define MCP3008_SPI_READ_TEMP_MAX 40.0
#define MCP3008_SPI_READ_TEMP_MIN 10.0
#define MCP3008_SPI_READ_TEMP_RANGE (MCP3008_SPI_READ_TEMP_MAX - MCP3008_SPI_READ_TEMP_MIN)
#define MCP3008_SPI_READ_TEMP_SCALE (MCP3008_SPI_READ_TEMP_RANGE / MCP3008_SPI_READ_VALUE_RANGE)

#define FLAME_DATA_FILE "flame_data.csv"

int main(void)
{
    int rc;
    int spi_handle;
    int flame_sensor_value;
    int mcp3008_value;
    double mcp3008_temp;
    FILE *flame_data_file;
    time_t timestamp;
    struct tm *timestamp_tm;
    char timestamp_str[256];

    // Initialize pigpio
    if ((rc = gpioInitialise()) < 0)
    {
        fprintf(stderr, "pigpio initialization failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    // Set up the flame sensor GPIO as an input
    if ((rc = gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT)) < 0)
    {
        fprintf(stderr, "failed to set flame sensor GPIO mode: %d\n", rc);
        goto cleanup;
    }

    // Set up the MCP3008 CE0 GPIO as an output
    if ((rc = gpioSetMode(MCP3008_CE0_GPIO, PI_OUTPUT)) < 0)
    {
        fprintf(stderr, "failed to set MCP3008 CE0 GPIO mode: %d\n", rc);
        goto cleanup;
    }

    // Set up the MCP3008 SCLK GPIO as an output
    if ((rc = gpioSetMode(MCP3008_SCLK_GPIO, PI_OUTPUT)) < 0)
    {
        fprintf(stderr, "failed to set MCP3008 SCLK GPIO mode: %d\n", rc);
        goto cleanup;
    }

    // Set up the MCP3008 MOSI GPIO as an output
    if ((rc = gpioSetMode(MCP3008_MOSI_GPIO, PI_OUTPUT)) < 0)
    {
        fprintf(stderr, "failed to set MCP3008 MOSI GPIO mode: %d\n", rc);
        goto cleanup;
    }

    // Set up the MCP3008 MISO GPIO as an input
    if ((rc = gpioSetMode(MCP3008_MISO_GPIO, PI_INPUT)) < 0)
    {
        fprintf(stderr, "failed to set MCP3008 MISO GPIO mode: %d\n", rc);
        goto cleanup;
    }

    // Open the MCP3008 SPI bus
    if ((spi_handle = spiOpen(MCP3008_CE0_GPIO, MCP3008_SPI_SPEED, MCP3008_SPI_MODE)) < 0)
    {
        fprintf(stderr, "failed to open MCP3008 SPI bus: %d\n", spi_handle);
        goto cleanup;
    }

    // Open the flame data file
    if ((flame_data_file = fopen(FLAME_DATA_FILE, "w")) == NULL)
    {
        fprintf(stderr, "failed to open flame data file: %s\n", FLAME_DATA_FILE);
        goto cleanup;
    }

    // Write the flame data file header
    fprintf(flame_data_file, "timestamp,flame_sensor,mcp3008_value,mcp3008_temp\n");

    // Loop forever, logging flame sensor and MCP3008 data every second
    while (1)
    {
        // Read the flame sensor GPIO
        if ((rc = gpioRead(FLAME_SENSOR_GPIO, &flame_sensor_value)) < 0)
        {
            fprintf(stderr, "failed to read flame sensor GPIO: %d\n", rc);
            goto cleanup;
        }

        // Read the MCP3008 value
        if ((rc = spiRead(spi_handle, MCP3008_SPI_READ_CMD, MCP3008_SPI_READ_START_BIT | MCP3008_SPI_READ_SINGLE_BIT | MCP3008_SPI_READ_CHANNEL_BIT | MCP3008_SPI_READ_CHANNEL_MASK, MCP3008_SPI_BITS, MCP3008_SPI_DELAY, &mcp3008_value, MCP3008_SPI_READ_VALUE_MASK)) < 0)
        {
            fprintf(stderr, "failed to read MCP3008 value: %d\n", rc);
            goto cleanup;
        }

        // Scale the MCP3008 value to a temperature
        mcp3008_temp = MCP3008_SPI_READ_TEMP_MIN + (mcp3008_value * MCP3008_SPI_READ_TEMP_SCALE);

        // Get the current timestamp
        timestamp = time(NULL);
        timestamp_tm = localtime(&timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timestamp_tm);

        // Write the flame data to the file
        fprintf(flame_data_file, "%s,%d,%d,%.1f\n", timestamp_str, flame_sensor_value, mcp3008_value, mcp3008_temp);

        // Sleep for one second
        sleep(1);
    }

cleanup:
    // Close the MCP3008 SPI bus
    if (spi_handle >= 0)
    {
        spiClose(spi_handle);
    }

    // Close the flame data file
    if (flame_data_file != NULL)
    {
        fclose(flame_data_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return EXIT_SUCCESS;
}

