#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define MIC_REG 0x00
#define MIC_SENS -38.0
#define MIC_REF 20e-6

#define LOG_FILE "audio_log.txt"

int mic1_handle, mic2_handle;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signo);
        gpioI2CClose(mic1_handle);
        gpioI2CClose(mic2_handle);
        gpioTerminate();
        exit(0);
    }
}

double read_mic(int handle, int addr) {
    uint8_t buf[2];
    if (gpioI2CReadDevice(handle, buf, 2) < 0) {
        return -999.0;
    }
    int16_t raw_data = (buf[0] << 8) | buf[1];
    double pressure = (double)raw_data / 32768.0 * 2.048;
    return MIC_SENS + 20.0 * log10(pressure / MIC_REF);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    mic1_handle = gpioI2COpen(1, MIC1_ADDR);
    if (mic1_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X\n", MIC1_ADDR);
        return 1;
    }
    mic2_handle = gpioI2COpen(1, MIC2_ADDR);
    if (mic2_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X\n", MIC2_ADDR);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return 1;
    }

    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (1) {
        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;
        double mic1_db = read_mic(mic1_handle, MIC1_ADDR);
        double mic2_db = read_mic(mic2_handle, MIC2_ADDR);
        double avg_db = (mic1_db + mic2_db) / 2.0;
        fprintf(log_file, "%.3f, %.1f, %.1f, %.1f\n", elapsed_time, mic1_db, mic2_db, avg_db);
        fflush(log_file);
        gpioDelay(100000);
    }

    fclose(log_file);
    gpioI2CClose(mic1_handle);
    gpioI2CClose(mic2_handle);
    gpioTerminate();
    return 0;
}

