	if (transfer(tx, rx, ARRAY_SIZE(tx)) < 0) {
		perror("SPI transfer failed");
		return -1;
	}

	return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_moisture(int channel)
{
	int adc = read_adc(channel);
	if (adc < 0)
		return -1;

	return (adc * 100) / 1023;
}

static int log_moisture(int moisture1, int moisture2)
{
	FILE *fp = fopen("moisture_log.csv", "a");
	if (!fp) {
		perror("Failed to open moisture_log.csv");
		return -1;
	}

	time_t t = time(NULL);
	struct tm *tm = localtime(&t);
	char timestamp[64];
	strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

	fprintf(fp, "%s,%d,%d\n", timestamp, moisture1, moisture2);
	fclose(fp);

	return 0;
}

static void signal_handler(int signum)
{
	printf("Caught signal %d\n", signum);
	close(fd);
	exit(0);
}

int main(int argc, char *argv[])
{
	struct gpiod_chip *chip;
	struct gpiod_line *cs;

	if (argc > 1)
		device = argv[1];

	fd = open(device, O_RDWR);
	if (fd < 0) {
		perror("Failed to open device");
		return 1;
	}

	if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
		perror("Failed to set SPI mode");
		return 1;
	}

	if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
		perror("Failed to set SPI bits per word");
		return 1;
	}

	if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
		perror("Failed to set SPI speed");
		return 1;
	}

	chip = gpiod_chip_open_by_name("gpiochip0");
	if (!chip) {
		perror("Failed to open gpiochip0");
		return 1;
	}

	cs = gpiod_chip_get_line(chip, 8);
	if (!cs) {
		perror("Failed to get gpio8");
		return 1;
	}

	if (gpiod_line_request_output(cs, "cs", 0) < 0) {
		perror("Failed to request gpio8");
		return 1;
	}

	if (gpiod_line_set_value(cs, 1) < 0) {
		perror("Failed to set gpio8");
		return 1;
	}

	signal(SIGINT, signal_handler);
	signal(SIGTERM, signal_handler);

	while (1) {
		int moisture1 = read_moisture(0);
		if (moisture1 < 0)
			return 1;

		int moisture2 = read_moisture(1);
		if (moisture2 < 0)
			return 1;

		if (log_moisture(moisture1, moisture2) < 0)
			return 1;

		sleep(5);
	}

	return 0;
}
