#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ALARM_PIN 4
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define ADC_MAX_VOLTAGE 3.3
#define ALARM_THRESHOLD 2.5

int main(int argc, char *argv[])
{
    FILE *logFile;
    int spiHandle;
    int adcValue;
    double adcVoltage;
    int alarmState;
    time_t currentTime;
    struct tm *localTime;
    char timeString[20];
    char voltageString[10];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spiHandle < 0)
    {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, PI_LOW);

    logFile = fopen("co_log.txt", "a");
    if (logFile == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
