        adcValue = spiRead(spiHandle, ADC_CHANNEL);
        if (adcValue < 0)
        {
            fprintf(stderr, "Failed to read ADC value\n");
            gpioWrite(ALARM_PIN, PI_LOW);
            sleep(1);
            continue;
        }

        adcVoltage = (double)adcValue * ADC_MAX_VOLTAGE / ADC_MAX_VALUE;

        currentTime = time(NULL);
        localTime = localtime(&currentTime);
        strftime(timeString, sizeof(timeString), "%F %T", localTime);
        snprintf(voltageString, sizeof(voltageString), "%.2f", adcVoltage);

        fprintf(logFile, "%s,Voltage: %s V\n", timeString, voltageString);
        fflush(logFile);

        alarmState = (adcVoltage > ALARM_THRESHOLD) ? PI_HIGH : PI_LOW;
        gpioWrite(ALARM_PIN, alarmState);

        sleep(1);
    }

    fclose(logFile);
    spiClose(spiHandle);
    gpioTerminate();

    return 0;
}
