#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHAN 0
#define SPI_FREQ 1000000
#define SPI_MODE 0
#define SPI_CMD_LEN 3
#define SPI_RX_LEN 3
#define SPI_CMD_START 0x01
#define SPI_CMD_CONFIG 0x80
#define SPI_CMD_DUMMY 0x00
#define SPI_ADC_MAX 1023
#define SPI_ADC_MIN 0
#define SPI_ADC_PPM_MAX 5000
#define SPI_ADC_PPM_MIN 0
#define SPI_ADC_PPM_LEAK 1000

int main(int argc, char *argv[])
{
    FILE *fp;
    int spi_handle;
    int spi_rx_len;
    uint8_t spi_cmd[SPI_CMD_LEN];
    uint8_t spi_rx[SPI_RX_LEN];
    uint16_t spi_adc;
    uint16_t spi_adc_ppm;
    time_t t;
    struct tm *tm;
    char time_str[64];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(EXIT_FAILURE);
    }

    spi_handle = spiOpen(SPI_BUS, SPI_CHAN, SPI_FREQ, SPI_MODE);
    if (spi_handle < 0)
    {
        fprintf(stderr, "spiOpen failed\n");
        exit(EXIT_FAILURE);
    }

    fp = fopen("methane_log.txt", "a");
    if (fp == NULL)
    {
        fprintf(stderr, "fopen failed\n");
        exit(EXIT_FAILURE);
    }

    while (1)
    {
        spi_cmd[0] = SPI_CMD_START;
        spi_cmd[1] = SPI_CMD_CONFIG;
        spi_cmd[2] = SPI_CMD_DUMMY;

        spi_rx_len = spiXfer(spi_handle, spi_cmd, spi_rx, SPI_CMD_LEN);
        if (spi_rx_len < 0)
        {
            fprintf(stderr, "spiXfer failed\n");
            continue;
        }

        spi_adc = ((spi_rx[1] & 0x03) << 8) | spi_rx[2];
        spi_adc_ppm = (spi_adc - SPI_ADC_MIN) * (SPI_ADC_PPM_MAX - SPI_ADC_PPM_MIN) / (SPI_ADC_MAX - SPI_ADC_MIN) + SPI_ADC_PPM_MIN;

        t = time(NULL);
        tm = localtime_r(&t, tm);
        strftime(time_str, sizeof(time_str), "%FT%TZ", tm);

        fprintf(fp, "%s %u\n", time_str, spi_adc_ppm);
        fflush(fp);

        if (spi_adc_ppm > SPI_ADC_PPM_LEAK)
        {
            fprintf(stderr, "LEAK ALARM\n");
        }

        sleep(1);
    }

    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

