#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define SAMPLING_INTERVAL 60

int main(void)
{
    FILE *fp;
    int adcValue;
    time_t timestamp;
    struct tm *timeInfo;
    char timeString[25];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if ((fp = fopen("moisture_log.txt", "a")) == NULL)
    {
        fprintf(stderr, "Failed to open moisture_log.txt\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1)
    {
        adcValue = gpioRead_Bits_0_31(SPI_CHANNEL, ADC_CHANNEL);

        if (adcValue < 0 || adcValue > ADC_MAX_VALUE)
        {
            fprintf(stderr, "Invalid ADC value: %d\n", adcValue);
            break;
        }

        timestamp = time(NULL);
        timeInfo = gmtime(&timestamp);
        strftime(timeString, sizeof(timeString), "%FT%TZ", timeInfo);

        fprintf(fp, "%s,%d\n", timeString, adcValue);
        fflush(fp);

        sleep(SAMPLING_INTERVAL);
    }

    fclose(fp);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOG_FREQUENCY 60
#define DEFAULT_RECIPIENT ""
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"

#define MAX_LINE_LENGTH 1024

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_raw = DEFAULT_MIN_RAW;
    int max_raw = DEFAULT_MAX_RAW;
    int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int log_frequency = DEFAULT_LOG_FREQUENCY;
    char *recipient = DEFAULT_RECIPIENT;
    char *msmtp_config = DEFAULT_MSMTP_CONFIG;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            spi_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            adc_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-m") == 0 && i + 1 < argc) {
            min_raw = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-M") == 0 && i + 1 < argc) {
            max_raw = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            moisture_threshold = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            log_frequency = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-r") == 0 && i + 1 < argc) {
            recipient = argv[++i];
        } else if (strcmp(argv[i], "-C") == 0 && i + 1 < argc) {
            msmtp_config = argv[++i];
        } else {
            fprintf(stderr, "Invalid argument: %s\n", argv[i]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI connection
    int spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI connection\n");
        gpioTerminate();
        return 1;
    }

    // Open plant_data.txt for appending
    FILE *data_file = fopen("plant_data.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open plant_data.txt\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open msmtp for piping
    FILE *msmtp_pipe = popen("msmtp -C /etc/msmtprc ", "w");
    if (msmtp_pipe == NULL) {
        fprintf(stderr, "Failed to open msmtp pipe\n");
        fclose(data_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        uint8_t tx_buf[3] = {0x01, (uint8_t)((adc_channel << 4) | 0x08), 0x00};
        uint8_t rx_buf[3] = {0};
        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "Failed to transfer SPI data\n");
            break;
        }
        int raw_adc = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Calculate moisture percentage
        int moisture_percent = (raw_adc - min_raw) * 100 / (max_raw - min_raw);

        // Log data to plant_data.txt
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        char time_string[MAX_LINE_LENGTH];
        strftime(time_string, MAX_LINE_LENGTH, "%F %T", time_info);
        fprintf(data_file, "%s, %d\n", time_string, moisture_percent);
        fflush(data_file);

        // Check moisture threshold and send email alert
        if (moisture_percent < moisture_threshold) {
            fprintf(msmtp_pipe, "Subject: Plant moisture alert\n\n");
            fprintf(msmtp_pipe, "The plant's moisture is below %d%%.\n", moisture_threshold);
            fflush(msmtp_pipe);
            int msmtp_status = pclose(msmtp_pipe);
            if (msmtp_status != 0) {
                fprintf(stderr, "msmtp exited with status %d\n", msmtp_status);
                break;
            }
        }

        // Sleep for log_frequency seconds
        sleep(log_frequency);
    }

    // Close SPI connection, terminate pigpio, and free memory
    spiClose(spi_handle);
    gpioTerminate();
    fclose(data_file);
    pclose(msmtp_pipe);

    return 0;
}

