#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_SPI_SPEED 1000000
#define ADC_SPI_MODE 0
#define ADC_SPI_BITS 8
#define ADC_SPI_BYTES 3
#define ADC_SPI_CE 0
#define ADC_SPI_CE_PIN 8
#define ADC_SPI_MAX_VALUE 1023
#define ADC_SPI_MAX_BITS 10
#define ADC_SPI_MAX_BYTES 2
#define ADC_SPI_MAX_READINGS 1000

#define LOG_FILE "soil_moisture.log"

#define ERROR_EXIT(msg) { fprintf(stderr, "%s\n", msg); exit(EXIT_FAILURE); }

int main(int argc, char *argv[]) {
    int sample_interval = 1;
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            ERROR_EXIT("Invalid sample interval");
        }
    }

    if (gpioInitialise() < 0) {
        ERROR_EXIT("Failed to initialize pigpio");
    }

    int spi_handle = spiOpen(ADC_SPI_CE, ADC_SPI_SPEED, ADC_SPI_MODE);
    if (spi_handle < 0) {
        ERROR_EXIT("Failed to open SPI");
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        ERROR_EXIT("Failed to open log file");
    }

    int adc_value;
    int adc_readings = 0;
    int adc_sum = 0;
    int adc_average;
    int adc_percentage;
    char timestamp[25];
    time_t now;
    struct tm *time_info;

    while (1) {
        adc_value = spiRead(spi_handle, ADC_SPI_BITS);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read SPI\n");
            continue;
        }

        adc_sum += adc_value;
        adc_readings++;

        if (adc_readings == ADC_SPI_MAX_READINGS) {
            adc_average = adc_sum / adc_readings;
            adc_percentage = (adc_average * 100) / ADC_SPI_MAX_VALUE;

            now = time(NULL);
            time_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%FT%T%z", time_info);

            fprintf(log_file, "%s,%d,%d\n", timestamp, adc_average, adc_percentage);
            fflush(log_file);

            adc_readings = 0;
            adc_sum = 0;
        }

        sleep(sample_interval);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}
