#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_DELAY 0
#define SPI_CHANNEL 0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define ADC_RANGE (MAX_ADC_VALUE - MIN_ADC_VALUE)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum)
{
    running = 0;
}

int main(void)
{
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config line_config;
    struct gpiod_line_bulk_config bulk_config;
    struct gpiod_line_bulk *bulk;
    struct gpiod_line_event event;
    struct gpiod_line_event_poll poll;
    struct timespec ts;
    int fd;
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int adc_value;
    float moisture;

    /* Set up signal handler */
    signal(SIGINT, sigint_handler);

    /* Open SPI device */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set SPI mode */
    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set SPI bits per word */
    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set SPI speed */
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set SPI delay */
    ret = ioctl(fd, SPI_IOC_WR_DELAY_USEC, &SPI_DELAY);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI delay: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set up GPIO line request config */
    gpiod_line_request_config_init(&line_config, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    gpiod_line_request_config_set_consumer(&line_config, "spi_cs");

    /* Request GPIO line */
    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Request GPIO line */
    ret = gpiod_line_request(line, &line_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set up GPIO bulk request config */
    gpiod_line_bulk_config_init(&bulk_config, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    gpiod_line_bulk_config_set_consumer(&bulk_config, "spi_cs");

    /* Request GPIO lines */
    bulk = gpiod_chip_get_lines(chip, (const unsigned[]){8, 11, 10, 9}, 4);
    if (!bulk) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Request GPIO lines */
    ret = gpiod_line_bulk_request(bulk, &bulk_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        gpiod_line_bulk_release(bulk);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set up GPIO line event poll */
    gpiod_line_event_poll_init(&poll);

    /* Set up GPIO line event */
    gpiod_line_event_init(&event, line);

    /* Set up GPIO line event poll */
    gpiod_line_event_poll_add_line(&poll, &event);

    /* Set up GPIO line event poll timeout */
    ts.tv_sec = 5;
    ts.tv_nsec = 0;

    /* Read sensor every 5 seconds */
    while (running) {
        /* Set CS low */
        gpiod_line_set_value(line, 0);

        /* Transfer SPI data */
        ret = read(fd, rx, sizeof(rx));
        if (ret < 0) {
            fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
            gpiod_line_bulk_release(bulk);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(fd);
            return EXIT_FAILURE;
        }

        /* Set CS high */
        gpiod_line_set_value(line, 1);

        /* Check for sensor-absent or bus-error paths */
        if (rx[1] == 0 || rx[1] == 0xff) {
