#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define SPI_DELAY 0
#define SPI_CHANNEL 0
#define SPI_CONFIG_BYTE 0x06
#define SPI_DUMMY_BYTE 0x00
#define SPI_READ_CMD_SIZE 3
#define SPI_READ_RESULT_SIZE 2
#define SPI_READ_RESULT_MASK 0x03FF
#define SPI_READ_RESULT_SHIFT 0
#define SPI_READ_RESULT_MAX 1023
#define SPI_READ_RESULT_MIN 0
#define SPI_READ_RESULT_RANGE 100

static volatile int keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    int fd;
    int ret;
    uint8_t tx[SPI_READ_CMD_SIZE];
    uint8_t rx[SPI_READ_RESULT_SIZE];
    uint16_t result;
    uint8_t moisture;
    struct timespec ts;
    struct timespec ts_sleep;
    struct spi_ioc_transfer tr;

    signal(SIGINT, int_handler);
    signal(SIGTERM, int_handler);

    fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("can't open device");
        exit(1);
    }

    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("can't set spi mode");
        close(fd);
        exit(1);
    }

    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret == -1) {
        perror("can't set bits per word");
        close(fd);
        exit(1);
    }

    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("can't set max speed hz");
        close(fd);
        exit(1);
    }

    ret = ioctl(fd, SPI_IOC_WR_LSB_FIRST, 0);
    if (ret == -1) {
        perror("can't set lsb first");
        close(fd);
        exit(1);
    }

    ret = ioctl(fd, SPI_IOC_WR_DELAY_USEC, &SPI_DELAY);
    if (ret == -1) {
        perror("can't set delay usec");
        close(fd);
        exit(1);
    }

    ts_sleep.tv_sec = 5;
    ts_sleep.tv_nsec = 0;

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: ", ts.tv_sec, ts.tv_nsec);

        tx[0] = 0x01;
        tx[1] = SPI_CONFIG_BYTE | (SPI_CHANNEL << 4);
        tx[2] = SPI_DUMMY_BYTE;

        tr.tx_buf = (unsigned long)tx;
        tr.rx_buf = (unsigned long)rx;
        tr.len = SPI_READ_CMD_SIZE;
        tr.delay_usecs = SPI_DELAY;
        tr.speed_hz = SPI_SPEED;
        tr.bits_per_word = SPI_BITS;

        ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 1) {
            perror("can't send spi message");
            close(fd);
            exit(1);
        }

        result = (rx[0] << 8) | rx[1];
        result = (result & SPI_READ_RESULT_MASK) >> SPI_READ_RESULT_SHIFT;
        moisture = (result * SPI_READ_RESULT_RANGE) / SPI_READ_RESULT_MAX;
        printf("moisture: %d%%\n", moisture);

        nanosleep(&ts_sleep, NULL);
    }

    close(fd);
    return 0;
}

