#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

#define SPI_PATH "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define LOG_PATH "soil_moisture_log.csv"

#define CS0_LINE 8
#define CS1_LINE 7
#define CS2_LINE 25

#define CS0_CHIP 0
#define CS1_CHIP 1
#define CS2_CHIP 2

#define CHANNEL 0

#define SLEEP_TIME 5

static int spi_fd = -1;
static struct gpiod_chip *cs_chip[3] = {NULL, NULL, NULL};
static struct gpiod_line *cs_line[3] = {NULL, NULL, NULL};

static void cleanup(void)
{
    int i;

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    for (i = 0; i < ARRAY_SIZE(cs_chip); i++) {
        if (cs_chip[i]) {
            gpiod_chip_close(cs_chip[i]);
            cs_chip[i] = NULL;
        }
    }

    for (i = 0; i < ARRAY_SIZE(cs_line); i++) {
        if (cs_line[i]) {
            gpiod_line_release(cs_line[i]);
            cs_line[i] = NULL;
        }
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_spi(void)
{
    int ret;

    spi_fd = open(SPI_PATH, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int init_cs(void)
{
    int i, ret;

    for (i = 0; i < ARRAY_SIZE(cs_chip); i++) {
        cs_chip[i] = gpiod_chip_open_by_number(i);
        if (!cs_chip[i]) {
            fprintf(stderr, "Failed to open GPIO chip %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    for (i = 0; i < ARRAY_SIZE(cs_line); i++) {
        cs_line[i] = gpiod_chip_get_line(cs_chip[i], i);
        if (!cs_line[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", i, strerror(errno));
            return -1;
        }

        ret = gpiod_line_request_output(cs_line[i], "soil_moisture", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    return 0;
}

static int read_sensor(int cs)
{
    int ret;
    uint8_t tx[3] = {0x01, (0x08 | CHANNEL) << 4, 0x00};
    uint8_t rx[3] = {0};

    ret = gpiod_line_set_value(cs_line[cs], 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line %d: %s\n", cs, strerror(errno));
        return -1;
    }

    ret = write(spi_fd, tx, sizeof(tx));
    if (ret < 0) {
        fprintf(stderr, "Failed to write to SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = read(spi_fd, rx, sizeof(rx));
    if (ret < 0) {
        fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = gpiod_line_set_value(cs_line[cs], 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line %d: %s\n", cs, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(void)
{
    int ret;
    FILE *log_file;
    struct stat st;
    bool log_header = false;

    ret = init_spi();
    if (ret < 0)
        goto error;

    ret = init_cs();
    if (ret < 0)
        goto error;

    ret = stat(LOG_PATH, &st);
    if (ret < 0) {
        fprintf(stderr, "Failed to stat log file: %s\n", strerror(errno));
        goto error;
    }

    log_file = fopen(LOG_PATH, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto error;
    }

    if (st.st_size == 0)
        log_header = true;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        int sensor1, sensor2, sensor3;

        sensor1 = read_sensor(CS0_CHIP);
        sensor2 = read_sensor(CS1_CHIP);
        sensor3 = read_sensor(CS2_CHIP);

        if (log_header) {
            fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
            log_header = false;
        }

        fprintf(log_file, "%ld,%d,%d,%d\n", time(NULL), sensor1, sensor2, sensor3);
        fflush(log_file);

        sleep(SLEEP_TIME);
    }

    fclose(log_file);
    cleanup();
    return EXIT_SUCCESS;

error:
    cleanup();
    return EXIT_FAILURE;
}

