#include <gpiod.h>

#define I2C_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"
#define I2C_CTRL_BYTE 0x40

int main(int argc, char *argv[])
{
    int i2c_fd;
    int i2c_ret;
    char i2c_buf[2];
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    i2c_ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (i2c_ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    i2c_buf[0] = I2C_CTRL_BYTE;
    i2c_ret = write(i2c_fd, i2c_buf, 1);
    if (i2c_ret != 1) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    i2c_ret = read(i2c_fd, i2c_buf, 1);
    if (i2c_ret != 1) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 25);
    if (!line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(line, "led", 0);

    while (1) {
        i2c_ret = read(i2c_fd, i2c_buf, 1);
        if (i2c_ret != 1) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        printf("%d\n", i2c_buf[0]);

        gpiod_line_set_value(line, i2c_buf[0] > 127);

        usleep(100000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

