#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_DEVICE 0
#define VREF 3.3
#define NUM_CHANNELS 3
#define NUM_SAMPLES 1024
#define SAMPLE_PERIOD 5000000

FILE *fp;
int spiHandle;

void sigHandler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        // Close the SPI handle and terminate pigpio
        gpioTerminate();
        fclose(fp);
        exit(EXIT_SUCCESS);
    }
}

int main(void) {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigHandler);
    signal(SIGTERM, sigHandler);

    // Initialize pigpio and check the return status
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open the SPI handle and check the return status
    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open the file for writing and check the return status
    fp = fopen("sensor_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        spiClose(spiHandle);
        return EXIT_FAILURE;
    }

    // Write the header line to the file
    fprintf(fp, "Timestamp,Channel 0,Channel 1,Channel 2\n");

    // Main loop to sample and log data
    while (1) {
        // Sample each channel
        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            // Construct the SPI command byte
            uint8_t cmd = 0x01;
            cmd |= (channel << 4);

            // Send the command byte and check the return status
            uint8_t txBuf[3] = {cmd, 0x00, 0x00};
            uint8_t rxBuf[3];
            if (spiXfer(spiHandle, txBuf, rxBuf, 3) != 3) {
                fprintf(stderr, "Failed to transfer SPI data\n");
                gpioTerminate();
                spiClose(spiHandle);
                fclose(fp);
                return EXIT_FAILURE;
            }

            // Extract the ADC value from the received data
            uint16_t adcValue = ((rxBuf[1] & 0x03) << 8) | rxBuf[2];

            // Calculate the voltage and log it to the file
            double voltage = (double)adcValue * VREF / NUM_SAMPLES;
            fprintf(fp, "%lf,%lf\n", gpioTime(), voltage);
        }

        // Wait for the next sample period
        gpioDelay(SAMPLE_PERIOD);
    }

    // Close the SPI handle and terminate pigpio
    gpioTerminate();
    spiClose(spiHandle);

    // Close the file
    fclose(fp);

    return EXIT_SUCCESS;
}

