#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define SPI_DELAY 0
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define ADC_THRESHOLD 500
#define PWM_FREQ 100
#define PWM_RANGE 1023
#define PWM_PIN1 17
#define PWM_PIN2 27
#define LOG_FILE "vibration_log.txt"

int main(void)
{
    int spi_fd, pwm_handle1, pwm_handle2;
    uint8_t tx_buf[3], rx_buf[3];
    uint16_t adc_value;
    time_t timestamp;
    struct tm *time_info;
    char time_str[20];
    FILE *log_file;

    // Initialize SPI
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    // Initialize PWM
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }
    pwm_handle1 = gpioHardwarePWM(PWM_PIN1, PWM_FREQ, 0);
    if (pwm_handle1 < 0) {
        perror("Failed to initialize PWM on pin 17");
        return -1;
    }
    pwm_handle2 = gpioHardwarePWM(PWM_PIN2, PWM_FREQ, 0);
    if (pwm_handle2 < 0) {
        perror("Failed to initialize PWM on pin 27");
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        tx_buf[0] = 0x01;
        tx_buf[1] = (0x80 | (ADC_CHANNEL << 4));
        tx_buf[2] = 0x00;
        if (write(spi_fd, tx_buf, 3) != 3) {
            perror("Failed to write to SPI device");
            continue;
        }
        if (read(spi_fd, rx_buf, 3) != 3) {
            perror("Failed to read from SPI device");
            continue;
        }
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Process ADC value
        if (adc_value > ADC_THRESHOLD) {
            // Modulate motors
            gpioHardwarePWM(PWM_PIN1, PWM_FREQ, adc_value * PWM_RANGE / 100);
            gpioHardwarePWM(PWM_PIN2, PWM_FREQ, adc_value * PWM_RANGE / 100);

            // Log event
            timestamp = time(NULL);
            time_info = localtime(&timestamp);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(log_file, "%s: ADC value: %d\n", time_str, adc_value);
            fflush(log_file);
        } else {
            // Turn off motors
            gpioHardwarePWM(PWM_PIN1, PWM_FREQ, 0);
            gpioHardwarePWM(PWM_PIN2, PWM_FREQ, 0);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();
    close(spi_fd);

    return 0;
}

