    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }
    pwm_handle1 = gpioHardwarePWM(PWM_PIN1, PWM_FREQ, 0);
    if (pwm_handle1 < 0) {
        perror("Failed to initialize PWM on pin 17");
        return -1;
    }
    pwm_handle2 = gpioHardwarePWM(PWM_PIN2, PWM_FREQ, 0);
    if (pwm_handle2 < 0) {
        perror("Failed to initialize PWM on pin 27");
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        tx_buf[0] = 0x01;
        tx_buf[1] = (0x80 | (ADC_CHANNEL << 4));
        tx_buf[2] = 0x00;
        if (write(spi_fd, tx_buf, 3) != 3) {
            perror("Failed to write to SPI device");
            continue;
        }
        if (read(spi_fd, rx_buf, 3) != 3) {
            perror("Failed to read from SPI device");
            continue;
        }
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Process ADC value
        if (adc_value > ADC_THRESHOLD) {
            // Modulate motors
            gpioHardwarePWM(PWM_PIN1, PWM_FREQ, adc_value * PWM_RANGE / 100);
            gpioHardwarePWM(PWM_PIN2, PWM_FREQ, adc_value * PWM_RANGE / 100);

            // Log event
            timestamp = time(NULL);
            time_info = localtime(&timestamp);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(log_file, "%s: ADC value: %d\n", time_str, adc_value);
            fflush(log_file);
        } else {
            // Turn off motors
            gpioHardwarePWM(PWM_PIN1, PWM_FREQ, 0);
            gpioHardwarePWM(PWM_PIN2, PWM_FREQ, 0);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();
    close(spi_fd);

    return 0;
}
