#include <signal.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_DEVICE 0
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define ADC_MAX_BITS 10
#define ADC_MAX_READING 1023
#define ADC_MIN_READING 0
#define ADC_MAX_VOLTAGE 3.3
#define ADC_MIN_VOLTAGE 0
#define ADC_MAX_CO2 1000
#define ADC_MIN_CO2 400
#define ADC_CO2_SLOPE 0.5
#define ADC_CO2_INTERCEPT -50
#define FAN_GPIO 18
#define FAN_ON 1
#define FAN_OFF 0
#define FAN_THRESHOLD 700
#define LOG_FILE "air_quality.log"
#define LOG_INTERVAL 5

static int spi_handle = -1;
static int fan_state = FAN_OFF;

static void cleanup(void)
{
    if (spi_handle >= 0) {
        gpioSetMode(FAN_GPIO, PI_INPUT);
        gpioWrite(FAN_GPIO, FAN_OFF);
        gpioTerminate();
        spiClose(spi_handle);
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_spi(void)
{
    int handle;

    if ((handle = spiOpen(SPI_DEVICE, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    return handle;
}

static int init_fan(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, FAN_OFF);

    return 0;
}

static int read_adc(int handle, int channel)
{
    uint8_t tx_buf[3] = {0x01, 0x80 | ((channel & 0x07) << 4), 0x00};
    uint8_t rx_buf[3] = {0};
    int reading;

    if (spiXfer(handle, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Failed to read ADC\n");
        return -1;
    }

    reading = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return reading;
}

static int convert_adc_reading(int reading)
{
    double voltage;
    double co2;

    if (reading < ADC_MIN_READING || reading > ADC_MAX_READING) {
        fprintf(stderr, "Invalid ADC reading: %d\n", reading);
        return -1;
    }

    voltage = (double)reading * (ADC_MAX_VOLTAGE - ADC_MIN_VOLTAGE) / ADC_MAX_READING + ADC_MIN_VOLTAGE;
    co2 = ADC_CO2_SLOPE * voltage + ADC_CO2_INTERCEPT;

    return (int)co2;
}

static int log_reading(int co2)
{
    FILE *fp;
    time_t now;
    struct tm *tm;
    char timestamp[32];

    if ((fp = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    now = time(NULL);
    tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, co2, fan_state);
    fclose(fp);

    return 0;
}

static int control_fan(int co2)
{
    if (co2 > FAN_THRESHOLD) {
        gpioWrite(FAN_GPIO, FAN_ON);
        fan_state = FAN_ON;
    } else {
        gpioWrite(FAN_GPIO, FAN_OFF);
        fan_state = FAN_OFF;
    }

    return 0;
}

int main(void)
{
    int adc_reading;
    int co2;

    if ((spi_handle = init_spi()) < 0) {
        return EXIT_FAILURE;
    }

    if (init_fan() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        adc_reading = read_adc(spi_handle, ADC_CHANNEL);
        co2 = convert_adc_reading(adc_reading);
        control_fan(co2);
        log_reading(co2);
        sleep(LOG_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

