#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_READ_RETRIES 3
#define SPI_READ_DELAY 1000000
#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED_MODE 0x08
#define MCP3008_CHANNEL_0 0x00
#define MCP3008_CHANNEL_1 0x01
#define MCP3008_CHANNEL_2 0x02
#define MCP3008_CHANNEL_3 0x03
#define MCP3008_CHANNEL_4 0x04
#define MCP3008_CHANNEL_5 0x05
#define MCP3008_CHANNEL_6 0x06
#define MCP3008_CHANNEL_7 0x07
#define MCP3008_RESPONSE_BYTES 2
#define MCP3008_RESPONSE_BITS 10
#define MCP3008_RESPONSE_MASK 0x03FF
#define MCP3008_RESPONSE_SHIFT 2
#define MCP3008_RESPONSE_MAX 1023
#define MCP3008_RESPONSE_MIN 0
#define AQI_MAX 500
#define AQI_MIN 0
#define AQI_RANGE (AQI_MAX - AQI_MIN)
#define AQI_RESPONSE_RANGE (MCP3008_RESPONSE_MAX - MCP3008_RESPONSE_MIN)
#define AQI_RESPONSE_RATIO (AQI_RANGE / AQI_RESPONSE_RANGE)
#define AQI_RESPONSE_OFFSET (AQI_MIN - (MCP3008_RESPONSE_MIN * AQI_RESPONSE_RATIO))
#define AQI_THRESHOLD 100
#define FAN_GPIO 18
#define FAN_GPIO_MODE GPIO_PULLDOWN
#define FAN_GPIO_VALUE_ON 1
#define FAN_GPIO_VALUE_OFF 0
#define LOG_FILE "air_quality.log"
#define LOG_FILE_MODE "a"

static int spi_handle = -1;
static int fan_gpio_handle = -1;
static FILE *log_file = NULL;

static void cleanup(void)
{
    if (fan_gpio_handle >= 0)
    {
        gpioWrite(fan_gpio_handle, FAN_GPIO_VALUE_OFF);
        gpioSetMode(fan_gpio_handle, PI_INPUT);
        gpioSetPullUpDown(fan_gpio_handle, PI_PUD_OFF);
        gpioClose(fan_gpio_handle);
        fan_gpio_handle = -1;
    }

    if (spi_handle >= 0)
    {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    if (log_file != NULL)
    {
        fclose(log_file);
        log_file = NULL;
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_spi(void)
