#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_CS 8
#define MCP3008_CLK 11
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_CH0 0
#define MCP3008_THRESHOLD 300
#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_SPEED 1000000
#define RELAY_GPIO 18
#define RELAY_ON 1
#define RELAY_OFF 0
#define LOG_FILE "irrigation.log"
#define LOG_FILE_MODE "a"
#define SLEEP_TIME 60

int main(int argc, char *argv[])
{
    int mcp3008_handle, relay_gpio_handle, log_file_handle;
    int mcp3008_reading, mcp3008_status;
    char log_message[100];
    time_t current_time;
    struct tm *time_info;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    mcp3008_handle = spiOpen(MCP3008_CS, MCP3008_SPI_SPEED, MCP3008_SPI_MODE);
    if (mcp3008_handle < 0)
    {
        fprintf(stderr, "MCP3008 SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    relay_gpio_handle = gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    if (relay_gpio_handle < 0)
    {
        fprintf(stderr, "Relay GPIO set mode failed\n");
        spiClose(mcp3008_handle);
        gpioTerminate();
        return 1;
    }

    log_file_handle = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_file_handle < 0)
    {
        fprintf(stderr, "Log file open failed\n");
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        mcp3008_reading = spiRead(mcp3008_handle, MCP3008_CH0);
        if (mcp3008_reading < 0)
        {
            fprintf(stderr, "MCP3008 SPI read failed\n");
            break;
        }

        if (mcp3008_reading < MCP3008_THRESHOLD)
        {
            mcp3008_status = RELAY_ON;
            gpioWrite(RELAY_GPIO, RELAY_ON);
        }
        else
        {
            mcp3008_status = RELAY_OFF;
            gpioWrite(RELAY_GPIO, RELAY_OFF);
        }

        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", time_info);
        sprintf(log_message, "%s, %d, %s\n", log_message, mcp3008_reading, mcp3008_status ? "ON" : "OFF");
        write(log_file_handle, log_message, strlen(log_message));

        sleep(SLEEP_TIME);
    }

    gpioWrite(RELAY_GPIO, RELAY_OFF);
    spiClose(mcp3008_handle);
    gpioTerminate();
    close(log_file_handle);

    return 0;
}

