#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED 17
#define MCP3008 0
#define MCP3008_CH0 0
#define MCP3008_CH1 1
#define MCP3008_CH2 2
#define MCP3008_CH3 3
#define MCP3008_CH4 4
#define MCP3008_CH5 5
#define MCP3008_CH6 6
#define MCP3008_CH7 7
#define MCP3008_CLK 11
#define MCP3008_MISO 9
#define MCP3008_MOSI 10
#define MCP3008_CS 8

#define SOUND_THRESHOLD 1.1
#define SOUND_DEBOUNCE 10

int sound_avg = 0;
int sound_threshold = 0;
int sound_debounce = 0;

void sound_calibrate(void) {
    int i;
    int sound_sum = 0;
    for (i = 0; i < 500; i++) {
        sound_sum += spiXfer(MCP3008, (MCP3008_CH0 << 4) | 0x08);
        delay(10);
    }
    sound_avg = sound_sum / 500;
    sound_threshold = sound_avg * SOUND_THRESHOLD;
}

void sound_check(void) {
    int sound_level = spiXfer(MCP3008, (MCP3008_CH0 << 4) | 0x08);
    if (sound_level > sound_threshold) {
        if (sound_debounce == 0) {
            gpioWrite(LED, 1);
            sound_debounce = SOUND_DEBOUNCE;
        }
    } else {
        gpioWrite(LED, 0);
        sound_debounce = 0;
    }
}

void sound_cleanup(int signum) {
    gpioWrite(LED, 0);
    spiClose(MCP3008);
    gpioTerminate();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (gpioSetMode(LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "failed to set LED mode\n");
        return 1;
    }
    if (gpioSetMode(MCP3008_CLK, PI_OUTPUT) != 0) {
        fprintf(stderr, "failed to set MCP3008_CLK mode\n");
        return 1;
    }
    if (gpioSetMode(MCP3008_MISO, PI_INPUT) != 0) {
        fprintf(stderr, "failed to set MCP3008_MISO mode\n");
        return 1;
    }
    if (gpioSetMode(MCP3008_MOSI, PI_OUTPUT) != 0) {
        fprintf(stderr, "failed to set MCP3008_MOSI mode\n");
        return 1;
    }
    if (gpioSetMode(MCP3008_CS, PI_OUTPUT) != 0) {
        fprintf(stderr, "failed to set MCP3008_CS mode\n");
        return 1;
    }
    if (spiOpen(MCP3008, 1000000, 0) < 0) {
        fprintf(stderr, "failed to open MCP3008 SPI\n");
        return 1;
    }
    signal(SIGINT, sound_cleanup);
    sound_calibrate();
    while (1) {
        sound_check();
        delay(10);
    }
    return 0;
}

