#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define SPI_COMMAND_SIZE 3
#define SPI_RESPONSE_SIZE 3
#define SPI_COMMAND_START_BIT 0x01
#define SPI_COMMAND_CONFIG_BIT (0x08 | (SPI_CHANNEL << 4))
#define SPI_COMMAND_DUMMY_BIT 0x00
#define SPI_RESPONSE_START_BIT 0x01
#define SPI_RESPONSE_CONFIG_BIT (0x08 | (SPI_CHANNEL << 4))
#define SPI_RESPONSE_DUMMY_BIT 0x00
#define SPI_RESPONSE_DATA_MASK 0x03FF

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8

#define LOG_FILE "audio_log.txt"

int main(void)
{
    int ret;
    int spi_fd;
    int gpio_line_fd;
    struct gpiod_chip *gpio_chip;
    struct gpiod_line *gpio_line;
    struct spi_ioc_transfer spi_xfer;
    uint8_t tx_buf[SPI_COMMAND_SIZE];
    uint8_t rx_buf[SPI_RESPONSE_SIZE];
    struct timespec ts;
    FILE *log_file;

    /* Open SPI device */
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set SPI mode */
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set SPI bits per word */
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set SPI max speed */
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Request GPIO line */
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set GPIO line as output */
    ret = gpiod_line_request_output(gpio_line, "audio_log", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line as output: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize SPI transfer structure */
    memset(&spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer.tx_buf = (unsigned long)tx_buf;
    spi_xfer.rx_buf = (unsigned long)rx_buf;
    spi_xfer.len = SPI_COMMAND_SIZE;
    spi_xfer.speed_hz = SPI_MAX_SPEED_HZ;
    spi_xfer.bits_per_word = SPI_BITS_PER_WORD;
    spi_xfer.delay_usecs = 0;

    /* Initialize SPI command buffer */
    tx_buf[0] = SPI_COMMAND_START_BIT;
    tx_buf[1] = SPI_COMMAND_CONFIG_BIT;
    tx_buf[2] = SPI_COMMAND_DUMMY_BIT;

    /* Initialize SPI response buffer */
    memset(rx_buf, 0, SPI_RESPONSE_SIZE);

    /* Initialize timestamp */
    memset(&ts, 0, sizeof(ts));

    /* Main loop */
    while (1) {
        /* Drive GPIO line low */
        ret = gpiod_line_set_value(gpio_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to drive GPIO line low: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        /* Transfer SPI command */
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer);
        if (ret < 0) {
            fprintf(stderr, "Failed to transfer SPI command: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        /* Drive GPIO line high */
        ret = gpiod_line_set_value(gpio_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to drive GPIO line high: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        /* Check SPI response */
        if (rx_buf[0] != SPI_RESPONSE_START_BIT || rx_buf[1] != SPI_RESPONSE_CONFIG_BIT || rx_buf[2] != SPI_RESPONSE_DUMMY_BIT) {
            fprintf(stderr, "Invalid SPI response\n");
            return EXIT_FAILURE;
        }

        /* Get timestamp */
        ret = clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        /* Parse ADC value */
        uint16_t adc_value = (rx_buf[1] << 8) | rx_buf[2];
        adc_value &= SPI_RESPONSE_DATA_MASK;

        /* Log ADC value */
        fprintf(log_file, "%ld|%d\n", ts.tv_nsec, adc_value);
        fflush(log_file);

        /* Sleep until next sample deadline */
        struct timespec sleep_time = {0, 1000000};
        ret = nanosleep(&sleep_time, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    /* Close log file */
    fclose(log_file);

    /* Release GPIO line request */
    gpiod_line_release(gpio_line);

    /* Close GPIO chip */
    gpiod_chip_close(gpio_chip);

    /* Close SPI device */
    close(spi_fd);

    return EXIT_SUCCESS;
}

