#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_VREF 3.3
#define SPI_MAX_VALUE 1023

#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023

#define LOG_FILE "gas_log.txt"

#define PPM_CALIBRATION_FACTOR 1000.0

int spi_handle;
FILE *log_file;

void close_resources(int signal) {
    if (spi_handle >= 0) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main(void) {
    int adc_value;
    double voltage, ppm;
    struct timespec timestamp;

    // Initialize SPI
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, close_resources);

    while (1) {
        // Read ADC value
        if (spiXfer(spi_handle, NULL, NULL, 2) != 2) {
            fprintf(stderr, "Failed to read ADC value.\n");
            continue;
        }
        adc_value = (spiRead(spi_handle) << 8) | spiRead(spi_handle);

        // Convert ADC value to voltage
        voltage = (double)adc_value * SPI_VREF / SPI_MAX_VALUE;

        // Calculate PPM
        ppm = voltage * PPM_CALIBRATION_FACTOR;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &timestamp);

        // Log timestamp, voltage, and PPM to file
        fprintf(log_file, "%ld.%09ld,%f,%f\n", timestamp.tv_sec, timestamp.tv_nsec, voltage, ppm);
        fflush(log_file);

        // Print voltage and PPM to console
        printf("Voltage: %f V, PPM: %f\n", voltage, ppm);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

