#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_COUNT 3
#define SENSOR_PINS {4, 17, 27}
#define SENSOR_SENSITIVITY 0.025
#define SENSOR_QUIESCENT 1.65
#define SENSOR_MIN -100
#define SENSOR_MAX 100
#define SENSOR_LOG_FILE "magnetic_log.txt"
#define SENSOR_LOG_FORMAT "%.2f,%.2f,%.2f\n"
#define SENSOR_LOG_INTERVAL 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[SENSOR_COUNT];
    int pins[SENSOR_COUNT] = SENSOR_PINS;
    int i;
    double sensor_values[SENSOR_COUNT];
    FILE *log_file;
    char log_line[100];

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to set SIGINT handler\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < SENSOR_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get GPIO line %d\n", pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(lines[i], "sensor") < 0) {
            fprintf(stderr, "Error: Failed to request GPIO line %d\n", pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(SENSOR_LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", SENSOR_LOG_FILE);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        for (i = 0; i < SENSOR_COUNT; i++) {
            if (gpiod_line_get_value(lines[i]) < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line %d\n", pins[i]);
                continue;
            }

            sensor_values[i] = (gpiod_line_get_value(lines[i]) * 3.3 - SENSOR_QUIESCENT) / SENSOR_SENSITIVITY;

            if (sensor_values[i] < SENSOR_MIN || sensor_values[i] > SENSOR_MAX) {
                fprintf(stderr, "Warning: Sensor %d value %.2f mT is out of range\n", i + 1, sensor_values[i]);
            }
        }

        sprintf(log_line, SENSOR_LOG_FORMAT, sensor_values[0], sensor_values[1], sensor_values[2]);
        fprintf(log_file, "%s", log_line);
        fflush(log_file);

        usleep(SENSOR_LOG_INTERVAL);
    }

    fclose(log_file);

    for (i = 0; i < SENSOR_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

