#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define ADC_CHANNEL 0
#define ADC_CE 0
#define ADC_SPEED 500000
#define ADC_MODE 0
#define ADC_BITS 1024
#define ADC_MAX 1023
#define ADC_MIN 0
#define ADC_RANGE (ADC_MAX - ADC_MIN)
#define ADC_THRESHOLD 30
#define ADC_THRESHOLD_VALUE (ADC_RANGE * ADC_THRESHOLD / 100)
#define ADC_THRESHOLD_MIN (ADC_MIN + ADC_THRESHOLD_VALUE)
#define ADC_THRESHOLD_MAX (ADC_MAX - ADC_THRESHOLD_VALUE)
#define PUMP_GPIO 17
#define PUMP_ON 1
#define PUMP_OFF 0
#define PUMP_DELAY 1000000
#define LOG_FILE "watering.log"
#define LOG_FORMAT "%s: %s\n"
#define LOG_FORMAT_SIZE 100
#define LOG_FORMAT_TIME_SIZE 20
#define LOG_FORMAT_EVENT_SIZE 80
#define LOG_FORMAT_EVENT_START "Program started"
#define LOG_FORMAT_EVENT_PUMP_ON "Pump on"
#define LOG_FORMAT_EVENT_PUMP_OFF "Pump off"
#define LOG_FORMAT_EVENT_ERROR "Error: %s"
#define LOG_FORMAT_EVENT_EXIT "Program terminated"

int pump_state = PUMP_OFF;

void log_event(const char *event)
{
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error: Unable to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char time_string[LOG_FORMAT_TIME_SIZE];
    strftime(time_string, LOG_FORMAT_TIME_SIZE, "%Y-%m-%d %H:%M:%S", time_info);

    char log_string[LOG_FORMAT_SIZE];
    snprintf(log_string, LOG_FORMAT_SIZE, LOG_FORMAT, time_string, event);

    fputs(log_string, log_file);
    fclose(log_file);
}

void log_error(const char *error)
{
    char error_string[LOG_FORMAT_EVENT_SIZE];
    snprintf(error_string, LOG_FORMAT_EVENT_SIZE, LOG_FORMAT_EVENT_ERROR, error);
    log_event(error_string);
}

void set_pump_state(int state)
{
    if (state != PUMP_ON && state != PUMP_OFF)
    {
        log_error("Invalid pump state");
        return;
    }

    if (state == pump_state)
    {
        return;
    }

    if (gpioWrite(PUMP_GPIO, state) != 0)
    {
        log_error("Unable to set pump state");
        return;
    }

    pump_state = state;

    if (state == PUMP_ON)
    {
        log_event(LOG_FORMAT_EVENT_PUMP_ON);
    }
    else
    {
        log_event(LOG_FORMAT_EVENT_PUMP_OFF);
    }
}

void handle_signal(int signal)
{
    set_pump_state(PUMP_OFF);
    log_event(LOG_FORMAT_EVENT_EXIT);
    exit(EXIT_SUCCESS);
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        log_error("Unable to initialise GPIO");
        return EXIT_FAILURE;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    set_pump_state(PUMP_OFF);

    log_event(LOG_FORMAT_EVENT_START);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1)
    {
        int adc_value = gpioAnalogRead(ADC_CHANNEL);
        if (adc_value < 0)
        {
            log_error("Unable to read ADC value");
            continue;
        }

        if (adc_value < ADC_THRESHOLD_MIN)
        {
            set_pump_state(PUMP_ON);
        }
        else if (adc_value > ADC_THRESHOLD_MAX)
        {
            set_pump_state(PUMP_OFF);
        }

        gpioDelay(PUMP_DELAY);
    }

    return EXIT_SUCCESS;
}

