#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define SPI_CHANNELS 3

#define SPI_CMD_START 0x01
#define SPI_CMD_SINGLE_ENDED 0x80

#define CSV_FILE "sensor_data.csv"

static int spi_fd = -1;
static FILE *csv_file = NULL;

static void close_spi(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

static void close_csv(void)
{
    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }
}

static void close_all(void)
{
    close_spi();
    close_csv();
}

static void sigint_handler(int signum)
{
    close_all();
    exit(EXIT_SUCCESS);
}

static int init_spi(void)
{
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED;

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

static int init_csv(void)
{
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("fopen");
        return -1;
    }

    fprintf(csv_file, "time,channel0,channel1,channel2\n");

    return 0;
}

static int read_spi(uint8_t channel, uint16_t *value)
{
    int ret;
    uint8_t tx[3] = {SPI_CMD_START, SPI_CMD_SINGLE_ENDED | (channel << 4), 0x00};
    uint8_t rx[3] = {0};

    ret = write(spi_fd, tx, sizeof(tx));
    if (ret < 0) {
        perror("write");
        return -1;
    }

    ret = read(spi_fd, rx, sizeof(rx));
    if (ret < 0) {
        perror("read");
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | rx[2];

    return 0;
}

int main(void)
{
    int ret;
    uint16_t value;
    struct timespec ts;
    struct tm tm;
    char time_str[32];
    uint8_t channel;

    signal(SIGINT, sigint_handler);

    ret = init_spi();
    if (ret < 0) {
        close_spi();
        return EXIT_FAILURE;
    }

    ret = init_csv();
    if (ret < 0) {
        close_spi();
        return EXIT_FAILURE;
    }

    while (1) {
        for (channel = 0; channel < SPI_CHANNELS; channel++) {
            ret = read_spi(channel, &value);
            if (ret < 0) {
                close_all();
                return EXIT_FAILURE;
            }

            clock_gettime(CLOCK_REALTIME, &ts);
            localtime_r(&ts.tv_sec, &tm);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm);

            fprintf(csv_file, "%s.%09ld,%u\n", time_str, ts.tv_nsec, value);
        }

        fflush(csv_file);
        sleep(1);
    }

    close_all();

    return EXIT_SUCCESS;
}

