#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_GPIO 17
#define LED_GPIO 18

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *led_line;

void cleanup(int signum) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    int ret, sensor_val;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        exit(1);
    }

    ret = gpiod_line_request_input(sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("Failed to request sensor line");
        exit(1);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED line");
        exit(1);
    }

    ret = gpiod_line_request_output(led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("Failed to request LED line");
        exit(1);
    }

    while (1) {
        sensor_val = gpiod_line_get_value(sensor_line);
        printf("Sound sensor value: %d\n", sensor_val);

        if (sensor_val == 0) {
            gpiod_line_set_value(led_line, 1);
            sleep(1);
            gpiod_line_set_value(led_line, 0);
        }

        usleep(100000);
    }

    return 0;
}

