#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

static volatile sig_atomic_t sig_flag = 0;

static void sig_handler(int sig)
{
    sig_flag = 1;
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    struct timespec ts;
    FILE *fp;
    int ret;

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_event(line, GPIOD_LINE_REQUEST_FALLING_EDGE, "vibration-monitor");
    if (ret < 0) {
        perror("gpiod_line_request_event");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    fp = fopen("/var/log/vibration_shutdown.log", "a");
    if (!fp) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!sig_flag) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(fp, "%ld.%09ld: vibration detected\n", ts.tv_sec, ts.tv_nsec);
        fflush(fp);
        printf("%ld.%09ld: vibration detected\n", ts.tv_sec, ts.tv_nsec);
        fflush(stdout);

        ret = system("sudo shutdown -h now");
        if (ret < 0) {
            perror("system");
            break;
        }
    }

    fclose(fp);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

