#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23
#define I2C_CMD 0x10
#define SPI_BUS "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define SPI_CMD 0x01
#define LOG_FILE "environmental_log.txt"

static volatile sig_atomic_t running = 1;

static void sig_handler(int signum)
{
    running = 0;
}

static int i2c_init(int *fd)
{
    int ret;

    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int i2c_read(int fd, uint16_t *data)
{
    int ret;
    uint8_t buf[2];

    ret = write(fd, &I2C_CMD, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write I2C command: %s\n", strerror(errno));
        return -1;
    }

    ret = read(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to read I2C data: %s\n", strerror(errno));
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];

    return 0;
}

static int spi_init(int *fd)
{
    int ret;
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED;

    *fd = open(SPI_BUS, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open SPI bus: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_RD_MODE, &mode);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI speed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int spi_read(int fd, uint8_t *data)
{
    int ret;
    uint8_t tx[3] = { SPI_CMD, 0, 0 };
    uint8_t rx[3] = { 0, 0, 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = SPI_DELAY,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
        return -1;
    }

    *data = rx[1];

    return 0;
}

int main(void)
{
    int i2c_fd, spi_fd, ret;
    uint16_t lux;
    uint8_t sound;
    FILE *log_file;
    struct tm *tm;
    time_t t;
    char buf[128];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = i2c_init(&i2c_fd);
    if (ret < 0)
        return -1;

    ret = spi_init(&spi_fd);
    if (ret < 0)
        return -1;

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    while (running) {
        ret = i2c_read(i2c_fd, &lux);
        if (ret < 0)
            break;

        ret = spi_read(spi_fd, &sound);
        if (ret < 0)
            break;

        t = time(NULL);
        tm = localtime(&t);
        strftime(buf, sizeof(buf), "%F %T", tm);
        fprintf(log_file, "%s, Light: %u, Sound: %u\n", buf, lux, sound);

        sleep(1);
    }

    fclose(log_file);
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

