#include <pigpio.h>

#define LED_PIN 16
#define ADC_CHANNEL 0
#define ADC_THRESHOLD 500
#define ADC_DELAY 10
#define LED_DELAY 500

int main(int argc, char *argv[])
{
    int spiHandle, adcValue, ledState = 0;
    time_t timestamp;
    struct tm *timeInfo;
    char timeString[20];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((spiHandle = spiOpen(0, 1000000, 0)) < 0)
    {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1)
    {
        if (spiXfer(spiHandle, NULL, NULL, 2) < 0)
        {
            fprintf(stderr, "Failed to transfer SPI data\n");
            break;
        }

        adcValue = (spiRead(spiHandle) & 0x03) << 8 | spiRead(spiHandle);

        if (adcValue > ADC_THRESHOLD && !ledState)
        {
            ledState = 1;
            gpioWrite(LED_PIN, 1);

            timestamp = time(NULL);
            timeInfo = localtime(&timestamp);
            strftime(timeString, sizeof(timeString), "%F %T", timeInfo);

            FILE *logFile = fopen("sound_events.log", "a");
            if (logFile == NULL)
            {
                fprintf(stderr, "Failed to open log file\n");
                break;
            }

            fprintf(logFile, "%s\n", timeString);
            fclose(logFile);
        }
        else if (adcValue <= ADC_THRESHOLD && ledState)
        {
            ledState = 0;
            gpioWrite(LED_PIN, 0);
        }

        time_sleep(ADC_DELAY / 1000.0);
    }

    spiClose(spiHandle);
    gpioTerminate();

    return 0;
}

