#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    uint8_t rx_buf[3] = {0};

    if (spiXfer(SPI_CHANNEL, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    return 100.0 - ((adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    if (moisture_level < 0.0 || moisture_level > 100.0) {
        fprintf(stderr, "Invalid moisture level: %f\n", moisture_level);
        return;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char time_string[20];
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s,%f\n", time_string, moisture_level);
    fclose(log_file);
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        exit(0);
    }
}

int spi_setup(spi_config_t config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_BAUD, config) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        return -1;
    }

    return 0;
}

int main() {
    if (spi_setup(0) < 0) {
        return -1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level < 0.0) {
            fprintf(stderr, "Failed to calculate moisture level, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        log_data(moisture_level);
        printf("Moisture level: %f\n", moisture_level);

        sleep(READ_DELAY);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

