#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_FORMAT V4L2_PIX_FMT_GREY
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_COUNT 100
#define IMAGE_TIMEOUT 2000

int main(int argc, char *argv[])
{
    int fd;
    int i;
    int ret;
    int index;
    int count;
    int timeout;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_buffer *pbuf;
    struct timeval tv;
    fd_set fds;
    void *pmem;
    char filename[256];

    if (argc > 1) {
        strncpy(VIDEO_DEVICE, argv[1], sizeof(VIDEO_DEVICE));
    }

    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", VIDEO_DEVICE, strerror(errno));
        return -1;
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        fprintf(stderr, "ioctl VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto err_close;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        goto err_close;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", VIDEO_DEVICE);
        goto err_close;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        fprintf(stderr, "ioctl VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto err_close;
    }

    if (fmt.fmt.pix.pixelformat != IMAGE_FORMAT) {
        fprintf(stderr, "pixel format %s is not supported\n", IMAGE_FORMAT);
        goto err_close;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "image size %dx%d is not supported\n", IMAGE_WIDTH, IMAGE_HEIGHT);
        goto err_close;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        fprintf(stderr, "ioctl VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto err_close;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        fprintf(stderr, "ioctl VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto err_close;
    }

    pmem = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (pmem == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        goto err_close;
    }

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        fprintf(stderr, "ioctl VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto err_munmap;
    }

    ret = ioctl(fd, VIDIOC_STREAMON, &buf.type);
    if (ret < 0) {
        fprintf(stderr, "ioctl VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto err_munmap;
    }

    count = 0;
    timeout = 0;
    while (count < IMAGE_COUNT) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 0;
        tv.tv_usec = IMAGE_TIMEOUT;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            fprintf(stderr, "select failed: %s\n", strerror(errno));
            goto err_streamoff;
        } else if (ret == 0) {
            timeout++;
            if (timeout >= 10) {
                fprintf(stderr, "timeout\n");
                goto err_streamoff;
            }
            continue;
        }

        ret = ioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            fprintf(stderr, "ioctl VIDIOC_DQBUF failed: %s\n", strerror(errno));
            goto err_streamoff;
        }

        pbuf = &buf;
        sprintf(filename, "image_%04d.pgm", count + 1);
        ret = write_image(pmem, pbuf->length, filename);
        if (ret < 0) {
            fprintf(stderr, "write_image failed: %s\n", strerror(errno));
            goto err_streamoff;
        }

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            fprintf(stderr, "ioctl VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto err_streamoff;
        }

        count++;
    }

    ret = ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
    if (ret < 0) {
        fprintf(stderr, "ioctl VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        goto err_munmap;
    }

    munmap(pmem, buf.length);
    close(fd);
    return 0;

err_streamoff:
    ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
err_munmap:
    munmap(pmem, buf.length);
err_close:
    close(fd);
