#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_FORMAT V4L2_PIX_FMT_MJPEG
#define FRAME_BUFFER_COUNT 4

int main(int argc, char *argv[])
{
    int video_fd = -1;
    int frame_log_fd = -1;
    struct v4l2_capability video_capability;
    struct v4l2_format video_format;
    struct v4l2_requestbuffers video_request_buffers;
    struct v4l2_buffer video_buffer;
    struct v4l2_buffer *video_buffers = NULL;
    struct timeval frame_timestamp;
    FILE *frame_log_file = NULL;

    // Open video device
    video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        fprintf(stderr, "Error opening video device: %s\n", strerror(errno));
        goto cleanup;
    }

    // Query video device capabilities
    if (ioctl(video_fd, VIDIOC_QUERYCAP, &video_capability) < 0) {
        fprintf(stderr, "Error querying video device capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    // Set video format
    video_format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    video_format.fmt.pix.width = FRAME_WIDTH;
    video_format.fmt.pix.height = FRAME_HEIGHT;
    video_format.fmt.pix.pixelformat = FRAME_FORMAT;
    video_format.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(video_fd, VIDIOC_S_FMT, &video_format) < 0) {
        fprintf(stderr, "Error setting video format: %s\n", strerror(errno));
        goto cleanup;
    }

    // Request video buffers
    video_request_buffers.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    video_request_buffers.memory = V4L2_MEMORY_MMAP;
    video_request_buffers.count = FRAME_BUFFER_COUNT;
    if (ioctl(video_fd, VIDIOC_REQBUFS, &video_request_buffers) < 0) {
        fprintf(stderr, "Error requesting video buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    // Allocate memory for video buffers
    video_buffers = (struct v4l2_buffer *)malloc(video_request_buffers.count * sizeof(struct v4l2_buffer));
    if (video_buffers == NULL) {
        fprintf(stderr, "Error allocating memory for video buffers\n");
        goto cleanup;
    }

    // Map video buffers to memory
    for (int i = 0; i < video_request_buffers.count; i++) {
        video_buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        video_buffer.memory = V4L2_MEMORY_MMAP;
        video_buffer.index = i;
        if (ioctl(video_fd, VIDIOC_QUERYBUF, &video_buffer) < 0) {
            fprintf(stderr, "Error querying video buffer: %s\n", strerror(errno));
            goto cleanup;
        }

        video_buffers[i].length = video_buffer.length;
        video_buffers[i].start = mmap(NULL, video_buffer.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, video_buffer.m.offset);
        if (video_buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping video buffer: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    // Queue video buffers for capture
    for (int i = 0; i < video_request_buffers.count; i++) {
        video_buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        video_buffer.memory = V4L2_MEMORY_MMAP;
        video_buffer.index = i;
        if (ioctl(video_fd, VIDIOC_QBUF, &video_buffer) < 0) {
            fprintf(stderr, "Error queuing video buffer: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    // Start video capture
    enum v4l2_buf_type video_type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(video_fd, VIDIOC_STREAMON, &video_type) < 0) {
        fprintf(stderr, "Error starting video capture: %s\n", strerror(errno));
        goto cleanup;
    }

    // Open frame log file
    frame_log_file = fopen(FRAME_LOG_FILE, "w");
    if (frame_log_file == NULL) {
        fprintf(stderr, "Error opening frame log file: %s\n", strerror(errno));
        goto cleanup;
    }

    // Capture frames and log timestamps
    fd_set read_fds;
    struct timeval timeout;
    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(video_fd, &read_fds);
        timeout.tv_sec = 1;
        timeout.tv_usec = 0;

        int select_result = select(video_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (select_result < 0) {
            fprintf(stderr, "Error in select(): %s\n", strerror(errno));
            goto cleanup;
        } else if (select_result == 0) {
            fprintf(stderr, "Timeout in select()\n");
            goto cleanup;
        }

        if (FD_ISSET(video_fd, &read_fds)) {
            // Dequeue video buffer
            if (ioctl(video_fd, VIDIOC_DQBUF, &video_buffer) < 0) {
                fprintf(stderr, "Error dequeueing video buffer: %s\n", strerror(errno));
                goto cleanup;
            }

            // Get frame timestamp
            if (ioctl(video_fd, VIDIOC_G_INPUT, &video_buffer.index) < 0) {
                fprintf(stderr, "Error getting frame timestamp: %s\n", strerror(errno));
                goto cleanup;
            }

            // Log frame timestamp
            gettimeofday(&frame_timestamp, NULL);
            fprintf(frame_log_file, "%ld.%06ld\n", frame_timestamp.tv_sec, frame_timestamp.tv_usec);
            fflush(frame_log_file);

            // Queue video buffer for capture again
            if (ioctl(video_fd, VIDIOC_QBUF, &video_buffer) < 0) {
                fprintf(stderr, "Error queuing video buffer: %s\n", strerror(errno));
                goto cleanup;
            }
        }
    }

cleanup:
    // Release resources
    if (video_buffers != NULL) {
        for (int i = 0; i < video_request_buffers.count; i++) {
            if (video_buffers[i].start != MAP_FAILED) {
                munmap(video_buffers[i].start, video_buffers[i].length);
            }
        }
        free(video_buffers);
    }
    if (video_fd >= 0) {
        close(video_fd);
    }
    if (frame_log_file != NULL) {
        fclose(frame_log_file);
    }

    return 0;
}

