#define NUM_BUFFERS 4

struct buffer {
    void *start;
    size_t length;
};

static struct buffer *buffers;
static int fd;

static void cleanup(void)
{
    int i;

    if (buffers) {
        for (i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i].start)
                munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
    }

    if (fd > 0)
        close(fd);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

