#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

static int fd;

static void cleanup(void)
{
    if (fd > 0)
        close(fd);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int ret;
    FILE *fp;
    char *buf;
    size_t buf_size;

    fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("ioctl VIDIOC_QUERYCAP");
        goto error;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "device does not support video capture\n");
        goto error;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "device does not support streaming\n");
        goto error;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("ioctl VIDIOC_S_FMT");
        goto error;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "device does not support MJPEG format\n");
        goto error;
    }

    if (fmt.fmt.pix.width != 1920 || fmt.fmt.pix.height != 1080) {
        fprintf(stderr, "device does not support 1920x1080 resolution\n");
        goto error;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("ioctl VIDIOC_REQBUFS");
        goto error;
    }

    if (req.count < 1) {
        fprintf(stderr, "device does not support 1 buffer\n");
        goto error;
    }

    ret = ioctl(fd, VIDIOC_STREAMON, &req.type);
    if (ret < 0) {
        perror("ioctl VIDIOC_STREAMON");
        goto error;
    }

    buf_size = fmt.fmt.pix.sizeimage;
    buf = malloc(buf_size);
    if (!buf) {
        fprintf(stderr, "out of memory\n");
        goto error;
    }

    ret = read(fd, buf, buf_size);
    if (ret < 0) {
        if (errno == EAGAIN) {
            fprintf(stderr, "no data in buffer\n");
            goto error;
        } else {
            perror("read");
            goto error;
        }
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("fopen");
        goto error;
    }

    ret = fwrite(buf, 1, ret, fp);
    if (ret < 0) {
        perror("fwrite");
        goto error;
    }

    fclose(fp);

    ret = ioctl(fd, VIDIOC_STREAMOFF, &req.type);
    if (ret < 0) {
        perror("ioctl VIDIOC_STREAMOFF");
        goto error;
    }

    cleanup();

    return EXIT_SUCCESS;

error:
    cleanup();
    return EXIT_FAILURE;
}
