#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

int main(int argc, char *argv[])
{
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum fsize;
    struct v4l2_frmivalenum fival;
    struct v4l2_queryctrl queryctrl;
    int ret;

    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/video0: %s\n", strerror(errno));
        return 1;
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming i/o\n");
        return 1;
    }

    printf("Supported resolutions:\n");
    fsize.index = 0;
    fsize.pixel_format = V4L2_PIX_FMT_YUYV;
    while ((ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize)) == 0) {
        if (fsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %dx%d\n", fsize.discrete.width, fsize.discrete.height);
        } else if (fsize.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  %dx%d to %dx%d, step %dx%d\n",
                   fsize.stepwise.min_width, fsize.stepwise.min_height,
                   fsize.stepwise.max_width, fsize.stepwise.max_height,
                   fsize.stepwise.step_width, fsize.stepwise.step_height);
        }
        fsize.index++;
    }
    if (ret != -1 || errno != EINVAL) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
        return 1;
    }

    printf("Supported frame rates:\n");
    fival.index = 0;
    fival.pixel_format = V4L2_PIX_FMT_YUYV;
    fival.width = 640;
    fival.height = 480;
    while ((ret = ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fival)) == 0) {
        if (fival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            printf("  %d/%d\n", fival.discrete.numerator, fival.discrete.denominator);
        } else if (fival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
            printf("  %d/%d to %d/%d, step %d/%d\n",
                   fival.stepwise.min.numerator, fival.stepwise.min.denominator,
                   fival.stepwise.max.numerator, fival.stepwise.max.denominator,
                   fival.stepwise.step.numerator, fival.stepwise.step.denominator);
        }
        fival.index++;
    }
    if (ret != -1 || errno != EINVAL) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
        return 1;
    }

    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    ret = ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl);
    if (ret < 0) {
        if (errno == EINVAL) {
            printf("Autofocus not supported\n");
        } else {
            fprintf(stderr, "VIDIOC_QUERYCTRL failed: %s\n", strerror(errno));
            return 1;
        }
    } else {
        printf("Autofocus supported\n");
    }

    close(fd);
    return 0;
}

