#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_DIRECTION "in"
#define GPIO_EDGE "falling"
#define GPIO_DEBOUNCE 50
#define IMAGE_PATH "/home/pi/images"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define IMAGE_TIMEOUT 2000
#define IMAGE_PREVIEW 0
#define LOG_PATH "/home/pi/motion_capture.log"

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    struct timespec ts;
    char filename[256];
    char command[1024];
    FILE *log;
    int ret;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = GPIO_PIN;
    req.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;
    req.flags = GPIOD_LINE_REQUEST_FLAG_DEBOUNCE_SUSPEND;
    req.consumer = "motion_capture";
    req.event_flags = GPIOD_LINE_EVENT_FALLING_EDGE;
    req.debounce_timeout = GPIO_DEBOUNCE;
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line, &req, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log = fopen(LOG_PATH, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_PATH);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(log, "Started motion capture\n");
    fclose(log);

    while (1) {
        ret = gpiod_line_event_wait(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for GPIO line event\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%L.jpg", localtime(&ts.tv_sec));
        snprintf(command, sizeof(command), "libcamera-still -o %s/%s --width %d --height %d -q %d --timeout %d --nopreview", IMAGE_PATH, filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY, IMAGE_TIMEOUT);
        ret = system(command);
        if (ret < 0) {
            fprintf(stderr, "Failed to execute command %s\n", command);
        }

        log = fopen(LOG_PATH, "a");
        if (!log) {
            fprintf(stderr, "Failed to open log file %s\n", LOG_PATH);
            break;
        }

        fprintf(log, "%s: %s\n", filename, ret == 0 ? "success" : "failure");
        fclose(log);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

