#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_PIN 17
#define TILT_PIN 18
#define PAN_MIN 500
#define PAN_MAX 2500
#define TILT_MIN 500
#define TILT_MAX 2500
#define PAN_NEUTRAL 1500
#define TILT_NEUTRAL 1500
#define PAN_STEP 50
#define TILT_STEP 50
#define DELAY 100

int pan_angle = PAN_NEUTRAL;
int tilt_angle = TILT_NEUTRAL;

void handle_sigint(int sig) {
    gpioServo(PAN_PIN, PAN_NEUTRAL);
    gpioServo(TILT_PIN, TILT_NEUTRAL);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);

    while (1) {
        char input;
        scanf("%c", &input);

        switch (input) {
            case 'w':
                tilt_angle += TILT_STEP;
                if (tilt_angle > TILT_MAX) {
                    tilt_angle = TILT_MAX;
                }
                break;
            case 's':
                tilt_angle -= TILT_STEP;
                if (tilt_angle < TILT_MIN) {
                    tilt_angle = TILT_MIN;
                }
                break;
            case 'a':
                pan_angle -= PAN_STEP;
                if (pan_angle < PAN_MIN) {
                    pan_angle = PAN_MIN;
                }
                break;
            case 'd':
                pan_angle += PAN_STEP;
                if (pan_angle > PAN_MAX) {
                    pan_angle = PAN_MAX;
                }
                break;
            case 'q':
                handle_sigint(SIGINT);
                break;
            default:
                printf("Invalid input. Use w, a, s, d, or q.\n");
                continue;
        }

        if (gpioServo(PAN_PIN, pan_angle) < 0) {
            fprintf(stderr, "Failed to set pan servo.\n");
            handle_sigint(SIGINT);
        }

        if (gpioServo(TILT_PIN, tilt_angle) < 0) {
            fprintf(stderr, "Failed to set tilt servo.\n");
            handle_sigint(SIGINT);
        }

        gpioDelay(DELAY);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <lcd.h>

#define GPIO_PIN 17
#define CALIBRATION_FACTOR 450
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define LCD_ROWS 2
#define LCD_COLS 16

static volatile int keepRunning = 1;

void handle_sigint(int sig) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (lcdInit(LCD_ROWS, LCD_COLS, LCD_I2C_BUS, LCD_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    uint32_t lastTick = gpioTick();
    uint32_t pulseCount = 0;
    uint32_t totalVolume = 0;

    while (keepRunning) {
        uint32_t currentTick = gpioTick();
        uint32_t diff = currentTick - lastTick;

        if (diff >= 1000) {
            uint32_t pulsesPerMinute = (pulseCount * 1000) / diff;
            float flowRate = (float)pulsesPerMinute / CALIBRATION_FACTOR;
            float volume = (float)totalVolume / CALIBRATION_FACTOR;

            printf("Flow rate: %.2f L/min, Total volume: %.2f L\n", flowRate, volume);

            lcdPosition(0, 0);
            lcdPrintf(LCD_I2C_BUS, LCD_I2C_ADDR, "Flow rate: %.2f", flowRate);
            lcdPosition(1, 0);
            lcdPrintf(LCD_I2C_BUS, LCD_I2C_ADDR, "Total volume: %.2f", volume);

            lastTick = currentTick;
            pulseCount = 0;
        }

        if (gpioRead_Bits_0_31_0_31(GPIO_PIN) & (1 << GPIO_PIN)) {
            pulseCount++;
            totalVolume++;
        }
    }

    lcdClear(LCD_I2C_BUS, LCD_I2C_ADDR);
    gpioTerminate();

    return EXIT_SUCCESS;
}

