#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define LCD_ROWS 2
#define LCD_COLS 16

static volatile int keepRunning = 1;

void handle_sigint(int sig) {
    keepRunning = 0;
}

