Write a C program for a Raspberry Pi 3 Model B+ using the pigpio library to measure water flow rate with a single YF-S201 water flow sensor connected to GPIO17 (physical pin 11), using the sensor's calibration factor of 7.5 pulses per liter. Calculate the flow rate in liters per minute by counting pulses over a 1-second interval. Display the real-time flow rate on an LCD1602 display connected via I2C (bus 1, PCF8574 address 0x27), showing "Flow Rate:" on the first line and the value as "X.XX L/min" on the second line. Implement robust error handling for pigpio initialization, GPIO mode and alert setup, I2C bus open and write failures, and sensor-absent paths such as zero pulses over an extended period. Ensure clean resource release on all exit paths, including graceful shutdown on SIGINT and SIGTERM.

### Response:
```
#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <lcd.h>

#define GPIO_PIN 17
#define FLOW_RATE_CALIBRATION_FACTOR 7.5

int main(int argc, char *argv[])
{
    int lcdHandle;
    int gpioHandle;
    int pulseCount = 0;
    int lastPulseCount = 0;
    int pulseCountDiff = 0;
    double flowRate = 0.0;
    char flowRateStr[10];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioHandle = gpioSetAlertFunc(GPIO_PIN, NULL);
    if (gpioHandle < 0)
    {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    lcdHandle = lcdInit(2, 16, 4, 0, 2, 1, 0, 0, 0, 0, 0, 0);
    if (lcdHandle < 0)
    {
        fprintf(stderr, "Failed to initialize LCD\n");
        gpioTerminate();
        return 1;
    }

    lcdPosition(lcdHandle, 0, 0);
    lcdPuts(lcdHandle, "Flow Rate:");

    while (1)
    {
        pulseCount = gpioRead_Bits_0_31_Clear();
        pulseCountDiff = pulseCount - lastPulseCount;
        lastPulseCount = pulseCount;

        flowRate = (double)pulseCountDiff / FLOW_RATE_CALIBRATION_FACTOR;

        sprintf(flowRateStr, "%.2f L/min", flowRate);
        lcdPosition(lcdHandle, 0, 1);
        lcdPuts(lcdHandle, flowRateStr);

        sleep(1);
    }

    gpioTerminate();
    return 0;
}
```

