#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define ROW_COUNT 8
#define COL_COUNT 8
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_PINS {14, 15, 18, 23, 24, 25, 8, 7}
#define ROW_MASK 0xFF
#define COL_MASK 0xFF
#define ROW_DIR_MASK 0x00
#define COL_DIR_MASK 0xFF
#define ROW_VAL_MASK 0xFF
#define COL_VAL_MASK 0x00
#define ROW_VAL_ON 0xFF
#define COL_VAL_ON 0x00
#define ROW_VAL_OFF 0x00
#define COL_VAL_OFF 0xFF
#define DELAY_MS 150

static struct gpiod_chip *chip;
static struct gpiod_line *rows[ROW_COUNT];
static struct gpiod_line *cols[COL_COUNT];

static void cleanup(void)
{
    for (int i = 0; i < ROW_COUNT; i++) {
        gpiod_line_release(rows[i]);
    }
    for (int i = 0; i < COL_COUNT; i++) {
        gpiod_line_release(cols[i]);
    }
    gpiod_chip_close(chip);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int row_pins[ROW_COUNT] = ROW_PINS;
    int col_pins[COL_COUNT] = COL_PINS;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < ROW_COUNT; i++) {
        rows[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!rows[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", row_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(rows[i], "led-matrix", ROW_VAL_OFF) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d\n", row_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < COL_COUNT; i++) {
        cols[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!cols[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", col_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(cols[i], "led-matrix", COL_VAL_OFF) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d\n", col_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (int i = 0; i < COL_COUNT; i++) {
            gpiod_line_set_value(cols[i], COL_VAL_ON);
            gpiod_line_set_value(rows[i], ROW_VAL_ON);
            usleep(DELAY_MS * 1000);
            gpiod_line_set_value(cols[i], COL_VAL_OFF);
            gpiod_line_set_value(rows[i], ROW_VAL_OFF);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

