#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define I2C_REG 0x0D
#define I2C_LEN 2
#define SAMPLING_PERIOD 100

FILE *fp;
int i2cHandle;

void sigintHandler(int sig) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    fp = fopen("depth_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if (fseek(fp, 0, SEEK_END) == 0 && ftell(fp) == 0) {
        fprintf(fp, "timestamp,distance\n");
    }

    signal(SIGINT, sigintHandler);

    while (1) {
        uint8_t buf[I2C_LEN];
        int result = i2cWriteRead(i2cHandle, I2C_REG, 1, buf, I2C_LEN);
        if (result < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            i2cClose(i2cHandle);
            i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2cHandle < 0) {
                fprintf(stderr, "Failed to re-open I2C handle\n");
                fclose(fp);
                gpioTerminate();
                return 1;
            }
            fprintf(fp, "%ld,-1\n", gpioTick());
            continue;
        }

        uint16_t distance = (buf[0] << 8) | buf[1];
        fprintf(fp, "%ld,%d\n", gpioTick(), distance);

        gpioDelay(SAMPLING_PERIOD);
    }

    return 0;
}

