#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_GPIO 4
#define LED_GPIO 17
#define POLL_INTERVAL 100000
#define LOG_FILE "proximity.log"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line, *led_line;
static FILE *log_file;

static void cleanup(void)
{
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (led_line)
        gpiod_line_release(led_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static void log_event(const char *event)
{
    time_t now;
    char timestamp[32];

    now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
    fprintf(log_file, "%s %s\n", timestamp, event);
    fflush(log_file);
}

int main(void)
{
    int ret, sensor_value, led_value;
    struct timespec poll_timeout;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(sensor_line, "proximity");
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "proximity", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    poll_timeout.tv_sec = 0;
    poll_timeout.tv_nsec = POLL_INTERVAL;

    sensor_value = gpiod_line_get_value(sensor_line);
    led_value = 0;

    while (1) {
        ret = gpiod_line_poll(sensor_line, &poll_timeout);
        if (ret < 0) {
            fprintf(stderr, "Failed to poll sensor GPIO line: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (ret > 0) {
            sensor_value = gpiod_line_get_value(sensor_line);
            if (sensor_value == 0) {
                if (led_value == 0) {
                    gpiod_line_set_value(led_line, 1);
                    led_value = 1;
                    log_event("Object detected");
                }
            } else {
                if (led_value == 1) {
                    gpiod_line_set_value(led_line, 0);
                    led_value = 0;
                }
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

