#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define I2C_TIMEOUT 1000

#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_CH_LIST 0x4F
#define REG_ALS_RATE 0x4E
#define REG_PS_RATE 0x4D
#define REG_COMMAND 0x30
#define REG_PS1_DATA 0x18
#define REG_ALS_VIS_DATA 0x22

#define CMD_ALS_FORCE 0x06
#define CMD_PS_FORCE 0x07

#define ALS_RATE 100
#define PS_RATE 100

#define LOG_FILE "biometric_data.log"

int main(void)
{
    int i2c_handle;
    FILE *log_file;
    char log_line[100];
    char timestamp[20];
    uint8_t part_id;
    uint8_t hw_key;
    uint8_t ch_list;
    uint8_t als_rate;
    uint8_t ps_rate;
    uint8_t command;
    uint16_t ps1_data;
    uint16_t als_vis_data;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, I2C_TIMEOUT);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadDevice(i2c_handle, &part_id, 1) != 1)
    {
        fprintf(stderr, "Failed to read PART_ID register\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (part_id != 0x45)
    {
        fprintf(stderr, "Invalid PART_ID 0x%02X\n", part_id);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    hw_key = 0x17;
    if (i2cWriteDevice(i2c_handle, &hw_key, 1) != 1)
    {
        fprintf(stderr, "Failed to write HW_KEY register\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ch_list = 0x03;
    if (i2cWriteDevice(i2c_handle, &ch_list, 1) != 1)
    {
        fprintf(stderr, "Failed to write CH_LIST register\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    als_rate = ALS_RATE;
    if (i2cWriteDevice(i2c_handle, &als_rate, 1) != 1)
    {
        fprintf(stderr, "Failed to write ALS_RATE register\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ps_rate = PS_RATE;
    if (i2cWriteDevice(i2c_handle, &ps_rate, 1) != 1)
    {
        fprintf(stderr, "Failed to write PS_RATE register\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1)
    {
        command = CMD_ALS_FORCE;
        if (i2cWriteDevice(i2c_handle, &command, 1) != 1)
        {
            fprintf(stderr, "Failed to write COMMAND register\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (i2cReadDevice(i2c_handle, &ps1_data, 2) != 2)
        {
            fprintf(stderr, "Failed to read PS1_DATA register\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        command = CMD_PS_FORCE;
        if (i2cWriteDevice(i2c_handle, &command, 1) != 1)
        {
            fprintf(stderr, "Failed to write COMMAND register\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
