            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        command = CMD_PS_FORCE;
        if (i2cWriteDevice(i2c_handle, &command, 1) != 1)
        {
            fprintf(stderr, "Failed to write COMMAND register\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (i2cReadDevice(i2c_handle, &als_vis_data, 2) != 2)
        {
            fprintf(stderr, "Failed to read ALS_VIS_DATA register\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
