#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define TRIGGER_PULSE_US 10
#define TRIGGER_TIMEOUT_US 10000
#define ECHO_TIMEOUT_US 30000
#define POLL_INTERVAL_S 60
#define DISTANCE_MIN_CM 2
#define DISTANCE_MAX_CM 400
#define DISTANCE_WATER_CM 15

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line_event echo_event;
static struct gpiod_line_event_request echo_request;
static FILE *log_file;
static int running = 1;

static void log_distance(int distance_cm)
{
    char timestamp[256];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%FT%T%z", tm);
    fprintf(log_file, "%s: %d cm\n", timestamp, distance_cm);
    fflush(log_file);
}

static void log_error(const char *message)
{
    fprintf(log_file, "ERROR: %s\n", message);
    fflush(log_file);
}

static void log_timeout(const char *message)
{
    fprintf(log_file, "TIMEOUT: %s\n", message);
    fflush(log_file);
}

static void log_shutdown(void)
{
    fprintf(log_file, "SHUTDOWN\n");
    fflush(log_file);
}

static void handle_shutdown(int signum)
{
    running = 0;
}

static int init_gpio(void)
{
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        log_error("Failed to get trigger line");
        return -1;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        log_error("Failed to request trigger line");
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        log_error("Failed to get echo line");
        return -1;
    }

    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        log_error("Failed to request echo line");
        return -1;
    }

    return 0;
}

static void release_gpio(void)
{
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
}

static int init_log(void)
{
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return -1;
    }

    return 0;
}

static void release_log(void)
{
    fclose(log_file);
}

static int init_echo_event(void)
{
    int ret;

    ret = gpiod_line_event_request_both_edges(&echo_request, echo_line, 0);
    if (ret < 0) {
        log_error("Failed to request echo event");
        return -1;
    }

    return 0;
}

static void release_echo_event(void)
{
    gpiod_line_event_cancel(&echo_request);
}

static int measure_distance(void)
{
    int ret;
    struct timespec start_time, end_time;
    int64_t pulse_us;
    int distance_cm;

    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        log_error("Failed to set trigger line");
        return -1;
    }

    usleep(TRIGGER_PULSE_US);

    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        log_error("Failed to set trigger line");
        return -1;
    }

    ret = gpiod_line_event_read(&echo_request, &echo_event);
    if (ret < 0) {
        log_error("Failed to read echo event");
        return -1;
    }

    if (echo_event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        log_error("Echo event is not rising edge");
        return -1;
    }

    ret = clock_gettime(CLOCK_MONOTONIC, &start_time);
    if (ret < 0) {
        log_error("Failed to get start time");
        return -1;
    }

    ret = gpiod_line_event_read(&echo_request, &echo_event);
    if (ret < 0) {
        log_error("Failed to read echo event");
        return -1;
    }

    if (echo_event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        log_error("Echo event is not falling edge");
        return -1;
    }

    ret = clock_gettime(CLOCK_MONOTONIC, &end_time);
    if (ret < 0) {
        log_error("Failed to get end time");
        return -1;
    }

    pulse_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000;

    if (pulse_us < 0 || pulse_us > ECHO_TIMEOUT_US) {
        log_timeout("Echo pulse timeout");
        return -1;
    }

    distance_cm = (pulse_us * 34300) / (2 * 1000000);

    if (distance_cm < DISTANCE_MIN_CM || distance_cm > DISTANCE_MAX_CM) {
        log_error("Distance out of range");
        return -1;
    }

    return distance_cm;
}

int main(void)
{
    int ret;
    int distance_cm;

    ret = init_gpio();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    ret = init_log();
    if (ret < 0) {
        release_gpio();
        return EXIT_FAILURE;
    }

    ret = init_echo_event();
    if (ret < 0) {
        release_log();
        release_gpio();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_shutdown);
    signal(SIGTERM, handle_shutdown);

    while (running) {
        ret = gpiod_line_event_wait(&echo_request, TRIGGER_TIMEOUT_US);
        if (ret < 0) {
            log_timeout("Trigger timeout");
            continue;
        }

        distance_cm = measure_distance();
        if (distance_cm < 0) {
            continue;
        }

        log_distance(distance_cm);

        if (distance_cm <= DISTANCE_WATER_CM) {
            log_error("Time to water the plant!");
        }

        sleep(POLL_INTERVAL_S);
    }

    release_echo_event();
    release_log();
    release_gpio();
    log_shutdown();

    return EXIT_SUCCESS;
}

