#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define I2C_ID_REG 0x92
#define I2C_ENABLE_REG 0x80
#define I2C_ATIME_REG 0x81
#define I2C_WTIME_REG 0x83
#define I2C_PPULSE_REG 0x8E
#define I2C_CONTROL_REG 0xF1
#define I2C_CONFIG2_REG 0x90
#define I2C_RGB_REG 0x96
#define I2C_PROX_REG 0x9C

#define I2C_ID_VAL 0xAB
#define I2C_ENABLE_VAL 0x03
#define I2C_ATIME_VAL 0xDB
#define I2C_WTIME_VAL 0xF6
#define I2C_PPULSE_VAL 0x87
#define I2C_CONTROL_VAL 0x03
#define I2C_CONFIG2_VAL 0x01

#define PROX_THRESHOLD 200

#define LOG_FILE "color_proximity_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void close_i2c_handle(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
}

static void close_log_file(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void close_resources(void)
{
    close_i2c_handle();
    close_log_file();
}

static void sig_handler(int signum)
{
    close_resources();
    exit(EXIT_SUCCESS);
}

static int init_i2c_handle(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return -1;
    }

    return 0;
}

static int init_log_file(void)
{
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        return -1;
    }

    return 0;
}

static int init_sensor(void)
{
    int ret;

    ret = i2cWriteByteData(i2c_handle, I2C_ENABLE_REG, I2C_ENABLE_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_ENABLE_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_ATIME_REG, I2C_ATIME_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_ATIME_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_WTIME_REG, I2C_WTIME_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_WTIME_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_PPULSE_REG, I2C_PPULSE_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_PPULSE_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_CONTROL_REG, I2C_CONTROL_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_CONTROL_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_CONFIG2_REG, I2C_CONFIG2_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_CONFIG2_REG);
        return -1;
    }

    return 0;
}

static int read_sensor(void)
{
    int ret;
    uint8_t id;
    uint16_t rgb;
    uint8_t prox;
    struct timespec ts;

    ret = i2cReadByteData(i2c_handle, I2C_ID_REG, &id);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X\n", I2C_ID_REG);
        return -1;
    }

    if (id != I2C_ID_VAL) {
        fprintf(stderr, "Invalid sensor ID 0x%02X\n", id);
        return -1;
    }

    ret = i2cReadWordData(i2c_handle, I2C_RGB_REG, &rgb);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X\n", I2C_RGB_REG);
        return -1;
    }

    ret = i2cReadByteData(i2c_handle, I2C_PROX_REG, &prox);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X\n", I2C_PROX_REG);
        return -1;
    }

    if (prox > PROX_THRESHOLD) {
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, rgb, prox);
    }

    return 0;
}

int main(void)
{
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (init_i2c_handle() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    if (init_log_file() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        ret = read_sensor();
        if (ret < 0) {
            close_i2c_handle();
            if (init_i2c_handle() < 0) {
                close_resources();
                return EXIT_FAILURE;
            }

            if (init_sensor() < 0) {
                close_resources();
                return EXIT_FAILURE;
            }
        }

        gpioDelay(100000);
    }

    close_resources();
    return EXIT_SUCCESS;
}

