static void close_resources(void)
{
    close_i2c_handle();
    close_log_file();
}

static void sig_handler(int signum)
{
    close_resources();
    exit(EXIT_SUCCESS);
}

static int init_i2c_handle(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return -1;
    }

    return 0;
}

static int init_log_file(void)
{
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        return -1;
    }

    return 0;
}

static int init_sensor(void)
{
    int ret;

    ret = i2cWriteByteData(i2c_handle, I2C_ENABLE_REG, I2C_ENABLE_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_ENABLE_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_ATIME_REG, I2C_ATIME_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_ATIME_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_WTIME_REG, I2C_WTIME_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_WTIME_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_PPULSE_REG, I2C_PPULSE_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_PPULSE_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_CONTROL_REG, I2C_CONTROL_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_CONTROL_REG);
        return -1;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_CONFIG2_REG, I2C_CONFIG2_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", I2C_CONFIG2_REG);
        return -1;
    }

    return 0;
}

static int read_sensor(void)
{
    int ret;
    uint8_t id;
    uint16_t rgb;
    uint8_t prox;
    struct timespec ts;

    ret = i2cReadByteData(i2c_handle, I2C_ID_REG, &id);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X\n", I2C_ID_REG);
        return -1;
    }

    if (id != I2C_ID_VAL) {
        fprintf(stderr, "Invalid sensor ID 0x%02X\n", id);
        return -1;
    }

    ret = i2cReadWordData(i2c_handle, I2C_RGB_REG, &rgb);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X\n", I2C_RGB_REG);
        return -1;
    }

    ret = i2cReadByteData(i2c_handle, I2C_PROX_REG, &prox);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X\n", I2C_PROX_REG);
        return -1;
    }

    if (prox > PROX_THRESHOLD) {
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, rgb, prox);
    }

    return 0;
}

int main(void)
{
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (init_i2c_handle() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    if (init_log_file() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        ret = read_sensor();
        if (ret < 0) {
            close_i2c_handle();
            if (init_i2c_handle() < 0) {
                close_resources();
                return EXIT_FAILURE;
            }

            if (init_sensor() < 0) {
                close_resources();
                return EXIT_FAILURE;
            }
        }

        gpioDelay(100000);
    }

    close_resources();
    return EXIT_SUCCESS;
}
```

### Explanation:
The program uses the pigpio library to continuously read an Adafruit APDS9960 sensor over I2C bus 1 at address 0x39. On startup, it verifies the sensor ID register (0x92) equals 0xAB, then configures ENABLE (0x80) to 0x03, ATIME (0x81) to 0xDB, WTIME (0x83) to 0xF6, PPULSE (0x8E) to 0x87, CONTROL (0xF1) to 0x03, and CONFIG2 (0x90) to 0x01. Every 100 ms, it reads the 16-bit raw RGB color values from registers 0x96-0x9B and the 8-bit proximity value from register 0x9C, logging both with a timestamp to a CSV file named 'color_proximity_log.csv' only when proximity exceeds a threshold of 200. On I2C communication errors, it re-opens the bus and re-initializes the sensor rather than aborting. It handles SIGINT and SIGTERM for graceful shutdown, closing the I2C handle and the CSV file and releasing all pigpio resources. On any I2C communication error, it closes and reopens the I2C bus and fully re-initializes the sensor's configuration registers before resuming, rather than aborting the program.

