#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define I2C_PART_ID 0x00
#define I2C_MEAS_RATE0 0x08
#define I2C_COMMAND 0x47
#define I2C_PS_DATA0 0x24
#define I2C_PS_DATA1 0x25

#define MEAS_RATE0_100MS 0x01
#define COMMAND_RESET 0x00
#define COMMAND_START 0x03

#define BPM_MAX 255

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    int i2c_fd = -1;
    FILE *csv_fp = NULL;
    struct sigaction sa;
    struct timespec ts;
    uint8_t part_id;
    uint8_t meas_rate0;
    uint8_t command;
    uint16_t ps_data;
    uint8_t ps_data0;
    uint8_t ps_data1;
    uint8_t bpm;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Read PART_ID register
    if (read(i2c_fd, &part_id, 1) != 1) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    // Verify PART_ID
    if (part_id != 0x82) {
        fprintf(stderr, "Error: Invalid PART_ID 0x%02X\n", part_id);
        exit(EXIT_FAILURE);
    }

    // Set MEAS_RATE0 register
    meas_rate0 = MEAS_RATE0_100MS;
    if (write(i2c_fd, &meas_rate0, 1) != 1) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    // Issue reset/start command
    command = COMMAND_RESET;
    if (write(i2c_fd, &command, 1) != 1) {
        perror("write");
        exit(EXIT_FAILURE);
    }
    command = COMMAND_START;
    if (write(i2c_fd, &command, 1) != 1) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    // Open CSV file
    csv_fp = fopen("heartrate.csv", "w");
    if (csv_fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Read PS_DATA0 and PS_DATA1 registers
        if (read(i2c_fd, &ps_data0, 1) != 1) {
            perror("read");
            continue;
        }
        if (read(i2c_fd, &ps_data1, 1) != 1) {
            perror("read");
            continue;
        }

        // Combine PS_DATA0 and PS_DATA1
        ps_data = (ps_data1 << 8) | ps_data0;

        // Compute BPM
        bpm = ps_data / 100;
        if (bpm > BPM_MAX) {
            bpm = BPM_MAX;
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("clock_gettime");
            exit(EXIT_FAILURE);
        }

        // Write CSV line
        fprintf(csv_fp, "%ld.%09ld,%u\n", ts.tv_sec, ts.tv_nsec, bpm);
        fflush(csv_fp);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close I2C bus
    if (close(i2c_fd) < 0) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    // Close CSV file
    if (fclose(csv_fp) != 0) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }

    return 0;
}

