#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_PIN 17

#define SYSRANGE_START 0x00
#define RESULT_RANGE_STATUS 0x14
#define RESULT_INTERRUPT_STATUS 0x13
#define SYSTEM_INTERRUPT_CLEAR 0x0B

#define TIMEOUT_MS 100

#define LOG_FILE "distance_log.txt"

int main(void)
{
    int i2c_handle;
    FILE *log_file;
    char log_line[100];
    uint8_t data[14];
    uint16_t distance;
    time_t timestamp;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0)
    {
        fprintf(stderr, "failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(i2c_handle, SYSRANGE_START, 0x01) < 0)
    {
        fprintf(stderr, "failed to write to register 0x%02X\n", SYSRANGE_START);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL)
    {
        fprintf(stderr, "failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0)
    {
        fprintf(stderr, "failed to set pull-up on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, NULL) < 0)
    {
        fprintf(stderr, "failed to set alert function on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        if (gpioWaitForEdge(GPIO_PIN, PI_FALLING_EDGE, TIMEOUT_MS) < 0)
        {
            fprintf(stderr, "failed to wait for falling edge on GPIO %d\n", GPIO_PIN);
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        if (i2cReadI2CBlockData(i2c_handle, RESULT_INTERRUPT_STATUS, data, 1) < 0)
        {
            fprintf(stderr, "failed to read from register 0x%02X\n", RESULT_INTERRUPT_STATUS);
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        if ((data[0] & 0x01) == 0)
        {
            fprintf(stderr, "timeout waiting for interrupt\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        if (i2cReadI2CBlockData(i2c_handle, RESULT_RANGE_STATUS, data, 14) < 0)
        {
            fprintf(stderr, "failed to read from register 0x%02X\n", RESULT_RANGE_STATUS);
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        distance = (data[10] << 8) | data[11];

        if (i2cWriteByte(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        {
            fprintf(stderr, "failed to write to register 0x%02X\n", SYSTEM_INTERRUPT_CLEAR);
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        timestamp = time(NULL);
        snprintf(log_line, sizeof(log_line), "%ld,%d\n", timestamp, distance);
        fputs(log_line, log_file);
        fflush(log_file);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

