#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define SENSOR_1 17
#define SENSOR_2 18
#define LOG_FILE "obstacle_log.txt"

FILE *log_file;

void sigint_handler(int sig)
{
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1)
    {
        int sensor_1_value = gpioRead(SENSOR_1);
        int sensor_2_value = gpioRead(SENSOR_2);

        if (sensor_1_value < 0 || sensor_2_value < 0)
        {
            fprintf(stderr, "Failed to read sensor values\n");
            continue;
        }

        time_t current_time = time(NULL);
        struct tm *local_time = localtime(&current_time);
        char time_string[30];
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", local_time);

        fprintf(log_file, "%s, Sensor 1: %d, Sensor 2: %d\n", time_string, sensor_1_value, sensor_2_value);

        sleep(100);
    }

    return 0;
}

