code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_ADDR 0x60
#define I2C_BUS 1
#define PROX_REG 0x18
#define AMB_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3

static int i2cHandle = -1;
static FILE *logFile = NULL;

void sigHandler(int sig)
{
    if (sig == SIGINT)
    {
        if (i2cHandle >= 0)
        {
            i2cClose(i2cHandle);
        }
        if (logFile != NULL)
        {
            fclose(logFile);
        }
        gpioTerminate();
        exit(0);
    }
}

int main(void)
{
    int ret;
    uint16_t proxData, ambData;
    struct timespec ts;

    signal(SIGINT, sigHandler);

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0)
    {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    logFile = fopen(LOG_FILE, "w");
    if (logFile == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        ret = i2cReadWordData(i2cHandle, PROX_REG);
        if (ret < 0)
        {
            fprintf(stderr, "Failed to read proximity data\n");
            break;
        }
        proxData = (uint16_t)ret;

        ret = i2cReadWordData(i2cHandle, AMB_REG);
        if (ret < 0)
        {
            fprintf(stderr, "Failed to read ambient light data\n");
            break;
        }
        ambData = (uint16_t)ret;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(logFile, "%ld.%09ld, %d, %d\n", ts.tv_sec, ts.tv_nsec, proxData, ambData);

        gpioDelay(500000);
    }

    i2cClose(i2cHandle);
    fclose(logFile);
    gpioTerminate();

    return 0;
}

