### Instruction:
Write a C program for a Raspberry Pi 4 Model B that uses the pigpio library for both I2C communication and GPIO control to interface with a TDK InvenSense ICU-20201 ultrasonic Time-of-Flight sensor over I2C bus 1 at its default address 0x6A. Continuously read distance measurements every 50 ms, logging each reading with a timestamp to 'tof_log.txt', and turn on an LED connected to GPIO 17 whenever the measured distance falls below a configurable threshold, default 100 mm, passed as the first command-line argument. Verify the sensor's WHO_AM_I register during initialization, check all I2C read/write return codes, and handle sensor-absent or bus-error conditions gracefully without crashing. Ensure clean resource release of the I2C handle, GPIO, and pigpio library on all exit paths via a SIGINT handler.

### Response:
```
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VAL 0x20
#define DISTANCE_REG 0x02
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100

int main(int argc, char *argv[])
{
    int i2cHandle, threshold, distance, ledState;
    time_t timestamp;
    struct tm *timeInfo;
    char timeString[20];
    char logString[50];

    if (argc < 2)
    {
        threshold = DEFAULT_THRESHOLD;
    }
    else
    {
        threshold = atoi(argv[1]);
    }

    if (threshold < 0)
    {
        threshold = DEFAULT_THRESHOLD;
    }

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);

    if (i2cHandle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cReadByteData(i2cHandle, WHO_AM_I_REG) != WHO_AM_I_VAL)
    {
        fprintf(stderr, "Failed to verify WHO_AM_I register\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    FILE *logFile = fopen("tof_log.txt", "w");

    if (logFile == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        distance = i2cReadWordData(i2cHandle, DISTANCE_REG);

        if (distance < 0)
        {
            fprintf(stderr, "Failed to read distance\n");
            break;
        }

        timestamp = time(NULL);
        timeInfo = localtime(&timestamp);
        strftime(timeString, sizeof(timeString), "%Y-%m-%d %H:%M:%S", timeInfo);
        sprintf(logString, "%s, %d\n", timeString, distance);
        fputs(logString, logFile);
        fflush(logFile);

        if (distance < threshold)
        {
            ledState = gpioRead(LED_GPIO);
            gpioWrite(LED_GPIO, !ledState);
        }

        sleep(50 / 1000);
    }

    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}
