    if (handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1)
    {
        distance_lsb = i2cReadByteData(handle, OPT3101_REG_DISTANCE_LSB);
        if (distance_lsb < 0)
        {
            fprintf(stderr, "Failed to read distance LSB\n");
            break;
        }

        distance_msb = i2cReadByteData(handle, OPT3101_REG_DISTANCE_MSB);
        if (distance_msb < 0)
        {
            fprintf(stderr, "Failed to read distance MSB\n");
            break;
        }

        distance = (distance_msb << 8) | distance_lsb;

        ambient_lsb = i2cReadByteData(handle, OPT3101_REG_AMBIENT_LSB);
        if (ambient_lsb < 0)
        {
            fprintf(stderr, "Failed to read ambient LSB\n");
            break;
        }

        ambient_msb = i2cReadByteData(handle, OPT3101_REG_AMBIENT_MSB);
        if (ambient_msb < 0)
        {
            fprintf(stderr, "Failed to read ambient MSB\n");
            break;
        }

        ambient = (ambient_msb << 8) | ambient_lsb;

        error_flag = i2cReadByteData(handle, OPT3101_REG_ERROR_FLAG);
        if (error_flag < 0)
        {
            fprintf(stderr, "Failed to read error flag\n");
            break;
        }

        printf("Distance: %d mm, Ambient: %d lux, Error: %d\n", distance, ambient, error_flag);

        gpioDelay(500000);
    }

    i2cClose(handle);
    gpioTerminate();

