            fprintf(stderr, "Failed to read ambient LSB\n");
            break;
        }

        ambient_msb = i2cReadByteData(handle, OPT3101_REG_AMBIENT_MSB);
        if (ambient_msb < 0)
        {
            fprintf(stderr, "Failed to read ambient MSB\n");
            break;
        }

        ambient = (ambient_msb << 8) | ambient_lsb;

        error_flag = i2cReadByteData(handle, OPT3101_REG_ERROR_FLAG);
        if (error_flag < 0)
        {
            fprintf(stderr, "Failed to read error flag\n");
            break;
        }

        printf("Distance: %d mm, Ambient: %d lux, Error: %d\n", distance, ambient, error_flag);

        gpioDelay(500000);
    }

    i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
