#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_GPIO 17
#define BUZZER_GPIO 18

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *buzzer_line;

static void log_transition(int state)
{
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char buf[64];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tm);
    printf("%s: %s\n", buf, state ? "Obstacle detected" : "Obstacle removed");
    FILE *fp = fopen("obstacle_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", buf, state ? "Obstacle detected" : "Obstacle removed");
        fclose(fp);
    }
}

static void sensor_callback(struct gpiod_line *line, unsigned int offset,
                            unsigned int flags, void *data)
{
    int state = gpiod_line_get_value(line);
    log_transition(state);
    if (state)
        gpiod_line_set_value(buzzer_line, 1);
    else
        gpiod_line_set_value(buzzer_line, 0);
}

static void shutdown(int signum)
{
    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main(void)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        return 1;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        perror("Failed to request sensor line");
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0) < 0) {
        perror("Failed to request buzzer line");
        return 1;
    }

    if (gpiod_line_event_request(sensor_line, GPIOD_LINE_EVENT_RISING_EDGE | GPIOD_LINE_EVENT_FALLING_EDGE,
                                 sensor_callback, NULL) < 0) {
        perror("Failed to request sensor event");
        return 1;
    }

    signal(SIGINT, shutdown);
    signal(SIGTERM, shutdown);

    while (1)
        sleep(1);

    return 0;
}

