    gpioSetAlertFunc(GPIO_PIN, NULL);
    gpioSetMode(GPIO_PIN, GPIO_ALT);

    // Close log file
    close(log_file_handle);

    // Terminate pigpio library
    gpioTerminate();

    return EXIT_SUCCESS;
}

