#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x20
#define I2C_CMD 0x00
#define I2C_READ_LEN 2
#define I2C_WRITE_LEN 1
#define I2C_TIMEOUT 1000
#define SENSOR_DELAY_MS 100

static volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    int handle;
    int ret;
    uint8_t buf[I2C_READ_LEN];
    uint8_t cmd = I2C_CMD;
    FILE *fp;
    struct timespec ts;
    struct tm *tm;
    char timestamp[64];
    int distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "failed to open i2c bus\n");
        return 1;
    }

    fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "failed to open distance_log.csv\n");
        return 1;
    }

    signal(SIGINT, intHandler);

    while (keepRunning) {
        ret = i2cWriteDevice(handle, &cmd, I2C_WRITE_LEN);
        if (ret != I2C_WRITE_LEN) {
            fprintf(stderr, "failed to write to i2c bus\n");
            break;
        }

        ret = i2cReadDevice(handle, buf, I2C_READ_LEN);
        if (ret != I2C_READ_LEN) {
            fprintf(stderr, "failed to read from i2c bus\n");
            break;
        }

        distance = (buf[0] << 8) | buf[1];

        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(fp, "%s,%d\n", timestamp, distance);

        gpioDelay(SENSOR_DELAY_MS * 1000);
    }

    fclose(fp);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

