#define DEBOUNCE_MS 50
#define POLL_MS 10

FILE *log_file;

void log_event(int sensor, int state) {
    time_t now;
    struct tm *time_info;
    char time_str[20];
    char event_str[10];

    time(&now);
    time_info = gmtime(&now);
    strftime(time_str, sizeof(time_str), "%FT%TZ", time_info);

    if (state == 0) {
        strcpy(event_str, "DETECTED");
    } else {
        strcpy(event_str, "CLEARED");
    }

    fprintf(log_file, "%s,%d,%s\n", time_str, sensor, event_str);
    fflush(log_file);
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        gpioTerminate();
        fclose(log_file);
        exit(0);
    }
}

int main() {
    int sensor_1_state = 0;
    int sensor_2_state = 0;
    int sensor_1_last_state = 0;
    int sensor_2_last_state = 0;
    int sensor_1_debounce_count = 0;
    int sensor_2_debounce_count = 0;
    int sensor_1_debounce_threshold = DEBOUNCE_MS / POLL_MS;
    int sensor_2_debounce_threshold = DEBOUNCE_MS / POLL_MS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for sensor 2\n");
        gpioTerminate();
        return 1;
    }

