#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define I2C_TIMEOUT_MS 50

#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

#define CSV_FILE "distance_log.csv"

int i2c_read_reg(int fd, uint8_t reg) {
    int ret;
    uint8_t buf[2];

    buf[0] = reg;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to the i2c bus: %s\n", strerror(errno));
        return -1;
    }

    ret = read(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to read from the i2c bus: %s\n", strerror(errno));
        return -1;
    }

    return buf[0] << 8 | buf[1];
}

int main(void) {
    int fd;
    int ret;
    uint8_t buf[1];
    uint16_t distance;
    struct timespec ts;
    FILE *csv_file;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set i2c address: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,distance_mm\n");

    while (true) {
        buf[0] = 0x01;
        ret = write(fd, buf, 1);
        if (ret != 1) {
            fprintf(stderr, "Failed to write to the i2c bus: %s\n", strerror(errno));
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += I2C_TIMEOUT_MS / 1000;
        ts.tv_nsec += (I2C_TIMEOUT_MS % 1000) * 1000000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }

        while (true) {
            ret = i2c_read_reg(fd, MEAS_STATUS);
            if (ret < 0) {
                break;
            }

            if (ret & 0x01) {
                break;
            }

            ret = clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL);
            if (ret == EINTR) {
                continue;
            } else if (ret != 0) {
                fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
                break;
            }
        }

        if (ret < 0) {
            break;
        }

        distance = i2c_read_reg(fd, DIST_HIGH);
        if (distance < 0) {
            break;
        }

        fprintf(csv_file, "%ld.%09ld,%d\n", ts.tv_sec, ts.tv_nsec, distance);
    }

    fclose(csv_file);
    close(fd);

    return EXIT_SUCCESS;
}

