    if (i2cHandle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(i2cHandle, I2C_SOFT_RESET_REG, 0x00) < 0)
    {
        fprintf(stderr, "Failed to write to I2C bus\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if (gpioDelay(10000) < 0)
    {
        fprintf(stderr, "Failed to delay\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(i2cHandle, I2C_START_RANGING_REG, 0x00) < 0)
