#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUZZER_GPIO 22
#define SENSOR_I2C_ADDR 0x29
#define SOFT_RESET_REG 0x0000
#define I2C_SLAVE_ADDR_REG 0x0001
#define SYSTEM_MODE_START_REG 0x0007
#define RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM_REG 0x0096
#define SOFT_RESET_VAL 0x0001
#define I2C_SLAVE_ADDR_VAL 0x0029
#define SYSTEM_MODE_START_VAL 0x0007
#define RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM_VAL 0x0096
#define DISTANCE_THRESHOLD_MM 100
#define SENSOR_READ_INTERVAL_MS 500

static volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    int handle;
    int distance;
    int buzzerState = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    handle = i2cOpen(1, SENSOR_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (i2cWriteWordData(handle, SOFT_RESET_REG, SOFT_RESET_VAL) < 0) {
        fprintf(stderr, "Failed to write to SOFT_RESET register\n");
        return 1;
    }

    if (i2cWriteWordData(handle, I2C_SLAVE_ADDR_REG, I2C_SLAVE_ADDR_VAL) < 0) {
        fprintf(stderr, "Failed to write to I2C_SLAVE_ADDR register\n");
        return 1;
    }

    if (i2cWriteWordData(handle, SYSTEM_MODE_START_REG, SYSTEM_MODE_START_VAL) < 0) {
        fprintf(stderr, "Failed to write to SYSTEM_MODE_START register\n");
        return 1;
    }

    if (i2cWriteWordData(handle, RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM_REG, RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM_VAL) < 0) {
