#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

#define TRIGGER 23
#define ECHO 24
#define SERVO 17
#define SPEED_OF_SOUND 343
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define MAX_ANGLE 90
#define MIN_ANGLE -90
#define MAX_PULSE 2000
#define MIN_PULSE 1000
#define MAX_TIMEOUT 50
#define SENSOR_DATA_LOG "sensor_data.log"

int main(int argc, char *argv[])
{
    int rc;
    int servo_pulse;
    int distance;
    int timeout;
    int angle;
    struct timespec ts;
    FILE *fp;

    rc = gpioInitialise();
    if (rc < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    fp = fopen(SENSOR_DATA_LOG, "a");
    if (fp == NULL)
    {
        fprintf(stderr, "Failed to open %s\n", SENSOR_DATA_LOG);
        gpioTerminate();
        return 1;
    }

    gpioSetSignalFunc(SIGINT, NULL);
    gpioSetSignalFunc(SIGTERM, NULL);

    while (1)
    {
        gpioWrite(TRIGGER, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIGGER, PI_LOW);

        timeout = 0;
        while (gpioRead(ECHO) == PI_LOW && timeout < MAX_TIMEOUT)
        {
            timeout++;
            gpioDelay(1);
        }

        if (timeout == MAX_TIMEOUT)
        {
            distance = -1;
        }
        else
        {
            ts.tv_sec = 0;
            ts.tv_nsec = 0;
            gpioTick(0, &ts);
            while (gpioRead(ECHO) == PI_HIGH)
            {
                gpioTick(0, &ts);
            }
            distance = (ts.tv_nsec / 1000000) * SPEED_OF_SOUND / 2;
        }

        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE)
        {
            angle = (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_ANGLE;
            servo_pulse = (angle - MIN_ANGLE) * (MAX_PULSE - MIN_PULSE) / (MAX_ANGLE - MIN_ANGLE) + MIN_PULSE;
            gpioServo(SERVO, servo_pulse);
            fprintf(fp, "%d,%d\n", distance, angle);
            fflush(fp);
        }

        gpioDelay(200000);
    }

    gpioTerminate();
    fclose(fp);

    return 0;
}

