#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 23
#define ECHO 24
#define LOG_FILE "distance_log.txt"
#define LOG_INTERVAL 200000
#define MAX_TIMEOUT 60000
#define MIN_PULSE 100
#define MAX_PULSE 30000
#define SPEED_OF_SOUND 0.0343

static FILE *log_file;
static int gpio_handle;
static int alert_handle;
static int rising_tick;
static int falling_tick;

static void log_distance(int distance)
{
    time_t now;
    struct tm *time_info;
    char time_string[20];

    now = time(NULL);
    time_info = localtime(&now);
    strftime(time_string, sizeof(time_string), "%FT%T%z", time_info);

    fprintf(log_file, "%s,%d\n", time_string, distance);
    fflush(log_file);
}

static void alert_callback(int gpio, int level, uint32_t tick)
{
    int pulse_width;

    if (level == 1) {
        rising_tick = tick;
    } else {
        falling_tick = tick;
        pulse_width = falling_tick - rising_tick;
        if (pulse_width < MIN_PULSE) {
            fprintf(stderr, "Warning: pulse width %d us is too short\n", pulse_width);
        } else if (pulse_width > MAX_PULSE) {
            fprintf(stderr, "Warning: pulse width %d us is too long\n", pulse_width);
        } else {
            log_distance((int)(pulse_width * SPEED_OF_SOUND / 2));
        }
    }
}

static void signal_handler(int signum)
{
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main(void)
{
    int rc;

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file %s\n", LOG_FILE);
        return 1;
    }

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: failed to initialize pigpio\n");
        return 1;
    }

    gpio_handle = gpioSetMode(TRIG, PI_OUTPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d mode\n", TRIG);
        return 1;
    }

    gpio_handle = gpioSetMode(ECHO, PI_INPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d mode\n", ECHO);
        return 1;
    }

    gpio_handle = gpioSetPullUpDown(ECHO, PI_PUD_DOWN);
    if (gpio_handle < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d pull-down\n", ECHO);
        return 1;
    }

    alert_handle = gpioSetAlertFuncEx(ECHO, alert_callback);
    if (alert_handle < 0) {
        fprintf(stderr, "Error: failed to set alert callback\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        gpioWrite(TRIG, 1);
        time_sleep(0.00001);
        gpioWrite(TRIG, 0);
        if (gpioWaitForAlert(ECHO, MAX_TIMEOUT) < 0) {
            fprintf(stderr, "Warning: timeout waiting for ECHO\n");
        }
        time_sleep(LOG_INTERVAL / 1000000.0);
    }

    return 0;
}

