#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <vl53l1x_api.h>

#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define SERVO_FREQ 50
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define SERVO_OPEN 1000
#define SERVO_CLOSED 2000
#define DISTANCE_MIN 50
#define DISTANCE_MAX 60
#define LOG_FILE "parking_log.txt"

VL53L1X_Dev_t dev;
VL53L1X_RangingMeasurementData_t data;

FILE *log_file;

int servo_pulse_width;

void log_distance(int distance)
{
    time_t now;
    struct tm *time_info;
    char time_string[20];

    time(&now);
    time_info = localtime(&now);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s: %d\n", time_string, distance);
    fflush(log_file);
}

void log_gate_state(bool open)
{
    time_t now;
    struct tm *time_info;
    char time_string[20];

    time(&now);
    time_info = localtime(&now);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s: %s\n", time_string, open ? "OPEN" : "CLOSED");
    fflush(log_file);
}

void handle_interrupt(int gpio, int level, uint32_t tick)
{
    if (level == 1)
    {
        VL53L1X_GetRangingMeasurementData(&dev, &data);
        if (data.RangeStatus == 0)
        {
            log_distance(data.RangeMilliMeter);
            if (data.RangeMilliMeter < DISTANCE_MIN)
            {
                servo_pulse_width = SERVO_OPEN;
            }
            else if (data.RangeMilliMeter > DISTANCE_MAX)
            {
                servo_pulse_width = SERVO_CLOSED;
            }
        }
    }
}

void handle_signal(int signal)
{
    VL53L1X_StopMeasurement(&dev);
    VL53L1X_ClearInterrupt(&dev);
    VL53L1X_DataInit(&dev);
    VL53L1X_SetDistanceMode(&dev, VL53L1X_DISTANCEMODE_LONG);
    VL53L1X_SetMeasurementTimingBudgetMicroSeconds(&dev, 100000);
    VL53L1X_StartMeasurement(&dev);
    gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ);
    gpioSetPWMrange(SERVO_PIN, 20000);
    gpioPWM(SERVO_PIN, servo_pulse_width);
    gpioSetAlertFunc(INTERRUPT_PIN, handle_interrupt);
    gpioSetSignalFunc(SIGINT, handle_signal);
    gpioSetSignalFunc(SIGTERM, handle_signal);
}

int main(int argc, char *argv[])
{
    int model_id;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (VL53L1X_Init(&dev, 1) != 0)
    {
        fprintf(stderr, "Failed to initialize VL53L1X\n");
        return 1;
    }

    if (VL53L1X_GetDeviceInfo(&dev, &model_id) != 0)
    {
        fprintf(stderr, "Failed to get device info\n");
        return 1;
    }

    if (model_id != 0xEACC)
    {
        fprintf(stderr, "Invalid device model ID\n");
        return 1;
    }

    if (VL53L1X_SetDistanceMode(&dev, VL53L1X_DISTANCEMODE_LONG) != 0)
    {
        fprintf(stderr, "Failed to set distance mode\n");
        return 1;
    }

    if (VL53L1X_SetMeasurementTimingBudgetMicroSeconds(&dev, 100000) != 0)
    {
        fprintf(stderr, "Failed to set measurement timing budget\n");
        return 1;
    }

    if (VL53L1X_StartMeasurement(&dev) != 0)
    {
        fprintf(stderr, "Failed to start measurement\n");
        return 1;
    }

    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set shutdown pin mode\n");
        return 1;
    }

    if (gpioWrite(SHUTDOWN_PIN, PI_HIGH) != 0)
    {
        fprintf(stderr, "Failed to set shutdown pin high\n");
        return 1;
    }

    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set interrupt pin mode\n");
        return 1;
    }

    if (gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP) != 0)
    {
        fprintf(stderr, "Failed to set interrupt pin pull-up\n");
        return 1;
    }

    if (gpioSetAlertFunc(INTERRUPT_PIN, handle_interrupt) != 0)
    {
        fprintf(stderr, "Failed to set interrupt pin alert function\n");
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set servo pin mode\n");
        return 1;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ) != 0)
    {
        fprintf(stderr, "Failed to set servo pin frequency\n");
        return 1;
    }

    if (gpioSetPWMrange(SERVO_PIN, 20000) != 0)
    {
        fprintf(stderr, "Failed to set servo pin range\n");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    servo_pulse_width = SERVO_CLOSED;
    gpioPWM(SERVO_PIN, servo_pulse_width);
    log_gate_state(false);

    gpioSetSignalFunc(SIGINT, handle_signal);
    gpioSetSignalFunc(SIGTERM, handle_signal);

    while (true)
    {
        gpioDelay(1000000);
    }

    return 0;
}
