        }

        if (gpio_led_time.tv_sec >= gpio_led_time.tv_sec + gpio_led_delay)
        {
            if (gpio_led_state == gpio_led_state_on)
            {
                if (gpioWrite(gpio_handle, gpio_led_pin, gpio_led_pin_clear) < 0)
                {
                    fprintf(stderr, "Error: Unable to clear GPIO pin %d\n", gpio_led_pin);
                    fclose(gpio_led_log);
                    gpioTerminate();
                    i2cClose(i2c_handle);
                    return EXIT_FAILURE;
                }

                gpio_led_state = gpio_led_state_off;
            }
            else if (gpio_led_state == gpio_led_state_off)
            {
                if (gpioWrite(gpio_handle, gpio_led_pin, gpio_led_pin_set) < 0)
                {
                    fprintf(stderr, "Error: Unable to set GPIO pin %d\n", gpio_led_pin);
                    fclose(gpio_led_log);
                    gpioTerminate();
                    i2cClose(i2c_handle);
                    return EXIT_FAILURE;
                }

                gpio_led_state = gpio_led_state_on;
            }
            else if (gpio_led_state == gpio_led_state_toggle)
            {
