                    fclose(gpio_led_log);
                    gpioTerminate();
                    i2cClose(i2c_handle);
                    return EXIT_FAILURE;
                }

                gpio_led_state = gpio_led_state_on;
            }
        }
    }

    fclose(gpio_led_log);
    gpioTerminate();
    i2cClose(i2c_handle);

    return EXIT_SUCCESS;
