#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define SPEED_OF_SOUND 343
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum)
{
    sigint_received = 1;
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct gpiod_line_request trigger_req, echo_req;
    struct timespec trigger_start, trigger_end, echo_start, echo_end;
    struct tm *timestamp;
    char timestamp_str[32];
    FILE *log_file;
    int distance, pulse_width;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the trigger line as output
    memset(&trigger_req, 0, sizeof(trigger_req));
    trigger_req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    trigger_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE;
    trigger_req.default_values[0] = 0;
    trigger_req.consumer = "trigger";
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(trigger_line, &trigger_req, 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the echo line as input
    memset(&echo_req, 0, sizeof(echo_req));
    echo_req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    echo_req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE;
    echo_req.default_values[0] = 0;
    echo_req.consumer = "echo";
    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(echo_line, &echo_req, 0) < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!sigint_received) {
        // Trigger the sensor
        clock_gettime(CLOCK_MONOTONIC, &trigger_start);
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for the echo rising edge
        if (gpiod_line_event_wait(echo_line, &echo_start, 30000000) < 0) {
            if (errno == ETIMEDOUT) {
                fprintf(stderr, "Echo timeout\n");
            } else {
                fprintf(stderr, "Echo event wait failed: %s\n", strerror(errno));
            }
            continue;
        }

        // Measure the echo pulse width
        if (gpiod_line_event_wait(echo_line, &echo_end, 30000000) < 0) {
            if (errno == ETIMEDOUT) {
                fprintf(stderr, "Echo timeout\n");
            } else {
                fprintf(stderr, "Echo event wait failed: %s\n", strerror(errno));
            }
            continue;
        }

        // Compute the distance
        pulse_width = (echo_end.tv_nsec - echo_start.tv_nsec) / 1000;
        distance = (pulse_width * SPEED_OF_SOUND) / (2 * 1000000);

        // Check the distance
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %d cm\n", distance);
            continue;
        }

        // Get the current time
        clock_gettime(CLOCK_REALTIME, &trigger_end);
        timestamp = gmtime(&trigger_end.tv_sec);
        if (!timestamp) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            continue;
        }
        strftime(timestamp_str, sizeof(timestamp_str), "%FT%TZ", timestamp);

        // Log the distance
        fprintf(log_file, "%s: %d cm\n", timestamp_str, distance);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

