#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TRIG 17
#define ECHO 18
#define LOG_FILE "distance_log.txt"

static int isr_count = 0;
static int isr_start = 0;
static int isr_end = 0;
static FILE *log_file;

static void isr_callback(int gpio, int level, uint32_t tick)
{
    if (level == 0) {
        isr_start = tick;
    } else {
        isr_end = tick;
        isr_count++;
    }
}

static void sig_handler(int signum)
{
    gpioSetISRFunc(ECHO, 0, 0, NULL);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[])
{
    int rc;
    int pulse_width;
    int distance;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    rc = gpioSetMode(TRIG, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(TRIG) failed: %s\n", gpioErrMsg(rc));
        gpioTerminate();
        return 1;
    }

    rc = gpioSetMode(ECHO, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(ECHO) failed: %s\n", gpioErrMsg(rc));
        gpioTerminate();
        return 1;
    }

    rc = gpioSetPullUpDown(ECHO, PI_PUD_OFF);
    if (rc != 0) {
        fprintf(stderr, "gpioSetPullUpDown(ECHO) failed: %s\n", gpioErrMsg(rc));
        gpioTerminate();
        return 1;
    }

    rc = gpioSetAlertFuncEx(ECHO, isr_callback);
    if (rc != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(ECHO) failed: %s\n", gpioErrMsg(rc));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        rc = gpioWrite(TRIG, PI_ON);
        if (rc != 0) {
            fprintf(stderr, "gpioWrite(TRIG) failed: %s\n", gpioErrMsg(rc));
            break;
        }

        time_sleep(0.00001);

        rc = gpioWrite(TRIG, PI_OFF);
        if (rc != 0) {
            fprintf(stderr, "gpioWrite(TRIG) failed: %s\n", gpioErrMsg(rc));
            break;
        }

        while (isr_count == 0) {
            time_sleep(0.001);
        }

        pulse_width = isr_end - isr_start;
        if (pulse_width < 58 || pulse_width > 25000000) {
            fprintf(stderr, "invalid pulse width: %d\n", pulse_width);
            break;
        }

        distance = pulse_width * 343 / 2000000;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld %d\n", ts.tv_sec, ts.tv_nsec, distance);

        isr_count = 0;
        time_sleep(1);
    }

    gpioSetISRFunc(ECHO, 0, 0, NULL);
    fclose(log_file);
    gpioTerminate();
    return 1;
}

