#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TRIG 17
#define ECHO 18
#define LOG_FILE "distance_log.txt"

static int isr_count = 0;
static int isr_start = 0;
static int isr_end = 0;
static FILE *log_file;

static void isr_callback(int gpio, int level, uint32_t tick)
{
    if (level == 0) {
        isr_start = tick;
    } else {
        isr_end = tick;
        isr_count++;
    }
}

static void sig_handler(int signum)
{
    gpioSetISRFunc(ECHO, 0, 0, NULL);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[])
