    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        rc = gpioWrite(TRIG, PI_ON);
        if (rc != 0) {
            fprintf(stderr, "gpioWrite(TRIG) failed: %s\n", gpioErrMsg(rc));
            break;
        }

        time_sleep(0.00001);

        rc = gpioWrite(TRIG, PI_OFF);
        if (rc != 0) {
            fprintf(stderr, "gpioWrite(TRIG) failed: %s\n", gpioErrMsg(rc));
            break;
        }

        while (isr_count == 0) {
            time_sleep(0.001);
        }

        pulse_width = isr_end - isr_start;
        if (pulse_width < 58 || pulse_width > 25000000) {
            fprintf(stderr, "invalid pulse width: %d\n", pulse_width);
