#define REG_TIMEOUT 0x0019
#define REG_START_RANGING 0x0020
#define REG_DISTANCE 0x0014
#define REG_STATUS 0x0016

#define CONTINUOUS_MODE 0x00
#define NO_TIMEOUT 0x00
#define START_RANGING 0x01

#define STATUS_OK 0x01

static int i2cHandle;

static void sigHandler(int sig)
{
    syslog(LOG_INFO, "Caught signal %d, cleaning up...", sig);
    i2cClose(i2cHandle);
    gpioSetMode(I2C_XSHUT, PI_INPUT);
