        syslog(LOG_ERR, "Failed to initialise pigpio");
        return EXIT_FAILURE;
    }

    gpioSetMode(I2C_XSHUT, PI_OUTPUT);
    gpioWrite(I2C_XSHUT, 0);

    if ((i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0)
