#define GPIO_LED 17
#define NUM_READINGS 10

int i2cHandle;
int ledState = 0;
int readings[NUM_READINGS];
int readIndex = 0;

void initSensor() {
    // Set default configuration
    uint8_t data[2] = {0x00, 0x00};
    if (i2cWriteDevice(i2cHandle, data, 2) < 0) {
        fprintf(stderr, "Error writing to sensor\n");
        exit(1);
    }

    // Enable signal rate check
    data[0] = 0x01;
    data[1] = 0x01;
    if (i2cWriteDevice(i2cHandle, data, 2) < 0) {
        fprintf(stderr, "Error writing to sensor\n");
        exit(1);
    }

    // Configure cross-talk compensation
    data[0] = 0x06;
    data[1] = 0x09;
    if (i2cWriteDevice(i2cHandle, data, 2) < 0) {
        fprintf(stderr, "Error writing to sensor\n");
        exit(1);
    }

    // Start ranging
    data[0] = 0x00;
    data[1] = 0x01;
    if (i2cWriteDevice(i2cHandle, data, 2) < 0) {
        fprintf(stderr, "Error writing to sensor\n");
        exit(1);
    }
}

void readDistance() {
    uint8_t data[2] = {0x01, 0x00};
    if (i2cWriteDevice(i2cHandle, data, 2) < 0) {
        fprintf(stderr, "Error writing to sensor\n");
        return;
    }

    uint8_t distance[2];
    if (i2cReadDevice(i2cHandle, distance, 2) < 0) {
        fprintf(stderr, "Error reading from sensor\n");
        return;
    }

    int distanceInMm = (distance[0] << 8) | distance[1];
    readings[readIndex] = distanceInMm;
    readIndex = (readIndex + 1) % NUM_READINGS;

    if (distanceInMm < 200) {
        ledState = 1;
    } else {
        ledState = 0;
    }
    gpioWrite(GPIO_LED, ledState);
}

void sigintHandler(int sig) {
    gpioWrite(GPIO_LED, 0);
    i2cClose(i2cHandle);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    initSensor();

    signal(SIGINT, sigintHandler);

    while (1) {
        readDistance();
        sleep(50);
    }

    return 0;
}
