#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>

#define TRIGGER 23
#define ECHO 24
#define SPEAKER 18
#define MIN_DIST 2
#define MAX_DIST 200
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define DUTY_CYCLE 50

int running = 1;

void stop(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);
    gpioSetMode(SPEAKER, PI_OUTPUT);

    gpioSetPullUpDown(TRIGGER, PI_PUD_OFF);
    gpioSetPullUpDown(ECHO, PI_PUD_OFF);
    gpioSetPullUpDown(SPEAKER, PI_PUD_OFF);

    gpioSetAlertFunc(ECHO, NULL);

    gpioHardwarePWM(SPEAKER, 0, 0);

    signal(SIGINT, stop);
    signal(SIGTERM, stop);

    while (running) {
        gpioTrigger(TRIGGER, 10, 1);

        while (gpioRead(ECHO) == PI_OFF) {
            if (!running) {
                break;
            }
        }

        if (!running) {
            break;
        }

        uint32_t start = gpioTick();

        while (gpioRead(ECHO) == PI_ON) {
            if (!running) {
                break;
            }
        }

        if (!running) {
            break;
        }

        uint32_t end = gpioTick();

        uint32_t diff = end - start;

        if (diff > 200000) {
            continue;
        }

        double distance = diff / 58.0;

        if (distance < MIN_DIST || distance > MAX_DIST) {
            continue;
        }

        double frequency = MIN_FREQ * exp(distance / 50.0);

        gpioHardwarePWM(SPEAKER, frequency, DUTY_CYCLE);
    }

    gpioHardwarePWM(SPEAKER, 0, 0);

    gpioTerminate();

    return 0;
}

