#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DIST 5
#define MAX_DIST 50
#define MIN_FREQ 200
#define MAX_FREQ 2000

int running = 1;

void sigint_handler(int sig)
{
    running = 0;
}

int main(int argc, char *argv[])
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, PI_LOW);

    signal(SIGINT, sigint_handler);

    while (running)
    {
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        uint32_t start = gpioTick();
        uint32_t end = start;

        while (gpioRead(ECHO_PIN) == PI_LOW && end - start < 100000)
        {
            end = gpioTick();
        }

        uint32_t pulse_width = end - start;

        if (pulse_width >= 100000)
        {
            fprintf(stderr, "Sensor read timed out\n");
            continue;
        }

        float distance = pulse_width / 58.0;

        if (distance < MIN_DIST || distance > MAX_DIST)
        {
            fprintf(stderr, "Invalid distance: %f\n", distance);
            continue;
        }

        float frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
        frequency = frequency < MIN_FREQ ? MIN_FREQ : frequency > MAX_FREQ ? MAX_FREQ : frequency;

        gpioHardwarePWM(BUZZER_PIN, (uint32_t)frequency, 500000);

        printf("Distance: %f cm, Frequency: %f Hz\n", distance, frequency);

        gpioDelay(10000);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_PULSE_WIDTH 10
#define MEASUREMENT_TIMEOUT 50
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_DISTANCE_WARNING 10

static volatile sig_atomic_t exit_flag = 0;

static void handle_sigint(int signum)
{
    exit_flag = 1;
}

int main(void)
{
    int rc;
    uint32_t pulse_width;
    double distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(TRIGGER_PULSE_WIDTH);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        pulse_width = gpioWaitPulse(ECHO_PIN, PI_HIGH, MEASUREMENT_TIMEOUT);

        if (pulse_width < 0) {
            fprintf(stderr, "Echo pulse measurement timeout\n");
            continue;
        }

        distance = pulse_width / 2.0 / 29.1;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance);

            if (distance < MIN_DISTANCE_WARNING) {
                printf("Too close!\n");
            }
        }

        gpioDelay(500000);
    }

    rc = gpioTerminate();

    if (rc < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

