Write a C program for a Raspberry Pi 4 Model B that uses the standard Linux I2C ioctl interface (no third-party C libraries) to interface with a Silicon Labs Si1175 ambient light and proximity sensor at its default I2C address 0x60. Read the 16-bit visible ambient light value from registers 0x22 (low byte) and 0x23 (high byte) every 5 seconds. Log each reading with an ISO-8601 timestamp to a CSV file named 'proximity_log.csv' with the header row 'timestamp,als_visible'. Check every I2C open/read/write call for errors, handling both sensor-absent conditions and bus-error paths without terminating unexpectedly, and cleanly release the I2C file descriptor and the log file on all exit paths, including those triggered by SIGINT and SIGTERM. Include <stdint.h> for the uint8_t and uint16_t types used to hold the register bytes and the combined light reading.

### Response:
```
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define I2C_REG_ALS_VIS_LOW 0x22
#define I2C_REG_ALS_VIS_HIGH 0x23
#define I2C_READ_LEN 2
#define LOG_FILE "proximity_log.csv"
#define LOG_HEADER "timestamp,als_visible"
#define LOG_FMT "%s,%d\n"
#define LOG_FMT_LEN 25
#define LOG_BUF_LEN 100
#define SLEEP_TIME 5

int i2c_fd = -1;
FILE *log_fp = NULL;

void cleanup(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
}

void sig_handler(int sig)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    uint8_t buf[I2C_READ_LEN];
    uint16_t als_vis;
    char log_buf[LOG_BUF_LEN];
    time_t now;
    struct tm *now_tm;
    char *now_str;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_fp = fopen(LOG_FILE, "w");
    if (log_fp == NULL) {
        perror("fopen");
        cleanup();
        exit(EXIT_FAILURE);
    }

    fprintf(log_fp, "%s\n", LOG_HEADER);

    while (1) {
        if (read(i2c_fd, buf, I2C_READ_LEN) != I2C_READ_LEN) {
            perror("read");
            cleanup();
            exit(EXIT_FAILURE);
        }

        als_vis = (buf[1] << 8) | buf[0];

        now = time(NULL);
        now_tm = localtime(&now);
        now_str = asctime(now_tm);
        now_str[strlen(now_str) - 1] = '\0';

        snprintf(log_buf, LOG_BUF_LEN, LOG_FMT, now_str, als_vis);
        fprintf(log_fp, "%s", log_buf);
        fflush(log_fp);

        sleep(SLEEP_TIME);
    }

    cleanup();
    exit(EXIT_SUCCESS);
}
