#define I2C_PS1_LO 0x18
#define I2C_PS1_HI 0x19
#define LOG_FILE "si1120_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;
    uint8_t part_id;
    uint16_t als, ps1;
    struct timespec ts;
    char buf[64];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }
    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, I2C_TIMEOUT)) < 0) {
        fprintf(stderr, "i2cOpen failed\n");
