        fprintf(stderr, "i2cWriteByteData failed\n");
        return EXIT_FAILURE;
    }
    ret = i2cReadByteData(i2c_handle, I2C_PART_ID, &part_id);
    if (ret < 0) {
        fprintf(stderr, "i2cReadByteData failed\n");
        return EXIT_FAILURE;
