#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER 4
#define ECHO 17
#define SERVO 18

#define TRIGGER_DELAY 10
#define MEASURE_DELAY 100

#define MIN_DISTANCE 20
#define MAX_DISTANCE 200

#define MIN_PULSE 500
#define MAX_PULSE 2500

#define MIN_ANGLE 0
#define MAX_ANGLE 180

static volatile int running = 1;

static void sigint_handler(int signum)
{
    running = 0;
}

int main(int argc, char *argv[])
{
    int rc;
    int distance;
    int pulse;
    int angle;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    rc = gpioSetMode(TRIGGER, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER) failed: %s\n", gpioErrMsg(rc));
        goto error;
    }

    rc = gpioSetMode(ECHO, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(ECHO) failed: %s\n", gpioErrMsg(rc));
        goto error;
    }

    rc = gpioSetMode(SERVO, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(SERVO) failed: %s\n", gpioErrMsg(rc));
        goto error;
    }

    rc = gpioSetPullUpDown(ECHO, PI_PUD_DOWN);
    if (rc != 0) {
        fprintf(stderr, "gpioSetPullUpDown(ECHO) failed: %s\n", gpioErrMsg(rc));
        goto error;
    }

    rc = gpioSetAlertFunc(ECHO, NULL);
    if (rc != 0) {
        fprintf(stderr, "gpioSetAlertFunc(ECHO) failed: %s\n", gpioErrMsg(rc));
        goto error;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        rc = gpioTrigger(TRIGGER, TRIGGER_DELAY, 1);
        if (rc != 0) {
            fprintf(stderr, "gpioTrigger(TRIGGER) failed: %s\n", gpioErrMsg(rc));
            goto error;
        }

        rc = gpioWaitAlert(ECHO, MEASURE_DELAY);
        if (rc < 0) {
            fprintf(stderr, "gpioWaitAlert(ECHO) failed: %s\n", gpioErrMsg(rc));
            goto error;
        }

        if (rc == 0) {
            distance = -1;
        } else {
            distance = gpioTick();
            rc = gpioRead(ECHO);
            if (rc != 0) {
                fprintf(stderr, "gpioRead(ECHO) failed: %s\n", gpioErrMsg(rc));
                goto error;
            }
            if (rc == 1) {
                distance = -1;
            } else {
                distance = gpioTick() - distance;
                distance = distance / 1000000 * 34000 / 2;
            }
        }

        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            pulse = MIN_PULSE + (MAX_PULSE - MIN_PULSE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
            angle = MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        } else {
            pulse = MIN_PULSE;
            angle = MIN_ANGLE;
        }

        rc = gpioServo(SERVO, pulse);
        if (rc != 0) {
            fprintf(stderr, "gpioServo(SERVO) failed: %s\n", gpioErrMsg(rc));
            goto error;
        }

        printf("%d cm, %d degrees\n", distance, angle);
    }

    rc = gpioServo(SERVO, 0);
    if (rc != 0) {
        fprintf(stderr, "gpioServo(SERVO) failed: %s\n", gpioErrMsg(rc));
        goto error;
    }

    rc = gpioTerminate();
    if (rc != 0) {
        fprintf(stderr, "gpioTerminate() failed: %s\n", gpioErrMsg(rc));
        return 1;
    }

    return 0;

error:
    gpioTerminate();
    return 1;
}
