#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_CONFIG 0x03
#define I2C_TEMP 0x01
#define I2C_HUMID 0x02

#define I2C_CONFIG_VAL 0x00
#define I2C_CONFIG_WAIT 10
#define I2C_READ_WAIT 10

#define TEMP_SCALE 175.72
#define TEMP_OFFSET -46.85
#define HUMID_SCALE 125.0
#define HUMID_OFFSET -6.0

#define LOG_INTERVAL 2

static volatile int running = 1;

static void sig_handler(int signo)
{
    if (signo == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        running = 0;
    }
}

int main(int argc, char *argv[])
{
    int handle;
    int config_val;
    int temp_val;
    int humid_val;
    double temp;
    double humid;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(handle, I2C_CONFIG, I2C_CONFIG_VAL) < 0) {
        fprintf(stderr, "Failed to write to I2C register %02x\n", I2C_CONFIG);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (gpioDelay(I2C_CONFIG_WAIT) < 0) {
        fprintf(stderr, "Failed to delay %d ms\n", I2C_CONFIG_WAIT);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);

    while (running) {
        if (i2cWriteByte(handle, I2C_TEMP, 0) < 0) {
            fprintf(stderr, "Failed to write to I2C register %02x\n", I2C_TEMP);
            i2cClose(handle);
            gpioTerminate();
            return 1;
        }

        if (gpioDelay(I2C_READ_WAIT) < 0) {
            fprintf(stderr, "Failed to delay %d ms\n", I2C_READ_WAIT);
            i2cClose(handle);
            gpioTerminate();
            return 1;
        }

        if (i2cReadByte(handle, &temp_val) < 0) {
            fprintf(stderr, "Failed to read from I2C register %02x\n", I2C_TEMP);
            i2cClose(handle);
            gpioTerminate();
            return 1;
        }

        if (i2cReadByte(handle, &humid_val) < 0) {
            fprintf(stderr, "Failed to read from I2C register %02x\n", I2C_HUMID);
            i2cClose(handle);
            gpioTerminate();
            return 1;
        }

        temp = (TEMP_SCALE * temp_val) / 65536.0 + TEMP_OFFSET;
        humid = (HUMID_SCALE * humid_val) / 65536.0 + HUMID_OFFSET;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humid);

        if (gpioDelay(LOG_INTERVAL * 1000) < 0) {
            fprintf(stderr, "Failed to delay %d ms\n", LOG_INTERVAL * 1000);
            i2cClose(handle);
            gpioTerminate();
            return 1;
        }
    }

    i2cClose(handle);
    gpioTerminate();

    return 0;
}

