#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD_MEASURE_HIGH_REP 0xFD
#define SHT40_CMD_MEASURE_HIGH_REP_DELAY_MS 10
#define SHT40_CMD_MEASURE_HIGH_REP_BYTES 6
#define SHT40_CRC8_POLY 0x31
#define SHT40_CRC8_INIT 0xFF

#define SHT40_TEMP_OFFSET -45
#define SHT40_TEMP_SCALE 175
#define SHT40_HUMID_OFFSET -6
#define SHT40_HUMID_SCALE 125

#define SHT40_TEMP_MIN -40
#define SHT40_TEMP_MAX 125
#define SHT40_HUMID_MIN 0
#define SHT40_HUMID_MAX 100

#define SHT40_MEASURE_PERIOD_MS 5000

static volatile int running = 1;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SHT40_CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sht40_read_measurement(int handle, uint16_t *temp, uint16_t *humid)
{
    uint8_t buf[SHT40_CMD_MEASURE_HIGH_REP_BYTES];
    if (i2cWriteByte(handle, SHT40_CMD_MEASURE_HIGH_REP) < 0) {
        fprintf(stderr, "i2cWriteByte failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(SHT40_CMD_MEASURE_HIGH_REP_DELAY_MS * 1000);
    if (i2cReadI2CBlockData(handle, buf, SHT40_CMD_MEASURE_HIGH_REP_BYTES) < 0) {
        fprintf(stderr, "i2cReadI2CBlockData failed: %s\n", strerror(errno));
        return -1;
    }
    if (sht40_crc8(buf, 2) != buf[2] || sht40_crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }
    *temp = (buf[0] << 8) | buf[1];
    *humid = (buf[3] << 8) | buf[4];
    return 0;
}

static void sht40_print_measurement(uint16_t temp, uint16_t humid)
{
    double temp_c = SHT40_TEMP_OFFSET + SHT40_TEMP_SCALE * temp / 65535.0;
    double humid_pct = SHT40_HUMID_OFFSET + SHT40_HUMID_SCALE * humid / 65535.0;
    if (temp_c < SHT40_TEMP_MIN) {
        temp_c = SHT40_TEMP_MIN;
    } else if (temp_c > SHT40_TEMP_MAX) {
        temp_c = SHT40_TEMP_MAX;
    }
    if (humid_pct < SHT40_HUMID_MIN) {
        humid_pct = SHT40_HUMID_MIN;
    } else if (humid_pct > SHT40_HUMID_MAX) {
        humid_pct = SHT40_HUMID_MAX;
    }
    printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp_c, humid_pct);
}

int main(void)
{
    int handle = i2cOpen(1, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);
    while (running) {
        uint16_t temp, humid;
        if (sht40_read_measurement(handle, &temp, &humid) == 0) {
            sht40_print_measurement(temp, humid);
        }
        usleep(SHT40_MEASURE_PERIOD_MS * 1000);
    }
    i2cClose(handle);
    return EXIT_SUCCESS;
}

