#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x40
#define SENSOR_TEMP_CMD 0xF3
#define SENSOR_HUMID_CMD 0xF5
#define SENSOR_BUS 1
#define SENSOR_TEMP_SCALE 175.72
#define SENSOR_TEMP_OFFSET -46.85
#define SENSOR_HUMID_SCALE 125.0
#define SENSOR_HUMID_OFFSET -6.0
#define SENSOR_HUMID_CLAMP 100.0
#define SENSOR_FILE "sensor_data.txt"
#define SENSOR_SAMPLE_INTERVAL 5000000

static int sensor_handle = -1;
static FILE *sensor_file = NULL;

static void sensor_cleanup(void)
{
    if (sensor_file) {
        fclose(sensor_file);
        sensor_file = NULL;
    }
    if (sensor_handle >= 0) {
        i2cClose(sensor_handle);
        sensor_handle = -1;
    }
    gpioTerminate();
}

static void sensor_sigint(int signum)
{
    sensor_cleanup();
    exit(EXIT_SUCCESS);
}

static void sensor_sample(void)
{
    uint8_t cmd;
    uint8_t buf[2];
    int ret;
    double temp, humid;

    if (sensor_handle < 0) {
        fprintf(stderr, "sensor: i2c handle not open\n");
        return;
    }

    cmd = SENSOR_TEMP_CMD;
    ret = i2cWriteByte(sensor_handle, cmd);
    if (ret < 0) {
        fprintf(stderr, "sensor: i2c write failed: %s\n", strerror(errno));
        return;
    }

    ret = i2cReadDevice(sensor_handle, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "sensor: i2c read failed: %s\n", strerror(errno));
        return;
    }

    temp = (SENSOR_TEMP_SCALE * (buf[0] * 256 + buf[1]) / 65536.0) + SENSOR_TEMP_OFFSET;

    cmd = SENSOR_HUMID_CMD;
    ret = i2cWriteByte(sensor_handle, cmd);
    if (ret < 0) {
        fprintf(stderr, "sensor: i2c write failed: %s\n", strerror(errno));
        return;
    }

    ret = i2cReadDevice(sensor_handle, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "sensor: i2c read failed: %s\n", strerror(errno));
        return;
    }

    humid = (SENSOR_HUMID_SCALE * (buf[0] * 256 + buf[1]) / 65536.0) + SENSOR_HUMID_OFFSET;
    if (humid > SENSOR_HUMID_CLAMP) {
        humid = SENSOR_HUMID_CLAMP;
    }

    if (sensor_file) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(sensor_file, "%04d-%02d-%02d %02d:%02d:%02d %0.1f %0.1f\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, temp, humid);
    }

    printf("temp: %0.1f humid: %0.1f\n", temp, humid);
}

int main(void)
{
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "sensor: gpio init failed: %s\n", pigpio_error(gpioInitialise()));
        return EXIT_FAILURE;
    }

    sensor_handle = i2cOpen(SENSOR_BUS, SENSOR_ADDR, 0);
    if (sensor_handle < 0) {
        fprintf(stderr, "sensor: i2c open failed: %s\n", pigpio_error(sensor_handle));
        return EXIT_FAILURE;
    }

    sensor_file = fopen(SENSOR_FILE, "a");
    if (!sensor_file) {
        fprintf(stderr, "sensor: open %s failed: %s\n", SENSOR_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, sensor_sigint);

    while (1) {
        sensor_sample();
        ret = gpioDelay(SENSOR_SAMPLE_INTERVAL);
        if (ret < 0) {
            fprintf(stderr, "sensor: gpio delay failed: %s\n", pigpio_error(ret));
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

