static void i2c_log(const char *msg)
{
    if (i2c_log_file == NULL) {
        i2c_log_file = fopen(I2C_LOG_FILE, "a");
        if (i2c_log_file == NULL) {
            fprintf(stderr, "Error: Failed to open log file\n");
            exit(EXIT_FAILURE);
        }
    }
    fprintf(i2c_log_file, "%s\n", msg);
    fflush(i2c_log_file);
}

static void i2c_err_log(const char *msg)
{
    if (i2c_err_log_file == NULL) {
        i2c_err_log_file = fopen(I2C_ERR_LOG_FILE, "a");
        if (i2c_err_log_file == NULL) {
