        return;
    }
    i2c_log(buf);
}

static void i2c_log_temp_err(uint16_t raw)
{
    char buf[64];
    if (snprintf(buf, sizeof(buf), "%s: 0x%04X", I2C_TEMP_ERR_STR, raw) < 0) {
        i2c_err_log("Error: Failed to format temperature error");
        return;
    }
    i2c_log(buf);
}

static void i2c_log_crc_err(uint8_t crc)
{
    char buf[64];
    if (snprintf(buf, sizeof(buf), "%s: 0x%02X", I2C_CRC_ERR_STR, crc) < 0) {
        i2c_err_log("Error: Failed to format CRC error");
