static void i2c_log_write_err(void)
{
    i2c_log(I2C_WRITE_ERR_STR);
}

static void i2c_log_init_err(void)
{
    i2c_log(I2C_INIT_ERR_STR);
}

static void i2c_log_sigint_err(void)
{
    i2c_log(I2C_SIGINT_ERR_STR);
}

static uint8_t i2c_crc(uint8_t crc, uint8_t data)
{
    crc ^= data;
    for (int i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc << 1) ^ I2C_CRC_POLY;
        } else {
            crc <<= 1;
        }
    }
    return crc;
}

static uint8_t i2c_calc_crc(uint8_t *data, size_t len)
{
    uint8_t crc = I2C_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc = i2c_crc(crc, data[i]);
    }
    return crc;
}

static void i2c_log_temp_read(void)
{
    uint8_t data[I2C_DATA_LEN];
    uint8_t crc = 0;
    uint16_t raw = 0;
