        i2c_log_read_err();
        return;
    }
    crc = i2c_calc_crc(data, I2C_DATA_LEN - 1);
    if (crc != data[I2C_DATA_LEN - 1]) {
        i2c_log_crc_err(crc);
        return;
    }
    raw = (data[0] << 8) | data[1];
    if (raw == I2C_TEMP_ERR) {
        i2c_log_temp_err(raw);
        return;
    }
    i2c_log_temp(raw);
}

static void i2c_log_temp_loop(void)
{
    while (1) {
        i2c_log_time();
        i2c_log_temp_read();
        gpioDelay(I2C_LOG_INTERVAL_MS);
    }
}

static void i2c_log_temp_init(void)
{
    if (gpioInitialise() < 0) {
        i2c_log_init_err();
        exit(EXIT_FAILURE);
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        i2c_log_init_err();
        exit(EXIT_FAILURE);
    }
    if (i2cWriteWordData(i2c_handle, I2C_CMD) != 0) {
        i2c_log_write_err();
        exit(EXIT_FAILURE);
    }
    gpioDelay(I2C_LOG_INTERVAL_MS);
    i2c_log_temp_loop();
}

static void i2c_log_temp_sigint(int sig)
{
    i2c_log_sigint_err();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (i2c_log_file != NULL) {
        fclose(i2c_log_file);
    }
    if (i2c_err_log_file != NULL) {
        fclose(i2c_err_log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    signal(SIGINT, i2c_log_temp_sigint);
    i2c_log_temp_init();
    return EXIT_SUCCESS;
}

