#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD 0xFD
#define SHT40_DATA_LEN 6
#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0xFF

#define LOG_FILE "sht40_log.txt"

#define I2C_DEV "/dev/i2c-1"

#define I2C_OPEN_ERR "Failed to open I2C device"
#define I2C_IOCTL_ERR "Failed to set I2C device address"
#define I2C_WRITE_ERR "Failed to write to I2C device"
#define I2C_READ_ERR "Failed to read from I2C device"
#define I2C_CRC_ERR "CRC error"
#define I2C_LOG_ERR "Failed to log to file"

#define I2C_ERR_EXIT(msg) { perror(msg); exit(EXIT_FAILURE); }

static int i2c_fd;
static FILE *log_fp;

static void i2c_close(void)
{
    if (i2c_fd >= 0)
        close(i2c_fd);
    if (log_fp)
        fclose(log_fp);
}

static void i2c_exit(int sig)
{
    i2c_close();
    exit(EXIT_SUCCESS);
}

static void i2c_init(void)
{
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0)
        I2C_ERR_EXIT(I2C_OPEN_ERR);
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0)
        I2C_ERR_EXIT(I2C_IOCTL_ERR);
    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp)
        I2C_ERR_EXIT(I2C_LOG_ERR);
    signal(SIGINT, i2c_exit);
}

static uint8_t i2c_crc(uint8_t *data, size_t len)
{
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SHT40_CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void i2c_read(uint8_t *data, size_t len)
{
    if (read(i2c_fd, data, len) != len)
        I2C_ERR_EXIT(I2C_READ_ERR);
}

static void i2c_write(uint8_t *data, size_t len)
{
    if (write(i2c_fd, data, len) != len)
        I2C_ERR_EXIT(I2C_WRITE_ERR);
}

static void i2c_log(uint8_t *data, size_t len)
{
    if (fwrite(data, 1, len, log_fp) != len)
        I2C_ERR_EXIT(I2C_LOG_ERR);
}

int main(void)
{
    i2c_init();
    uint8_t data[SHT40_DATA_LEN];
    while (1) {
        i2c_write(&SHT40_CMD, 1);
        usleep(8500);
        i2c_read(data, SHT40_DATA_LEN);
        if (i2c_crc(data, 2) != data[2] || i2c_crc(data + 3, 2) != data[5]) {
            fprintf(stderr, "%s\n", I2C_CRC_ERR);
            continue;
        }
        float temp = -45.0 + 175.0 * (data[0] << 8 | data[1]) / 65535.0;
        float humidity = 100.0 * (data[3] << 8 | data[4]) / 65535.0;
        time_t now = time(NULL);
        i2c_log(&now, sizeof(now));
        i2c_log(&temp, sizeof(temp));
        i2c_log(&humidity, sizeof(humidity));
        i2c_log("\n", 1);
        sleep(5);
    }
    i2c_close();
    return 0;
}

