#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define SENSOR_TIMEOUT 50
#define SENSOR_MIN_TEMP -40
#define SENSOR_MAX_TEMP 150
#define SENSOR_ERROR_COUNT 3
#define SENSOR_LOG_FILE "temperature_log.txt"

static volatile int keep_running = 1;

static void signal_handler(int signum)
{
    keep_running = 0;
}

int main(int argc, char *argv[])
{
    FILE *log_file = NULL;
    int sensor_th, sensor_tl, sensor_error_count = 0;
    double temperature;
    time_t current_time;
    struct tm *local_time;
    char time_string[32];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    log_file = fopen(SENSOR_LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running)
    {
        sensor_th = gpioTick();
        if (gpioWaitEdge(SENSOR_PIN, PI_RISING_EDGE, SENSOR_TIMEOUT) < 0)
        {
            fprintf(stderr, "Sensor timeout\n");
            sensor_error_count++;
        }
        else
        {
            sensor_tl = gpioTick() - sensor_th;
            sensor_th = gpioTick() - sensor_th;
            temperature = 4215.0 - (2143.0 * sensor_th / sensor_tl);
            if (temperature < SENSOR_MIN_TEMP || temperature > SENSOR_MAX_TEMP)
            {
                fprintf(stderr, "Sensor reading out of range\n");
                sensor_error_count++;
            }
            else
            {
                sensor_error_count = 0;
                current_time = time(NULL);
                local_time = localtime(&current_time);
                strftime(time_string, sizeof(time_string), "%FT%T%z", local_time);
                fprintf(log_file, "%s, %.1f\n", time_string, temperature);
                fflush(log_file);
            }
        }

        if (sensor_error_count >= SENSOR_ERROR_COUNT)
        {
            fprintf(log_file, "%s, SENSOR MALFUNCTION\n", time_string);
            fflush(log_file);
            sensor_error_count = 0;
        }

        gpioDelay(5000000);
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

