#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_PATH "/dev/i2c-1"
#define I2C_TIMEOUT_MS 100
#define I2C_RESET_CMD 0xFE
#define I2C_TEMP_CMD 0xF3
#define I2C_HUMID_CMD 0xF5
#define I2C_TEMP_HUMID_CMD 0xE0
#define I2C_TEMP_SCALE 175.72
#define I2C_TEMP_OFFSET -46.85
#define I2C_HUMID_SCALE 125.0
#define I2C_HUMID_OFFSET -6.0
#define I2C_CRC_POLY 0x31
#define I2C_CRC_INIT 0x00
#define I2C_CRC_MASK 0xFF
#define I2C_READ_SIZE 3
#define I2C_READ_RETRIES 10
#define I2C_READ_RETRY_DELAY_US 100000
#define I2C_READ_RETRY_DELAY_MS 100
#define I2C_READ_RETRY_DELAY_S 5
#define I2C_READ_RETRY_DELAY_NS 0
#define I2C_LOG_PATH "environment.log"
#define I2C_LOG_HEADER "timestamp,temperature_C,humidity_percent"
#define I2C_LOG_ERROR "ERROR"

static int i2c_fd = -1;
static bool i2c_running = true;

static void i2c_exit(int status) {
  if (i2c_fd >= 0) {
    close(i2c_fd);
  }
  exit(status);
}

static void i2c_sigint(int signum) {
  i2c_running = false;
}

static void i2c_log(const char *timestamp, float temperature, float humidity) {
  FILE *log_file = fopen(I2C_LOG_PATH, "a");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    return;
  }
  fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, humidity);
  fclose(log_file);
}

static void i2c_log_error(const char *message) {
  FILE *log_file = fopen(I2C_LOG_PATH, "a");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    return;
  }
  fprintf(log_file, "%s,%s,%s\n", I2C_LOG_ERROR, I2C_LOG_ERROR, message);
  fclose(log_file);
}

static bool i2c_read(uint8_t command, uint8_t *data) {
  struct timespec timeout = {
    .tv_sec = 0,
    .tv_nsec = I2C_READ_RETRY_DELAY_NS,
  };
  for (int i = 0; i < I2C_READ_RETRIES; i++) {
    if (i > 0) {
      timeout.tv_sec = I2C_READ_RETRY_DELAY_S;
      timeout.tv_nsec = I2C_READ_RETRY_DELAY_NS;
      if (nanosleep(&timeout, NULL) < 0) {
        fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
        return false;
      }
    }
    if (write(i2c_fd, &command, 1) != 1) {
      fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
      return false;
    }
    timeout.tv_sec = 0;
    timeout.tv_nsec = I2C_READ_RETRY_DELAY_NS;
    if (nanosleep(&timeout, NULL) < 0) {
      fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
      return false;
    }
    if (read(i2c_fd, data, I2C_READ_SIZE) != I2C_READ_SIZE) {
      fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
      return false;
    }
    if (data[2] == i2c_crc8(data, I2C_READ_SIZE - 1)) {
      return true;
    }
  }
  return false;
}

static uint8_t i2c_crc8(const uint8_t *data, size_t size) {
  uint8_t crc = I2C_CRC_INIT;
  for (size_t i = 0; i < size; i++) {
    crc ^= data[i];
    for (int j = 0; j < 8; j++) {
      if (crc & 0x80) {
        crc = (crc << 1) ^ I2C_CRC_POLY;
      } else {
        crc <<= 1;
      }
    }
  }
  return crc & I2C_CRC_MASK;
}

static bool i2c_reset() {
  if (write(i2c_fd, &I2C_RESET_CMD, 1) != 1) {
    fprintf(stderr, "Failed to write reset command: %s\n", strerror(errno));
    return false;
  }
  return true;
}

static bool i2c_measure(float *temperature, float *humidity) {
  uint8_t data[I2C_READ_SIZE];
  if (!i2c_read(I2C_TEMP_CMD, data)) {
    fprintf(stderr, "Failed to read temperature\n");
    return false;
  }
  *temperature = I2C_TEMP_SCALE * ((data[0] << 8) | data[1]) / 65536.0 + I2C_TEMP_OFFSET;
  if (!i2c_read(I2C_HUMID_CMD, data)) {
    fprintf(stderr, "Failed to read humidity\n");
    return false;
  }
  *humidity = I2C_HUMID_SCALE * ((data[0] << 8) | data[1]) / 65536.0 + I2C_HUMID_OFFSET;
  if (!i2c_read(I2C_TEMP_HUMID_CMD, data)) {
    fprintf(stderr, "Failed to read paired temperature\n");
    return false;
  }
  return true;
}

int main(int argc, char *argv[]) {
  if (argc > 1) {
    fprintf(stderr, "Usage: %s\n", argv[0]);
    return EXIT_FAILURE;
  }
  if (signal(SIGINT, i2c_sigint) == SIG_ERR) {
    fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
    return EXIT_FAILURE;
  }
  if (signal(SIGTERM, i2c_sigint) == SIG_ERR) {
    fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
    return EXIT_FAILURE;
  }
  if (access(I2C_LOG_PATH, F_OK) == 0) {
    if (unlink(I2C_LOG_PATH) < 0) {
      fprintf(stderr, "Failed to delete log file: %s\n", strerror(errno));
      return EXIT_FAILURE;
    }
  }
  i2c_fd = open(I2C_PATH, O_RDWR);
  if (i2c_fd < 0) {
    fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
    return EXIT_FAILURE;
  }
  if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
    fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
    i2c_exit(EXIT_FAILURE);
  }
  i2c_log(I2C_LOG_HEADER, 0.0, 0.0);
  while (i2c_running) {
    struct timespec timeout = {
      .tv_sec = I2C_READ_RETRY_DELAY_S,
      .tv_nsec = I2C_READ_RETRY_DELAY_NS,
    };
    if (nanosleep(&timeout, NULL) < 0) {
      fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
      i2c_exit(EXIT_FAILURE);
    }
    float temperature = 0.0;
    float humidity = 0.0;
    if (!i2c_measure(&temperature, &humidity)) {
      if (!i2c_reset()) {
        i2c_exit(EXIT_FAILURE);
      }
      i2c_log_error("Failed to measure");
      continue;
    }
    char timestamp[256];
    if (strftime(timestamp, sizeof(timestamp), "%FT%T%z", gmtime(NULL)) == 0) {
      fprintf(stderr, "Failed to format timestamp\n");
      i2c_exit(EXIT_FAILURE);
    }
    i2c_log(timestamp, temperature, humidity);
  }
  i2c_exit(EXIT_SUCCESS);
}

