#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define I2C_CMD 0x3603
#define I2C_READ_LEN 9
#define I2C_CRC_POLY 0x31
#define I2C_CRC_LEN 3
#define I2C_SCALE_FACTOR 60.0
#define I2C_CONV_TIME 45
#define I2C_LOG_FILE "pressure_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void i2c_crc_calc(uint8_t *data, uint8_t len, uint8_t *crc)
{
    uint8_t i, j;
    uint8_t crc_val = 0xFF;

    for (i = 0; i < len; i++) {
        crc_val ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc_val & 0x80)
                crc_val = (crc_val << 1) ^ I2C_CRC_POLY;
            else
                crc_val = (crc_val << 1);
        }
    }

    *crc = crc_val;
}

static int i2c_crc_check(uint8_t *data, uint8_t len)
{
    uint8_t crc;

    i2c_crc_calc(data, len, &crc);

    return (crc == data[len]);
}

static void i2c_read_pressure(void)
{
    uint8_t data[I2C_READ_LEN];
    uint16_t raw_pressure;
    double pressure;
    time_t now;
    struct tm *tm;
    char time_str[64];

    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle not initialized\n");
        return;
    }

    if (i2cWriteWordData(i2c_handle, I2C_CMD) < 0) {
        fprintf(stderr, "Failed to write I2C command\n");
        return;
    }

    if (gpioDelay(I2C_CONV_TIME * 1000) < 0) {
        fprintf(stderr, "Failed to delay for conversion time\n");
        return;
    }

    if (i2cReadI2CBlockData(i2c_handle, I2C_READ_LEN, data) < 0) {
        fprintf(stderr, "Failed to read I2C data\n");
        return;
    }

    if (!i2c_crc_check(data, I2C_READ_LEN - I2C_CRC_LEN)) {
        fprintf(stderr, "CRC check failed\n");
        return;
    }

    raw_pressure = (data[0] << 8) | data[1];
    pressure = raw_pressure * I2C_SCALE_FACTOR;

    now = time(NULL);
    tm = localtime(&now);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s, %.2f\n", time_str, pressure);
    fflush(log_file);
}

static void i2c_init(void)
{
    if (i2c_handle >= 0) {
        fprintf(stderr, "I2C handle already initialized\n");
        return;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return;
    }
}

static void i2c_deinit(void)
{
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle not initialized\n");
        return;
    }

    if (i2cClose(i2c_handle) < 0) {
        fprintf(stderr, "Failed to close I2C handle\n");
        return;
    }

    i2c_handle = -1;
}

static void log_init(void)
{
    if (log_file != NULL) {
        fprintf(stderr, "Log file already initialized\n");
        return;
    }

    log_file = fopen(I2C_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
}

static void log_deinit(void)
{
    if (log_file == NULL) {
        fprintf(stderr, "Log file not initialized\n");
        return;
    }

    if (fclose(log_file) < 0) {
        fprintf(stderr, "Failed to close log file\n");
        return;
    }

    log_file = NULL;
}

static void sig_handler(int sig)
{
    i2c_deinit();
    log_deinit();
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_init();
    log_init();

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        i2c_read_pressure();
        gpioDelay(5 * 1000 * 1000);
    }

    return EXIT_SUCCESS;
}

