#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define I2C_ADDR 0x28
#define I2C_BUS 1
#define FAN_PIN 18
#define FAN_FREQ 25000
#define FAN_MIN_DUTY 0
#define FAN_MAX_DUTY 100
#define FLOW_MIN_COUNT 1638
#define FLOW_MAX_COUNT 14745
#define FLOW_MIN_SLPM 0
#define FLOW_MAX_SLPM 10
#define FLOW_LOG_FILE "flow_log.txt"
#define FLOW_LOG_INTERVAL 100

static int i2c_handle = -1;
static FILE *flow_log = NULL;
static int fan_duty = 0;

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (flow_log) {
        fclose(flow_log);
    }
    gpioPWM(FAN_PIN, 0);
    gpioTerminate();
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static void log_flow(int flow_count)
{
    time_t now = time(NULL);
    fprintf(flow_log, "%ld,%d\n", now, flow_count);
    fflush(flow_log);
}

static void set_fan_duty(int duty)
{
    if (duty < FAN_MIN_DUTY) {
        duty = FAN_MIN_DUTY;
    } else if (duty > FAN_MAX_DUTY) {
        duty = FAN_MAX_DUTY;
    }
    gpioPWM(FAN_PIN, duty);
    fan_duty = duty;
}

static void set_fan_slpm(int slpm)
{
    if (slpm < FLOW_MIN_SLPM) {
        slpm = FLOW_MIN_SLPM;
    } else if (slpm > FLOW_MAX_SLPM) {
        slpm = FLOW_MAX_SLPM;
    }
    int duty = FAN_MIN_DUTY + (slpm - FLOW_MIN_SLPM) * (FAN_MAX_DUTY - FAN_MIN_DUTY) / (FLOW_MAX_SLPM - FLOW_MIN_SLPM);
    set_fan_duty(duty);
}

static int get_flow_count(void)
{
    uint8_t buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static int get_flow_slpm(void)
{
    int flow_count = get_flow_count();
    if (flow_count < 0) {
        return -1;
    }
    flow_count = (flow_count >> 2) & 0x3FFF;
    return FLOW_MIN_SLPM + (flow_count - FLOW_MIN_COUNT) * (FLOW_MAX_SLPM - FLOW_MIN_SLPM) / (FLOW_MAX_COUNT - FLOW_MIN_COUNT);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_PIN, FAN_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_PIN, FAN_MAX_DUTY) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return EXIT_FAILURE;
    }
    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }
    if ((flow_log = fopen(FLOW_LOG_FILE, "w")) == NULL) {
