#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_CONFIG_REG 0x02
#define I2C_TEMP_REG 0x00
#define I2C_TEMP_RES 165.0
#define I2C_TEMP_OFFSET -40.0
#define I2C_HUMID_RES 100.0
#define I2C_DELAY_MS 20
#define I2C_READ_LEN 4

static int i2c_fd = -1;

static void i2c_close(void)
{
