        i2c_fd = -1;
    }
}

static void sig_handler(int sig)
{
    i2c_close();
    exit(0);
}

int main(void)
{
    int ret;
    uint8_t buf[I2C_READ_LEN];
    uint16_t temp, humid;
    float temp_c, humid_rh;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to access I2C address\n");
        i2c_close();
        return -1;
    }

