#define MLX90819_CONFIG_TEMP_DISABLE 0x00
#define MLX90819_CONFIG_TEMP_MASK 0x04

#define MLX90819_STATUS_MEASUREMENT_READY 0x01
#define MLX90819_STATUS_MEASUREMENT_NOT_READY 0x00
#define MLX90819_STATUS_MEASUREMENT_MASK 0x01

#define MLX90819_SCALE_FACTOR 0.1

int fd;

void sigint_handler(int sig) {
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int ret;
    uint8_t buf[2];
    uint16_t raw_pressure;
    float pressure;
    struct timespec ts;
    struct tm *tm;
    char time_str[64];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    ret = ioctl(fd, I2C_SLAVE, MLX90819_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        exit(1);
    }

    ret = write(fd, &MLX90819_REG_CONFIGURATION, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }

    ret = read(fd, &buf, 1);
    if (ret != 1) {
        perror("Failed to read from I2C device");
        exit(1);
    }

    buf[0] &= ~MLX90819_CONFIG_TEMP_MASK;
    buf[0] |= MLX90819_CONFIG_TEMP_DISABLE;
    buf[0] |= MLX90819_CONFIG_ONE_SHOT;

    ret = write(fd, buf, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        ret = write(fd, &MLX90819_REG_PRESSURE_MSB, 1);
        if (ret != 1) {
            perror("Failed to write to I2C device");
            exit(1);
        }

        ret = read(fd, buf, 2);
        if (ret != 2) {
            perror("Failed to read from I2C device");
            exit(1);
        }

        raw_pressure = (buf[0] << 8) | buf[1];
        pressure = raw_pressure * MLX90819_SCALE_FACTOR;

        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
        printf("%s.%09ld, %f\n", time_str, ts.tv_nsec, pressure);

        sleep(1);
    }

    return 0;
}
