#define SDP800_I2C_ADDR 0x25
#define SDP800_I2C_BUS 1
#define SDP800_CMD_CONT_MEAS 0x362F
#define SDP800_CMD_READ_DATA 0x0000
#define SDP800_CRC_POLY 0x31
#define SDP800_CRC_INIT 0xFF
#define SDP800_DATA_LEN 3
#define SDP800_DATA_SCALE 60.0
#define SDP800_DATA_OFFSET 0
#define SDP800_DATA_MAX 0x7FFF
#define SDP800_DATA_MIN 0x8000
#define SDP800_DATA_RANGE (SDP800_DATA_MAX - SDP800_DATA_MIN)
#define SDP800_DATA_MAX_PA 500.0
#define SDP800_DATA_MIN_PA -500.0
#define SDP800_DATA_RANGE_PA (SDP800_DATA_MAX_PA - SDP800_DATA_MIN_PA)
#define SDP800_DATA_SCALE_PA (SDP800_DATA_RANGE_PA / SDP800_DATA_RANGE)
#define SDP800_DATA_OFFSET_PA (SDP800_DATA_MIN_PA - (SDP800_DATA_OFFSET * SDP800_DATA_SCALE_PA))

#define LOG_FILE "airflow_log.csv"
#define LOG_HEADER "timestamp,pressure\n"
#define LOG_FMT "%s,%.2f\n"

#define ERR_MSG_LEN 1024
#define ERR_MSG_FMT "%s:%d: %s\n"

#define ERR_MSG_I2C_INIT "pigpio I2C init failed"
#define ERR_MSG_I2C_CMD "pigpio I2C command failed"
#define ERR_MSG_I2C_READ "pigpio I2C read failed"
#define ERR_MSG_I2C_CRC "CRC mismatch"
#define ERR_MSG_I2C_DATA "data out of range"
#define ERR_MSG_I2C_WRITE "pigpio I2C write failed"
#define ERR_MSG_I2C_CLOSE "pigpio I2C close failed"
#define ERR_MSG_FILE_OPEN "failed to open file"
#define ERR_MSG_FILE_WRITE "failed to write to file"
#define ERR_MSG_FILE_CLOSE "failed to close file"

#define ERR_EXIT(msg) do { \
    fprintf(stderr, ERR_MSG_FMT, __FILE__, __LINE__, msg); \
    exit(EXIT_FAILURE); \
} while (0)

#define ERR_EXIT_I2C(msg, err) do { \
    fprintf(stderr, ERR_MSG_FMT, __FILE__, __LINE__, msg); \
    fprintf(stderr, ERR_MSG_FMT, __FILE__, __LINE__, err); \
    exit(EXIT_FAILURE); \
} while (0)

#define ERR_EXIT_FILE(msg, err) do { \
    fprintf(stderr, ERR_MSG_FMT, __FILE__, __LINE__, msg); \
    fprintf(stderr, ERR_MSG_FMT, __FILE__, __LINE__, err); \
    exit(EXIT_FAILURE); \
} while (0)

#define ERR_EXIT_FILE_ERRNO(msg) do { \
    fprintf(stderr, ERR_MSG_FMT, __FILE__, __LINE__, msg); \
    perror(NULL); \
    exit(EXIT_FAILURE); \
} while (0)

static void log_data(int fd, const char *timestamp, float pressure)
{
    char buf[ERR_MSG_LEN];
    int ret;

    ret = snprintf(buf, sizeof(buf), LOG_FMT, timestamp, pressure);
    if (ret < 0)
        ERR_EXIT(ERR_MSG_FILE_WRITE);
    if (ret >= sizeof(buf))
        ERR_EXIT(ERR_MSG_FILE_WRITE);

    ret = write(fd, buf, strlen(buf));
    if (ret < 0)
        ERR_EXIT_FILE(ERR_MSG_FILE_WRITE, strerror(errno));
    if (ret != strlen(buf))
        ERR_EXIT(ERR_MSG_FILE_WRITE);
}

static void log_header(int fd)
{
    int ret;

    ret = write(fd, LOG_HEADER, strlen(LOG_HEADER));
    if (ret < 0)
        ERR_EXIT_FILE(ERR_MSG_FILE_WRITE, strerror(errno));
    if (ret != strlen(LOG_HEADER))
        ERR_EXIT(ERR_MSG_FILE_WRITE);
}

static int open_log_file(void)
{
    int fd;

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0)
        ERR_EXIT_FILE_ERRNO(ERR_MSG_FILE_OPEN);

    return fd;
}

static void close_log_file(int fd)
{
    int ret;

    ret = close(fd);
    if (ret < 0)
        ERR_EXIT_FILE(ERR_MSG_FILE_CLOSE, strerror(errno));
}

static void log_pressure(int fd, const char *timestamp, uint16_t raw)
{
    float pressure;

    if (raw > SDP800_DATA_MAX)
        ERR_EXIT(ERR_MSG_I2C_DATA);
    if (raw < SDP800_DATA_MIN)
        ERR_EXIT(ERR_MSG_I2C_DATA);

    pressure = (raw - SDP800_DATA_OFFSET) * SDP800_DATA_SCALE_PA;

    log_data(fd, timestamp, pressure);
}

static void log_timestamp(int fd)
{
    char timestamp[32];
    time_t t;
    struct tm *tm;

    t = time(NULL);
    if (t < 0)
        ERR_EXIT(ERR_MSG_FILE_WRITE);

    tm = localtime(&t);
    if (tm == NULL)
        ERR_EXIT(ERR_MSG_FILE_WRITE);

    if (strftime(timestamp, sizeof(timestamp), "%F %T", tm) == 0)
        ERR_EXIT(ERR_MSG_FILE_WRITE);

    log_data(fd, timestamp, 0.0);
}

