#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define I2C_CMD 0x00
#define I2C_DATA_LEN 4
#define I2C_TIMEOUT 1000
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_MAX_SIZE 1048576

int main(void)
{
    int i2c_handle;
    uint8_t i2c_data[I2C_DATA_LEN];
    int i2c_status;
    int i2c_raw_t;
    int i2c_raw_h;
    double i2c_temp;
    double i2c_humid;
    FILE *log_file;
    struct timespec log_time;
    char log_time_str[26];
    int log_file_size;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "i2cOpen failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "fopen failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        i2c_status = i2cWriteByte(i2c_handle, I2C_CMD);
        if (i2c_status < 0)
        {
            fprintf(stderr, "i2cWriteByte failed\n");
            break;
        }

        gpioDelay(40000);

        i2c_status = i2cReadI2C(i2c_handle, i2c_data, I2C_DATA_LEN, I2C_TIMEOUT);
        if (i2c_status < 0)
        {
            fprintf(stderr, "i2cReadI2C failed\n");
            break;
        }

        i2c_raw_t = (i2c_data[0] << 8) | i2c_data[1];
        i2c_raw_h = (i2c_data[2] << 8) | i2c_data[3];

        if ((i2c_raw_t & 0x8000) || (i2c_raw_h & 0x8000))
        {
            fprintf(stderr, "i2c sensor status error\n");
            break;
        }

        i2c_temp = i2c_raw_t * 165.0 / 16383.0 - 40.0;
        i2c_humid = i2c_raw_h * 100.0 / 16383.0;

        clock_gettime(CLOCK_REALTIME, &log_time);
        strftime(log_time_str, sizeof(log_time_str), "%FT%T%z", gmtime(&log_time.tv_sec));

        fprintf(log_file, "%s,%.1f,%.1f\n", log_time_str, i2c_temp, i2c_humid);
        fflush(log_file);

        log_file_size = ftell(log_file);
        if (log_file_size >= LOG_FILE_MAX_SIZE)
        {
            fclose(log_file);
            log_file = fopen(LOG_FILE, "w");
            if (log_file == NULL)
            {
                fprintf(stderr, "fopen failed\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }

        gpioDelay(5000000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

