    ret = i2cClose(shtc3_i2c_handle);
    if (ret < 0) {
        fprintf(stderr, "i2cClose failed: %d\n", ret);
        return ret;
    }

    shtc3_i2c_handle = SHTC3_I2C_HANDLE;

    return 0;
}

static int shtc3_i2c_write(uint16_t cmd)
{
    int ret;
    uint8_t buf[SHTC3_I2C_CMD_LEN];

    buf[SHTC3_I2C_CMD_OFFSET] = cmd >> 8;
    buf[SHTC3_I2C_CMD_OFFSET + 1] = cmd & 0xFF;

    ret = i2cWriteDevice(shtc3_i2c_handle, buf, SHTC3_I2C_CMD_LEN);
    if (ret < 0) {
        fprintf(stderr, "i2cWriteDevice failed: %d\n", ret);
        return ret;
    }

    return 0;
}

static int shtc3_i2c_read(uint8_t *data)
{
    int ret;

    ret = i2cReadDevice(shtc3_i2c_handle, data, SHTC3_I2C_DATA_LEN);
    if (ret < 0) {
        fprintf(stderr, "i2cReadDevice failed: %d\n", ret);
        return ret;
    }

    return 0;
}

static uint8_t shtc3_i2c_crc(uint8_t *data, int len)
{
    int i;
    uint8_t crc = SHTC3_I2C_CRC_INIT;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHTC3_I2C_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

static int shtc3_i2c_crc_check(uint8_t *data, int len, uint8_t crc)
{
    uint8_t calc_crc;

    calc_crc = shtc3_i2c_crc(data, len);
    if (calc_crc != crc) {
        fprintf(stderr, "CRC check failed: %02X != %02X\n", calc_crc, crc);
        return -1;
    }

    return 0;
}

static int shtc3_i2c_read_data(uint8_t *data)
