    if (ret < 0) {
        return ret;
    }

    ret = i2cBusy(shtc3_i2c_handle, SHTC3_I2C_TIMEOUT);
    if (ret < 0) {
        fprintf(stderr, "i2cBusy failed: %d\n", ret);
        return ret;
