#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define I2C_REG 0x00
#define I2C_RESOLUTION 0.0078125

#define MAX_RETRIES 3

int i2c_handle = -1;

void sigint_handler(int sig) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int ret, retries = 0;
    uint16_t temp_raw;
    double temp_c;
    char timestamp[32];
    time_t now;
    struct tm *tm_info;

    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    while (retries < MAX_RETRIES) {
        i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C handle\n");
            retries++;
            continue;
        }

        while (1) {
            ret = i2cReadWordData(i2c_handle, I2C_REG);
            if (ret < 0) {
                fprintf(stderr, "Failed to read temperature\n");
                break;
            }

            temp_raw = (uint16_t) ret;
            temp_c = temp_raw * I2C_RESOLUTION;

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            printf("%s, Temperature: %.2f C\n", timestamp, temp_c);

            sleep(1);
        }

        i2cClose(i2c_handle);
        retries++;
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    gpioTerminate();
    return 1;
}

