#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define DHT11_PIN 4
#define DHT11_TIMEOUT 1000000
#define DHT11_READING_INTERVAL 2000000

#define DHT11_ERROR_START_SIGNAL_TIMEOUT 1
#define DHT11_ERROR_RESPONSE_TIMEOUT 2
#define DHT11_ERROR_DATA_TIMEOUT 3
#define DHT11_ERROR_CHECKSUM 4
#define DHT11_ERROR_SENSOR_ABSENT 5

#define DHT11_ERROR_STRING_START_SIGNAL_TIMEOUT "DHT11_ERROR_START_SIGNAL_TIMEOUT"
#define DHT11_ERROR_STRING_RESPONSE_TIMEOUT "DHT11_ERROR_RESPONSE_TIMEOUT"
#define DHT11_ERROR_STRING_DATA_TIMEOUT "DHT11_ERROR_DATA_TIMEOUT"
#define DHT11_ERROR_STRING_CHECKSUM "DHT11_ERROR_CHECKSUM"
#define DHT11_ERROR_STRING_SENSOR_ABSENT "DHT11_ERROR_SENSOR_ABSENT"

#define DHT11_READING_FILE "dht11_readings.txt"

static FILE *reading_file;

static void dht11_log_reading(uint8_t humidity, uint8_t temperature)
{
    time_t now;
    struct tm *now_tm;
    char now_string[256];

    now = time(NULL);
    now_tm = localtime(&now);
    strftime(now_string, sizeof(now_string), "%FT%T%z", now_tm);

    fprintf(reading_file, "%s %d %d\n", now_string, humidity, temperature);
    fflush(reading_file);
}

static void dht11_log_error(uint8_t error_code)
{
    time_t now;
    struct tm *now_tm;
    char now_string[256];

    now = time(NULL);
    now_tm = localtime(&now);
    strftime(now_string, sizeof(now_string), "%FT%T%z", now_tm);

    switch (error_code) {
        case DHT11_ERROR_START_SIGNAL_TIMEOUT:
            fprintf(reading_file, "%s %s\n", now_string, DHT11_ERROR_STRING_START_SIGNAL_TIMEOUT);
            break;
        case DHT11_ERROR_RESPONSE_TIMEOUT:
            fprintf(reading_file, "%s %s\n", now_string, DHT11_ERROR_STRING_RESPONSE_TIMEOUT);
            break;
        case DHT11_ERROR_DATA_TIMEOUT:
            fprintf(reading_file, "%s %s\n", now_string, DHT11_ERROR_STRING_DATA_TIMEOUT);
            break;
        case DHT11_ERROR_CHECKSUM:
            fprintf(reading_file, "%s %s\n", now_string, DHT11_ERROR_STRING_CHECKSUM);
            break;
        case DHT11_ERROR_SENSOR_ABSENT:
            fprintf(reading_file, "%s %s\n", now_string, DHT11_ERROR_STRING_SENSOR_ABSENT);
            break;
        default:
            fprintf(reading_file, "%s DHT11_ERROR_UNKNOWN\n", now_string);
            break;
    }

    fflush(reading_file);
}

static void dht11_read_sensor(void)
{
    uint8_t data[5];
    uint8_t checksum;
    uint8_t i;
    uint8_t j;
    uint8_t bit;
    uint32_t start_time;
    uint32_t end_time;
    uint32_t duration;

    gpioWrite(DHT11_PIN, 0);
    gpioDelay(18000);
    gpioWrite(DHT11_PIN, 1);

    start_time = gpioTick();
    while (gpioRead(DHT11_PIN) == 0) {
        end_time = gpioTick();
        duration = end_time - start_time;
        if (duration > DHT11_TIMEOUT) {
            dht11_log_error(DHT11_ERROR_START_SIGNAL_TIMEOUT);
            return;
        }
    }

    start_time = gpioTick();
    while (gpioRead(DHT11_PIN) == 1) {
        end_time = gpioTick();
        duration = end_time - start_time;
        if (duration > DHT11_TIMEOUT) {
            dht11_log_error(DHT11_ERROR_RESPONSE_TIMEOUT);
            return;
        }
    }

    for (i = 0; i < 5; i++) {
        data[i] = 0;
        for (j = 0; j < 8; j++) {
            start_time = gpioTick();
            while (gpioRead(DHT11_PIN) == 0) {
                end_time = gpioTick();
                duration = end_time - start_time;
                if (duration > DHT11_TIMEOUT) {
                    dht11_log_error(DHT11_ERROR_DATA_TIMEOUT);
                    return;
                }
            }

            start_time = gpioTick();
            while (gpioRead(DHT11_PIN) == 1) {
                end_time = gpioTick();
                duration = end_time - start_time;
                if (duration > DHT11_TIMEOUT) {
                    dht11_log_error(DHT11_ERROR_DATA_TIMEOUT);
                    return;
                }
            }

            if (duration > 40) {
                bit = 1;
            } else {
                bit = 0;
            }

            data[i] |= (bit << (7 - j));
        }
    }

    checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        dht11_log_error(DHT11_ERROR_CHECKSUM);
        return;
    }

    if (data[0] == 0 && data[2] == 0) {
        dht11_log_error(DHT11_ERROR_SENSOR_ABSENT);
        return;
    }

    dht11_log_reading(data[0], data[2]);
}

static void dht11_cleanup(int signum)
{
    gpioTerminate();
    fclose(reading_file);
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DHT11_PIN, PI_OUTPUT);
    gpioWrite(DHT11_PIN, 1);

    reading_file = fopen(DHT11_READING_FILE, "a");
    if (reading_file == NULL) {
        fprintf(stderr, "Failed to open %s\n", DHT11_READING_FILE);
        return 1;
    }

    signal(SIGINT, dht11_cleanup);
    signal(SIGTERM, dht11_cleanup);

    while (1) {
        dht11_read_sensor();
        gpioDelay(DHT11_READING_INTERVAL);
    }

    return 0;
}

