#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT31D_ADDR 0x44
#define SHT31D_CMD 0x2C06
#define SHT31D_DATA_LEN 6
#define SHT31D_CRC_LEN 1
#define SHT31D_CRC_POLY 0x31
#define SHT31D_CRC_INIT 0xFF
#define SHT31D_TEMP_OFFSET -45.0
#define SHT31D_TEMP_SCALE 175.0
#define SHT31D_HUMID_SCALE 100.0
#define SHT31D_RETRY_MAX 3
#define SHT31D_LOG_FILE "sht31d_data.log"
#define SHT31D_LOG_FMT "%04d-%02d-%02d %02d:%02d:%02d,%.1f,%.1f\n"

static int sht31d_bus = 1;
static int sht31d_handle = -1;
static FILE *sht31d_log = NULL;
static bool sht31d_running = true;

static void sht31d_log_data(float temp, float humid)
{
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(sht31d_log, SHT31D_LOG_FMT, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, temp, humid);
    fflush(sht31d_log);
}

static bool sht31d_crc_check(uint8_t *data, size_t len)
{
    uint8_t crc = SHT31D_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT31D_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == 0;
}

static bool sht31d_read_data(float *temp, float *humid)
{
    uint8_t data[SHT31D_DATA_LEN];
    for (int i = 0; i < SHT31D_RETRY_MAX; i++) {
        if (i > 0) {
            fprintf(stderr, "Retrying...\n");
        }
        if (i2cWriteWordData(sht31d_handle, SHT31D_CMD) < 0) {
            fprintf(stderr, "Failed to write command\n");
            continue;
        }
        if (gpioDelay(15000) < 0) {
            fprintf(stderr, "Failed to delay\n");
            continue;
        }
        if (i2cReadI2CBlockData(sht31d_handle, SHT31D_DATA_LEN, data) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }
        if (!sht31d_crc_check(data, SHT31D_DATA_LEN - SHT31D_CRC_LEN)) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }
        *temp = SHT31D_TEMP_OFFSET + SHT31D_TEMP_SCALE * (float) (data[0] << 8 | data[1]) / 65535.0;
        *humid = SHT31D_HUMID_SCALE * (float) (data[3] << 8 | data[4]) / 65535.0;
        return true;
    }
    return false;
}

static void sht31d_sig_handler(int sig)
{
    sht31d_running = false;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }
    sht31d_handle = i2cOpen(sht31d_bus, SHT31D_ADDR, 0);
    if (sht31d_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", sht31d_bus);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    sht31d_log = fopen(SHT31D_LOG_FILE, "a");
    if (sht31d_log == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", SHT31D_LOG_FILE);
        i2cClose(sht31d_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    signal(SIGINT, sht31d_sig_handler);
    signal(SIGTERM, sht31d_sig_handler);
    while (sht31d_running) {
        float temp, humid;
        if (sht31d_read_data(&temp, &humid)) {
            sht31d_log_data(temp, humid);
        } else {
            fprintf(stderr, "Failed to read data\n");
        }
        if (gpioDelay(5000000) < 0) {
            fprintf(stderr, "Failed to delay\n");
            break;
        }
    }
    fclose(sht31d_log);
    i2cClose(sht31d_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
