#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define SLAVE_ADDR 0x25
#define I2C_BUS 1
#define SDP800_CMD 0x362F
#define SDP800_DATA_LEN 9
#define SDP800_CRC_LEN 1
#define SDP800_SCALE_LEN 3
#define SDP800_SCALE_OFFSET 6
#define SDP800_SCALE_MASK 0xFFFF
#define SDP800_SCALE_SHIFT 16
#define SDP800_TEMP_OFFSET 2
#define SDP800_TEMP_MASK 0xFFFF
#define SDP800_TEMP_SHIFT 16
#define SDP800_TEMP_SCALE 200
#define SDP800_PRESS_OFFSET 0
#define SDP800_PRESS_MASK 0xFFFF
#define SDP800_PRESS_SHIFT 16

#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

#define LOG_FILE "flow_data.txt"

static int running = 1;

static void sig_handler(int signo)
{
    if (signo == SIGINT) {
        running = 0;
    }
}

static uint8_t crc8(uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp800(int handle, uint16_t *scale, uint16_t *temp, uint16_t *press)
{
    uint8_t buf[SDP800_DATA_LEN + SDP800_CRC_LEN];
    uint8_t crc;

    if (gpioI2CWriteWord(handle, SDP800_CMD) < 0) {
        fprintf(stderr, "Failed to write command\n");
        return -1;
    }

    if (gpioDelay(45000) < 0) {
        fprintf(stderr, "Failed to delay\n");
        return -1;
    }

    if (gpioI2CReadDevice(handle, buf, SDP800_DATA_LEN + SDP800_CRC_LEN) < 0) {
        fprintf(stderr, "Failed to read data\n");
        return -1;
    }

    crc = crc8(buf, SDP800_DATA_LEN);
    if (crc != buf[SDP800_DATA_LEN]) {
        fprintf(stderr, "CRC mismatch for data\n");
        return -1;
    }

    *scale = (buf[SDP800_SCALE_OFFSET] << 8) | buf[SDP800_SCALE_OFFSET + 1];
    *temp = (buf[SDP800_TEMP_OFFSET] << 8) | buf[SDP800_TEMP_OFFSET + 1];
    *press = (buf[SDP800_PRESS_OFFSET] << 8) | buf[SDP800_PRESS_OFFSET + 1];

    return 0;
}

static int log_sdp800(int handle, FILE *fp)
{
    uint16_t scale, temp, press;
    double temp_scaled, press_scaled;
    struct timespec ts;

    if (read_sdp800(handle, &scale, &temp, &press) < 0) {
        return -1;
    }

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Failed to get time\n");
        return -1;
    }

    temp_scaled = (double)temp / SDP800_TEMP_SCALE;
    press_scaled = (double)press / (scale & SDP800_SCALE_MASK);

    fprintf(fp, "%ld.%09ld %f %f\n", ts.tv_sec, ts.tv_nsec, temp_scaled, press_scaled);

    return 0;
}

int main(void)
{
    int handle;
    FILE *fp;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    handle = gpioI2COpen(I2C_BUS, SLAVE_ADDR);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);

    while (running) {
        if (log_sdp800(handle, fp) < 0) {
            break;
        }
    }

    fclose(fp);
    gpioI2CClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

