#include <pigpio.h>

#define HDC1080_ADDR 0x40
#define HDC1080_CONFIG_REG 0x02
#define HDC1080_TEMP_REG 0x00
#define HDC1080_TEMP_RES 14
#define HDC1080_HUMID_REG 0x01
#define HDC1080_HUMID_RES 14
#define HDC1080_TEMP_OFFSET -40.0
#define HDC1080_TEMP_SCALE 165.0
#define HDC1080_HUMID_SCALE 100.0
#define HDC1080_CONVERSION_TIME 20
#define HDC1080_CONVERSION_TIME_US 20000
#define HDC1080_I2C_BUS 1
#define HDC1080_I2C_HANDLE 0
#define HDC1080_I2C_TIMEOUT 1000
#define HDC1080_I2C_RETRIES 10
#define HDC1080_LOG_FILE "enviro_log.txt"
#define HDC1080_LOG_FORMAT "%ld,%.2f,%.2f\n"
#define HDC1080_LOG_INTERVAL 5

int main(void)
{
    int i2c_handle;
    int i2c_status;
    int i2c_retries;
    int i2c_timeout;
    int i2c_bus;
    int i2c_addr;
    int i2c_config_reg;
    int i2c_temp_reg;
    int i2c_humid_reg;
    int i2c_temp_res;
    int i2c_humid_res;
    int i2c_temp_raw;
    int i2c_humid_raw;
    float i2c_temp;
    float i2c_humid;
    time_t i2c_time;
    struct tm *i2c_tm;
    char i2c_time_str[20];
    FILE *i2c_log;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(HDC1080_I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "i2cOpen failed\n");
        gpioTerminate();
        return 1;
    }

    i2c_status = i2cSetSlaveAddress(i2c_handle, HDC1080_ADDR);
    if (i2c_status < 0)
    {
        fprintf(stderr, "i2cSetSlaveAddress failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2c_status = i2cSetTimeout(i2c_handle, HDC1080_I2C_TIMEOUT);
    if (i2c_status < 0)
    {
        fprintf(stderr, "i2cSetTimeout failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2c_status = i2cSetFlags(i2c_handle, I2C_FLAGS_NO_RD_ACK);
    if (i2c_status < 0)
    {
        fprintf(stderr, "i2cSetFlags failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2c_status = i2cSetSlaveFlags(i2c_handle, I2C_SLAVE_FLAGS_READ_LEN_MAX);
    if (i2c_status < 0)
    {
        fprintf(stderr, "i2cSetSlaveFlags failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2c_status = i2cSetSlaveReadLength(i2c_handle, 4);
    if (i2c_status < 0)
    {
        fprintf(stderr, "i2cSetSlaveReadLength failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2c_status = i2cWriteByteData(i2c_handle, HDC1080_CONFIG_REG, (HDC1080_TEMP_RES << 12) | (HDC1080_HUMID_RES << 8));
    if (i2c_status < 0)
    {
        fprintf(stderr, "i2cWriteByteData failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2c_log = fopen(HDC1080_LOG_FILE, "w");
    if (i2c_log == NULL)
    {
        fprintf(stderr, "fopen failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        i2c_status = i2cWriteByte(i2c_handle, HDC1080_TEMP_REG);
        if (i2c_status < 0)
        {
            fprintf(stderr, "i2cWriteByte failed\n");
            break;
        }

        gpioDelay(HDC1080_CONVERSION_TIME_US);

        i2c_status = i2cReadDevice(i2c_handle, (char *)&i2c_temp_raw, 2);
        if (i2c_status < 0)
        {
            fprintf(stderr, "i2cReadDevice failed\n");
            break;
        }

        i2c_status = i2cReadDevice(i2c_handle, (char *)&i2c_humid_raw, 2);
        if (i2c_status < 0)
        {
            fprintf(stderr, "i2cReadDevice failed\n");
            break;
        }

        i2c_temp = (i2c_temp_raw / 65536.0) * HDC1080_TEMP_SCALE + HDC1080_TEMP_OFFSET;
        i2c_humid = (i2c_humid_raw / 65536.0) * HDC1080_HUMID_SCALE;

        i2c_time = time(NULL);
        i2c_tm = localtime(&i2c_time);
        strftime(i2c_time_str, sizeof(i2c_time_str), "%Y-%m-%d %H:%M:%S", i2c_tm);

        fprintf(i2c_log, HDC1080_LOG_FORMAT, i2c_time, i2c_temp, i2c_humid);
        fflush(i2c_log);

        gpioDelay(HDC1080_LOG_INTERVAL * 1000000);
    }

    fclose(i2c_log);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
