#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <math.h>

#define I2C_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define POLYNOMIAL 0x31
#define CRC_INIT 0xFF

int main(int argc, char *argv[]) {
    int fd;
    int rc;
    int i;
    int crc;
    int raw;
    double celsius;
    char buf[3];
    struct timespec ts;
    struct tm *tm;
    char time_str[64];
    FILE *fp;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }

    rc = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (rc < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        exit(1);
    }

    fp = fopen("temperature_log.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    while (1) {
        rc = write(fd, "\x2C\xE0", 2);
        if (rc != 2) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            exit(1);
        }

        usleep(10000);

        rc = read(fd, buf, 3);
        if (rc != 3) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            exit(1);
        }

        crc = CRC_INIT;
        for (i = 0; i < 2; i++) {
            crc ^= buf[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ POLYNOMIAL;
                } else {
                    crc = (crc << 1);
                }
            }
        }

        if (crc != buf[2]) {
            fprintf(stderr, "CRC mismatch\n");
            exit(1);
        }

        raw = (buf[0] << 8) | buf[1];
        celsius = -45 + 175 * raw / 65535.0;

        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(time_str, sizeof(time_str), "%FT%T", tm);

        fprintf(fp, "%s.%03ld %f\n", time_str, ts.tv_nsec / 1000000, celsius);
        fflush(fp);

        sleep(5);
    }

    fclose(fp);
    close(fd);

    return 0;
}

