#include <pigpio.h>

#define I2C_ADDR 0x62
#define I2C_BUS 1
#define I2C_TIMEOUT 1000
#define I2C_RETRIES 10
#define I2C_DELAY 5000
#define BUF_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define LOG_FILE_PREFIX "scd40_data_"
#define LOG_FILE_SUFFIX ".csv"
#define LOG_ERROR_FILE "/var/log/scd40_error.log"

typedef struct {
    uint32_t timestamp;
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} reading_t;

typedef struct {
    reading_t readings[BUF_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} buffer_t;

volatile sig_atomic_t running = 1;
buffer_t buffer;

void sigint_handler(int signum) {
    running = 0;
}

void log_error(const char *message) {
    FILE *error_file = fopen(LOG_ERROR_FILE, "a");
    if (error_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0';
        fprintf(error_file, "%s: %s\n", timestamp, message);
        fclose(error_file);
    }
}

void log_readings(const char *filename, const reading_t *readings, int count) {
    FILE *log_file = fopen(filename, "w");
    if (log_file) {
        fprintf(log_file, "Timestamp,CO2,Temperature,Humidity\n");
        for (int i = 0; i < count; i++) {
            fprintf(log_file, "%u,%u,%u,%u\n", readings[i].timestamp, readings[i].co2, readings[i].temperature, readings[i].humidity);
        }
        fclose(log_file);
    } else {
        log_error("Failed to open log file");
    }
}

void *log_thread(void *arg) {
    while (running) {
        sleep(60);
        pthread_mutex_lock(&buffer.mutex);
        if (buffer.count > 0) {
            char filename[100];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", tm);
            strcat(filename, LOG_FILE_SUFFIX);
            log_readings(filename, buffer.readings, buffer.count);
            buffer.count = 0;
            buffer.head = 0;
            buffer.tail = 0;
        }
        pthread_mutex_unlock(&buffer.mutex);
    }
    return NULL;
}

uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

bool validate_crc(const uint8_t *data, int len) {
    return crc8(data, len) == data[len];
}

bool read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t data[9];
    if (i2cReadDevice(I2C_BUS, I2C_ADDR, data, 9) < 0) {
        log_error("Failed to read measurement");
        return false;
    }
    if (!validate_crc(data, 3) || !validate_crc(data + 3, 3) || !validate_crc(data + 6, 3)) {
        log_error("CRC check failed");
        return false;
    }
    *co2 = (data[0] << 8) | data[1];
    *temperature = (data[3] << 8) | data[4];
    *humidity = (data[6] << 8) | data[7];
    return true;
}

void *main_loop(void *arg) {
    while (running) {
        uint16_t co2, temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity)) {
            reading_t reading = {
                .timestamp = time(NULL),
                .co2 = co2,
                .temperature = temperature,
                .humidity = humidity
            };
            pthread_mutex_lock(&buffer.mutex);
            buffer.readings[buffer.head] = reading;
            buffer.head = (buffer.head + 1) % BUF_SIZE;
            if (buffer.count < BUF_SIZE) {
                buffer.count++;
            }
            pthread_mutex_unlock(&buffer.mutex);
        }
        sleep(I2C_DELAY / 1000);
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }
    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cSetTimeout(handle, I2C_TIMEOUT) < 0) {
        log_error("Failed to set I2C timeout");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cSetSlaveAddress(handle, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cSetSlaveTimeout(handle, I2C_TIMEOUT) < 0) {
        log_error("Failed to set I2C slave timeout");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (i2cSetSlaveRetries(handle, I2C_RETRIES) < 0) {
        log_error("Failed to set I2C slave retries");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    uint8_t start_command[2] = {0x21, 0xB1};
    if (i2cWriteDevice(handle, start_command, 2) < 0) {
        log_error("Failed to send start command");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    sleep(1);
    pthread_t main_thread, log_thread;
    pthread_mutex_init(&buffer.mutex, NULL);
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;
    if (pthread_create(&log_thread, NULL, log_thread, NULL) != 0) {
        log_error("Failed to create log thread");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (pthread_create(&main_thread, NULL, main_loop, NULL) != 0) {
        log_error("Failed to create main thread");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    signal(SIGINT, sigint_handler);
    pthread_join(main_thread, NULL);
    uint8_t stop_command[2] = {0x3F, 0x86};
    if (i2cWriteDevice(handle, stop_command, 2) < 0) {
        log_error("Failed to send stop command");
    }
    pthread_join(log_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

