#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I 0x08
#define CALIBRATION_COEFFICIENTS 0x05
#define MEASUREMENT_TRIGGER 0x00
#define MEASUREMENT_DATA 0x00
#define MEASUREMENT_DATA_LENGTH 6
#define SAMPLE_INTERVAL 5
#define FILE_NAME "environmental_data.txt"

int main(void)
{
    int i2cHandle;
    uint8_t whoAmI;
    uint8_t calibrationCoefficients[4];
    uint8_t measurementData[MEASUREMENT_DATA_LENGTH];
    uint32_t c0, c1, c2, c3;
    double p, t;
    FILE *file;
    time_t timestamp;
    struct tm *timeInfo;
    char timeString[20];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadByteData(i2cHandle, WHO_AM_I, &whoAmI) < 0)
    {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (whoAmI != 0x08)
    {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", whoAmI);
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadI2CBlockData(i2cHandle, CALIBRATION_COEFFICIENTS, 4, calibrationCoefficients) < 0)
    {
        fprintf(stderr, "Failed to read calibration coefficients.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    c0 = (calibrationCoefficients[0] << 8) | calibrationCoefficients[1];
    c1 = (calibrationCoefficients[2] << 8) | calibrationCoefficients[3];
    c2 = (calibrationCoefficients[4] << 8) | calibrationCoefficients[5];
    c3 = (calibrationCoefficients[6] << 8) | calibrationCoefficients[7];

    file = fopen(FILE_NAME, "a");
    if (file == NULL)
    {
        fprintf(stderr, "Failed to open file.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1)
    {
        if (i2cWriteByteData(i2cHandle, MEASUREMENT_TRIGGER, 0x00) < 0)
        {
            fprintf(stderr, "Failed to trigger measurement.\n");
            continue;
        }

        gpioDelay(10000);

        if (i2cReadI2CBlockData(i2cHandle, MEASUREMENT_DATA, MEASUREMENT_DATA_LENGTH, measurementData) < 0)
        {
            fprintf(stderr, "Failed to read measurement data.\n");
            continue;
        }

        p = (measurementData[0] << 16) | (measurementData[1] << 8) | measurementData[2];
        t = (measurementData[3] << 16) | (measurementData[4] << 8) | measurementData[5];

        p = (p / 4294967296.0) * 1000.0;
        t = (t / 4294967296.0) * 1000.0;

        p = (p - c0) / c1;
        t = (t - c2) / c3;

        timestamp = time(NULL);
        timeInfo = localtime(&timestamp);
        strftime(timeString, sizeof(timeString), "%FT%T%z", timeInfo);

        fprintf(file, "%s, %.2f, %.2f\n", timeString, p, t);
        fflush(file);

        printf("%s, %.2f, %.2f\n", timeString, p, t);

        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    fclose(file);
    i2cClose(i2cHandle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

