#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x38
#define RELAY_GPIO 17
#define RELAY_ACTIVE_HIGH 1
#define RETRIES 3
#define RETRY_DELAY_MS 10
#define MEASURE_DELAY_MS 80
#define POLL_DELAY_S 5

static int i2c_fd = -1;
static struct gpiod_line *relay_line = NULL;

static void cleanup(void)
{
    if (relay_line) {
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(0);
}

static int init_i2c(void)
{
    int ret;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int init_relay(void)
{
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay_line, "dehumidifier", RELAY_ACTIVE_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(relay_line);
        relay_line = NULL;
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);

    return 0;
}

static int init_sensor(void)
{
    int ret;
    unsigned char buf[3] = {0xBE, 0x08, 0x00};

    ret = write(i2c_fd, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C bus: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int measure(void)
{
    int ret;
    unsigned char buf[3] = {0xAC, 0x33, 0x00};

    ret = write(i2c_fd, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C bus: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASURE_DELAY_MS * 1000);

    return 0;
}

static int read_data(unsigned char *data)
{
    int ret;
    unsigned char buf[6];

    ret = read(i2c_fd, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ret != sizeof(buf)) {
        fprintf(stderr, "Failed to read 6 bytes from I2C bus\n");
        return -1;
    }

    if (buf[0] & 0x01) {
        fprintf(stderr, "Sensor is busy\n");
        return -1;
    }

    if (!(buf[0] & 0x02)) {
        fprintf(stderr, "Sensor is not calibrated\n");
        return -1;
    }

    memcpy(data, buf + 1, 5);

    return 0;
}

static int read_humidity(void)
{
    int ret;
    unsigned char data[5];
    unsigned int humidity;

    ret = measure();
    if (ret < 0) {
        return -1;
    }

    ret = read_data(data);
    if (ret < 0) {
        return -1;
    }

    humidity = (data[0] << 16) | (data[1] << 8) | data[2];
    humidity = (humidity * 1000) >> 12;

    return humidity;
}

static int set_relay(int state)
{
    int ret;

    ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int retry_i2c(int (*func)(void))
{
    int ret;
    int i;

    for (i = 0; i < RETRIES; i++) {
        ret = func();
        if (ret == 0) {
            return 0;
        }

        usleep(RETRY_DELAY_MS * 1000);
    }

    return -1;
}

static void log_humidity(int humidity)
{
    time_t t;
    struct tm *tm;
    char buf[64];

    t = time(NULL);
    tm = localtime(&t);
    if (tm) {
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
        printf("%s: Humidity = %d.%03d%%\n", buf, humidity / 1000, humidity % 1000);
    }
}

int main(void)
{
    int ret;
    int humidity;
    int relay_state;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = init_i2c();
    if (ret < 0) {
        return -1;
    }

    ret = init_relay();
    if (ret < 0) {
        cleanup();
        return -1;
    }

    ret = init_sensor();
    if (ret < 0) {
        cleanup();
        return -1;
    }

    while (1) {
        ret = retry_i2c(read_humidity);
        if (ret < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        humidity = ret;
        log_humidity(humidity);

        relay_state = (humidity > 60000) ? 1 : 0;
        ret = set_relay(relay_state);
        if (ret < 0) {
            fprintf(stderr, "Failed to set relay\n");
            continue;
        }

        sleep(POLL_DELAY_S);
    }

    cleanup();

    return 0;
}

