            return 0;
        }

        usleep(RETRY_DELAY_MS * 1000);
    }

    return -1;
}

static void log_humidity(int humidity)
{
    time_t t;
    struct tm *tm;
    char buf[64];

    t = time(NULL);
    tm = localtime(&t);
    if (tm) {
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
        printf("%s: Humidity = %d.%03d%%\n", buf, humidity / 1000, humidity % 1000);
    }
}

int main(void)
{
    int ret;
    int humidity;
    int relay_state;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = init_i2c();
    if (ret < 0) {
        return -1;
    }

    ret = init_relay();
    if (ret < 0) {
        cleanup();
        return -1;
    }

    ret = init_sensor();
    if (ret < 0) {
        cleanup();
        return -1;
    }

    while (1) {
        ret = retry_i2c(read_humidity);
        if (ret < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        humidity = ret;
        log_humidity(humidity);

        relay_state = (humidity > 60000) ? 1 : 0;
        ret = set_relay(relay_state);
        if (ret < 0) {
            fprintf(stderr, "Failed to set relay\n");
            continue;
        }

        sleep(POLL_DELAY_S);
    }

    cleanup();

    return 0;
}
