#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x76
#define I2C_TIMEOUT 1000
#define I2C_RETRIES 3
#define I2C_DELAY 10000
#define I2C_CHIP_ID 0xD0
#define I2C_CALIB_START 0x88
#define I2C_CALIB_SIZE 24
#define I2C_CTRL_MEAS 0xF4
#define I2C_CTRL_MEAS_VAL 0x27
#define I2C_DATA_START 0xF7
#define I2C_DATA_SIZE 6
#define I2C_CHIP_ID_VAL 0x58
#define I2C_PRESS_MIN 980
#define I2C_PRESS_MAX 1020
#define I2C_LOG_FILE "pressure_log.txt"

static int i2c_handle = -1;
static bool running = true;

static void i2c_exit(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
}

static void i2c_init(void)
{
    i2c_exit();
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        exit(EXIT_FAILURE);
    }
}

static void i2c_read(uint8_t reg, uint8_t *buf, size_t len)
{
    int ret;

    ret = i2cWriteByte(i2c_handle, reg);
    if (ret < 0) {
        fprintf(stderr, "i2cWriteByte failed: %d\n", ret);
        exit(EXIT_FAILURE);
    }

    ret = i2cReadDevice(i2c_handle, buf, len);
    if (ret < 0) {
        fprintf(stderr, "i2cReadDevice failed: %d\n", ret);
        exit(EXIT_FAILURE);
    }
}

static void i2c_write(uint8_t reg, uint8_t val)
{
    int ret;

    ret = i2cWriteByteData(i2c_handle, reg, val);
    if (ret < 0) {
        fprintf(stderr, "i2cWriteByteData failed: %d\n", ret);
        exit(EXIT_FAILURE);
    }
}

static void i2c_verify_chip_id(void)
{
    uint8_t chip_id;

    i2c_read(I2C_CHIP_ID, &chip_id, 1);
    if (chip_id != I2C_CHIP_ID_VAL) {
        fprintf(stderr, "chip ID mismatch: 0x%02x\n", chip_id);
        exit(EXIT_FAILURE);
    }
}

static void i2c_read_calibration(uint8_t *buf)
{
    i2c_read(I2C_CALIB_START, buf, I2C_CALIB_SIZE);
}

static void i2c_write_ctrl_meas(void)
{
    i2c_write(I2C_CTRL_MEAS, I2C_CTRL_MEAS_VAL);
}

static void i2c_read_data(uint8_t *buf)
{
    i2c_read(I2C_DATA_START, buf, I2C_DATA_SIZE);
}

static void i2c_read_raw_data(uint8_t *buf)
{
    i2c_write_ctrl_meas();
    usleep(I2C_DELAY);
    i2c_read_data(buf);
}

static void i2c_read_raw_data_retry(uint8_t *buf)
{
    int retries = I2C_RETRIES;

    while (retries--) {
        i2c_read_raw_data(buf);
        if (buf[0] != 0) {
            return;
        }
        i2c_init();
    }

    fprintf(stderr, "i2c_read_raw_data_retry failed\n");
    exit(EXIT_FAILURE);
}

