#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENABLE_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24

#define MOTOR_FORWARD 0
#define MOTOR_BACKWARD 1

#define MOTOR_RUN_TIME 5

#define LOG_FILE "rain_sensor.log"

struct gpiod_chip *chip;
struct gpiod_line *rain_sensor_line;
struct gpiod_line *motor_enable_line;
struct gpiod_line *motor_in1_line;
struct gpiod_line *motor_in2_line;

int motor_running = 0;

void log_event(char *event)
{
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';

    fprintf(log_file, "%s: %s\n", time_str, event);
    fclose(log_file);
}

void motor_stop()
{
    if (motor_running) {
        gpiod_line_set_value(motor_enable_line, 0);
        gpiod_line_set_value(motor_in1_line, 0);
        gpiod_line_set_value(motor_in2_line, 0);
        motor_running = 0;
        log_event("Motor stopped");
    }
}

void motor_run(int direction)
{
    if (!motor_running) {
        gpiod_line_set_value(motor_enable_line, 1);
        if (direction == MOTOR_FORWARD) {
            gpiod_line_set_value(motor_in1_line, 1);
            gpiod_line_set_value(motor_in2_line, 0);
        } else {
            gpiod_line_set_value(motor_in1_line, 0);
            gpiod_line_set_value(motor_in2_line, 1);
        }
        motor_running = 1;
        log_event("Motor started");
    }
}

void motor_run_for_time(int direction, int time_seconds)
{
    motor_run(direction);
    sleep(time_seconds);
    motor_stop();
}

void rain_sensor_callback(struct gpiod_line *line, void *data)
{
    int value = gpiod_line_get_value(line);
    if (value == 0) {
        log_event("Rain detected");
        motor_run_for_time(MOTOR_FORWARD, MOTOR_RUN_TIME);
    }
}

void cleanup()
{
    motor_stop();
    gpiod_line_release(rain_sensor_line);
    gpiod_line_release(motor_enable_line);
    gpiod_line_release(motor_in1_line);
    gpiod_line_release(motor_in2_line);
    gpiod_chip_close(chip);
}

void signal_handler(int signal)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main()
{
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_number(0);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_GPIO);
    if (rain_sensor_line == NULL) {
        fprintf(stderr, "Error getting rain sensor GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    motor_enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_GPIO);
    if (motor_enable_line == NULL) {
        fprintf(stderr, "Error getting motor enable GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_GPIO);
    if (motor_in1_line == NULL) {
        fprintf(stderr, "Error getting motor IN1 GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_GPIO);
    if (motor_in2_line == NULL) {
        fprintf(stderr, "Error getting motor IN2 GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(rain_sensor_line, "rain_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting rain sensor GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(motor_enable_line, "motor_enable", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting motor enable GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(motor_in1_line, "motor_in1", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting motor IN1 GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(motor_in2_line, "motor_in2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting motor IN2 GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_event_request(rain_sensor_line, GPIOD_LINE_EVENT_RISING_EDGE, rain_sensor_callback, NULL);
    if (ret < 0) {
        fprintf(stderr, "Error requesting rain sensor event: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(2);
    }

    cleanup();
    return EXIT_SUCCESS;
}

