#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_CAL_START 0xAA
#define BMP180_CAL_END 0xBF
#define BMP180_REG_CTRL 0xF4
#define BMP180_REG_DATA 0xF6
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRES 0x34
#define BMP180_LOG_FILE "bmp180_log.txt"
#define BMP180_LOG_INTERVAL 500

static int bmp180_fd = -1;
static int bmp180_timer = -1;
static int bmp180_log_fd = -1;

static void bmp180_log_cleanup(void)
{
    if (bmp180_log_fd >= 0) {
        close(bmp180_log_fd);
        bmp180_log_fd = -1;
    }
}

static void bmp180_cleanup(void)
{
    if (bmp180_timer >= 0) {
        gpioSetTimerFuncEx(bmp180_timer, NULL, NULL);
        bmp180_timer = -1;
    }
    if (bmp180_fd >= 0) {
        gpioTerminate();
        bmp180_fd = -1;
    }
    bmp180_log_cleanup();
}

static void bmp180_signal_handler(int signum)
{
    bmp180_cleanup();
    exit(EXIT_SUCCESS);
}

static int bmp180_init(void)
{
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n",
                gpioErrMsg(ret));
        return -1;
    }

    bmp180_fd = i2cOpen(1, BMP180_ADDR, 0);
    if (bmp180_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", gpioErrMsg(ret));
        return -1;
    }

    return 0;
}

static int bmp180_validate_calibration(void)
{
    uint8_t buf[22];
    int ret;

    ret = i2cReadDevice(bmp180_fd, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n",
                gpioErrMsg(ret));
        return -1;
    }

    if (buf[0] != 0x55) {
        fprintf(stderr, "Invalid calibration data\n");
        return -1;
    }

    return 0;
}

static int bmp180_read_temperature(int32_t *temp)
{
    uint8_t buf[2];
    int ret;

    ret = i2cWriteByte(bmp180_fd, BMP180_REG_CTRL, BMP180_CMD_TEMP);
    if (ret < 0) {
        fprintf(stderr, "Failed to write command: %s\n", gpioErrMsg(ret));
        return -1;
    }

    ret = i2cReadDevice(bmp180_fd, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "Failed to read temperature data: %s\n",
                gpioErrMsg(ret));
        return -1;
    }

    *temp = (buf[0] << 8) | buf[1];

    return 0;
}

static int bmp180_read_pressure(int32_t *pres)
{
    uint8_t buf[3];
    int ret;

    ret = i2cWriteByte(bmp180_fd, BMP180_REG_CTRL, BMP180_CMD_PRES);
    if (ret < 0) {
        fprintf(stderr, "Failed to write command: %s\n", gpioErrMsg(ret));
        return -1;
    }

    ret = i2cReadDevice(bmp180_fd, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "Failed to read pressure data: %s\n",
                gpioErrMsg(ret));
        return -1;
    }

    *pres = (buf[0] << 16) | (buf[1] << 8) | buf[2];

    return 0;
}

static void bmp180_log_timer_callback(int timer_id, void *user_data)
{
    int32_t temp, pres;
    int ret;

    ret = bmp180_read_temperature(&temp);
    if (ret < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return;
    }

    ret = bmp180_read_pressure(&pres);
    if (ret < 0) {
        fprintf(stderr, "Failed to read pressure\n");
        return;
    }

    ret = dprintf(bmp180_log_fd, "%d %d\n", temp, pres);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return;
    }
}

static int bmp180_log_init(void)
{
    bmp180_log_fd = open(BMP180_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (bmp180_log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    bmp180_timer = gpioSetTimerFunc(BMP180_LOG_INTERVAL, bmp180_log_timer_callback, NULL);
    if (bmp180_timer < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", gpioErrMsg(bmp180_timer));
        bmp180_log_cleanup();
        return -1;
    }

    return 0;
}

int main(void)
{
    int ret;

    signal(SIGINT, bmp180_signal_handler);
    signal(SIGTERM, bmp180_signal_handler);

    ret = bmp180_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize BMP180\n");
        goto error;
    }

    ret = bmp180_validate_calibration();
    if (ret < 0) {
        fprintf(stderr, "Failed to validate calibration data\n");
        goto error;
    }

    ret = bmp180_log_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize log\n");
        goto error;
    }

    while (1) {
        sleep(1);
    }

error:
    bmp180_cleanup();
    return EXIT_FAILURE;
}

