#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define FAN_FREQ 25000
#define FAN_RANGE 255
#define FAN_MIN_TEMP 40
#define FAN_MAX_TEMP 70
#define FAN_LOG_FILE "fan_log.txt"
#define FAN_LOG_INTERVAL 5

static int fan_handle = -1;
static FILE *fan_log_file = NULL;

static void fan_log(int temp, int duty)
{
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char time_str[64];

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fan_log_file, "%s: %d°C, %d%%\n", time_str, temp, duty);
    fflush(fan_log_file);
}

static void fan_set_duty(int duty)
{
    if (duty < 0)
        duty = 0;
    else if (duty > FAN_RANGE)
        duty = FAN_RANGE;

    gpioPWM(FAN_GPIO, duty);
    fan_log(0, duty);
}

static void fan_set_temp(int temp)
{
    int duty = (temp - FAN_MIN_TEMP) * FAN_RANGE / (FAN_MAX_TEMP - FAN_MIN_TEMP);
    fan_set_duty(duty);
}

static void fan_cleanup(void)
{
    if (fan_handle >= 0) {
        gpioPWM(FAN_GPIO, 0);
        gpioSetMode(FAN_GPIO, PI_INPUT);
        gpioTerminate();
    }

    if (fan_log_file)
        fclose(fan_log_file);
}

static void fan_sig_handler(int sig)
{
    fan_cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int temp;
    char temp_str[16];
    char *endptr;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, FAN_FREQ);
    gpioSetPWMrange(FAN_GPIO, FAN_RANGE);

    fan_log_file = fopen(FAN_LOG_FILE, "w");
    if (!fan_log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, fan_sig_handler);
    signal(SIGTERM, fan_sig_handler);

    while (1) {
        if (gpioRead_file("/sys/class/thermal/thermal_zone0/temp", temp_str, sizeof(temp_str)) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            return EXIT_FAILURE;
        }

        temp = strtol(temp_str, &endptr, 10);
        if (*endptr != '\0') {
            fprintf(stderr, "Invalid temperature value\n");
            return EXIT_FAILURE;
        }

        fan_set_temp(temp / 1000);
        fan_log(temp / 1000, 0);

        sleep(FAN_LOG_INTERVAL);
    }

    return EXIT_SUCCESS;
}

