#include <inttypes.h>
#include <pthread.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define I2C_TEMP_REG 0x00
#define I2C_TEMP_SCALE 256.0
#define I2C_TEMP_THRESHOLD 28.0
#define I2C_TEMP_PERIOD 1
#define GPIO_LED 18
#define GPIO_LED_ON 1
#define GPIO_LED_OFF 0
#define BUFFER_SIZE 60

static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static pthread_t thread;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static float buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_tail = 0;

static void cleanup(void)
{
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void sigint_handler(int signum)
{
    (void)signum;
    cleanup();
    exit(EXIT_SUCCESS);
}

static void *read_temperature(void *arg)
{
    (void)arg;
    while (true) {
        int16_t temp;
        if (read(i2c_fd, &temp, sizeof(temp)) != sizeof(temp)) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            cleanup();
            exit(EXIT_FAILURE);
        }
        temp >>= 5;
        float temp_c = (float)temp / I2C_TEMP_SCALE;
        pthread_mutex_lock(&mutex);
        buffer[buffer_head] = temp_c;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_head == buffer_tail) {
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }
        pthread_mutex_unlock(&mutex);
        if (temp_c > I2C_TEMP_THRESHOLD) {
            gpiod_line_set_value(led_line, GPIO_LED_ON);
        } else {
            gpiod_line_set_value(led_line, GPIO_LED_OFF);
        }
        sleep(I2C_TEMP_PERIOD);
    }
    return NULL;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_number(GPIO_CHIP_NUMBER);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(led_line, "led", GPIO_LED_OFF) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&thread, NULL, read_temperature, NULL) != 0) {
        fprintf(stderr, "Failed to create thread: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (true) {
        pthread_mutex_lock(&mutex);
        float sum = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i];
        }
        float avg = sum / BUFFER_SIZE;
        pthread_mutex_unlock(&mutex);
        printf("Average temperature: %.2f\n", avg);
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

