    if (i2cRead(handle, BMP180_READ_ADDR, data, 3) != 0) {
        fprintf(stderr, "Failed to read from BMP180\n");
        return -1;
    }

    press = (data[0] << 16) | (data[1] << 8) | data[2];
    press >>= (8 - BMP180_OSS);

    return press;
}

int32_t BMP180_get_temp(int32_t temp) {
    int32_t X1, X2, T;

    X1 = (temp - calibration.AC6) * calibration.AC5 >> 15;
    X2 = (calibration.MC << 11) / (X1 + calibration.MD);
    T = X1 + X2;

    return T;
}

int32_t BMP180_get_press(int32_t temp, int32_t press) {
    int32_t X1, X2, X3, B3, B5, B6, P;
    uint32_t B4, B7;

    X1 = (temp - calibration.AC6) * calibration.AC5 >> 15;
    X2 = (calibration.MC << 11) / (X1 + calibration.MD);
    B5 = X1 + X2;
    B6 = B5 - 4000;
    X1 = (calibration.B2 * (B6 * B6 >> 12)) >> 11;
    X2 = (calibration.AC2 * B6) >> 11;
    X3 = X1 + X2;
    B3 = (((calibration.AC1 * 4 + X3) << BMP180_OSS) + 2) >> 2;
    X1 = (calibration.AC3 * B6) >> 13;
    X2 = (calibration.B1 * (B6 * B6 >> 12)) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    B4 = (calibration.AC4 * (uint32_t)(X3 + 32768)) >> 15;
    B7 = ((uint32_t)press - B3) * (50000 >> BMP180_OSS);
    if (B7 < 0x80000000) {
        P = (B7 << 1) / B4;
    } else {
        P = (B7 / B4) << 1;
    }
    X1 = (P >> 8) * (P >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * P) >> 16;
    P = P + ((X1 + X2 + 3791) >> 4);

    return P;
}

void BMP180_read_calibration(int handle) {
    uint8_t data[BMP180_CAL_LEN];

    if (i2cRead(handle, BMP180_CAL_ADDR, data, BMP180_CAL_LEN) != 0) {
        fprintf(stderr, "Failed to read from BMP180\n");
        exit(1);
    }

    calibration.AC1 = (data[0] << 8) | data[1];
    calibration.AC2 = (data[2] << 8) | data[3];
    calibration.AC3 = (data[4] << 8) | data[5];
    calibration.AC4 = (data[6] << 8) | data[7];
    calibration.AC5 = (data[8] << 8) | data[9];
    calibration.AC6 = (data[10] << 8) | data[11];
    calibration.B1 = (data[12] << 8) | data[13];
    calibration.B2 = (data[14] << 8) | data[15];
    calibration.MB = (data[16] << 8) | data[17];
    calibration.MC = (data[18] << 8) | data[19];
    calibration.MD = (data[20] << 8) | data[21];
}

void BMP180_timer_callback(int handle) {
    int32_t temp, press;

    temp = BMP180_read_temp(handle);
    if (temp == -1) {
        return;
    }

    press = BMP180_read_press(handle);
    if (press == -1) {
        return;
    }

    temp = BMP180_get_temp(temp);
    press = BMP180_get_press(temp, press);

    buffer[buffer_index].timestamp = gpioTick();
    buffer[buffer_index].temp = temp;
    buffer[buffer_index].press = press;
    buffer_index = (buffer_index + 1) % BMP180_BUFFER_LEN;

    if (temp > BMP180_FAN_TEMP * 100) {
        gpioWrite(BMP180_FAN_PIN, 1);
    } else {
        gpioWrite(BMP180_FAN_PIN, 0);
    }
}

void BMP180_signal_handler(int signum) {
    gpioWrite(BMP180_FAN_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int handle;
    int timer;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        return 1;
    }

    handle = i2cOpen(1, BMP180_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C\n");
        return 1;
    }

    BMP180_read_calibration(handle);

    gpioSetMode(BMP180_FAN_PIN, PI_OUTPUT);
    gpioWrite(BMP180_FAN_PIN, 0);

    timer = gpioSetTimerFunc(BMP180_TIMER_MS, BMP180_timer_callback, handle);
    if (timer < 0) {
        fprintf(stderr, "Failed to set timer\n");
        return 1;
    }

    signal(SIGINT, BMP180_signal_handler);
    signal(SIGTERM, BMP180_signal_handler);

    while (1) {
        int i;

        for (i = 0; i < BMP180_BUFFER_LEN; i++) {
            int index = (buffer_index + i) % BMP180_BUFFER_LEN;
            printf("%u %d.%02d %d.%02d\n", buffer[index].timestamp, buffer[index].temp / 100, abs(buffer[index].temp % 100), buffer[index].press / 100, abs(buffer[index].press % 100));
        }

        sleep(1);
    }

    return 0;
}
