#include <pigpio.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define TEMP_THRESHOLD_LOW 40000
#define TEMP_THRESHOLD_HIGH 60000

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

#define PWM_RANGE 255

static volatile sig_atomic_t interrupted = 0;

static void sig_handler(int signo)
{
    interrupted = 1;
}

int main(void)
{
    int fd;
