        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RED_PIN, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpioSetMode(GREEN_PIN, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpioSetMode(BLUE_PIN, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", strerror(errno));
