    ret = gpioSetPWMfrequency(BLUE_PIN, 1000);
    if (ret < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpioPWM(RED_PIN, PWM_RANGE);
    if (ret < 0) {
        fprintf(stderr, "gpioPWM failed: %s\n", strerror(errno));
        goto cleanup;
