#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_PIN 4
#define DHT22_MAX_TIMINGS 85
#define DHT22_READ_RETRIES 3

#define HTTP_POST_URL "http://yourserver.com/api/humidity"
#define HTTP_POST_TIMEOUT_SEC 5

#define JSON_PAYLOAD_SIZE 128

#define LOG_ERROR(fmt, ...) fprintf(stderr, "[ERROR] " fmt "\n", ##__VA_ARGS__)
#define LOG_INFO(fmt, ...) fprintf(stdout, "[INFO] " fmt "\n", ##__VA_ARGS__)

static volatile sig_atomic_t g_exit_requested = 0;

static void sig_handler(int signum)
{
    g_exit_requested = 1;
}

static void init_signal_handler()
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

static int dht22_read_data(int *humidity, int *temperature)
{
    int timings[DHT22_MAX_TIMINGS];
    int count = 0;
    int last_state = 1;
    int i = 0;
    int j = 0;
    int checksum = 0;
    int data[5] = {0, 0, 0, 0, 0};

    if (gpioInitialise() < 0) {
        LOG_ERROR("Failed to initialize pigpio");
        return -1;
    }

    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    gpioWrite(DHT22_PIN, 0);
    usleep(1000 * 1000);
    gpioWrite(DHT22_PIN, 1);
    usleep(40);

    gpioSetMode(DHT22_PIN, PI_INPUT);

    while (gpioRead(DHT22_PIN) == 1 && i < DHT22_MAX_TIMINGS) {
        timings[i++] = micros();
    }

    while (gpioRead(DHT22_PIN) == 0 && i < DHT22_MAX_TIMINGS) {
        timings[i++] = micros();
    }

    while (i < DHT22_MAX_TIMINGS) {
        count = micros() - timings[i - 1];
        if (count > 100) {
            if (last_state == 1) {
                last_state = 0;
                data[j / 8] <<= 1;
            } else {
                last_state = 1;
                data[j / 8] |= 1;
                ++j;
            }
        }
        timings[i++] = micros();
    }

    for (i = 0; i < 40; ++i) {
        if (i >= 24 && i < 32) {
            data[0] <<= 1;
            data[0] |= timings[i] > 40 ? 1 : 0;
        } else if (i >= 16 && i < 24) {
            data[1] <<= 1;
            data[1] |= timings[i] > 40 ? 1 : 0;
        } else if (i >= 8 && i < 16) {
            data[2] <<= 1;
            data[2] |= timings[i] > 40 ? 1 : 0;
        } else if (i >= 0 && i < 8) {
            data[3] <<= 1;
            data[3] |= timings[i] > 40 ? 1 : 0;
        }
    }

    for (i = 0; i < 4; ++i) {
        checksum += data[i];
    }

    if (data[4] != (checksum & 0xFF)) {
        LOG_ERROR("Checksum mismatch");
        return -1;
    }

    *humidity = data[0];
    *temperature = data[2];

    return 0;
}

static size_t http_post_callback(void *contents, size_t size, size_t nmemb, void *userp)
{
    size_t realsize = size * nmemb;
    char *response = (char *)userp;

    memcpy(response, contents, realsize);
    response[realsize] = '\0';

    return realsize;
}

static int http_post(const char *url, const char *payload, char *response)
{
    CURL *curl = NULL;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, http_post_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)response);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, HTTP_POST_TIMEOUT_SEC);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            LOG_ERROR("curl_easy_perform() failed: %s", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            return -1;
        }

        curl_easy_cleanup(curl);
    }

    return 0;
}

int main(int argc, char *argv[])
{
    int humidity = 0;
    int temperature = 0;
    char json_payload[JSON_PAYLOAD_SIZE];
    char http_response[HTTP_POST_TIMEOUT_SEC * 1000];
    int ret = 0;
    int i = 0;

    init_signal_handler();

    while (i < DHT22_READ_RETRIES && !g_exit_requested) {
        ret = dht22_read_data(&humidity, &temperature);
        if (ret == 0) {
            break;
        }
        ++i;
    }

    if (ret != 0) {
        LOG_ERROR("Failed to read data from DHT22 sensor");
        return -1;
    }

    snprintf(json_payload, JSON_PAYLOAD_SIZE, "{\"humidity\":%d,\"temperature\":%d}", humidity, temperature);

    i = 0;
    while (i < DHT22_READ_RETRIES && !g_exit_requested) {
        ret = http_post(HTTP_POST_URL, json_payload, http_response);
        if (ret == 0) {
            break;
        }
        ++i;
    }

    if (ret != 0) {
        LOG_ERROR("Failed to send HTTP POST request");
        return -1;
    }

    LOG_INFO("HTTP POST response: %s", http_response);

    return 0;
}

