#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 25000
#define PWM_RANGE 100
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5000000

int fan_handle = -1;
FILE *log_file = NULL;

void cleanup(void)
{
    if (fan_handle >= 0)
    {
        gpioPWM(PWM_PIN, 0);
        gpioTerminate();
    }
    if (log_file)
    {
        fclose(log_file);
    }
}

void sig_handler(int signum)
{
    cleanup();
    exit(0);
}

int main(void)
{
    int temp, duty_cycle;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    fan_handle = gpioSetMode(PWM_PIN, PI_OUTPUT);
    if (fan_handle < 0)
    {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0)
    {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file)
    {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fprintf(log_file, "Timestamp,Temperature (°C),PWM Duty Cycle (%%)\n");

    while (1)
    {
        FILE *temp_file = fopen(TEMP_FILE, "r");
        if (!temp_file)
        {
            fprintf(stderr, "Failed to open temperature file\n");
            cleanup();
            return 1;
        }

        if (fscanf(temp_file, "%d", &temp) != 1)
        {
            fprintf(stderr, "Failed to read temperature\n");
            fclose(temp_file);
            cleanup();
            return 1;
        }

        fclose(temp_file);

        temp /= 1000; // Convert from millidegrees Celsius to degrees Celsius

        if (temp < 40)
        {
            duty_cycle = 0;
        }
        else if (temp > 70)
        {
            duty_cycle = PWM_RANGE;
        }
        else
        {
            duty_cycle = (temp - 40) * PWM_RANGE / 30;
        }

        if (gpioPWM(PWM_PIN, duty_cycle) < 0)
        {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            cleanup();
            return 1;
        }

        fprintf(log_file, "%ld,%d,%d\n", time(NULL), temp, duty_cycle);
        fflush(log_file);

        usleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

