#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

#define PIN_A 17
#define PIN_B 18
#define DEG_PER_PULSE 10.0
#define PULSES_PER_REV 360

int main(int argc, char *argv[])
{
    FILE *fp;
    int a, b, prev_a, prev_b, state, prev_state, i;
    double angle;
    struct timespec ts;
    char time_str[26];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIN_A, PI_INPUT);
    gpioSetMode(PIN_B, PI_INPUT);
    gpioSetPullUpDown(PIN_A, PI_PUD_UP);
    gpioSetPullUpDown(PIN_B, PI_PUD_UP);

    fp = fopen("encoder_log.txt", "w");
    if (fp == NULL)
    {
        fprintf(stderr, "Error opening file\n");
        return 1;
    }

    prev_a = gpioRead(PIN_A);
    prev_b = gpioRead(PIN_B);
    prev_state = prev_a | (prev_b << 1);
    angle = 0.0;

    while (1)
    {
        a = gpioRead(PIN_A);
        b = gpioRead(PIN_B);
        state = a | (b << 1);

        if (state != prev_state)
        {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

            switch (state)
            {
            case 0:
                if (prev_state == 1)
                {
                    angle += DEG_PER_PULSE;
                }
                else if (prev_state == 2)
                {
                    angle -= DEG_PER_PULSE;
                }
                break;
            case 1:
                if (prev_state == 0)
                {
                    angle -= DEG_PER_PULSE;
                }
                else if (prev_state == 3)
                {
                    angle += DEG_PER_PULSE;
                }
                break;
            case 2:
                if (prev_state == 0)
                {
                    angle += DEG_PER_PULSE;
                }
                else if (prev_state == 3)
                {
                    angle -= DEG_PER_PULSE;
                }
                break;
            case 3:
                if (prev_state == 1)
                {
                    angle -= DEG_PER_PULSE;
                }
                else if (prev_state == 2)
                {
                    angle += DEG_PER_PULSE;
                }
                break;
            }

            if (angle < 0.0)
            {
                angle += 360.0;
            }
            else if (angle >= 360.0)
