static int i2c_read(uint8_t reg, uint8_t *buf, size_t len)
{
    int ret;

    ret = write(i2c_fd, &reg, 1);
    if (ret < 0) {
        fprintf(stderr, "i2c_read: write: %s\n", strerror(errno));
        return -1;
    }
    if (ret != 1) {
        fprintf(stderr, "i2c_read: write: short write\n");
        return -1;
    }

    ret = read(i2c_fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "i2c_read: read: %s\n", strerror(errno));
        return -1;
    }
    if (ret != len) {
        fprintf(stderr, "i2c_read: read: short read\n");
        return -1;
    }

    return 0;
}

static int i2c_write(uint8_t reg, uint8_t *buf, size_t len)
{
    int ret;
    uint8_t *data;

    data = malloc(len + 1);
    if (!data) {
        fprintf(stderr, "i2c_write: malloc: %s\n", strerror(errno));
        return -1;
    }

    data[0] = reg;
    memcpy(&data[1], buf, len);

    ret = write(i2c_fd, data, len + 1);
    free(data);
    if (ret < 0) {
        fprintf(stderr, "i2c_write: write: %s\n", strerror(errno));
        return -1;
    }
    if (ret != len + 1) {
        fprintf(stderr, "i2c_write: write: short write\n");
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_number(GPIO_BUS);
    if (!chip) {
        fprintf(stderr, "gpio_init: gpiod_chip_open_by_number: %s\n", strerror(errno));
        return -1;
    }

    gpio_led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!gpio_led) {
        fprintf(stderr, "gpio_init: gpiod_chip_get_line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_led, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "gpio_init: gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_line_release(gpio_led);
        gpio_led = NULL;
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);

    return 0;
}

static int i2c_init(void)
{
    char i2c_dev[16];
    int ret;

    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "i2c_init: open: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "i2c_init: ioctl: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int log_init(void)
{
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "log_init: fopen: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_write(uint16_t red, uint16_t ir)
{
    int ret;
    struct timespec ts;

    ret = clock_gettime(CLOCK_REALTIME, &ts);
    if (ret < 0) {
        fprintf(stderr, "log_write: clock_gettime: %s\n", strerror(errno));
