        return EXIT_FAILURE;
    }

    ret = log_init();
    if (ret < 0) {
        fprintf(stderr, "main: log_init: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = atexit(cleanup);
    if (ret < 0) {
        fprintf(stderr, "main: atexit: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

