#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

static volatile int pulse_count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        if (log_file) {
            fclose(log_file);
        }
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        exit(0);
    }
}

void isr_callback(int gpio, int level, uint32_t tick)
{
    pthread_mutex_lock(&mutex);
    pulse_count++;
    pthread_mutex_unlock(&mutex);
}

int main(int argc, char *argv[])
{
    int rc;
    struct timespec start_time, end_time;
    double elapsed_time, rpm;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set GPIO pin pull-down\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, isr_callback) != 0) {
        fprintf(stderr, "Failed to set GPIO pin alert function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        pulse_count = 0;
        sleep(1);

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        pthread_mutex_lock(&mutex);
        rpm = pulse_count / elapsed_time * 60.0;
        pthread_mutex_unlock(&mutex);

        fprintf(log_file, "%.6lf, %.2lf\n", elapsed_time, rpm);
        fflush(log_file);
    }

    return 0;
}

