#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define MAX9814_GAIN_PIN 18
#define MAX9814_OUT_PIN 17

#define LOG_FILE "audio_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *gain_line;
struct gpiod_line *out_line;

void signal_handler(int sig) {
    printf("Exiting...\n");
    gpiod_line_release(gain_line);
    gpiod_line_release(out_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int level;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        printf("Error opening gpiochip0\n");
        return 1;
    }

    // Configure MAX9814 gain pin as output
    gain_line = gpiod_chip_get_line(chip, MAX9814_GAIN_PIN);
    if (!gain_line) {
        printf("Error getting line %d\n", MAX9814_GAIN_PIN);
        return 1;
    }
    if (gpiod_line_request_output(gain_line, "gain", 0) < 0) {
        printf("Error requesting output for line %d\n", MAX9814_GAIN_PIN);
        return 1;
    }

    // Configure MAX9814 out pin as input
    out_line = gpiod_chip_get_line(chip, MAX9814_OUT_PIN);
    if (!out_line) {
        printf("Error getting line %d\n", MAX9814_OUT_PIN);
        return 1;
    }
    if (gpiod_line_request_input(out_line, "out") < 0) {
        printf("Error requesting input for line %d\n", MAX9814_OUT_PIN);
        return 1;
    }

    // Set gain to 60dB
    if (gpiod_line_set_value(gain_line, 0) < 0) {
        printf("Error setting value for line %d\n", MAX9814_GAIN_PIN);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        printf("Error opening log file\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Poll MAX9814 out pin for rising edges
        if (gpiod_line_event_wait(out_line, -1) < 0) {
            printf("Error waiting for event on line %d\n", MAX9814_OUT_PIN);
            return 1;
        }
        if (gpiod_line_event_read(out_line) == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Get current timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            tm = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

            // Log timestamp and level
            level = gpiod_line_get_value(out_line);
            fprintf(log_file, "%s %d\n", timestamp, level);
            fflush(log_file);
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x70
#define I2C_BUS 1
#define I2C_REG 0x00
#define I2C_LEN 7

#define LOG_FILE "air_quality_log.csv"

#define TVOC_SCALE 10.0
#define ECO2_SCALE 50.0
#define ECO2_OFFSET 400.0

#define IAQ_MIN 0
#define IAQ_MAX 100

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void sigint_handler(int signum)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

static int clamp(int value, int min, int max)
{
    if (value < min) {
        return min;
    } else if (value > max) {
        return max;
    } else {
        return value;
    }
}

int main(int argc, char *argv[])
{
    int ret;
    uint8_t buf[I2C_LEN];
    uint16_t tvoc, eco2;
    int iaq;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "failed to open log file '%s'\n", LOG_FILE);
        return 1;
    }

    while (1) {
        ret = i2cReadI2CBlockData(i2c_handle, I2C_REG, buf, I2C_LEN);
        if (ret < 0) {
            fprintf(stderr, "failed to read I2C data\n");
            break;
        }

        tvoc = (buf[1] << 8) | buf[0];
        eco2 = (buf[5] << 8) | buf[4];

        iaq = clamp(100 - (tvoc / TVOC_SCALE) - ((eco2 - ECO2_OFFSET) / ECO2_SCALE), IAQ_MIN, IAQ_MAX);

        fprintf(log_file, "%ld,%d,%d,%d\n", time(NULL), iaq, tvoc, eco2);

        gpioDelay(5000000);
    }

    return 0;
}

