        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, TTP223_CONSUMER);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(-ret));
        return EXIT_FAILURE;
    }

    pfd.fd = gpiod_line_event_get_fd(line);
    pfd.events = POLLPRI;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

