#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BYTES 32768
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24

#define MAGIC_NUMBER 0x52444144
#define START_FREQ 77000000000
#define END_FREQ 79000000000
#define CHIRPS 64
#define SAMPLES 256
#define FRAME_PERIOD 100000000

typedef struct {
    uint64_t start_freq;
    uint64_t end_freq;
    uint16_t chirps;
    uint16_t samples;
    uint32_t frame_period;
} config_t;

static int spi_handle;
static int gpio_trigger;
static int gpio_data_ready;
static FILE *file;

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (gpio_trigger >= 0) {
        gpioSetMode(gpio_trigger, PI_INPUT);
    }
    if (gpio_data_ready >= 0) {
        gpioSetMode(gpio_data_ready, PI_INPUT);
    }
    if (file) {
        fclose(file);
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;
    uint8_t *buf;
    uint64_t timestamp;
    config_t config;
    uint32_t frame_num;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(ret));
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(spi_handle));
        return EXIT_FAILURE;
    }

    gpio_trigger = gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    if (gpio_trigger < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(gpio_trigger));
        return EXIT_FAILURE;
    }

    gpio_data_ready = gpioSetMode(GPIO_DATA_READY, PI_INPUT);
    if (gpio_data_ready < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(gpio_data_ready));
        return EXIT_FAILURE;
    }

    file = fopen("log.bin", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    buf = malloc(SPI_BYTES);
    if (!buf) {
        fprintf(stderr, "Failed to allocate buffer: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    config.start_freq = START_FREQ;
    config.end_freq = END_FREQ;
    config.chirps = CHIRPS;
    config.samples = SAMPLES;
    config.frame_period = FRAME_PERIOD;

    ret = fwrite(&MAGIC_NUMBER, sizeof(MAGIC_NUMBER), 1, file);
    if (ret != 1) {
        fprintf(stderr, "Failed to write magic number: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = fwrite(&timestamp, sizeof(timestamp), 1, file);
    if (ret != 1) {
        fprintf(stderr, "Failed to write timestamp: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = fwrite(&config, sizeof(config), 1, file);
    if (ret != 1) {
        fprintf(stderr, "Failed to write config: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    frame_num = 0;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        ret = gpioWrite(gpio_trigger, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write GPIO: %s\n", strerror(ret));
            return EXIT_FAILURE;
        }

        ret = gpioWaitInterrupt(gpio_data_ready, EITHER_EDGE);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for interrupt: %s\n", strerror(ret));
            return EXIT_FAILURE;
        }

        ret = spiXfer(spi_handle, NULL, buf, SPI_BYTES);
        if (ret < 0) {
            fprintf(stderr, "Failed to transfer SPI data: %s\n", strerror(ret));
            return EXIT_FAILURE;
        }

        ret = fwrite(&timestamp, sizeof(timestamp), 1, file);
        if (ret != 1) {
            fprintf(stderr, "Failed to write timestamp: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

