#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUM 20
#define GPIO_LINE_NAME "gpio20"
#define GPIO_LINE_DIRECTION "in"
#define GPIO_LINE_ACTIVE_STATE "active_low"
#define GPIO_LINE_EDGE "both"
#define GPIO_LINE_CONSUMER "flame_sensor"
#define LOG_FILE_NAME "flame_log.txt"
#define LOG_FILE_MODE "a"
#define LOG_FILE_FORMAT "%s: %s\n"
#define LOG_FILE_TIMESTAMP_FORMAT "%FT%TZ"
#define LOG_FILE_TIMESTAMP_SIZE 25
#define LOG_FILE_LINE_SIZE 100
#define POLL_TIMEOUT_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line_request_config line_config;
static struct gpiod_line_event event;
static struct gpiod_line_event_poll poll;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

static void sig_handler(int signum)
{
    running = 0;
}

static void log_event(const char *state)
{
    char timestamp[LOG_FILE_TIMESTAMP_SIZE];
    char line[LOG_FILE_LINE_SIZE];
    time_t now;
    struct tm *tm;

    now = time(NULL);
    tm = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), LOG_FILE_TIMESTAMP_FORMAT, tm);
    snprintf(line, sizeof(line), LOG_FILE_FORMAT, timestamp, state);
    fputs(line, log_file);
    fflush(log_file);
}

static void poll_events(void)
{
    int ret;

    while (running) {
        ret = gpiod_line_event_poll_wait(poll);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error polling GPIO line: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_event_poll_read(poll, &event);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO line event: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            log_event("flame detected");
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_event("flame cleared");
        }
    }
}

int main(void)
{
    int ret;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_NUM);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    memset(&line_config, 0, sizeof(line_config));
    line_config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;
    line_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    line_config.consumer = GPIO_LINE_CONSUMER;
    ret = gpiod_line_request_config(line, &line_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line config: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE_NAME, LOG_FILE_MODE);
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    memset(&poll, 0, sizeof(poll));
    poll.line = line;
    poll.timeout_ms = POLL_TIMEOUT_MS;
    ret = gpiod_line_event_poll_init(&poll);
    if (ret < 0) {
        fprintf(stderr, "Error initializing GPIO line event poll: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    poll_events();

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

