#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define I2C_REG_RESULT 0x00
#define I2C_REG_CONFIG 0x01
#define I2C_REG_LOW_LIMIT 0x02
#define I2C_REG_HIGH_LIMIT 0x03
#define I2C_REG_MANUFACTURER_ID 0x7E
#define I2C_REG_DEVICE_ID 0x7F

#define I2C_CONFIG_CONTINUOUS_MODE 0x1000
#define I2C_CONFIG_100_MS_CONVERSION_TIME 0x0000
#define I2C_CONFIG_AUTO_FULL_SCALE_RANGE 0x0000

#define LUX_SCALE 0.01

#define LOG_FILE "light_data.txt"

#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file) {
        fclose(log_file);
    }

    gpioTerminate();
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int i2c_read_word(int i2c_handle, uint8_t reg)
{
    int ret;
    uint8_t buf[2];

    ret = i2cReadI2CBlockData(i2c_handle, reg, 2, buf);
    if (ret < 0) {
        return ret;
    }

    return (buf[0] << 8) | buf[1];
}

static int i2c_write_word(int i2c_handle, uint8_t reg, uint16_t value)
{
    int ret;
    uint8_t buf[2];

    buf[0] = value >> 8;
    buf[1] = value & 0xFF;

    ret = i2cWriteI2CBlockData(i2c_handle, reg, 2, buf);
    if (ret < 0) {
        return ret;
    }

    return 0;
}

static int i2c_read_device_id(int i2c_handle)
{
    int ret;
    uint16_t device_id;

    ret = i2c_read_word(i2c_handle, I2C_REG_DEVICE_ID);
    if (ret < 0) {
        return ret;
    }

    device_id = ret;

    if (device_id != 0x3001) {
        return -1;
    }

    return 0;
}

static int i2c_read_manufacturer_id(int i2c_handle)
{
    int ret;
    uint16_t manufacturer_id;

    ret = i2c_read_word(i2c_handle, I2C_REG_MANUFACTURER_ID);
    if (ret < 0) {
        return ret;
    }

    manufacturer_id = ret;

    if (manufacturer_id != 0x5449) {
        return -1;
    }

    return 0;
}

static int i2c_configure(int i2c_handle)
{
    int ret;
    uint16_t config;

    ret = i2c_read_word(i2c_handle, I2C_REG_CONFIG);
    if (ret < 0) {
        return ret;
    }

    config = ret;

    config &= ~I2C_CONFIG_CONTINUOUS_MODE;
    config &= ~I2C_CONFIG_100_MS_CONVERSION_TIME;
    config &= ~I2C_CONFIG_AUTO_FULL_SCALE_RANGE;

    ret = i2c_write_word(i2c_handle, I2C_REG_CONFIG, config);
    if (ret < 0) {
        return ret;
    }

    return 0;
}

static int i2c_read_result(int i2c_handle, double *lux)
{
    int ret;
    uint16_t result;
    uint16_t exponent;
    uint16_t mantissa;

    ret = i2c_read_word(i2c_handle, I2C_REG_RESULT);
    if (ret < 0) {
        return ret;
    }

    result = ret;

    exponent = (result >> 12) & 0x0F;
    mantissa = result & 0x0FFF;

    *lux = LUX_SCALE * (1 << exponent) * mantissa;

    return 0;
}

static int i2c_read_data(int i2c_handle, double *lux)
{
    int ret;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        ret = i2c_read_result(i2c_handle, lux);
        if (ret == 0) {
            return 0;
        }

        retries++;
    }

    return ret;
}

static int log_data(double lux)
{
    int ret;
    time_t now;
    struct tm *tm;
    char timestamp[32];

    now = time(NULL);
    tm = localtime(&now);
    if (!tm) {
        return -1;
    }

    ret = strftime(timestamp, sizeof(timestamp), "%FT%T%z", tm);
    if (ret == 0) {
        return -1;
    }

    ret = fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    if (ret < 0) {
        return -1;
    }

    fflush(log_file);

    return 0;
}

int main(void)
{
    int ret;
    double lux;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = gpioInitialise();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        goto error;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        goto error;
    }

    ret = i2c_read_manufacturer_id(i2c_handle);
    if (ret < 0) {
        goto error;
    }

    ret = i2c_read_device_id(i2c_handle);
    if (ret < 0) {
        goto error;
    }

    ret = i2c_configure(i2c_handle);
    if (ret < 0) {
        goto error;
    }

    while (1) {
        ret = i2c_read_data(i2c_handle, &lux);
        if (ret < 0) {
            goto error;
        }

        ret = log_data(lux);
        if (ret < 0) {
            goto error;
        }
    }

error:
    cleanup();
    return EXIT_FAILURE;
}

