#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_LINES 8
#define LINE_OFFSET 2

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_LINES];
static int running = 1;

static void sigint_handler(int signum)
{
    running = 0;
}

int main(void)
{
    int i;
    int ret;
    struct timespec ts;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request the lines
    for (i = 0; i < NUM_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + LINE_OFFSET);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", i + LINE_OFFSET);
            goto error;
        }

        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d\n", i + LINE_OFFSET);
            goto error;
        }
    }

    // Set up the signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read the lines
        for (i = 0; i < NUM_LINES; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read line %d\n", i + LINE_OFFSET);
                goto error;
            }

            printf("Line %d: %d\n", i + LINE_OFFSET, ret);
        }

        // Sleep for 100 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;
        nanosleep(&ts, NULL);
    }

    // Clean up
    for (i = 0; i < NUM_LINES; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

