#define SENSOR_SAMPLE_BUFFER_NEXT(index) ((index + 1) & SENSOR_SAMPLE_BUFFER_MASK)

#define SENSOR_SAMPLE_BUFFER_PREV(index) ((index + SENSOR_SAMPLE_BUFFER_MASK) & SENSOR_SAMPLE_BUFFER_MASK)

