	do { \
		if (SENSOR_SAMPLE_BUFFER_IS_FULL(head, tail)) { \
			tail = SENSOR_SAMPLE_BUFFER_NEXT(tail); \
		} \
		head = SENSOR_SAMPLE_BUFFER_NEXT(head); \
