#include <signal.h>
#include <libgpiod.h>

#define POLL_INTERVAL_MS 50
#define NUM_LINES 8

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_LINES];
static int running = 1;

void sigint_handler(int signum)
{
    running = 0;
}

int main(int argc, char *argv[])
{
    int i;
    struct timespec ts;
    struct gpiod_line_bulk_read bulk_read;
    struct gpiod_line_event event;
    int line_values[NUM_LINES];

    // Open the gpiochip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip\n");
        return EXIT_FAILURE;
    }

    // Request the lines
    for (i = 0; i < NUM_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 2);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get line %d\n", i + 2);
            goto error;
        }

        if (gpiod_line_request_input(lines[i], "touch_sensor")) {
            fprintf(stderr, "Error: Failed to request line %d\n", i + 2);
            goto error;
        }
    }

    // Set up the bulk read
    gpiod_line_bulk_read_init(&bulk_read, lines, NUM_LINES);

    // Set up the signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read the lines
        if (gpiod_line_bulk_read(lines, NUM_LINES, &bulk_read)) {
            fprintf(stderr, "Error: Failed to read lines\n");
            goto error;
        }

        // Get the current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Print the line values
        printf("%ld.%09ld", ts.tv_sec, ts.tv_nsec);
        for (i = 0; i < NUM_LINES; i++) {
