#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

int main(int argc, char *argv[])
{
    int rc;
    int tilt_state = -1;
    int prev_tilt_state = -1;

    printf("Starting tilt sensor polling...\n");

    rc = gpioInitialise();
    if (rc < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", gpioErrMsg(rc));
        exit(EXIT_FAILURE);
    }

    rc = gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    if (rc != 0)
    {
        fprintf(stderr, "Failed to set GPIO %d mode: %s\n", TILT_SENSOR_GPIO, gpioErrMsg(rc));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    rc = gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);
    if (rc != 0)
    {
        fprintf(stderr, "Failed to set GPIO %d pull-up resistor: %s\n", TILT_SENSOR_GPIO, gpioErrMsg(rc));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (1)
    {
        tilt_state = gpioRead(TILT_SENSOR_GPIO);
        if (tilt_state < 0)
        {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", TILT_SENSOR_GPIO, gpioErrMsg(tilt_state));
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        if (tilt_state != prev_tilt_state)
        {
            if (tilt_state == 0)
            {
                printf("Tilted\n");
            }
            else
            {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            prev_tilt_state = tilt_state;
        }

        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
}

