#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>

#define SENSOR_ADDR 0x60
#define SENSOR_PART_ID 0x45
#define SENSOR_HW_KEY 0x07
#define SENSOR_CHLIST 0x01
#define SENSOR_ALS_FORCE 0x06
#define SENSOR_ALS_VIS_DATA 0x22
#define SENSOR_UV_DATA 0x2C

#define SENSOR_PART_ID_VAL 0x45
#define SENSOR_HW_KEY_VAL 0x17
#define SENSOR_CHLIST_VAL 0x03

#define SENSOR_ALS_FORCE_VAL 0x01

#define SENSOR_ALS_VIS_DATA_VAL 0x00
#define SENSOR_UV_DATA_VAL 0x00

#define SENSOR_ALS_VIS_DATA_LEN 2
#define SENSOR_UV_DATA_LEN 2

#define SENSOR_TIMEOUT 1000

#define CSV_FILE "uv_als_log.csv"

int main(int argc, char *argv[])
{
    int handle;
    int ret;
    int uv_index;
    int als_visible;
    time_t timestamp;
    FILE *csv_file;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    handle = i2cOpen(1, SENSOR_ADDR, 0);
    if (handle < 0)
    {
        fprintf(stderr, "i2cOpen failed\n");
        gpioTerminate();
        return 1;
    }

    ret = i2cWriteByteData(handle, SENSOR_HW_KEY, SENSOR_HW_KEY_VAL);
    if (ret < 0)
    {
        fprintf(stderr, "i2cWriteByteData failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    ret = i2cWriteByteData(handle, SENSOR_CHLIST, SENSOR_CHLIST_VAL);
    if (ret < 0)
    {
        fprintf(stderr, "i2cWriteByteData failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    ret = i2cWriteByteData(handle, SENSOR_ALS_FORCE, SENSOR_ALS_FORCE_VAL);
    if (ret < 0)
    {
        fprintf(stderr, "i2cWriteByteData failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL)
    {
        fprintf(stderr, "fopen failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    fprintf(csv_file, "timestamp,uv_index,als_visible\n");

    while (1)
    {
        ret = i2cReadI2CBlockData(handle, SENSOR_UV_DATA, SENSOR_UV_DATA_LEN, (char *)&uv_index);
        if (ret < 0)
        {
            fprintf(stderr, "i2cReadI2CBlockData failed\n");
            break;
        }

        ret = i2cReadI2CBlockData(handle, SENSOR_ALS_VIS_DATA, SENSOR_ALS_VIS_DATA_LEN, (char *)&als_visible);
        if (ret < 0)
        {
            fprintf(stderr, "i2cReadI2CBlockData failed\n");
            break;
        }

        timestamp = time(NULL);

        fprintf(csv_file, "%ld,%d,%d\n", timestamp, uv_index, als_visible);

        gpioDelay(1000000);
    }

    fclose(csv_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

typedef struct {
    time_t timestamp;
    int reading;
} entry_t;

entry_t buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_sigint(int signum) {
    printf("SIGINT received, printing buffer contents...\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        entry_t entry = buffer[index];
        struct tm *tm = localtime(&entry.timestamp);
        char time_str[32];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
        printf("Entry %d: Timestamp: %s, Reading: %d\n", i + 1, time_str, entry.reading);
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to enable pull-up resistor on GPIO pin %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int reading = gpioRead(GPIO_PIN);
        if (reading == 0) {
            time_t timestamp = time(NULL);
            buffer[buffer_index].timestamp = timestamp;
            buffer[buffer_index].reading = reading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            printf("Alert: Obstacle detected at %ld\n", timestamp);
        }
        gpioDelay(50000);
    }

    gpioTerminate();
    return 0;
}

