#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_OUT 23
#define SENSOR_2_OUT 24
#define LED_OUT 25

#define SENSOR_1_ON 0
#define SENSOR_2_ON 0

#define SENSOR_1_OFF 1
#define SENSOR_2_OFF 1

#define LED_ON 1
#define LED_OFF 0

#define POLL_INTERVAL 100

int main(int argc, char *argv[])
{
    int sensor1_state = SENSOR_1_OFF;
    int sensor2_state = SENSOR_2_OFF;
    int led_state = LED_OFF;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_OUT, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set mode for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2_OUT, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set mode for sensor 2\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_OUT, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set mode for LED\n");
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        sensor1_state = gpioRead(SENSOR_1_OUT);
        sensor2_state = gpioRead(SENSOR_2_OUT);

        if (sensor1_state == SENSOR_1_ON || sensor2_state == SENSOR_2_ON)
        {
            led_state = LED_ON;
        }
        else
        {
            led_state = LED_OFF;
        }

        gpioWrite(LED_OUT, led_state);

        gpioDelay(POLL_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

