Write a C program for a Raspberry Pi 3 Model B+ using the libgpiod library's line event interface to read touch input from a SainSmart TTP223B capacitive touch sensor connected to GPIO 17 (physical pin 11), which outputs HIGH (3.3 V) when touched and LOW when idle. On each rising-edge touch detection (with approximately 50 ms software debounce), toggle an LED connected to GPIO 18 (physical pin 12). Initialize the LED line as output and drive it LOW at startup. Check every libgpiod call (chip open, line request, event wait, read, write) and print meaningful messages to stderr on failure. Handle SIGINT and SIGTERM gracefully: release all libgpiod resources (lines and chip) and exit cleanly.

### Response:
```
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define LED_GPIO 18
#define TOUCH_GPIO 17

static struct gpiod_chip *chip;
static struct gpiod_line *led_line, *touch_line;
static int led_value = 0;

static void cleanup(void)
{
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
        touch_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!touch_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_rising_edge_events(touch_line, "touch");
    if (ret < 0) {
        perror("gpiod_line_request_rising_edge_events");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_line_event_wait(touch_line, NULL);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        ret = gpiod_line_get_value(touch_line);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            exit(EXIT_FAILURE);
        }
        if (ret == 0)
            continue;

        led_value = !led_value;
        ret = gpiod_line_set_value(led_line, led_value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            exit(EXIT_FAILURE);
        }

        /* Software debounce */
        usleep(50000);
    }

    cleanup();
    return 0;
}
```

