#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LED_1 27
#define LED_2 22
#define SENSOR_1 4
#define SENSOR_2 17
#define BUFFER_SIZE 100

typedef struct {
    int pin;
    time_t timestamp;
    int state;
} event_t;

event_t buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_overflow = 0;

void handle_event(int pin, int state) {
    event_t event = {pin, time(NULL), state};
    buffer[buffer_index] = event;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        buffer_overflow++;
    }
}

void handle_shutdown(int signal) {
    gpioWrite(LED_1, 0);
    gpioWrite(LED_2, 0);
    gpioTerminate();
    printf("Buffer overflow count: %d\n", buffer_overflow);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Event %d: pin=%d, timestamp=%ld, state=%d\n", i, buffer[i].pin, buffer[i].timestamp, buffer[i].state);
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(LED_1, PI_OUTPUT);
    gpioSetMode(LED_2, PI_OUTPUT);
    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);

    gpioSetPullUpDown(SENSOR_1, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2, PI_PUD_UP);

    gpioSetAlertFunc(SENSOR_1, handle_event);
    gpioSetAlertFunc(SENSOR_2, handle_event);

    signal(SIGINT, handle_shutdown);
    signal(SIGTERM, handle_shutdown);

    while (1) {
        gpioWrite(LED_1, gpioRead(SENSOR_1));
        gpioWrite(LED_2, gpioRead(SENSOR_2));
        time_sleep(0.05);
    }

    return 0;
}

