#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_DELAY 5000 // 5 ms debounce delay
#define LOG_FILE "shaft_log.txt"

int sensor1_state = 0;
int sensor2_state = 0;

void handle_error(const char *message)
{
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

void handle_gpio_error(int error)
{
    if (error < 0)
    {
        handle_error(pigpio_error(error));
    }
}

void handle_file_error(FILE *file)
{
    if (file == NULL)
    {
        handle_error(strerror(errno));
    }
}

void log_state_change(FILE *log_file, int sensor1_state, int sensor2_state)
{
    if (log_file != NULL)
    {
        fprintf(log_file, "%ld,%d,%d\n", gpioTick(), sensor1_state, sensor2_state);
        fflush(log_file);
    }
}

void handle_sensor_change(int sensor_pin, int sensor_state)
{
    if (sensor_pin == SENSOR1_PIN)
    {
        sensor1_state = sensor_state;
    }
    else if (sensor_pin == SENSOR2_PIN)
    {
        sensor2_state = sensor_state;
    }
}

void handle_sensor_event(int sensor_pin, int sensor_state, int tick)
{
    static int last_tick = 0;
    static int last_sensor1_state = 0;
    static int last_sensor2_state = 0;

    if (tick - last_tick >= DEBOUNCE_DELAY)
    {
        if (sensor_pin == SENSOR1_PIN && sensor_state != last_sensor1_state)
        {
            handle_sensor_change(sensor_pin, sensor_state);
            last_sensor1_state = sensor_state;
        }
        else if (sensor_pin == SENSOR2_PIN && sensor_state != last_sensor2_state)
        {
            handle_sensor_change(sensor_pin, sensor_state);
            last_sensor2_state = sensor_state;
        }

        last_tick = tick;
    }
}

void handle_sensor_event_callback(int sensor_pin, int sensor_state, uint32_t tick)
{
    handle_sensor_event(sensor_pin, sensor_state, tick);
}

void handle_signal(int signal)
{
    if (signal == SIGINT)
    {
