#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HR_REG 0x02
#define SPO2_REG 0x04

FILE *log_file;

void sigint_handler(int sig)
{
    if (log_file)
    {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main(void)
{
    int ret;
    uint8_t part_id;
    uint8_t config;
    uint8_t hr;
    uint8_t spo2;
    time_t timestamp;
    struct tm *time_info;
    char time_str[32];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    ret = gpioI2COpen(I2C_BUS, I2C_ADDR);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    ret = gpioI2CReadDevice(ret, &part_id, 1);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to read PART_ID register\n");
        gpioI2CClose(ret);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x82)
    {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        gpioI2CClose(ret);
        gpioTerminate();
        return 1;
    }

    config = 0x01;
    ret = gpioI2CWriteDevice(ret, &config, 1);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to write CONFIG register\n");
        gpioI2CClose(ret);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(ret);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1)
    {
        ret = gpioI2CReadDevice(ret, &hr, 1);
        if (ret < 0)
        {
            fprintf(stderr, "Failed to read HR register\n");
            break;
        }

        ret = gpioI2CReadDevice(ret, &spo2, 1);
        if (ret < 0)
        {
            fprintf(stderr, "Failed to read SPO2 register\n");
            break;
