        timestamp = time(NULL);
        time_info = localtime(&timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", time_str, hr, spo2);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpioI2CClose(ret);
    gpioTerminate();

    return 0;
}

