#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1 17
#define SENSOR_2 18
#define ALARM 27
#define POLL_INTERVAL 100
#define THRESHOLD 2000

FILE *log_file;

void log_event(char *event)
{
    time_t now;
    struct tm *time_info;
    char time_string[20];

    time(&now);
    time_info = localtime(&now);
    strftime(time_string, sizeof(time_string), "%FT%T", time_info);

    fprintf(log_file, "%s: %s\n", time_string, event);
    fflush(log_file);
}

void handle_alarm(int sensor)
{
    static int sensor_state[2] = {0, 0};
    static int alarm_active = 0;
    static int alarm_start_time = 0;

    if (sensor == SENSOR_1) {
        sensor_state[0] = gpioRead(SENSOR_1);
    } else if (sensor == SENSOR_2) {
        sensor_state[1] = gpioRead(SENSOR_2);
    }

    if (sensor_state[0] == 1 || sensor_state[1] == 1) {
        if (!alarm_active) {
            alarm_start_time = millis();
            gpioWrite(ALARM, 1);
            alarm_active = 1;
            log_event("Alarm activated");
        } else if (millis() - alarm_start_time > THRESHOLD) {
            gpioWrite(ALARM, 0);
            alarm_active = 0;
            log_event("Alarm deactivated");
        }
    } else {
        if (alarm_active) {
            gpioWrite(ALARM, 0);
            alarm_active = 0;
            log_event("Alarm deactivated");
        }
    }
}

void handle_signal(int signal)
{
    gpioWrite(ALARM, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    log_file = fopen("bridge_integrity.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1, PI_PUD_DOWN);
    gpioSetAlertFunc(SENSOR_1, handle_alarm);

    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2, PI_PUD_DOWN);
    gpioSetAlertFunc(SENSOR_2, handle_alarm);

    gpioSetMode(ALARM, PI_OUTPUT);
    gpioWrite(ALARM, 0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        gpioDelay(POLL_INTERVAL);
    }

    return 0;
}

