#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1 17
#define SENSOR_2 18
#define ALARM 27
#define POLL_INTERVAL 100
#define THRESHOLD 2000

FILE *log_file;

void log_event(char *event)
{
    time_t now;
    struct tm *time_info;
    char time_string[20];

    time(&now);
    time_info = localtime(&now);
    strftime(time_string, sizeof(time_string), "%FT%T", time_info);

    fprintf(log_file, "%s: %s\n", time_string, event);
    fflush(log_file);
}

void handle_alarm(int sensor)
