    } else if (sensor == SENSOR_2) {
        sensor_state[1] = gpioRead(SENSOR_2);
    }

    if (sensor_state[0] == 1 || sensor_state[1] == 1) {
        if (!alarm_active) {
            alarm_start_time = millis();
            gpioWrite(ALARM, 1);
            alarm_active = 1;
            log_event("Alarm activated");
        } else if (millis() - alarm_start_time > THRESHOLD) {
            gpioWrite(ALARM, 0);
            alarm_active = 0;
            log_event("Alarm deactivated");
