    log_file = fopen("bridge_integrity.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1, PI_PUD_DOWN);
    gpioSetAlertFunc(SENSOR_1, handle_alarm);

    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2, PI_PUD_DOWN);
