#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>
#include <signal.h>

#define SENSOR_ADDR 0x1D
#define SENSOR_CTRL1 0x1F
#define SENSOR_CTRL2 0x20
#define SENSOR_CTRL3 0x21
#define SENSOR_CTRL4 0x22
#define SENSOR_CTRL5 0x23
#define SENSOR_CTRL6 0x24
#define SENSOR_CTRL7 0x25
#define SENSOR_STATUS 0x27
#define SENSOR_OUT_X_L 0x28
#define SENSOR_OUT_X_H 0x29
#define SENSOR_OUT_Y_L 0x2A
#define SENSOR_OUT_Y_H 0x2B
#define SENSOR_OUT_Z_L 0x2C
#define SENSOR_OUT_Z_H 0x2D
#define SENSOR_FIFO_CTRL 0x2E
#define SENSOR_FIFO_SRC 0x2F
#define SENSOR_INT1_CFG 0x30
#define SENSOR_INT1_SRC 0x31
#define SENSOR_INT1_TSH_XH 0x32
#define SENSOR_INT1_TSH_XL 0x33
#define SENSOR_INT1_TSH_YH 0x34
#define SENSOR_INT1_TSH_YL 0x35
#define SENSOR_INT1_TSH_ZH 0x36
#define SENSOR_INT1_TSH_ZL 0x37
#define SENSOR_INT1_DURATION 0x38

#define LED_GPIO 17
#define LED_ON 1
#define LED_OFF 0

#define THRESHOLD 500
#define SAMPLING_INTERVAL 100
#define RETRIES 3

#define LOG_FILE "seismic_events.log"

static int i2cHandle = -1;
static FILE *logFile = NULL;

static void cleanup(void)
{
    if (i2cHandle >= 0)
    {
        gpioI2CClose(i2cHandle);
        i2cHandle = -1;
    }

    if (logFile != NULL)
    {
        fclose(logFile);
        logFile = NULL;
    }
}

static void sigHandler(int sig)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int initSensor(void)
{
    int ret;

    ret = gpioI2CWriteByte(i2cHandle, SENSOR_CTRL1, 0x00);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to clear power-down bit in CTRL1\n");
        return ret;
    }

    return 0;
}

static int readSensor(int *x, int *y, int *z)
{
    int ret;
    uint8_t buf[6];

    ret = gpioI2CReadDevice(i2cHandle, buf, sizeof(buf));
    if (ret < 0)
    {
        fprintf(stderr, "Failed to read sensor data\n");
        return ret;
    }

    *x = (buf[1] << 8) | buf[0];
    *y = (buf[3] << 8) | buf[2];
    *z = (buf[5] << 8) | buf[4];

    return 0;
}

static int readSensorWithRetries(int *x, int *y, int *z)
{
    int ret;
    int retries = RETRIES;

    while (retries > 0)
    {
        ret = readSensor(x, y, z);
        if (ret == 0)
        {
            return 0;
        }

        retries--;
    }

    return ret;
}

static int getTimestamp(char *buf, size_t bufSize)
{
    struct timeval tv;
    struct tm tm;
    int ret;

    ret = gettimeofday(&tv, NULL);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to get time of day\n");
        return ret;
    }

    ret = localtime_r(&tv.tv_sec, &tm);
    if (ret == NULL)
    {
        fprintf(stderr, "Failed to convert time to local time\n");
        return ret;
    }

    ret = strftime(buf, bufSize, "%FT%T", &tm);
    if (ret == 0)
    {
        fprintf(stderr, "Failed to format timestamp\n");
        return ret;
    }

    return 0;
}

static int logEvent(int x, int y, int z)
{
    char timestamp[32];
    int ret;

    ret = getTimestamp(timestamp, sizeof(timestamp));
    if (ret < 0)
    {
        return ret;
    }

    ret = fprintf(logFile, "%s: %d %d %d\n", timestamp, x, y, z);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to write to log file\n");
        return ret;
    }

    return 0;
}

static int detectSeismicEvent(void)
{
    int x, y, z;
    int ret;

    ret = readSensorWithRetries(&x, &y, &z);
    if (ret < 0)
    {
        return ret;
    }

    if (sqrt(x * x + y * y + z * z) > THRESHOLD)
    {
        ret = gpioWrite(LED_GPIO, LED_ON);
        if (ret < 0)
        {
            fprintf(stderr, "Failed to turn on LED\n");
            return ret;
        }

        ret = logEvent(x, y, z);
        if (ret < 0)
        {
            return ret;
        }

        gpioDelay(1000);

        ret = gpioWrite(LED_GPIO, LED_OFF);
        if (ret < 0)
        {
            fprintf(stderr, "Failed to turn off LED\n");
            return ret;
        }
    }

    return 0;
}

int main(void)
{
    int ret;

    ret = gpioInitialise();
    if (ret < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return ret;
    }

    i2cHandle = gpioI2COpen(1, SENSOR_ADDR);
    if (i2cHandle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus\n");
        return i2cHandle;
    }

    ret = initSensor();
    if (ret < 0)
    {
        return ret;
    }

    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    ret = gpioSetMode(LED_GPIO, PI_OUTPUT);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        return ret;
    }

    ret = gpioWrite(LED_GPIO, LED_OFF);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to turn off LED\n");
        return ret;
    }

    signal(SIGINT, sigHandler);

    while (1)
    {
        ret = detectSeismicEvent();
        if (ret < 0)
        {
            return ret;
        }

        gpioDelay(SAMPLING_INTERVAL);
    }

    return 0;
}

