void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM)
    {
        gpiod_line_release(led_line);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_3);
        gpiod_line_release(sensor_line_4);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main(void)
{
    int ret;
    int value;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request the LED line
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line)
    {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0)
    {
        perror("Failed to request LED line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the sensor lines
    sensor_line_1 = gpiod_chip_get_line(chip, SENSOR_GPIO_1);
    if (!sensor_line_1)
    {
        perror("Failed to get sensor line 1");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(sensor_line_1, "sensor_1");
    if (ret < 0)
    {
        perror("Failed to request sensor line 1");
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor_line_2 = gpiod_chip_get_line(chip, SENSOR_GPIO_2);
    if (!sensor_line_2)
    {
        perror("Failed to get sensor line 2");
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(sensor_line_2, "sensor_2");
    if (ret < 0)
    {
        perror("Failed to request sensor line 2");
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor_line_3 = gpiod_chip_get_line(chip, SENSOR_GPIO_3);
    if (!sensor_line_3)
    {
        perror("Failed to get sensor line 3");
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(sensor_line_3, "sensor_3");
    if (ret < 0)
    {
        perror("Failed to request sensor line 3");
        gpiod_line_release(sensor_line_3);
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor_line_4 = gpiod_chip_get_line(chip, SENSOR_GPIO_4);
    if (!sensor_line_4)
    {
        perror("Failed to get sensor line 4");
        gpiod_line_release(sensor_line_3);
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(sensor_line_4, "sensor_4");
    if (ret < 0)
    {
        perror("Failed to request sensor line 4");
        gpiod_line_release(sensor_line_4);
        gpiod_line_release(sensor_line_3);
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1)
    {
        // Read sensor values
        value = gpiod_line_get_value(sensor_line_1);
        if (value < 0)
        {
            perror("Failed to read sensor line 1");
            break;
        }

        value = gpiod_line_get_value(sensor_line_2);
        if (value < 0)
        {
            perror("Failed to read sensor line 2");
            break;
        }

        value = gpiod_line_get_value(sensor_line_3);
        if (value < 0)
        {
            perror("Failed to read sensor line 3");
            break;
        }

        value = gpiod_line_get_value(sensor_line_4);
        if (value < 0)
        {
            perror("Failed to read sensor line 4");
            break;
        }

        // Check if any sensor detects an object
        if (value == 0)
        {
            // Turn ON the LED
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0)
            {
                perror("Failed to set LED line");
                break;
            }
        }
        else
        {
            // Turn OFF the LED
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0)
            {
                perror("Failed to set LED line");
                break;
            }
        }

        // Poll every 50 ms
        usleep(50000);
    }

    // Clean up
    gpiod_line_release(sensor_line_4);
    gpiod_line_release(sensor_line_3);
    gpiod_line_release(sensor_line_2);
    gpiod_line_release(sensor_line_1);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
