    if (ret < 0)
    {
        perror("Failed to request sensor line 2");
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor_line_3 = gpiod_chip_get_line(chip, SENSOR_GPIO_3);
    if (!sensor_line_3)
    {
        perror("Failed to get sensor line 3");
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(sensor_line_3, "sensor_3");
    if (ret < 0)
    {
        perror("Failed to request sensor line 3");
        gpiod_line_release(sensor_line_3);
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor_line_4 = gpiod_chip_get_line(chip, SENSOR_GPIO_4);
    if (!sensor_line_4)
    {
        perror("Failed to get sensor line 4");
        gpiod_line_release(sensor_line_3);
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(sensor_line_4, "sensor_4");
    if (ret < 0)
    {
        perror("Failed to request sensor line 4");
        gpiod_line_release(sensor_line_4);
        gpiod_line_release(sensor_line_3);
        gpiod_line_release(sensor_line_2);
        gpiod_line_release(sensor_line_1);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1)
    {
        // Read sensor values
        value = gpiod_line_get_value(sensor_line_1);
        if (value < 0)
        {
            perror("Failed to read sensor line 1");
            break;
        }

        value = gpiod_line_get_value(sensor_line_2);
        if (value < 0)
        {
            perror("Failed to read sensor line 2");
            break;
        }

        value = gpiod_line_get_value(sensor_line_3);
        if (value < 0)
        {
            perror("Failed to read sensor line 3");
            break;
        }

        value = gpiod_line_get_value(sensor_line_4);
        if (value < 0)
        {
            perror("Failed to read sensor line 4");
            break;
        }

        // Check if any sensor detects an object
        if (value == 0)
        {
            // Turn ON the LED
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0)
            {
                perror("Failed to set LED line");
                break;
            }
        }
        else
        {
            // Turn OFF the LED
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0)
            {
                perror("Failed to set LED line");
                break;
            }
        }

        // Poll every 50 ms
        usleep(50000);
    }

    // Clean up
    gpiod_line_release(sensor_line_4);
    gpiod_line_release(sensor_line_3);
    gpiod_line_release(sensor_line_2);
    gpiod_line_release(sensor_line_1);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}
