#define SENSOR_LOG_FILE_LOCK_RETRIES 10
#define SENSOR_LOG_FILE_LOCK_RETRY_DELAY 1
#define SENSOR_DEBOUNCE_DELAY_MS 50

#define ARRAY_SIZE(arr) (sizeof(arr) / sizeof((arr)[0]))

static volatile sig_atomic_t sig_received = 0;

static void sig_handler(int sig)
{
    sig_received = 1;
}

static int sensor_log_file_lock(FILE **file)
{
    int ret = 0;
    int lock_fd = -1;
    int lock_retries = SENSOR_LOG_FILE_LOCK_RETRIES;
    int lock_delay = SENSOR_LOG_FILE_LOCK_RETRY_DELAY;

    do {
        lock_fd = open(SENSOR_LOG_FILE_LOCK, O_CREAT | O_RDWR, 0644);
        if (lock_fd < 0) {
            LOG_ERRNO("open");
            ret = -1;
            break;
        }

        if (flock(lock_fd, LOCK_EX | LOCK_NB) < 0) {
            if (errno == EWOULDBLOCK) {
                syslog(LOG_WARNING, "Failed to lock %s, retrying in %d seconds", SENSOR_LOG_FILE_LOCK, lock_delay);
                sleep(lock_delay);
                lock_delay *= 2;
                if (lock_delay > SENSOR_LOG_FILE_LOCK_TIMEOUT) {
                    lock_delay = SENSOR_LOG_FILE_LOCK_TIMEOUT;
                }
            } else {
                LOG_ERRNO("flock");
                ret = -1;
                break;
            }
        } else {
            break;
        }
    } while (lock_retries-- > 0);

    if (ret == 0) {
        *file = fopen(SENSOR_LOG_FILE, "a");
        if (*file == NULL) {
            LOG_ERRNO("fopen");
            ret = -1;
        }
    }

    if (ret != 0) {
        if (lock_fd >= 0) {
            close(lock_fd);
        }
    }

    return ret;
}

static void sensor_log_file_unlock(FILE *file)
{
    if (file != NULL) {
        fclose(file);
    }

    if (unlink(SENSOR_LOG_FILE_LOCK) < 0) {
        LOG_ERRNO("unlink");
    }
}

static int sensor_log_event(int sensor_id, int gpio_pin, int flame_detected)
{
    int ret = 0;
    FILE *file = NULL;
    time_t now;
    struct tm *now_tm;
    char now_str[64];

    if (sensor_log_file_lock(&file) < 0) {
        ret = -1;
    }

    if (ret == 0) {
        now = time(NULL);
        now_tm = gmtime(&now);
        if (now_tm == NULL) {
            LOG_ERRNO("gmtime");
            ret = -1;
        } else {
            if (strftime(now_str, sizeof(now_str), "%FT%TZ", now_tm) == 0) {
                LOG_ERRNO("strftime");
                ret = -1;
            }
        }
    }

    if (ret == 0) {
        if (fprintf(file, "%s - Sensor ID: %d (%s) - %s\n", now_str, sensor_id, SENSOR_GPIO_NAMES[sensor_id], flame_detected ? "Flame Detected" : "No Flame") < 0) {
            LOG_ERRNO("fprintf");
            ret = -1;
        }
    }

    if (ret == 0) {
        if (fflush(file) < 0) {
            LOG_ERRNO("fflush");
            ret = -1;
        }
    }

    sensor_log_file_unlock(file);

    return ret;
}

