#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define ARRAY_SIZE(x) (sizeof(x) / sizeof((x)[0]))

static const int pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
static const int num_pins = ARRAY_SIZE(pins);

static struct gpiod_chip *chip;
static struct gpiod_line *lines[num_pins];
static struct gpiod_line_bulk *bulk;
static int line_values[num_pins];

static void cleanup(void)
{
    gpiod_line_bulk_free(bulk);
    gpiod_chip_close(chip);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static void print_timestamp(void)
{
    struct timespec ts;
    char buf[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        exit(EXIT_FAILURE);
    }

    if (strftime(buf, sizeof(buf), "%FT%T%z", gmtime(&ts.tv_sec)) == 0) {
        fprintf(stderr, "strftime failed\n");
        exit(EXIT_FAILURE);
    }

    printf("%s.%09ld ", buf, ts.tv_nsec);
}

static void print_line_values(void)
{
    int i;

    print_timestamp();

    for (i = 0; i < num_pins; i++) {
        printf("%d:%d ", pins[i], line_values[i]);
    }

    printf("\n");
}

static void poll_lines(void)
{
    int i;

    if (gpiod_line_bulk_read(bulk, line_values) == -1) {
        perror("gpiod_line_bulk_read");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < num_pins; i++) {
        if (line_values[i] != gpiod_line_get_value(lines[i])) {
            gpiod_line_set_value(lines[i], line_values[i]);
            print_line_values();
        }
    }
}

int main(void)
{
    int i;

    if (gpiod_init_chip("gpiochip0", &chip) == -1) {
        perror("gpiod_init_chip");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %d\n", pins[i]);
            exit(EXIT_FAILURE);
        }
    }

    bulk = gpiod_line_bulk_new(lines, num_pins);
    if (bulk == NULL) {
        fprintf(stderr, "gpiod_line_bulk_new failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_bulk_request_input(bulk, "touch_sensor") == -1) {
        perror("gpiod_line_bulk_request_input");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        poll_lines();
        usleep(50000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

