#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define I2C_CONFIG_REG 0x00
#define I2C_ALS_REG 0x04
#define I2C_CONFIG_VAL 0x0000
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LUX_100 100
#define LUX_500 500
#define LUX_1000 1000
#define LUX_SCALE 0.0576

int main(void) {
    FILE *log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(i2c_handle, I2C_CONFIG_REG, I2C_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing to I2C config register\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int lux_raw = i2cReadWordData(i2c_handle, I2C_ALS_REG);
        if (lux_raw < 0) {
            fprintf(stderr, "Error reading from I2C ALS register\n");
            return EXIT_FAILURE;
        }

        double lux = lux_raw * LUX_SCALE;
        int brightness = 0;
        if (lux < LUX_100) {
            brightness = PWM_RANGE;
        } else if (lux < LUX_500) {
            brightness = PWM_RANGE * 3 / 4;
        } else if (lux < LUX_1000) {
            brightness = PWM_RANGE / 2;
        } else {
            brightness = PWM_RANGE / 4;
        }

        if (gpioPWM(PWM_GPIO, brightness) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle\n");
            return EXIT_FAILURE;
        }

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", time_info);

        fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, brightness);
        fflush(log_file);

        sleep(1);
    }

    gpioPWM(PWM_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 17
#define TOUCH_PIN_BASE 2
#define TOUCH_PIN_COUNT 8
#define TOUCH_LOG_FILE "touch_log.txt"
#define TOUCH_LOG_FORMAT "%04d-%02d-%02d %02d:%02d:%02d - Channel %d Touched\n"
#define TOUCH_LOG_FORMAT_LEN 40
#define DEBOUNCE_DELAY_MS 50

static volatile int keep_running = 1;

static void signal_handler(int signum)
{
    keep_running = 0;
}

static void log_touch(int channel)
{
    FILE *fp = fopen(TOUCH_LOG_FILE, "a");
    if (fp == NULL)
    {
        fprintf(stderr, "Error opening touch log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    if (tm == NULL)
    {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    int ret = fprintf(fp, TOUCH_LOG_FORMAT, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, channel);
    if (ret < 0)
    {
        fprintf(stderr, "Error writing to touch log file: %s\n", strerror(errno));
    }
    else if (ret != TOUCH_LOG_FORMAT_LEN)
    {
        fprintf(stderr, "Error writing to touch log file: unexpected number of bytes written\n");
    }

    fclose(fp);
}

static void check_touch(int channel, int level, int tick)
{
    static int last_level[TOUCH_PIN_COUNT] = {0};
    static int last_tick[TOUCH_PIN_COUNT] = {0};

    if (level != last_level[channel])
    {
        if (level == 1 && tick - last_tick[channel] >= DEBOUNCE_DELAY_MS)
        {
            log_touch(channel + 1);
        }

        last_level[channel] = level;
        last_tick[channel] = tick;
    }
}

static void check_all_touches(int tick)
{
    for (int i = 0; i < TOUCH_PIN_COUNT; i++)
    {
        check_touch(i, gpioRead(TOUCH_PIN_BASE + i), tick);
    }
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioErrMsg);
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    for (int i = 0; i < TOUCH_PIN_COUNT; i++)
    {
        gpioSetMode(TOUCH_PIN_BASE + i, PI_INPUT);
        gpioSetPullUpDown(TOUCH_PIN_BASE + i, PI_PUD_DOWN);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running)
    {
        check_all_touches(gpioTick());
        gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

