#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define OPT3001_CONFIG 0x01
#define OPT3001_RESULT 0x00
#define OPT3001_CONFIG_WORD 0xC810
#define OPT3001_CONVERSION_TIME 100

#define LOG_FILE "light_data.txt"

int main(void)
{
    int handle;
    FILE *log_file;
    char log_line[100];
    time_t now;
    struct tm *time_info;
    int result;
    int exponent;
    int mantissa;
    double lux;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteWordData(handle, OPT3001_CONFIG, OPT3001_CONFIG_WORD) < 0)
    {
        fprintf(stderr, "Failed to write configuration word\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (i2cReadWordData(handle, OPT3001_RESULT) < 0)
    {
        fprintf(stderr, "Failed to read result register\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        if (i2cReadWordData(handle, OPT3001_RESULT) < 0)
        {
            fprintf(stderr, "Failed to read result register\n");
            break;
        }

        result = i2cReadWordData(handle, OPT3001_RESULT);
        if (result < 0)
        {
            fprintf(stderr, "Failed to read result register\n");
            break;
        }

        result = (result >> 8) | ((result & 0xFF) << 8);
        exponent = (result & 0xF000) >> 12;
        mantissa = result & 0x0FFF;
        lux = mantissa * 0.01 * (1 << exponent);

        now = time(NULL);
        time_info = localtime(&now);
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", time_info);
        sprintf(log_line + strlen(log_line), ", %.2f\n", lux);
        fputs(log_line, log_file);
        fflush(log_file);

        printf("%s, %.2f\n", log_line, lux);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

