#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"

FILE *log_file;

void cleanup(void)
{
    if (log_file)
        fclose(log_file);
    gpioTerminate();
}

void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int sensor_value;
    time_t timestamp;
    struct tm *time_info;
    char time_str[32];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (1)
    {
        sensor_value = gpioRead(SENSOR_GPIO);
        if (sensor_value < 0)
        {
            fprintf(stderr, "Failed to read sensor value\n");
            continue;
        }

        timestamp = time(NULL);
        time_info = localtime(&timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        if (sensor_value == 0)
        {
            fprintf(log_file, "%s: Fire detected\n", time_str);
            gpioWrite(ALERT_GPIO, 1);
            sleep(1);
            gpioWrite(ALERT_GPIO, 0);
        }
        else
        {
            fprintf(log_file, "%s: No fire\n", time_str);
        }

        sleep(500);
    }

    cleanup();
    return EXIT_SUCCESS;
}

