#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_LINE 4
#define GPIO_CHIP "gpiochip0"
#define LOG_FILE "touch_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S: %s\n"
#define LOG_FORMAT_SIZE 25
#define DEBOUNCE_INTERVAL 50000

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

static void sig_handler(int signum)
{
    running = 0;
}

static int init_gpio(void)
{
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        ret = -1;
        goto err_close_chip;
    }

    ret = gpiod_line_request_input(line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        goto err_close_line;
    }

    ret = gpiod_line_set_debounce(line, DEBOUNCE_INTERVAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to set debounce interval: %s\n", strerror(errno));
        goto err_close_line;
    }

    return 0;

err_close_line:
    gpiod_line_release(line);
err_close_chip:
    gpiod_chip_close(chip);
    return ret;
}

static void release_gpio(void)
{
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

static int init_log(void)
{
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void release_log(void)
{
    fclose(log_file);
}

static int log_event(const char *event)
{
    char buf[LOG_FORMAT_SIZE];
    time_t now;
    struct tm *tm;

    now = time(NULL);
    tm = localtime(&now);
    if (!tm) {
        fprintf(stderr, "Failed to get local time: %s\n", strerror(errno));
        return -1;
    }

    if (!strftime(buf, sizeof(buf), LOG_FORMAT, tm)) {
        fprintf(stderr, "Failed to format time: %s\n", strerror(errno));
        return -1;
    }

    if (fputs(buf, log_file) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) < 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int ret;
    int value;

    if (init_gpio() < 0)
        return EXIT_FAILURE;

    if (init_log() < 0) {
        release_gpio();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
            break;
        }

        if (value) {
            if (log_event("Touch Detected") < 0)
                break;
        } else {
            if (log_event("Touch Released") < 0)
                break;
        }

        usleep(DEBOUNCE_INTERVAL);
    }

    release_log();
    release_gpio();

    return EXIT_SUCCESS;
}

