#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_LEFT 17
#define GPIO_LINE_MIDDLE 27
#define GPIO_LINE_RIGHT 22
#define LOG_FILE_NAME "path_log.csv"
#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *line_left;
static struct gpiod_line *line_middle;
static struct gpiod_line *line_right;
static int log_file;

static void cleanup(void)
{
    gpiod_line_release(line_left);
    gpiod_line_release(line_middle);
    gpiod_line_release(line_right);
    gpiod_chip_close(chip);
    fflush(stdout);
    close(log_file);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static void log_path(void)
{
    struct timespec ts;
    char timestamp[26];
    int left, middle, right;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        cleanup();
        exit(EXIT_FAILURE);
    }
    strftime(timestamp, sizeof(timestamp), "%FT%T%z", gmtime(&ts.tv_sec));
    left = gpiod_line_get_value(line_left);
    if (left == -1) {
        perror("gpiod_line_get_value");
        cleanup();
        exit(EXIT_FAILURE);
    }
    middle = gpiod_line_get_value(line_middle);
    if (middle == -1) {
        perror("gpiod_line_get_value");
        cleanup();
        exit(EXIT_FAILURE);
    }
    right = gpiod_line_get_value(line_right);
    if (right == -1) {
        perror("gpiod_line_get_value");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (dprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right) == -1) {
        perror("dprintf");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

int main(void)
{
    struct sigaction sa;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        exit(EXIT_FAILURE);
    }
    line_left = gpiod_chip_get_line(chip, GPIO_LINE_LEFT);
    if (line_left == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_LEFT, strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(line_left, "path_log") == -1) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE_LEFT, strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    line_middle = gpiod_chip_get_line(chip, GPIO_LINE_MIDDLE);
    if (line_middle == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_MIDDLE, strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(line_middle, "path_log") == -1) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE_MIDDLE, strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    line_right = gpiod_chip_get_line(chip, GPIO_LINE_RIGHT);
    if (line_right == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_RIGHT, strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(line_right, "path_log") == -1) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE_RIGHT, strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }
    log_file = open(LOG_FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_file == -1) {
        perror("open");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (dprintf(log_file, "timestamp,left,middle,right\n") == -1) {
        perror("dprintf");
        cleanup();
        exit(EXIT_FAILURE);
    }
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup();
        exit(EXIT_FAILURE);
    }
    while (true) {
        log_path();
        usleep(POLL_INTERVAL_MS * 1000);
    }
}

