#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "4"
#define GPIO_LINE_DIRECTION "in"
#define GPIO_LINE_ACTIVE_STATE "low"
#define GPIO_LINE_EDGE "falling"
#define GPIO_LINE_CONSUMER "flame_sensor"

#define LOG_FILE "flame_events.txt"

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    struct timespec ts;
    FILE *fp;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %s: %s\n",
                GPIO_LINE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Request the GPIO line */
    memset(&req, 0, sizeof(req));
    req.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;
    req.consumer = GPIO_LINE_CONSUMER;
    if (gpiod_line_request(line, &req, 0)) {
        fprintf(stderr, "Failed to request GPIO line %s: %s\n",
                GPIO_LINE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the log file */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Loop until interrupted */
    while (1) {
        /* Wait for an event */
        if (gpiod_line_event_wait(line, NULL)) {
            fprintf(stderr, "Failed to wait for GPIO line event: %s\n",
                    strerror(errno));
            return EXIT_FAILURE;
        }

        /* Get the event */
        if (gpiod_line_event_read(line, &event)) {
            fprintf(stderr, "Failed to read GPIO line event: %s\n",
                    strerror(errno));
            return EXIT_FAILURE;
        }

        /* Get the timestamp */
        if (clock_gettime(CLOCK_REALTIME, &ts)) {
            fprintf(stderr, "Failed to get timestamp: %s\n",
                    strerror(errno));
            return EXIT_FAILURE;
        }

        /* Print the alert */
        printf("Flame detected at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

        /* Log the event */
        fprintf(fp, "%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        fflush(fp);
    }

    /* Close the log file */
    fclose(fp);

    /* Release the GPIO line */
    gpiod_line_release(line);

    /* Close the GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

