#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define BUZZER_SLICE_MS 100
#define LOG_FILE "alert_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;
static volatile sig_atomic_t shutdown_requested = 0;

static void shutdown_handler(int signum)
{
    shutdown_requested = 1;
}

static void log_event(const char *event)
{
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), event);
    fflush(log_file);
}

static void buzzer_on(void)
{
    int ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer line value: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void buzzer_off(void)
{
    int ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer line value: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void buzzer_activate(void)
{
    buzzer_on();
    usleep(BUZZER_DURATION_MS * 1000);
    buzzer_off();
}

static void buzzer_activate_sliced(void)
{
    int num_slices = BUZZER_DURATION_MS / BUZZER_SLICE_MS;
    for (int i = 0; i < num_slices; i++) {
        buzzer_on();
        usleep(BUZZER_SLICE_MS * 1000);
        buzzer_off();
        usleep(BUZZER_SLICE_MS * 1000);
        if (shutdown_requested) {
            break;
        }
    }
}

int main(void)
{
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Get the flame sensor line
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Get the buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request input for the flame sensor line
    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting input for flame sensor line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request output for the buzzer line
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting output for buzzer line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    // Log system started
    log_event("System started");

    // Main loop
    while (!shutdown_requested) {
        // Poll the flame sensor
        int flame_detected = gpiod_line_get_value(flame_sensor_line);
        if (flame_detected < 0) {
            fprintf(stderr, "Error getting flame sensor line value: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Check for a flame detection
        if (flame_detected == 0) {
            // Log the event
            log_event("Flame detected");

            // Activate the buzzer
            buzzer_activate_sliced();
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Log system stopped
    log_event("System stopped");

    // Turn off the buzzer
    buzzer_off();

    // Release the lines
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);

    // Close the chip
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

    return EXIT_SUCCESS;
}

