    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Get the flame sensor line
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Get the buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request input for the flame sensor line
    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting input for flame sensor line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request output for the buzzer line
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting output for buzzer line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    // Log system started
    log_event("System started");

    // Main loop
    while (!shutdown_requested) {
        // Poll the flame sensor
        int flame_detected = gpiod_line_get_value(flame_sensor_line);
        if (flame_detected < 0) {
            fprintf(stderr, "Error getting flame sensor line value: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

