            // Activate the buzzer
            buzzer_activate_sliced();
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Log system stopped
    log_event("System stopped");

    // Turn off the buzzer
    buzzer_off();

    // Release the lines
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);

    // Close the chip
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

