#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_MS 200
#define LOG_FILE "touch_log.txt"

static FILE *log_file;
static int led_state = 0;
static int last_touch_state = 0;
static time_t last_touch_time = 0;

static void toggle_led(void)
{
    led_state = !led_state;
    gpioWrite(LED_PIN, led_state);
}

static void log_touch(void)
{
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char time_str[32];

    strftime(time_str, sizeof(time_str), "%FT%TZ", time_info);
    fprintf(log_file, "%s\n", time_str);
    fflush(log_file);
}

static void handle_touch(int touch_state)
{
    if (touch_state == last_touch_state) {
        return;
    }

    if (touch_state == 0) {
        time_t now = time(NULL);
        if (now - last_touch_time < DEBOUNCE_MS / 1000) {
            return;
        }
        last_touch_time = now;
    }

    last_touch_state = touch_state;
    toggle_led();
    log_touch();
}

static void handle_signal(int signum)
{
    gpioWrite(LED_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioErrMsg(ret));
        return 1;
    }

    ret = gpioSetMode(TOUCH_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", gpioErrMsg(ret));
        return 1;
    }

    ret = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", gpioErrMsg(ret));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int touch_state = gpioRead(TOUCH_PIN);
        if (touch_state < 0) {
