#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define I2C_PART_ID 0x00
#define I2C_HW_REV 0x01
#define I2C_LED_CURRENT 0x3F
#define I2C_AVERAGING 0x04
#define I2C_ENABLE 0x01
#define I2C_HEART_RATE 0x2A

#define LED_CURRENT 0x0F
#define AVERAGING 0x01
#define ENABLE 0x01

#define BPM_MIN 30
#define BPM_MAX 220

#define LOG_FILE "heart_rate.csv"

int main(void)
{
    int i2cHandle;
    int partId;
    int hwRev;
    int ledCurrent;
    int averaging;
    int enable;
    int heartRate;
    int bpm;
    int bpmAvg;
    int bpmAvgCount;
    int bpmAvgSum;
    int bpmAvgIndex;
    int bpmAvgArray[5];
    FILE *logFile;
    time_t now;
    struct tm *timeInfo;
    char timeString[20];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    partId = i2cReadByteData(i2cHandle, I2C_PART_ID);
    if (partId < 0)
    {
        fprintf(stderr, "Failed to read PART_ID register\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (partId != 0x02)
    {
        fprintf(stderr, "Invalid PART_ID 0x%02X\n", partId);
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    hwRev = i2cReadByteData(i2cHandle, I2C_HW_REV);
    if (hwRev < 0)
    {
        fprintf(stderr, "Failed to read HW_REV register\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (hwRev != 0x01)
    {
        fprintf(stderr, "Invalid HW_REV 0x%02X\n", hwRev);
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ledCurrent = i2cWriteByteData(i2cHandle, I2C_LED_CURRENT, LED_CURRENT);
    if (ledCurrent < 0)
    {
        fprintf(stderr, "Failed to write LED_CURRENT register\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    averaging = i2cWriteByteData(i2cHandle, I2C_AVERAGING, AVERAGING);
    if (averaging < 0)
    {
        fprintf(stderr, "Failed to write AVERAGING register\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    enable = i2cWriteByteData(i2cHandle, I2C_ENABLE, ENABLE);
    if (enable < 0)
    {
        fprintf(stderr, "Failed to write ENABLE register\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL)
    {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bpmAvgCount = 0;
    bpmAvgSum = 0;
    bpmAvgIndex = 0;

    while (1)
    {
        heartRate = i2cReadWordData(i2cHandle, I2C_HEART_RATE);
        if (heartRate < 0)
        {
            fprintf(stderr, "Failed to read HEART_RATE register\n");
            break;
        }

        bpm = heartRate * 0.5;

        if (bpm >= BPM_MIN && bpm <= BPM_MAX)
        {
            bpmAvgArray[bpmAvgIndex] = bpm;
            bpmAvgIndex = (bpmAvgIndex + 1) % 5;
            bpmAvgCount++;
            bpmAvgSum += bpm;
            bpmAvg = bpmAvgSum / bpmAvgCount;

            now = time(NULL);
            timeInfo = localtime(&now);
            strftime(timeString, sizeof(timeString), "%Y-%m-%d %H:%M:%S", timeInfo);

            fprintf(logFile, "%s,%d\n", timeString, bpmAvg);
            fflush(logFile);
        }
    }

    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

