#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "17"
#define GPIO_LINE_DIRECTION "in"
#define GPIO_LINE_ACTIVE_STATE "1"
#define GPIO_LINE_EDGE "falling"
#define GPIO_LINE_PULL "up"
#define GPIO_LINE_CONSUMER "flame_sensor"
#define GPIO_LINE_DELAY_MS 100

#define LOG_FILE_NAME "flame_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_line_request req;
struct gpiod_line_event event;

FILE *log_file;

void sigint_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(0);
    }
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    req.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    req.consumer = GPIO_LINE_CONSUMER;
    req.event_flags = GPIOD_LINE_REQUEST_FLAG_EVENT_FALLING_EDGE;
    req.line_offset = gpiod_line_get_offset(line);
    req.default_values = 0;
    req.flags = 0;

    if (gpiod_line_request(line, &req, 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_active_state(line, GPIO_LINE_ACTIVE_STATE) < 0) {
        fprintf(stderr, "Error: Failed to set active state\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_direction(line, GPIO_LINE_DIRECTION) < 0) {
        fprintf(stderr, "Error: Failed to set direction\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_edge_flags(line, GPIOD_LINE_EVENT_FALLING_EDGE) < 0) {
        fprintf(stderr, "Error: Failed to set edge flags\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_pull(line, GPIO_LINE_PULL) < 0) {
        fprintf(stderr, "Error: Failed to set pull\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        if (gpiod_line_event_wait(line, &event) < 0) {
            fprintf(stderr, "Error: Failed to wait for GPIO line event\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return 1;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

            printf("FLAME DETECTED\n");
            fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
            fflush(log_file);
        }

        usleep(GPIO_LINE_DELAY_MS * 1000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
