#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define SENSOR_COUNT 4
#define SENSOR_GPIO_PINS {17, 18, 27, 22}

static struct gpiod_chip *chip;
static struct gpiod_line *lines[SENSOR_COUNT];
static FILE *csv_file;

static void cleanup(void)
{
    if (csv_file) {
        fclose(csv_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < SENSOR_COUNT; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;
    int sensor_values[SENSOR_COUNT];
    int sensor_gpio_pins[SENSOR_COUNT] = SENSOR_GPIO_PINS;
    struct timespec ts;
    char timestamp[32];
    char line[128];

    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Failed to register cleanup function\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < SENSOR_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", sensor_gpio_pins[i]);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(lines[i], "tracking");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d\n", sensor_gpio_pins[i]);
            return EXIT_FAILURE;
        }
    }

    csv_file = fopen("tracking_log.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        for (int i = 0; i < SENSOR_COUNT; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read GPIO line %d\n", sensor_gpio_pins[i]);
                return EXIT_FAILURE;
            }
            sensor_values[i] = ret;
        }

        snprintf(line, sizeof(line), "%s,%d,%d,%d,%d\n", timestamp, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3]);
        fputs(line, csv_file);
        fflush(csv_file);

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

