#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define LOG_FILE "/var/log/tilt_events.log"
#define LOG_FILE_MODE (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)
#define LOG_FILE_BUF_SIZE 100
#define LOG_FILE_LINE_SIZE 100
#define LOG_FILE_LINE_FORMAT "%04d-%02d-%02d %02d:%02d:%02d, Sensor %d tilted\n"

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_1_NAME "17"
#define GPIO_LINE_2_NAME "18"
#define GPIO_LINE_REQUEST_FLAGS (GPIOD_LINE_REQUEST_BIAS_PULL_UP | GPIOD_LINE_REQUEST_ACTIVE_STATE_LOW)
#define GPIO_LINE_REQUEST_EVENT_FLAGS (GPIOD_LINE_REQUEST_EVENT_RISING_EDGE | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE)
#define GPIO_LINE_REQUEST_EVENT_DEBOUNCE_NS 50000000

#define POLL_INTERVAL_NS 100000000

#define EXIT_SUCCESS 0
#define EXIT_FAILURE 1

static struct gpiod_chip *chip;
static struct gpiod_line *line1;
static struct gpiod_line *line2;
static struct gpiod_line_event event;
static struct gpiod_line_event_poll poll;
static struct timespec timestamp;
static FILE *log_file;
static char log_file_buf[LOG_FILE_BUF_SIZE];

static void log_event(int sensor)
{
    if (clock_gettime(CLOCK_REALTIME, &timestamp) == -1) {
        fprintf(stderr, "Failed to get timestamp\n");
        exit(EXIT_FAILURE);
    }

    if (strftime(log_file_buf, LOG_FILE_BUF_SIZE, LOG_FILE_LINE_FORMAT, localtime(&timestamp.tv_sec)) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        exit(EXIT_FAILURE);
    }

    if (fprintf(log_file, log_file_buf, sensor) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        exit(EXIT_FAILURE);
    }

    if (fflush(log_file) == EOF) {
        fprintf(stderr, "Failed to flush log file\n");
        exit(EXIT_FAILURE);
    }
}

static void handle_signal(int signal)
{
    if (gpiod_line_release(line1) == -1) {
        fprintf(stderr, "Failed to release line 1\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_release(line2) == -1) {
        fprintf(stderr, "Failed to release line 2\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_close(chip) == -1) {
        fprintf(stderr, "Failed to close chip\n");
        exit(EXIT_FAILURE);
    }

    if (fclose(log_file) == EOF) {
        fprintf(stderr, "Failed to close log file\n");
        exit(EXIT_FAILURE);
    }

    exit(EXIT_SUCCESS);
}

int main(void)
{
    if ((chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME)) == NULL) {
        fprintf(stderr, "Failed to open chip\n");
        exit(EXIT_FAILURE);
    }

    if ((line1 = gpiod_chip_get_line(chip, GPIO_LINE_1_NAME)) == NULL) {
        fprintf(stderr, "Failed to get line 1\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line1, "tilt_monitor", GPIO_LINE_REQUEST_FLAGS) == -1) {
        fprintf(stderr, "Failed to request line 1\n");
        exit(EXIT_FAILURE);
    }

    if ((line2 = gpiod_chip_get_line(chip, GPIO_LINE_2_NAME)) == NULL) {
        fprintf(stderr, "Failed to get line 2\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line2, "tilt_monitor", GPIO_LINE_REQUEST_FLAGS) == -1) {
        fprintf(stderr, "Failed to request line 2\n");
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_event(line1, "tilt_monitor", GPIO_LINE_REQUEST_EVENT_FLAGS, GPIO_LINE_REQUEST_EVENT_DEBOUNCE_NS) == -1) {
        fprintf(stderr, "Failed to request line 1 event\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_event(line2, "tilt_monitor", GPIO_LINE_REQUEST_EVENT_FLAGS, GPIO_LINE_REQUEST_EVENT_DEBOUNCE_NS) == -1) {
        fprintf(stderr, "Failed to request line 2 event\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_event_poll_init(&poll) == -1) {
        fprintf(stderr, "Failed to initialize event poll\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_event_poll_add_fd(line1, &poll) == -1) {
        fprintf(stderr, "Failed to add line 1 to event poll\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_event_poll_add_fd(line2, &poll) == -1) {
        fprintf(stderr, "Failed to add line 2 to event poll\n");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (gpiod_line_event_poll_wait(&poll, &event, POLL_INTERVAL_NS) == -1) {
            fprintf(stderr, "Failed to wait for event\n");
            exit(EXIT_FAILURE);
        }

        if (event.line == line1) {
            log_event(1);
        } else if (event.line == line2) {
            log_event(2);
        }
    }

    return EXIT_SUCCESS;
}

