#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR1 17
#define SENSOR2 27
#define LED 22

struct gpiod_chip *chip;
struct gpiod_line *sensor1, *sensor2, *led;

void sigint_handler(int sig)
{
    gpiod_line_set_value(led, 0);
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    exit(0);
}

int main(void)
{
    struct timespec ts;
    FILE *fp;
    int sensor1_val, sensor2_val, led_val;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiochip0");
        exit(1);
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1);
    if (!sensor1) {
        perror("sensor1");
        exit(1);
    }
    gpiod_line_request_input(sensor1, "sensor1");

    sensor2 = gpiod_chip_get_line(chip, SENSOR2);
    if (!sensor2) {
        perror("sensor2");
        exit(1);
    }
    gpiod_line_request_input(sensor2, "sensor2");

    led = gpiod_chip_get_line(chip, LED);
    if (!led) {
        perror("led");
        exit(1);
    }
    gpiod_line_request_output(led, 0, "led");

    fp = fopen("obstacle_log.csv", "w");
    if (!fp) {
        perror("obstacle_log.csv");
        exit(1);
    }

    while (1) {
        sensor1_val = gpiod_line_get_value(sensor1);
        sensor2_val = gpiod_line_get_value(sensor2);
        led_val = (sensor1_val == 0 && sensor2_val == 0) ? 1 : 0;
        gpiod_line_set_value(led, led_val);

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(fp, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_val, sensor2_val, led_val);
        fflush(fp);

        usleep(100000);
    }

    return 0;
}

