#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define MIC_PIN 4
#define LED_PIN 17

volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        return 1;
    }

    signal(SIGINT, intHandler);

    while (keep_running) {
        if (gpioRead(MIC_PIN) == 1) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%03ld\n", ts.tv_sec, ts.tv_nsec / 1000000);
            gpioWrite(LED_PIN, 1);
            gpioDelay(100000);
            gpioWrite(LED_PIN, 0);
        }
        gpioDelay(125);
    }

    gpioTerminate();
    return 0;
}

