struct gpiod_line *center_sensor_line;
struct gpiod_line *right_sensor_line;
struct gpiod_chip *chip;

void cleanup() {
    gpiod_line_release(left_sensor_line);
    gpiod_line_release(center_sensor_line);
    gpiod_line_release(right_sensor_line);
    gpiod_chip_close(chip);
    gpiod_exit();
}

