#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define I2C_REG_ALS_VIS_LSB 0x24
#define I2C_REG_ALS_VIS_MSB 0x25
#define I2C_READ_LEN 2
#define I2C_READ_DELAY_MS 100

int i2c_fd = -1;

void cleanup(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void sig_handler(int signo)
{
    if (signo == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        cleanup();
        exit(0);
    }
}

int main(void)
{
    int ret;
    char i2c_dev_path[20];
    char i2c_read_buf[I2C_READ_LEN];
    unsigned short i2c_read_val;

    // Register signal handler for SIGINT
    signal(SIGINT, sig_handler);

    // Open I2C bus
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        printf("Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        printf("Error setting I2C slave address: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    // Read ALS visible data registers
    while (1) {
        ret = read(i2c_fd, i2c_read_buf, I2C_READ_LEN);
        if (ret < 0) {
            printf("Error reading from I2C device: %s\n", strerror(errno));
            cleanup();
            return -1;
        }

        // Combine LSB and MSB into a 16-bit value
        i2c_read_val = (i2c_read_buf[1] << 8) | i2c_read_buf[0];

        // Log the raw sensor values
        printf("ALS visible data: 0x%04X\n", i2c_read_val);

        // Delay for 100 ms
        usleep(I2C_READ_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
