#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_LEFT 2
#define GPIO_LINE_MIDDLE 3
#define GPIO_LINE_RIGHT 4

static struct gpiod_chip *chip;
static struct gpiod_line *line_left, *line_middle, *line_right;
static int running = 1;

static void sigint_handler(int signum)
{
    running = 0;
}

int main(void)
{
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP_NAME);
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    line_left = gpiod_chip_get_line(chip, GPIO_LINE_LEFT);
    if (!line_left) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE_LEFT);
        goto err_close_chip;
    }
    ret = gpiod_line_request_input(line_left, "line_left");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LINE_LEFT);
        goto err_close_line_left;
    }

    line_middle = gpiod_chip_get_line(chip, GPIO_LINE_MIDDLE);
    if (!line_middle) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE_MIDDLE);
        goto err_close_line_left;
    }
    ret = gpiod_line_request_input(line_middle, "line_middle");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LINE_MIDDLE);
        goto err_close_line_middle;
    }

    line_right = gpiod_chip_get_line(chip, GPIO_LINE_RIGHT);
    if (!line_right) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE_RIGHT);
        goto err_close_line_middle;
    }
    ret = gpiod_line_request_input(line_right, "line_right");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LINE_RIGHT);
        goto err_close_line_right;
    }

    // Install signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read the GPIO lines
        int value_left = gpiod_line_get_value(line_left);
        int value_middle = gpiod_line_get_value(line_middle);
        int value_right = gpiod_line_get_value(line_right);

        // Print the sensor values
        printf("L:%d M:%d R:%d\n", value_left, value_middle, value_right);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(line_right);
err_close_line_right:
    gpiod_line_release(line_middle);
err_close_line_middle:
    gpiod_line_release(line_left);
err_close_line_left:
    gpiod_chip_close(chip);
err_close_chip:
    return EXIT_SUCCESS;
}

