#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

static struct gpiod_line *lines[8];
static struct gpiod_chip *chip;

static void sigint_handler(int sig)
{
	int i;

	for (i = 0; i < ARRAY_SIZE(lines); i++)
		gpiod_line_release(lines[i]);
	gpiod_chip_close(chip);
	exit(0);
}

int main(void)
{
	struct timespec ts;
	int i, ret;

	signal(SIGINT, sigint_handler);
	signal(SIGTERM, sigint_handler);

	chip = gpiod_chip_open_by_name("gpiochip0");
	if (!chip) {
		fprintf(stderr, "Failed to open gpiochip0\n");
		return 1;
	}

	for (i = 0; i < ARRAY_SIZE(lines); i++) {
		lines[i] = gpiod_chip_get_line(chip, 5 + i);
		if (!lines[i]) {
			fprintf(stderr, "Failed to get line %d\n", 5 + i);
			return 1;
		}

		ret = gpiod_line_request_input(lines[i], "touch");
		if (ret < 0) {
			fprintf(stderr, "Failed to request line %d\n", 5 + i);
			return 1;
		}
	}

	while (1) {
		clock_gettime(CLOCK_MONOTONIC, &ts);
		printf("[%ld.%03lds] ", ts.tv_sec, ts.tv_nsec / 1000000);

		for (i = 0; i < ARRAY_SIZE(lines); i++) {
			ret = gpiod_line_get_value(lines[i]);
			if (ret < 0) {
				fprintf(stderr, "Failed to read line %d\n", 5 + i);
				return 1;
			}
			printf("CH%d=%d ", i + 1, ret);
		}
		printf("\n");

		usleep(200000);
	}

	return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDR 0x29
#define I2C_BUS 1
#define I2C_FILE "/dev/i2c-1"
#define GPIO_PIN 17

#define REG_ENABLE 0x00
#define REG_ATIME 0x01
#define REG_CONTROL 0x0F
#define REG_ID 0x12
#define REG_CLEAR_LO 0x14
#define REG_CLEAR_HI 0x15
#define REG_RED_LO 0x16
#define REG_RED_HI 0x17
#define REG_GREEN_LO 0x18
#define REG_GREEN_HI 0x19
#define REG_BLUE_LO 0x1A
#define REG_BLUE_HI 0x1B

#define ENABLE_PON 0x01
#define ENABLE_AEN 0x02
#define ATIME_154MS 0x00
#define CONTROL_1X 0x00
#define ID_TCS34725 0x44

#define GAIN_RED 1.0
#define GAIN_GREEN 1.0
#define GAIN_BLUE 1.0
#define GAIN_CLEAR 1.0
#define OFFSET_RED 0
#define OFFSET_GREEN 0
#define OFFSET_BLUE 0
#define OFFSET_CLEAR 0

#define THRESHOLD 200

int main(void)
{
    int fd;
    int ret;
    uint8_t buf[2];
    uint16_t clear, red, green, blue;
    bool led_on = false;

    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    buf[0] = REG_ENABLE;
    buf[1] = ENABLE_PON;
    ret = write(fd, buf, 2);
    if (ret < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    buf[0] = REG_ATIME;
    buf[1] = ATIME_154MS;
    ret = write(fd, buf, 2);
    if (ret < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    buf[0] = REG_CONTROL;
    buf[1] = CONTROL_1X;
    ret = write(fd, buf, 2);
    if (ret < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    buf[0] = REG_ENABLE;
    buf[1] = ENABLE_PON | ENABLE_AEN;
    ret = write(fd, buf, 2);
    if (ret < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    buf[0] = REG_ID;
    ret = write(fd, buf, 1);
    if (ret < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    ret = read(fd, buf, 1);
    if (ret < 0) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    if (buf[0] != ID_TCS34725) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X\n", buf[0]);
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        exit(EXIT_FAILURE);
    }

    while (true) {
        buf[0] = REG_CLEAR_LO;
        ret = write(fd, buf, 1);
        if (ret < 0) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        ret = read(fd, buf, 2);
        if (ret < 0) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        clear = buf[0] | (buf[1] << 8);

        buf[0] = REG_RED_LO;
        ret = write(fd, buf, 1);
        if (ret < 0) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        ret = read(fd, buf, 2);
        if (ret < 0) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        red = buf[0] | (buf[1] << 8);

        buf[0] = REG_GREEN_LO;
        ret = write(fd, buf, 1);
        if (ret < 0) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        ret = read(fd, buf, 2);
        if (ret < 0) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        green = buf[0] | (buf[1] << 8);

        buf[0] = REG_BLUE_LO;
        ret = write(fd, buf, 1);
        if (ret < 0) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        ret = read(fd, buf, 2);
        if (ret < 0) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        blue = buf[0] | (buf[1] << 8);

        clear = (uint16_t)((float)clear * GAIN_CLEAR + OFFSET_CLEAR);
        red = (uint16_t)((float)red * GAIN_RED + OFFSET_RED);
        green = (uint16_t)((float)green * GAIN_GREEN + OFFSET_GREEN);
        blue = (uint16_t)((float)blue * GAIN_BLUE + OFFSET_BLUE);

        printf("C: %u, R: %u, G: %u, B: %u\n", clear, red, green, blue);

        if (red > THRESHOLD) {
            if (!led_on) {
                gpioWrite(GPIO_PIN, 1);
                led_on = true;
            }
        } else {
            if (led_on) {
                gpioWrite(GPIO_PIN, 0);
                led_on = false;
            }
        }

        usleep(200000);
    }

    gpioTerminate();
    close(fd);

    return 0;
}

