#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>

#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_CONTINUOUS_HIGH_RES_MODE_2 0x11
#define BH1750_CONTINUOUS_LOW_RES_MODE 0x13
#define BH1750_POWER_DOWN 0x00
#define BH1750_POWER_ON 0x01
#define BH1750_RESET 0x07

#define APA102_START_FRAME 0x00
#define APA102_GLOBAL_BRIGHTNESS 0x00
#define APA102_END_FRAME 0xFF

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000

#define I2C_BUS 1

#define NUM_SENSORS 3

#define FADE_DELAY 500
#define FADE_STEP 1

#define SENSOR_READ_DELAY 180

#define LUX_TO_BRIGHTNESS(lux) (31 - (lux / 100))

#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define MIN(a, b) ((a) < (b) ? (a) : (b))

#define ARRAY_SIZE(arr) (sizeof(arr) / sizeof((arr)[0]))

static int spi_handle = -1;
static int i2c_handles[NUM_SENSORS] = { -1, -1, -1 };
static int brightness = 0;

static void cleanup(void)
{
    int i;

    if (spi_handle >= 0) {
        gpioTerminate();
        spi_handle = -1;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_spi(void)
{
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrMsg(ret));
        return -1;
    }

    spi_handle = spiOpen(SPI_BUS, SPI_DEVICE, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", spiErrMess(spi_handle));
        return -1;
    }

    return 0;
}

static int init_i2c(void)
{
    int i;

    for (i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, BH1750_ADDR_LOW + i, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to open I2C device: %s\n", i2cErrMess(i2c_handles[i]));
            return -1;
        }
    }

    return 0;
}

static int init_bh1750(int i2c_handle)
{
    int ret;

    ret = i2cWriteByte(i2c_handle, BH1750_ONE_TIME_HIGH_RES_MODE_2);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", i2cErrMess(ret));
        return -1;
    }

    return 0;
}

static int read_bh1750(int i2c_handle, uint16_t *lux)
{
    int ret;
    uint8_t buf[2];

    ret = i2cReadI2CBlockData(i2c_handle, 0, 2, buf);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", i2cErrMess(ret));
        return -1;
    }

    *lux = (buf[0] << 8) | buf[1];

    return 0;
}

static int write_apa102(uint8_t brightness)
{
    int ret;
    uint8_t buf[4];

    buf[0] = APA102_START_FRAME;
    buf[1] = brightness;
    buf[2] = APA102_END_FRAME;
    buf[3] = APA102_END_FRAME;

    ret = spiWrite(spi_handle, buf, ARRAY_SIZE(buf));
    if (ret < 0) {
        fprintf(stderr, "Failed to write to SPI device: %s\n", spiErrMess(ret));
        return -1;
    }

    return 0;
}

static int fade_brightness(int target)
{
    int ret;
    int step;
    int i;

    step = (target > brightness) ? FADE_STEP : -FADE_STEP;

    for (i = brightness; i != target; i += step) {
