#define LED_DIRECTION GPIOD_LINE_DIRECTION_OUTPUT

#define FLAME_SENSOR_CONSUMER "flame_sensor"
#define BUZZER_CONSUMER "buzzer"
#define LED_CONSUMER "led"

#define FLAME_SENSOR_REQUEST_FLAGS (GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)
#define BUZZER_REQUEST_FLAGS (GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)
#define LED_REQUEST_FLAGS (GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)

