#define FLAME_SENSOR_EVENT_TYPE GPIOD_LINE_EVENT_RISING_EDGE

#define FLAME_SENSOR_POLL_INTERVAL_MS 50
#define FLAME_SENSOR_SELF_TEST_INTERVAL_MS 100
#define FLAME_SENSOR_SELF_TEST_COUNT 5

#define FLAME_SENSOR_SELF_TEST_FAILURE_LED_BLINK_INTERVAL_MS 100
#define FLAME_SENSOR_SELF_TEST_FAILURE_LED_BLINK_COUNT 5
