    current_time = time(NULL);
    current_time_string = ctime(&current_time);
    current_time_string[strlen(current_time_string) - 1] = '\0';

    fprintf(stderr, FLAME_SENSOR_EVENT_LOG_FORMAT, current_time, event);

    dprintf(flame_sensor_event_log_file_descriptor, FLAME_SENSOR_EVENT_LOG_FORMAT, current_time, event);
}

void flame_sensor_event_log_close()
{
    close(flame_sensor_event_log_file_descriptor);
}

void flame_sensor_event_log_open()
{
    flame_sensor_event_log_file_descriptor = open(FLAME_SENSOR_EVENT_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);

    if (flame_sensor_event_log_file_descriptor < 0)
    {
        perror("open");
        exit(EXIT_FAILURE);
    }
}

void flame_sensor_event_log_init()
{
    flame_sensor_event_log_open();
    flame_sensor_event_log("flame sensor event log initialized");
}

