        for (j = 0; j < FLAME_SENSOR_SELF_TEST_FAILURE_BUZZER_PATTERN_LONG_MS / FLAME_SENSOR_SELF_TEST_INTERVAL_MS; j++)
        {
            gpiod_line_set_value(buzzer_line, 1);
            usleep(FLAME_SENSOR_SELF_TEST_INTERVAL_MS * 1000);
        }
