    for (i = 0; i < FLAME_SENSOR_SELF_TEST_FAILURE_LED_BLINK_COUNT; i++)
    {
        for (j = 0; j < FLAME_SENSOR_SELF_TEST_FAILURE_LED_BLINK_INTERVAL_MS / FLAME_SENSOR_SELF_TEST_INTERVAL_MS; j++)
        {
            gpiod_line_set_value(led_line, 1);
            usleep(FLAME_SENSOR_SELF_TEST_INTERVAL_MS * 1000);
        }

        for (j = 0; j < FLAME_SENSOR_SELF_TEST_FAILURE_LED_BLINK_INTERVAL_MS / FLAME_SENSOR_SELF_TEST_INTERVAL_MS; j++)
        {
            gpiod_line_set_value(led_line, 0);
            usleep(FLAME_SENSOR_SELF_TEST_INTERVAL_MS * 1000);
