    flame_sensor_event_log(FLAME_SENSOR_EVENT_LOG_FORMAT_SELF_TEST_FAILURE);
    flame_sensor_self_test_failure_buzzer_pattern();
    flame_sensor_self_test_failure_led_blink();
    exit(EXIT_FAILURE);
}

void flame_sensor_self_test()
{
    int i;

    for (i = 0; i < FLAME_SENSOR_SELF_TEST_COUNT; i++)
    {
        flame_sensor_self_test_value = gpiod_line_get_value(flame_sensor_line);

        if (flame_sensor_self_test_value < 0)
        {
            perror("gpiod_line_get_value");
            exit(EXIT_FAILURE);
        }

        if (flame_sensor_self_test_value == FLAME_SENSOR_ACTIVE_LOW)
        {
            flame_sensor_self_test_failure();
        }

        usleep(FLAME_SENSOR_SELF_TEST_INTERVAL_MS * 1000);
    }
}

void flame_sensor_event_handler(const struct gpiod_line_event *event, void *data)
{
    if (event->event_type == FLAME_SENSOR_EVENT_TYPE)
    {
        flame_sensor_value = gpiod_line_get_value(flame_sensor_line);

        if (flame_sensor_value < 0)
        {
            perror("gpiod_line_get_value");
            exit(EXIT_FAILURE);
        }

        if (flame_sensor_value == FLAME_SENSOR_ACTIVE_LOW)
        {
            flame_sensor_event_log(FLAME_SENSOR_EVENT_LOG_FORMAT_FLAME_DETECTED);
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
        }
        else
        {
            flame_sensor_event_log(FLAME_SENSOR_EVENT_LOG_FORMAT_FLAME_GONE);
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
        }
    }
}

void flame_sensor_init()
{
    chip = gpiod_chip_open_by_name(FLAME_SENSOR_NAME);

    if (chip == NULL)
    {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);

    if (flame_sensor_line == NULL)
    {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(flame_sensor_line, FLAME_SENSOR_CONSUMER) < 0)
    {
        perror("gpiod_line_request_input");
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_LINE);

    if (buzzer_line == NULL)
    {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, BUZZER_CONSUMER, 0) < 0)
    {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);

    if (led_line == NULL)
    {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, LED_CONSUMER, 0) < 0)
    {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    flame_sensor_self_test();

    if (gpiod_line_event_request(flame_sensor_line, FLAME_SENSOR_CONSUMER, FLAME_SENSOR_EVENT_TYPE) < 0)
    {
        perror("gpiod_line_event_request");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_event_set_consumer(flame_sensor_line, FLAME_SENSOR_CONSUMER) < 0)
    {
        perror("gpiod_line_event_set_consumer");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_event_set_callback(flame_sensor_line, flame_sensor_event_handler, NULL) < 0)
    {
        perror("gpiod_line_event_set_callback");
        exit(EXIT_FAILURE);
    }
}

void flame_sensor_deinit()
{
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
}

void signal_handler(int signal)
{
    flame_sensor_deinit();
    flame_sensor_event_log_deinit();
    exit(EXIT_SUCCESS);
}

int main()
{
    signal(SIGINT, signal_handler);

    flame_sensor_event_log_init();
    flame_sensor_init();

    while (1)
    {
        usleep(FLAME_SENSOR_POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

