#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define I2C_ADDR 0x23
#define I2C_BUS 1
#define I2C_DEV "/dev/i2c-1"
#define GPIO_PIN 17
#define GPIO_DEV "/sys/class/gpio/gpio17"
#define GPIO_DIR "/sys/class/gpio/gpio17/direction"
#define GPIO_VAL "/sys/class/gpio/gpio17/value"
#define BUF_SIZE 60

int fd;
int gpio_fd;
int buf_index = 0;
int buf[BUF_SIZE];

void cleanup() {
    close(fd);
    close(gpio_fd);
    system("echo 17 > /sys/class/gpio/unexport");
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    // Open I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return 1;
    }

    // Initialize BH1750 in continuous high-resolution mode
    char init_cmd = 0x10;
    if (write(fd, &init_cmd, 1) != 1) {
        perror("Failed to initialize BH1750");
        close(fd);
        return 1;
    }

    // Open GPIO device
    system("echo 17 > /sys/class/gpio/export");
    system("echo out > /sys/class/gpio/gpio17/direction");
    gpio_fd = open(GPIO_VAL, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(fd);
        system("echo 17 > /sys/class/gpio/unexport");
        return 1;
    }

    // Main loop
    while (1) {
        // Read raw value from BH1750
        char raw_data[2];
        if (read(fd, raw_data, 2) != 2) {
            perror("Failed to read from BH1750");
            continue;
        }

        // Convert raw value to lux
        int raw_value = (raw_data[0] << 8) | raw_data[1];
        double lux = raw_value / 1.2;

        // Store lux in circular buffer
        buf[buf_index] = lux;
        buf_index = (buf_index + 1) % BUF_SIZE;

        // Compute average lux over buffer
        double avg_lux = 0;
        for (int i = 0; i < BUF_SIZE; i++) {
            avg_lux += buf[i];
        }
        avg_lux /= BUF_SIZE;

        // Compute blink rate
        double rate = 0.5 + (avg_lux / 1000) * 4.5;
        rate = fmin(fmax(rate, 0.5), 5.0);

        // Blink LED at computed rate
        struct timespec on_time = {0, (int)(1e9 / rate / 2)};
        struct timespec off_time = {0, (int)(1e9 / rate / 2)};
        write(gpio_fd, "1", 1);
        nanosleep(&on_time, NULL);
        write(gpio_fd, "0", 1);
        nanosleep(&off_time, NULL);
    }

    return 0;
}

