#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>

#define LED_GPIO 17
#define BUTTON_GPIO 18

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;

static void cleanup(void)
{
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;
    struct gpiod_line_event event;

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(button_line, "blink_button");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_rising_edge_events(button_line, "blink_button");
    if (ret < 0) {
        perror("gpiod_line_request_rising_edge_events");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        ret = gpiod_line_event_wait(button_line, &event, 1000);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        if (ret == 0) {
            ret = gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
            if (ret < 0) {
                perror("gpiod_line_set_value");
                exit(EXIT_FAILURE);
            }
        } else {
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                exit(EXIT_FAILURE);
            }

            printf("Button pressed\n");
            break;
        }
    }

    cleanup();
    return 0;
}

