static int init_gpio(void)
{
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return -1;
    }

    ret = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO pin %s mode: %s\n", GPIO_PIN_STR, strerror(errno));
        return -1;
    }
    gpio_handle = GPIO_PIN;

    return 0;
}

static int init_log(void)
{
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE_STR, strerror(errno));
        return -1;
    }

    return 0;
}

static int poll_sensor(void)
{
    int ret;
    uint8_t buf[I2C_REG_AUTO_INC_LEN];

    ret = i2cReadI2CBlockData(i2c_handle, I2C_REG_OUT_X_L_A | I2C_REG_AUTO_INC, I2C_REG_AUTO_INC_LEN, buf);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C register %s: %s\n", I2C_REG_OUT_X_L_A_STR, strerror(errno));
        return -1;
    }

    int16_t x = (buf[1] << 8) | buf[0];
    int16_t y = (buf[3] << 8) | buf[2];
    int16_t z = (buf[5] << 8) | buf[4];

    double g_force = sqrt(x * x + y * y + z * z) / G_FORCE_SENSITIVITY;

    if (g_force > g_force_thresh) {
        ret = gpioWrite(gpio_handle, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to GPIO pin %s: %s\n", GPIO_PIN_STR, strerror(errno));
            return -1;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(log_file, "%ld.%09ld %d %d %d\n", ts.tv_sec, ts.tv_nsec, x, y, z);

        ret = gpioDelay(GPIO_PULSE_DUR);
        if (ret < 0) {
            fprintf(stderr, "Failed to delay GPIO pin %s: %s\n", GPIO_PIN_STR, strerror(errno));
            return -1;
        }

        ret = gpioWrite(gpio_handle, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to GPIO pin %s: %s\n", GPIO_PIN_STR, strerror(errno));
            return -1;
        }
    }

    return 0;
}

int main(int argc, char *argv[])
{
    int ret;

    if (argc > 1) {
        g_force_thresh = atof(argv[1]);
    }

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO pin %s mode: %s\n", GPIO_PIN_STR, strerror(errno));
        return EXIT_FAILURE;
    }
    gpio_handle = GPIO_PIN;

    ret = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    i2c_handle = ret;

    ret = i2cWriteByteData(i2c_handle, I2C_REG_CTRL_REG1_A, I2C_REG_CTRL_REG1_A_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register %s: %s\n", I2C_REG_CTRL_REG1_A_STR, strerror(errno));
        return EXIT_FAILURE;
    }

    ret = i2cWriteByteData(i2c_handle, I2C_REG_CTRL_REG4_A, I2C_REG_CTRL_REG4_A_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C register %s: %s\n", I2C_REG_CTRL_REG4_A_STR, strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE_STR, strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        ret = poll_sensor();
        if (ret < 0) {
            fprintf(stderr, "Failed to poll sensor: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        ret = gpioDelay(POLL_INTERVAL);
        if (ret < 0) {
            fprintf(stderr, "Failed to delay GPIO pin %s: %s\n", GPIO_PIN_STR, strerror(errno));
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
