#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_PIN 18
#define SAMPLE_DELAY 500
#define RETRY_DELAY 100

FILE *csv_file;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM)
    {
        fprintf(stderr, "Received signal %d, exiting...\n", signo);
        gpioPWM(LED_PIN, 0);
        gpioTerminate();
        fclose(csv_file);
        exit(0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_PIN, 1000) != 0)
    {
        fprintf(stderr, "Failed to set LED PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(LED_PIN, 255) != 0)
    {
        fprintf(stderr, "Failed to set LED PWM range\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x01) != 0)
    {
        fprintf(stderr, "Failed to write to MODE register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    csv_file = fopen("color_log.csv", "w");
    if (csv_file == NULL)
    {
        fprintf(stderr, "Failed to open CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue\n");

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1)
    {
        uint8_t lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);
        if (lsb < 0)
        {
            fprintf(stderr, "Failed to read ALS LSB\n");
            sleep(RETRY_DELAY);
            continue;
        }

        uint8_t msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);
        if (msb < 0)
        {
            fprintf(stderr, "Failed to read ALS MSB\n");
            sleep(RETRY_DELAY);
            continue;
