        uint16_t als = (msb << 8) | lsb;

        lsb = i2cReadByteData(i2c_handle, RED_REG);
        if (lsb < 0)
        {
            fprintf(stderr, "Failed to read Red LSB\n");
            sleep(RETRY_DELAY);
            continue;
        }

        msb = i2cReadByteData(i2c_handle, RED_REG + 1);
        if (msb < 0)
        {
            fprintf(stderr, "Failed to read Red MSB\n");
            sleep(RETRY_DELAY);
            continue;
        }

        uint16_t red = (msb << 8) | lsb;

        lsb = i2cReadByteData(i2c_handle, GREEN_REG);
        if (lsb < 0)
        {
            fprintf(stderr, "Failed to read Green LSB\n");
            sleep(RETRY_DELAY);
            continue;
        }

        msb = i2cReadByteData(i2c_handle, GREEN_REG + 1);
        if (msb < 0)
        {
            fprintf(stderr, "Failed to read Green MSB\n");
            sleep(RETRY_DELAY);
            continue;
        }

        uint16_t green = (msb << 8) | lsb;

        lsb = i2cReadByteData(i2c_handle, BLUE_REG);
        if (lsb < 0)
        {
            fprintf(stderr, "Failed to read Blue LSB\n");
            sleep(RETRY_DELAY);
            continue;
        }

        msb = i2cReadByteData(i2c_handle, BLUE_REG + 1);
        if (msb < 0)
        {
            fprintf(stderr, "Failed to read Blue MSB\n");
            sleep(RETRY_DELAY);
            continue;
        }

        uint16_t blue = (msb << 8) | lsb;

        fprintf(csv_file, "%ld,%d,%d,%d,%d\n", time(NULL), als, red, green, blue);
        fflush(csv_file);

        gpioPWM(LED_PIN, als >> 8);

        sleep(SAMPLE_DELAY);
    }

    return 0;
}

