#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E
#define ACCEL_REG_CTRL1 0x20
#define ACCEL_REG_OUT_X_L 0x28
#define MAG_REG_MR 0x02
#define MAG_REG_OUT_X_H 0x03

#define ACCEL_CTRL1_50HZ 0x27
#define MAG_MR_CONTINUOUS 0x00

#define ACCEL_SCALE 0.001
#define MAG_SCALE 0.00015

#define SAMPLING_PERIOD 100

#define LOG_FILE "compass_log.txt"

int accel_handle = -1;
int mag_handle = -1;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM)
    {
        if (accel_handle >= 0)
        {
            i2cClose(accel_handle);
        }
        if (mag_handle >= 0)
        {
            i2cClose(mag_handle);
        }
        gpioTerminate();
        exit(0);
    }
}

int main(int argc, char *argv[])
{
    int ret;
    uint8_t buf[6];
    double accel[3];
    double mag[3];
    double heading;
    FILE *log_file;
    int log_file_exists;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    accel_handle = i2cOpen(I2C_BUS, ACCEL_ADDR, 0);
    if (accel_handle < 0)
    {
        fprintf(stderr, "Failed to open accelerometer\n");
        return 1;
    }

    ret = i2cWriteByteData(accel_handle, ACCEL_REG_CTRL1, ACCEL_CTRL1_50HZ);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to set accelerometer sampling rate\n");
        return 1;
    }

    mag_handle = i2cOpen(I2C_BUS, MAG_ADDR, 0);
    if (mag_handle < 0)
    {
        fprintf(stderr, "Failed to open magnetometer\n");
        return 1;
    }

    ret = i2cWriteByteData(mag_handle, MAG_REG_MR, MAG_MR_CONTINUOUS);
    if (ret < 0)
    {
        fprintf(stderr, "Failed to set magnetometer sampling rate\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "r");
    if (log_file == NULL)
    {
        log_file_exists = 0;
    }
    else
    {
        fclose(log_file);
        log_file_exists = 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    if (!log_file_exists)
    {
        fprintf(log_file, "timestamp,heading,ax,ay,az,mx,my,mz\n");
    }

    while (1)
    {
        ret = i2cReadI2CBlockData(accel_handle, ACCEL_REG_OUT_X_L, buf, 6);
        if (ret < 0)
        {
            fprintf(stderr, "Failed to read accelerometer data\n");
            return 1;
        }

        accel[0] = (int16_t)((buf[1] << 8) | buf[0]) * ACCEL_SCALE;
        accel[1] = (int16_t)((buf[3] << 8) | buf[2]) * ACCEL_SCALE;
        accel[2] = (int16_t)((buf[5] << 8) | buf[4]) * ACCEL_SCALE;

        ret = i2cReadI2CBlockData(mag_handle, MAG_REG_OUT_X_H, buf, 6);
        if (ret < 0)
        {
            fprintf(stderr, "Failed to read magnetometer data\n");
            return 1;
        }

        mag[0] = (int16_t)((buf[0] << 8) | buf[1]) * MAG_SCALE;
        mag[1] = (int16_t)((buf[2] << 8) | buf[3]) * MAG_SCALE;
        mag[2] = (int16_t)((buf[4] << 8) | buf[5]) * MAG_SCALE;

        heading = atan2(mag[1], mag[0]) * 180 / M_PI;

        fprintf(log_file, "%ld,%f,%f,%f,%f,%f,%f,%f\n", gpioTick(), heading, accel[0], accel[1], accel[2], mag[0], mag[1], mag[2]);
        fflush(log_file);

        gpioDelay(SAMPLING_PERIOD);
    }

    return 0;
}
