#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define SENSOR_REG 0x01
#define CTRL_REG 0x00
#define CTRL_VAL 0x80
#define SAMPLING_INTERVAL_MS 10

FILE *log_file;

void sigint_handler(int sig)
{
    if (log_file)
    {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main(void)
{
    int sensor1_handle, sensor2_handle;
    int16_t sensor1_data, sensor2_data;
    struct timespec timestamp;
    int tdoa;

    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    sensor1_handle = i2cOpen(1, SENSOR1_ADDR, 0);
    sensor2_handle = i2cOpen(1, SENSOR2_ADDR, 0);

    if (sensor1_handle < 0 || sensor2_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(sensor1_handle, CTRL_REG, CTRL_VAL) < 0 ||
        i2cWriteByte(sensor2_handle, CTRL_REG, CTRL_VAL) < 0)
    {
        fprintf(stderr, "Failed to enable sensors\n");
        i2cClose(sensor1_handle);
        i2cClose(sensor2_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("audio_log.dat", "w");
    if (!log_file)
    {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(sensor1_handle);
        i2cClose(sensor2_handle);
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        if (clock_gettime(CLOCK_REALTIME, &timestamp) < 0)
        {
            fprintf(stderr, "Failed to get timestamp\n");
            break;
        }

        if (i2cReadWordData(sensor1_handle, SENSOR_REG, &sensor1_data) < 0 ||
            i2cReadWordData(sensor2_handle, SENSOR_REG, &sensor2_data) < 0)
        {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        tdoa = sensor1_data - sensor2_data;

        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", timestamp.tv_sec, timestamp.tv_nsec, sensor1_data, sensor2_data, tdoa);

        gpioDelay(SAMPLING_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(sensor1_handle);
    i2cClose(sensor2_handle);
    gpioTerminate();

    return 0;
}

