#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0b11000000000
#define SPI_WORD_SIZE 16
#define SPI_DUMMY_READ_DELAY 40

#define GYRO_X_REG 0x04
#define GYRO_Y_REG 0x06
#define GYRO_Z_REG 0x08
#define ACCEL_X_REG 0x0A
#define ACCEL_Y_REG 0x0C
#define ACCEL_Z_REG 0x0E

#define GYRO_X_SENSITIVITY 0.005
#define GYRO_Y_SENSITIVITY 0.005
#define GYRO_Z_SENSITIVITY 0.005
#define ACCEL_X_SENSITIVITY 0.00025
#define ACCEL_Y_SENSITIVITY 0.00025
#define ACCEL_Z_SENSITIVITY 0.00025

#define SAMPLE_DELAY_MS 100

#define CSV_FILE_NAME "imu_data.csv"
#define CSV_HEADER "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z"

static int spi_handle;
static FILE *csv_file;

static void cleanup(void)
{
    if (spi_handle >= 0)
    {
        spiClose(spi_handle);
    }

    if (csv_file != NULL)
    {
        fclose(csv_file);
    }

    gpioTerminate();
}

static int read_register(uint8_t reg)
{
    uint16_t request = (1 << 15) | (reg << 8);
    uint16_t response;

    if (spiXfer(spi_handle, &request, &response, 2) < 0)
    {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }

    return response & 0x7FFF;
}

static void sample_data(void)
{
    struct timespec timestamp;
    int gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    clock_gettime(CLOCK_REALTIME, &timestamp);

    gyro_x = read_register(GYRO_X_REG);
    gyro_y = read_register(GYRO_Y_REG);
    gyro_z = read_register(GYRO_Z_REG);
    accel_x = read_register(ACCEL_X_REG);
    accel_y = read_register(ACCEL_Y_REG);
    accel_z = read_register(ACCEL_Z_REG);

    fprintf(csv_file, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
            timestamp.tv_sec, timestamp.tv_nsec,
            gyro_x, gyro_y, gyro_z,
            accel_x, accel_y, accel_z);
}

int main(void)
{
    int running = 1;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);

    if (spi_handle < 0)
    {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE_NAME, "w");

    if (csv_file == NULL)
    {
        fprintf(stderr, "Failed to open CSV file %s\n", CSV_FILE_NAME);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "%s\n", CSV_HEADER);

    while (running)
    {
        sample_data();
        usleep(SPI_DUMMY_READ_DELAY);
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}

