#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_GPIO 8
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS 8
#define SPI_DELAY 0

#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

#define GYRO_SCALE 0.02
#define ACCL_SCALE 0.00025

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

static volatile int keep_running = 1;

static void int_handler(int dummy) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    int fd;
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct spi_ioc_transfer tr;
    uint8_t tx[2];
    uint8_t rx[2];
    uint16_t data;
    float gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;
    struct timespec ts;

    // Open SPI device
    fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and bits per word
    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return 1;
    }
    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return 1;
    }

    // Set SPI max speed
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        close(fd);
        return 1;
    }

    // Open libgpiod chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open libgpiod chip");
        close(fd);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    // Set line as output
    ret = gpiod_line_request_output(line, "cs", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    // Set signal handler for SIGINT and SIGTERM
    signal(SIGINT, int_handler);
    signal(SIGTERM, int_handler);

    // Main loop
    while (keep_running) {
        // Set CS low
        gpiod_line_set_value(line, 0);

        // Read gyroscope X
        tx[0] = XGYRO_OUT | 0x80;
        tx[1] = 0x00;
        tr.tx_buf = (unsigned long)tx;
        tr.rx_buf = (unsigned long)rx;
        tr.len = ARRAY_SIZE(tx);
        tr.delay_usecs = SPI_DELAY;
        tr.speed_hz = SPI_SPEED;
        tr.bits_per_word = SPI_BITS;
        ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 1) {
            perror("Failed to read SPI message");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(fd);
            return 1;
        }
        data = (rx[0] << 8) | rx[1];
        gyro_x = data * GYRO_SCALE;

        // Read gyroscope Y
        tx[0] = YGYRO_OUT | 0x80;
