#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define I2C_FILE "/dev/i2c-1"

#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B

#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

#define RETRY_COUNT 3

int main(int argc, char *argv[])
{
    int fd;
    int ret;
    int i;
    char buf[16];

    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        exit(1);
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to select I2C device %02x: %s\n", I2C_ADDR, strerror(errno));
        close(fd);
        exit(1);
    }

    ret = i2c_smbus_read_byte_data(fd, WHO_AM_I);
    if (ret < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", strerror(errno));
        close(fd);
        exit(1);
    }
    if (ret != 0x86) {
        fprintf(stderr, "Invalid WHO_AM_I value: %02x\n", ret);
        close(fd);
        exit(1);
    }

    ret = i2c_smbus_write_byte_data(fd, PWR_MGMT_1, 0x00);
    if (ret < 0) {
        fprintf(stderr, "Failed to write PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        exit(1);
    }

    ret = i2c_smbus_write_byte_data(fd, ACCEL_CONFIG, 0x00);
    if (ret < 0) {
        fprintf(stderr, "Failed to write ACCEL_CONFIG: %s\n", strerror(errno));
        close(fd);
        exit(1);
    }

    ret = i2c_smbus_write_byte_data(fd, GYRO_CONFIG, 0x00);
    if (ret < 0) {
        fprintf(stderr, "Failed to write GYRO_CONFIG: %s\n", strerror(errno));
        close(fd);
        exit(1);
    }

    while (1) {
        for (i = 0; i < RETRY_COUNT; i++) {
            ret = i2c_smbus_read_i2c_block_data(fd, ACCEL_XOUT_H, 14, buf);
            if (ret == 14) {
                break;
            }
        }
        if (i == RETRY_COUNT) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
            close(fd);
            exit(1);
        }

        printf("Accelerometer: %d %d %d\n",
                (buf[0] << 8) | buf[1],
                (buf[2] << 8) | buf[3],
                (buf[4] << 8) | buf[5]);

        for (i = 0; i < RETRY_COUNT; i++) {
            ret = i2c_smbus_read_i2c_block_data(fd, GYRO_XOUT_H, 14, buf);
            if (ret == 14) {
                break;
            }
        }
        if (i == RETRY_COUNT) {
            fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
            close(fd);
            exit(1);
        }

        printf("Gyroscope: %d %d %d\n",
                (buf[8] << 8) | buf[9],
                (buf[10] << 8) | buf[11],
                (buf[12] << 8) | buf[13]);

        usleep(50000);
    }

    close(fd);
    return 0;
}

