#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x35
#define I2C_REG_X 0x10
#define I2C_REG_Y 0x11
#define I2C_REG_Z 0x12
#define I2C_READ_LEN 2
#define CSV_FILE "magnetic_field_log.csv"
#define CSV_HEADER "timestamp,x,y,z\n"

static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void cleanup(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_fp) {
        fclose(csv_fp);
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static void log_csv(int x, int y, int z)
{
    struct timespec ts;
    char buf[100];

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        return;
    }

    snprintf(buf, sizeof(buf), "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
    if (fputs(buf, csv_fp) < 0) {
        fprintf(stderr, "fputs: %s\n", strerror(errno));
        return;
    }
}

int main(void)
{
    int x, y, z;
    uint8_t buf[I2C_READ_LEN];

    if (atexit(cleanup) < 0) {
        fprintf(stderr, "atexit: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR || signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "signal: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((csv_fp = fopen(CSV_FILE, "a")) == NULL) {
        fprintf(stderr, "fopen: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (fputs(CSV_HEADER, csv_fp) < 0) {
        fprintf(stderr, "fputs: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (true) {
        if (read(i2c_fd, buf, I2C_READ_LEN) != I2C_READ_LEN) {
            fprintf(stderr, "read: %s\n", strerror(errno));
            continue;
        }

        x = (buf[0] << 8) | buf[1];
        if (read(i2c_fd, buf, I2C_READ_LEN) != I2C_READ_LEN) {
            fprintf(stderr, "read: %s\n", strerror(errno));
            continue;
        }

        y = (buf[0] << 8) | buf[1];
        if (read(i2c_fd, buf, I2C_READ_LEN) != I2C_READ_LEN) {
            fprintf(stderr, "read: %s\n", strerror(errno));
            continue;
        }

        z = (buf[0] << 8) | buf[1];
        log_csv(x, y, z);
        sleep(1);
    }

    return EXIT_SUCCESS;
}

