    int i2c_out_y = 0;
    int i2c_out_z = 0;
    int i2c_out_x_dps = 0;
    int i2c_out_y_dps = 0;
    int i2c_out_z_dps = 0;
    struct timespec i2c_time;
    struct timespec i2c_time_start;
    struct timespec i2c_time_end;
    struct timespec i2c_time_diff;
    struct timespec i2c_time_delay;
    struct timespec i2c_time_delay_rem;

