        fprintf(stderr, "failed to open i2c bus %d\n", I2C_BUS);
        return 1;
    }

    gpioI2CWriteByte(i2c_handle, I2C_CTRL_REG1, I2C_CTRL_REG1_VAL);
    gpioI2CWriteByte(i2c_handle, I2C_CTRL_REG4, I2C_CTRL_REG4_VAL);

    i2c_log = fopen(I2C_LOG_FILE, "w");
    if (i2c_log == NULL) {
        fprintf(stderr, "failed to open log file %s\n", I2C_LOG_FILE);
        return 1;
    }

    fprintf(i2c_log, "Timestamp,X,Y,Z\n");

    clock_gettime(CLOCK_MONOTONIC, &i2c_time_start);

