        i2c_who_am_i = gpioI2CReadByte(i2c_handle, I2C_WHO_AM_I);
        if (i2c_who_am_i < 0) {
            fprintf(stderr, "failed to read WHO_AM_I register\n");
            return 1;
        }
        if (i2c_who_am_i != I2C_WHO_AM_I_VAL) {
            fprintf(stderr, "WHO_AM_I register read 0x%02X, expected 0x%02X\n", i2c_who_am_i, I2C_WHO_AM_I_VAL);
            return 1;
        }

        i2c_ctrl_reg1 = gpioI2CReadByte(i2c_handle, I2C_CTRL_REG1);
        if (i2c_ctrl_reg1 < 0) {
            fprintf(stderr, "failed to read CTRL_REG1 register\n");
            return 1;
        }
        if (i2c_ctrl_reg1 != I2C_CTRL_REG1_VAL) {
            fprintf(stderr, "CTRL_REG1 register read 0x%02X, expected 0x%02X\n", i2c_ctrl_reg1, I2C_CTRL_REG1_VAL);
            return 1;
        }

        i2c_ctrl_reg4 = gpioI2CReadByte(i2c_handle, I2C_CTRL_REG4);
        if (i2c_ctrl_reg4 < 0) {
            fprintf(stderr, "failed to read CTRL_REG4 register\n");
            return 1;
        }
        if (i2c_ctrl_reg4 != I2C_CTRL_REG4_VAL) {
            fprintf(stderr, "CTRL_REG4 register read 0x%02X, expected 0x%02X\n", i2c_ctrl_reg4, I2C_CTRL_REG4_VAL);
            return 1;
        }

        i2c_out_x_l = i2c_read_buf[0];
        i2c_out_x_h = i2c_read_buf[1];
        i2c_out_y_l = i2c_read_buf[2];
        i2c_out_y_h = i2c_read_buf[3];
        i2c_out_z_l = i2c_read_buf[4];
        i2c_out_z_h = i2c_read_buf[5];

        i2c_out_x = (i2c_out_x_h << 8) | i2c_out_x_l;
        i2c_out_y = (i2c_out_y_h << 8) | i2c_out_y_l;
        i2c_out_z = (i2c_out_z_h << 8) | i2c_out_z_l;

        i2c_out_x_dps = i2c_out_x / I2C_SENSITIVITY;
        i2c_out_y_dps = i2c_out_y / I2C_SENSITIVITY;
        i2c_out_z_dps = i2c_out_z / I2C_SENSITIVITY;

        clock_gettime(CLOCK_MONOTONIC, &i2c_time);
        i2c_time_diff.tv_sec = i2c_time.tv_sec - i2c_time_start.tv_sec;
        i2c_time_diff.tv_nsec = i2c_time.tv_nsec - i2c_time_start.tv_nsec;
        fprintf(i2c_log, "%ld.%09ld,%d,%d,%d\n", i2c_time_diff.tv_sec, i2c_time_diff.tv_nsec, i2c_out_x_dps, i2c_out_y_dps, i2c_out_z_dps);

        i2c_time_delay.tv_sec = 0;
        i2c_time_delay.tv_nsec = I2C_READ_DELAY;
        nanosleep(&i2c_time_delay, &i2c_time_delay_rem);
    }

    return 0;
}
