#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define FLAME_SENSOR_PULL_UP_ENABLED 1
#define FLAME_SENSOR_POLL_INTERVAL_MS 500
#define FLAME_SENSOR_LOG_FILE "flame_events.log"

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum)
{
    stop = 1;
}

int main(void)
{
    FILE *log_file = NULL;
    int sensor_value = 0;
    int sensor_read_result = 0;
    time_t current_time;
    struct tm *local_time;
    char time_string[32];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(FLAME_SENSOR_GPIO, FLAME_SENSOR_PULL_UP_ENABLED);

    log_file = fopen(FLAME_SENSOR_LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file '%s'\n", FLAME_SENSOR_LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop)
    {
        sensor_read_result = gpioRead(FLAME_SENSOR_GPIO);
        if (sensor_read_result < 0)
        {
            fprintf(stderr, "Failed to read sensor value\n");
            continue;
        }

        sensor_value = sensor_read_result;

        current_time = time(NULL);
        local_time = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%F %T", local_time);

        fprintf(log_file, "%s - Flame detected: %s\n", time_string, sensor_value ? "NO" : "YES");
        fflush(log_file);

        if (sensor_value == 0)
        {
            printf("FLAME DETECTED!\n");
        }

        gpioDelay(FLAME_SENSOR_POLL_INTERVAL_MS * 1000);
    }

    if (log_file != NULL)
    {
        fclose(log_file);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

