#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x53
#define I2C_REG_X_LSB 0x28
#define I2C_REG_X_MSB 0x29
#define I2C_REG_Y_LSB 0x2A
#define I2C_REG_Y_MSB 0x2B
#define I2C_REG_Z_LSB 0x2C
#define I2C_REG_Z_MSB 0x2D
#define I2C_READ_LEN 6
#define CSV_FILE "vibration_log.csv"
