{
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_fp) {
        fclose(csv_fp);
    }
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static bool init_i2c(void)
{
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return false;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return false;
    }
    return true;
}

static bool init_csv(void)
{
    csv_fp = fopen(CSV_FILE, "w");
    if (!csv_fp) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return false;
    }
    fprintf(csv_fp, "%s\n", CSV_HEADER);
    return true;
}

static bool read_i2c(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[I2C_READ_LEN];
    if (read(i2c_fd, buf, I2C_READ_LEN) != I2C_READ_LEN) {
        fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
        return false;
    }
    *x = (int16_t)(buf[I2C_REG_X_MSB] << 8 | buf[I2C_REG_X_LSB]);
    *y = (int16_t)(buf[I2C_REG_Y_MSB] << 8 | buf[I2C_REG_Y_LSB]);
    *z = (int16_t)(buf[I2C_REG_Z_MSB] << 8 | buf[I2C_REG_Z_LSB]);
    return true;
}

static bool write_csv(int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Failed to get time: %s\n", strerror(errno));
        return false;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&ts.tv_sec)) == 0) {
        fprintf(stderr, "Failed to format time\n");
        return false;
    }
    fprintf(csv_fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    return true;
}

int main(void)
{
    if (!init_i2c()) {
        return EXIT_FAILURE;
    }
    if (!init_csv()) {
        return EXIT_FAILURE;
    }
    signal(SIGINT, sigint_handler);
    while (true) {
        int16_t x, y, z;
        if (!read_i2c(&x, &y, &z)) {
            continue;
        }
        if (!write_csv(x, y, z)) {
            return EXIT_FAILURE;
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }
    return EXIT_SUCCESS;
}

