{
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_1, strerror(errno));
        return -1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_2, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request_input_flags(line1, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE_1, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request_input_flags(line2, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE_2, strerror(errno));
        return -1;
    }

    return 0;
}

static void deinit_gpio(void)
{
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
}

