#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD_RATE 1000000
#define SPI_MODE 3
#define SPI_DELAY 10000

#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.0025

#define LOG_FILE "imu_log.csv"

int spi_handle;
FILE *log_file;

void sigint_handler(int sig)
{
    if (spi_handle >= 0)
    {
        spiClose(spi_handle);
    }

    if (log_file != NULL)
    {
        fflush(log_file);
        fclose(log_file);
    }

    gpioTerminate();

    exit(0);
}

int read_register(uint8_t address, uint16_t *data)
{
    uint8_t tx_buf[2] = {address | 0x80, 0x00};
    uint8_t rx_buf[2];
    int ret;

    ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret < 0)
    {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", address, spiError(ret));
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

int main(void)
{
    uint16_t x_gyro, y_gyro, z_gyro, x_accl, y_accl, z_accl;
    struct timespec timestamp;
    char timestamp_str[32];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD_RATE, SPI_MODE);
    if (spi_handle < 0)
    {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n", SPI_CHANNEL, spiError(spi_handle));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    signal(SIGINT, sigint_handler);

    while (1)
    {
        if (read_register(X_GYRO, &x_gyro) < 0)
        {
            continue;
        }

        if (read_register(Y_GYRO, &y_gyro) < 0)
        {
            continue;
        }

        if (read_register(Z_GYRO, &z_gyro) < 0)
        {
            continue;
        }

        if (read_register(X_ACCL, &x_accl) < 0)
        {
            continue;
        }

        if (read_register(Y_ACCL, &y_accl) < 0)
        {
            continue;
        }

        if (read_register(Z_ACCL, &z_accl) < 0)
        {
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp.tv_sec));
        fprintf(log_file, "%s.%09ld,%.2f,%.2f,%.2f,%.4f,%.4f,%.4f\n", timestamp_str, timestamp.tv_nsec,
                x_gyro * GYRO_SCALE, y_gyro * GYRO_SCALE, z_gyro * GYRO_SCALE,
                x_accl * ACCL_SCALE, y_accl * ACCL_SCALE, z_accl * ACCL_SCALE);

        gpioDelay(SPI_DELAY);
    }

    return 0;
}

