#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_NUM 17
#define GPIO_LINE_NAME "gpio17"
#define GPIO_LINE_DIRECTION GPIOD_LINE_DIRECTION_INPUT
#define GPIO_LINE_REQUEST_TYPE GPIOD_LINE_REQUEST_DIRECTION_AS_IS
#define GPIO_LINE_REQUEST_CONSUMER "self-parking"
#define GPIO_LINE_REQUEST_EVENT_TYPE GPIOD_LINE_REQUEST_EVENT_BOTH_EDGES
#define GPIO_LINE_REQUEST_FLAG GPIOD_LINE_REQUEST_FLAG_DEFAULT
#define POLL_INTERVAL_MS 1000

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int running = 1;

static void sigint_handler(int signum)
{
    running = 0;
}

int main(void)
{
    int ret;
    struct timespec ts;

    // Open the gpiochip device
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip device %s\n", GPIO_CHIP_NAME);
        return EXIT_FAILURE;
    }

    // Request the line for input direction
    line = gpiod_chip_get_line(chip, GPIO_LINE_NUM);
    if (!line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE_NUM);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, GPIO_LINE_REQUEST_CONSUMER);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d for input direction\n", GPIO_LINE_NUM);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, sigint_handler);

    // Poll the sensor every 1 second
    while (running) {
        // Read the line value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read line %d\n", GPIO_LINE_NUM);
            break;
        }

        // Check if an obstacle is detected (line reads LOW)
        if (value == 0) {
            // Trigger a simulated "self-parking" sequence
            printf("Self-parking sequence started\n");
            sleep(5);
            printf("Self-parking sequence completed\n");
        }

        // Wait 1 second
        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&ts, NULL);
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIOCHIP_NAME "gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 27
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *line1;
static struct gpiod_line *line2;
static struct gpiod_line_bulk *bulk;
static struct gpiod_line_request *req;
static int running = 1;

static void sigint_handler(int signum)
{
    running = 0;
}

int main(void)
{
    int ret;
    struct timespec ts;
    struct gpiod_line_values values;

    /* Set up signal handler */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* Open gpiochip */
    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines */
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_1, strerror(errno));
        goto err_close_chip;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_2, strerror(errno));
        goto err_close_line1;
    }

    /* Request lines */
    req = gpiod_line_request_new(line1, "input", 0);
    if (!req) {
        fprintf(stderr, "Failed to create line request: %s\n", strerror(errno));
        goto err_close_line2;
    }
    ret = gpiod_line_request_add_line(req, line2);
    if (ret < 0) {
        fprintf(stderr, "Failed to add line to request: %s\n", strerror(errno));
        goto err_free_req;
    }
    ret = gpiod_line_request_commit(req);
    if (ret < 0) {
        fprintf(stderr, "Failed to commit line request: %s\n", strerror(errno));
        goto err_free_req;
    }

    /* Create bulk */
    bulk = gpiod_line_bulk_new(chip);
    if (!bulk) {
        fprintf(stderr, "Failed to create bulk: %s\n", strerror(errno));
        goto err_free_req;
    }
    ret = gpiod_line_bulk_add_line(bulk, line1);
    if (ret < 0) {
        fprintf(stderr, "Failed to add line to bulk: %s\n", strerror(errno));
        goto err_free_bulk;
    }
    ret = gpiod_line_bulk_add_line(bulk, line2);
    if (ret < 0) {
        fprintf(stderr, "Failed to add line to bulk: %s\n", strerror(errno));
        goto err_free_bulk;
    }

    /* Main loop */
    while (running) {
        /* Get values */
        ret = gpiod_line_bulk_read(bulk, &values);
        if (ret < 0) {
            fprintf(stderr, "Failed to read bulk: %s\n", strerror(errno));
            goto err_free_bulk;
        }

        /* Print values */
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: %d %d\n", ts.tv_sec, ts.tv_nsec, values.values[0], values.values[1]);

        /* Sleep */
        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean up */
    gpiod_line_bulk_free(bulk);
err_free_bulk:
    gpiod_line_request_free(req);
err_free_req:
    gpiod_line_put(line2);
err_close_line2:
    gpiod_line_put(line1);
err_close_line1:
    gpiod_chip_close(chip);
err_close_chip:
    return EXIT_SUCCESS;
}

