#define I2C_REG_X 0x32
#define I2C_REG_Y 0x34
#define I2C_REG_Z 0x36
#define I2C_REG_POWER_CTL 0x2D
#define I2C_REG_POWER_CTL_MEASURE 0x08
#define I2C_REG_DATA_FORMAT 0x31
#define I2C_REG_DATA_FORMAT_FULL_RES 0x08
#define I2C_REG_DATA_FORMAT_RANGE_2G 0x00
#define I2C_REG_DATA_FORMAT_RANGE_4G 0x01
#define I2C_REG_DATA_FORMAT_RANGE_8G 0x02
#define I2C_REG_DATA_FORMAT_RANGE_16G 0x03
#define I2C_REG_BW_RATE 0x2C
#define I2C_REG_BW_RATE_RATE_100HZ 0x0A

#define TILT_THRESHOLD 30.0
#define TILT_LOG_FILE "/var/log/tilt_events.log"

static int i2c_fd = -1;

static void i2c_init(void)
{
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    uint8_t buf[2];

    buf[0] = I2C_REG_POWER_CTL;
    buf[1] = I2C_REG_POWER_CTL_MEASURE;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    buf[0] = I2C_REG_DATA_FORMAT;
    buf[1] = I2C_REG_DATA_FORMAT_FULL_RES | I2C_REG_DATA_FORMAT_RANGE_2G;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    buf[0] = I2C_REG_BW_RATE;
    buf[1] = I2C_REG_BW_RATE_RATE_100HZ;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("write");
        exit(EXIT_FAILURE);
    }
}

static void i2c_deinit(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void i2c_read(uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, buf, len) != len) {
        perror("read");
        exit(EXIT_FAILURE);
    }
}

static void tilt_log(double tilt)
{
    FILE *fp = fopen(TILT_LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char time_str[64];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %.1f\n", time_str, tilt);
    fclose(fp);
}

static void sig_handler(int sig)
{
    i2c_deinit();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    i2c_init();

    signal(SIGINT, sig_handler);

    uint8_t buf[6];
    while (1) {
        i2c_read(I2C_REG_X, buf, 6);

        int16_t x = (buf[1] << 8) | buf[0];
        int16_t y = (buf[3] << 8) | buf[2];
        int16_t z = (buf[5] << 8) | buf[4];

        double tilt = atan2(z, sqrt(x * x + y * y)) * 180.0 / M_PI;
        if (tilt > TILT_THRESHOLD) {
            tilt_log(tilt);
        }

        usleep(100000);
    }

    return 0;
}
