#include <sys/socket.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

#define PORT 12345
#define SECRET "MySecretKey"
#define MAX_FREQ 880
#define MIN_FREQ 220
#define MAX_TOUCH 4095
#define MIN_TOUCH 0
#define LOG_FILE "frequency_log.txt"
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define SAMPLING_PERIOD 20
#define PLAYBACK_WINDOW 5

int main(void)
{
    int sock, client_sock, addrlen, i2c_handle, pwm_handle, freq, touch;
    char buffer[1024];
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, 0x5A, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x01) < 0)
    {
        fprintf(stderr, "Failed to initialize MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure MPR121
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0)
    {
        fprintf(stderr, "Failed to configure MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == 0)
    {
        fprintf(stderr, "Failed to create socket\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to port
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0)
    {
        fprintf(stderr, "Failed to bind socket to port\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0)
    {
        fprintf(stderr, "Failed to listen for incoming connections\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Accept incoming connection
    addrlen = sizeof(server_addr);
    client_sock = accept(sock, (struct sockaddr *)&server_addr, (socklen_t *)&addrlen);
    if (client_sock < 0)
    {
        fprintf(stderr, "Failed to accept incoming connection\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Receive message from client
