#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define I2C_REG_CTRL_REG1_M 0x20
#define I2C_REG_OUT_X_L_M 0x08
#define I2C_REG_OUT_X_H_M 0x09
#define I2C_REG_OUT_Y_L_M 0x0A
#define I2C_REG_OUT_Y_H_M 0x0B
#define I2C_REG_OUT_Z_L_M 0x0C
#define I2C_REG_OUT_Z_H_M 0x0D
#define I2C_REG_CTRL_REG1_M_VAL 0x18
#define I2C_READ_LEN 6
#define GPIO_LED 17
#define PWM_PERIOD 1000000
#define PWM_DUTY_MAX 1000000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_STEP 10000
#define SAMPLING_INTERVAL 100000
#define LOG_FILE "magnetometer.log"

int main(void)
{
    int i2c_fd, pwm_fd, log_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request req;
    uint8_t i2c_buf[I2C_READ_LEN];
    int16_t x, y, z;
    int32_t mag;
    int32_t pwm_duty;
    int ret;

    /* Open I2C bus */
    i2c_fd = open(I2C_DEV_NAME, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    /* Set I2C slave address */
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    /* Initialize magnetometer */
    ret = i2c_smbus_write_byte_data(i2c_fd, I2C_REG_CTRL_REG1_M, I2C_REG_CTRL_REG1_M_VAL);
    if (ret < 0) {
        perror("Failed to initialize magnetometer");
        exit(EXIT_FAILURE);
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_number(GPIO_CHIP_NUMBER);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    /* Request GPIO line */
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE;
    req.default_values[0] = 0;
    req.consumer = "magnetometer";
    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request(line, &req, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    /* Open PWM */
    pwm_fd = gpiod_line_get_fd(line);
    if (pwm_fd < 0) {
        perror("Failed to open PWM");
        exit(EXIT_FAILURE);
    }

    /* Open log file */
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    /* Main loop */
    while (1) {
        /* Read magnetometer data */
        ret = i2c_smbus_read_i2c_block_data(i2c_fd, I2C_REG_OUT_X_L_M, I2C_READ_LEN, i2c_buf);
        if (ret < 0) {
            perror("Failed to read magnetometer data");
            continue;
        }

        /* Parse magnetometer data */
        x = (int16_t)((i2c_buf[1] << 8) | i2c_buf[0]);
        y = (int16_t)((i2c_buf[3] << 8) | i2c_buf[2]);
        z = (int16_t)((i2c_buf[5] << 8) | i2c_buf[4]);

        /* Compute magnitude of Z-axis field */
        mag = (int32_t)sqrt(x * x + y * y + z * z);

        /* Adjust LED brightness proportionally */
        pwm_duty = PWM_DUTY_MIN + (PWM_DUTY_MAX - PWM_DUTY_MIN) * mag / 65536;
        pwm_duty = pwm_duty < PWM_DUTY_MIN ? PWM_DUTY_MIN : pwm_duty;
        pwm_duty = pwm_duty > PWM_DUTY_MAX ? PWM_DUTY_MAX : pwm_duty;
        ret = write(pwm_fd, &pwm_duty, sizeof(pwm_duty));
        if (ret < 0) {
            perror("Failed to adjust LED brightness");
            continue;
        }

        /* Log magnetometer data */
        ret = dprintf(log_fd, "X: %d, Y: %d, Z: %d, Magnitude: %d\n", x, y, z, mag);
        if (ret < 0) {
            perror("Failed to log magnetometer data");
            continue;
        }

        /* Sleep for sampling interval */
        usleep(SAMPLING_INTERVAL);
    }

    /* Clean up */
    close(log_fd);
    close(pwm_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

