#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define I2C_WHO_AM_I 0x0F
#define I2C_WHO_AM_I_VAL 0x49
#define I2C_CTRL_REG1 0x20
#define I2C_CTRL_REG1_VAL 0x57
#define I2C_CTRL_REG4 0x23
#define I2C_CTRL_REG4_VAL 0x00
#define I2C_INT1_CFG 0x30
#define I2C_INT1_CFG_VAL 0x2A
#define I2C_INT1_THS 0x32
#define I2C_INT1_THS_VAL 0x7D
#define I2C_INT1_DURATION 0x33
#define I2C_INT1_DURATION_VAL 0x00
#define I2C_OUT_X_L_A 0x28
#define I2C_OUT_X_L_A_VAL 0x80
#define I2C_OUT_X_L_A_LEN 6
#define GPIO_INT1 23
#define GPIO_INT1_NAME "gpio23"
#define BUF_LEN 64

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_line_request_config gpio_line_config;
static struct timespec ts_start;
static int16_t buf[BUF_LEN][3];
static int buf_idx = 0;

static void cleanup(void)
{
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void sigint_handler(int signum)
{
    (void)signum;
    cleanup();
    exit(0);
}

static int i2c_read(uint8_t reg, uint8_t *val)
{
    int ret;

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE) failed: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (ret < 0) {
        fprintf(stderr, "i2c_smbus_read_byte_data() failed: %s\n", strerror(errno));
        return -1;
    }

    *val = ret;
    return 0;
}

static int i2c_write(uint8_t reg, uint8_t val)
{
    int ret;

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE) failed: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_smbus_write_byte_data(i2c_fd, reg, val);
    if (ret < 0) {
        fprintf(stderr, "i2c_smbus_write_byte_data() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, size_t len)
{
    int ret;

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE) failed: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, reg, len, buf);
    if (ret < 0) {
        fprintf(stderr, "i2c_smbus_read_i2c_block_data() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int init_i2c(void)
{
    uint8_t val;
    int ret;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open() failed: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_read(I2C_WHO_AM_I, &val);
    if (ret < 0) {
        fprintf(stderr, "i2c_read(WHO_AM_I) failed\n");
        return -1;
    }
    if (val != I2C_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I read 0x%02X, expected 0x%02X\n", val, I2C_WHO_AM_I_VAL);
        return -1;
    }

    ret = i2c_write(I2C_CTRL_REG1, I2C_CTRL_REG1_VAL);
    if (ret < 0) {
        fprintf(stderr, "i2c_write(CTRL_REG1) failed\n");
        return -1;
    }

    ret = i2c_write(I2C_CTRL_REG4, I2C_CTRL_REG4_VAL);
    if (ret < 0) {
        fprintf(stderr, "i2c_write(CTRL_REG4) failed\n");
        return -1;
    }

    ret = i2c_write(I2C_INT1_CFG, I2C_INT1_CFG_VAL);
    if (ret < 0) {
        fprintf(stderr, "i2c_write(INT1_CFG) failed\n");
        return -1;
    }

    ret = i2c_write(I2C_INT1_THS, I2C_INT1_THS_VAL);
    if (ret < 0) {
        fprintf(stderr, "i2c_write(INT1_THS) failed\n");
        return -1;
    }

    ret = i2c_write(I2C_INT1_DURATION, I2C_INT1_DURATION_VAL);
    if (ret < 0) {
        fprintf(stderr, "i2c_write(INT1_DURATION) failed\n");
        return -1;
    }

    return 0;
}

static int init_gpio(void)
{
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_INT1_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name() failed: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_INT1);
    if (!gpio_line) {
        fprintf(stderr, "gpiod_chip_get_line() failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&gpio_line_config, 0, sizeof(gpio_line_config));
    gpio_line_config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    gpio_line_config.consumer = "lsm303d_mon";
    ret = gpiod_line_request_config(gpio_line, &gpio_line_config, NULL);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_config() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void print_buf(void)
{
    int i;

    for (i = 0; i < 10; i++) {
        printf("%d %d %d\n", buf[(buf_idx + BUF_LEN - 10 + i) % BUF_LEN][0], buf[(buf_idx + BUF_LEN - 10 + i) % BUF_LEN][1], buf[(buf_idx + BUF_LEN - 10 + i) % BUF_LEN][2]);
    }
}

static void print_ts(void)
{
    struct timespec ts_now;
    int ret;

    ret = clock_gettime(CLOCK_MONOTONIC, &ts_now);
    if (ret < 0) {
        fprintf(stderr, "clock_gettime() failed: %s\n", strerror(errno));
        return;
    }

    printf("%ld.%09ld\n", ts_now.tv_sec - ts_start.tv_sec, ts_now.tv_nsec - ts_start.tv_nsec);
}

static void int1_handler(struct gpiod_line *line, void *data)
{
    (void)line;
    (void)data;

    print_ts();
    print_buf();
}

int main(void)
{
    uint8_t buf_i2c[I2C_OUT_X_L_A_LEN];
    int ret;

    ret = init_i2c();
    if (ret < 0) {
        fprintf(stderr, "init_i2c() failed\n");
        return -1;
    }

    ret = init_gpio();
    if (ret < 0) {
        fprintf(stderr, "init_gpio() failed\n");
        return -1;
    }

    ret = clock_gettime(CLOCK_MONOTONIC, &ts_start);
    if (ret < 0) {
        fprintf(stderr, "clock_gettime() failed: %s\n", strerror(errno));
        return -1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        ret = i2c_read_block(I2C_OUT_X_L_A, buf_i2c, I2C_OUT_X_L_A_LEN);
        if (ret < 0) {
            fprintf(stderr, "i2c_read_block() failed\n");
            continue;
        }

        buf[buf_idx][0] = (int16_t)((buf_i2c[1] << 8) | buf_i2c[0]);
        buf[buf_idx][1] = (int16_t)((buf_i2c[3] << 8) | buf_i2c[2]);
        buf[buf_idx][2] = (int16_t)((buf_i2c[5] << 8) | buf_i2c[4]);

        buf_idx = (buf_idx + 1) % BUF_LEN;

        gpiod_line_event_wait(gpio_line, -1);
        gpiod_line_event_read(gpio_line, &int1_handler, NULL);
    }

    return 0;
}

