        fprintf(stderr, "i2c_write(INT1_THS) failed\n");
        return -1;
    }

    ret = i2c_write(I2C_INT1_DURATION, I2C_INT1_DURATION_VAL);
    if (ret < 0) {
        fprintf(stderr, "i2c_write(INT1_DURATION) failed\n");
        return -1;
    }

    return 0;
}

static int init_gpio(void)
{
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_INT1_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name() failed: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_INT1);
    if (!gpio_line) {
        fprintf(stderr, "gpiod_chip_get_line() failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&gpio_line_config, 0, sizeof(gpio_line_config));
    gpio_line_config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    gpio_line_config.consumer = "lsm303d_mon";
    ret = gpiod_line_request_config(gpio_line, &gpio_line_config, NULL);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_config() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void print_buf(void)
{
    int i;

    for (i = 0; i < 10; i++) {
        printf("%d %d %d\n", buf[(buf_idx + BUF_LEN - 10 + i) % BUF_LEN][0], buf[(buf_idx + BUF_LEN - 10 + i) % BUF_LEN][1], buf[(buf_idx + BUF_LEN - 10 + i) % BUF_LEN][2]);
    }
}

static void print_ts(void)
{
    struct timespec ts_now;
    int ret;

    ret = clock_gettime(CLOCK_MONOTONIC, &ts_now);
    if (ret < 0) {
        fprintf(stderr, "clock_gettime() failed: %s\n", strerror(errno));
        return;
    }

    printf("%ld.%09ld\n", ts_now.tv_sec - ts_start.tv_sec, ts_now.tv_nsec - ts_start.tv_nsec);
}

static void int1_handler(struct gpiod_line *line, void *data)
{
    (void)line;
    (void)data;

    print_ts();
    print_buf();
}

int main(void)
{
    uint8_t buf_i2c[I2C_OUT_X_L_A_LEN];
    int ret;

    ret = init_i2c();
    if (ret < 0) {
        fprintf(stderr, "init_i2c() failed\n");
        return -1;
    }

    ret = init_gpio();
    if (ret < 0) {
        fprintf(stderr, "init_gpio() failed\n");
        return -1;
    }

    ret = clock_gettime(CLOCK_MONOTONIC, &ts_start);
    if (ret < 0) {
        fprintf(stderr, "clock_gettime() failed: %s\n", strerror(errno));
        return -1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        ret = i2c_read_block(I2C_OUT_X_L_A, buf_i2c, I2C_OUT_X_L_A_LEN);
        if (ret < 0) {
            fprintf(stderr, "i2c_read_block() failed\n");
            continue;
        }

        buf[buf_idx][0] = (int16_t)((buf_i2c[1] << 8) | buf_i2c[0]);
        buf[buf_idx][1] = (int16_t)((buf_i2c[3] << 8) | buf_i2c[2]);
        buf[buf_idx][2] = (int16_t)((buf_i2c[5] << 8) | buf_i2c[4]);

        buf_idx = (buf_idx + 1) % BUF_LEN;

        gpiod_line_event_wait(gpio_line, -1);
        gpiod_line_event_read(gpio_line, &int1_handler, NULL);
    }

    return 0;
}
