#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DOOR_LOCK_PIN_1 17
#define DOOR_LOCK_PIN_2 27
#define DOOR_UNLOCK_TIME_MS 2000
#define CODE_LENGTH 6
#define CODE_TIMEOUT_MS 5000
#define CODE_EXPECTED "123456"

static char code_1[CODE_LENGTH + 1];
static char code_2[CODE_LENGTH + 1];
static int code_1_len = 0;
static int code_2_len = 0;

static void handle_signal(int signum)
{
    gpioWrite(DOOR_LOCK_PIN_1, 0);
    gpioWrite(DOOR_LOCK_PIN_2, 0);
    gpioTerminate();
    exit(0);
}

static void handle_error(const char *msg)
{
    fprintf(stderr, "%s\n", msg);
    handle_signal(0);
}

static void read_code(int fd, char *code, int *code_len)
{
    char c;
    while (read(fd, &c, 1) > 0) {
        if (c >= '0' && c <= '9') {
            code[*code_len] = c;
            (*code_len)++;
            if (*code_len == CODE_LENGTH) {
                code[*code_len] = '\0';
                return;
            }
        } else {
            *code_len = 0;
        }
    }
}

int main(void)
{
    int fd_1, fd_2;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    ret = gpioInitialise();
    if (ret < 0) {
        handle_error("Failed to initialize pigpio");
    }

    ret = gpioSetMode(DOOR_LOCK_PIN_1, PI_OUTPUT);
    if (ret != 0) {
        handle_error("Failed to set GPIO mode for door lock 1");
    }

    ret = gpioSetMode(DOOR_LOCK_PIN_2, PI_OUTPUT);
    if (ret != 0) {
        handle_error("Failed to set GPIO mode for door lock 2");
    }

    fd_1 = open("/dev/serial0", O_RDONLY | O_NONBLOCK);
    if (fd_1 < 0) {
        handle_error("Failed to open serial port 1");
    }

    fd_2 = open("/dev/serial1", O_RDONLY | O_NONBLOCK);
    if (fd_2 < 0) {
        handle_error("Failed to open serial port 2");
    }

    while (1) {
        read_code(fd_1, code_1, &code_1_len);
        read_code(fd_2, code_2, &code_2_len);

        if (code_1_len == CODE_LENGTH && code_2_len == CODE_LENGTH) {
            if (strcmp(code_1, code_2) == 0 && strcmp(code_1, CODE_EXPECTED) == 0) {
                ret = gpioWrite(DOOR_LOCK_PIN_1, 1);
                if (ret != 0) {
                    handle_error("Failed to write to GPIO for door lock 1");
                }

                ret = gpioWrite(DOOR_LOCK_PIN_2, 1);
                if (ret != 0) {
                    handle_error("Failed to write to GPIO for door lock 2");
                }

                usleep(DOOR_UNLOCK_TIME_MS * 1000);

                ret = gpioWrite(DOOR_LOCK_PIN_1, 0);
                if (ret != 0) {
                    handle_error("Failed to write to GPIO for door lock 1");
                }

                ret = gpioWrite(DOOR_LOCK_PIN_2, 0);
                if (ret != 0) {
                    handle_error("Failed to write to GPIO for door lock 2");
                }
            }

            code_1_len = 0;
            code_2_len = 0;
        }

        usleep(1000);
    }

    return 0;
}

