#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>

#define RELAY_1 4
#define RELAY_2 17
#define RELAY_3 27
#define RELAY_4 22

#define RELAY_ON 0
#define RELAY_OFF 1

#define RELAY_ACTIVATION_TIME 300
#define RELAY_PAUSE_TIME 60

#define RELAY_STATE_ACTIVATION 0
#define RELAY_STATE_PAUSE 1

#define RELAY_COUNT 4

static volatile sig_atomic_t keep_running = 1;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

static void relay_state_change(int relay, int state)
{
    if (gpioWrite(relay, state) != 0) {
        syslog(LOG_ERR, "Failed to set relay %d to %d", relay, state);
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }

    syslog(LOG_INFO, "Set relay %d to %d", relay, state);
}

static void relay_timer_callback(int timer_id, void *user_data)
{
    static int relay_state = RELAY_STATE_ACTIVATION;
    static int relay_index = 0;

    if (relay_state == RELAY_STATE_ACTIVATION) {
        relay_state_change(relay_index + 1, RELAY_ON);
        gpioSetTimerFuncEx(0, RELAY_PAUSE_TIME * 1000, 0, relay_timer_callback);
        relay_state = RELAY_STATE_PAUSE;
    } else {
        relay_state_change(relay_index + 1, RELAY_OFF);
        relay_index = (relay_index + 1) % RELAY_COUNT;
        gpioSetTimerFuncEx(0, RELAY_ACTIVATION_TIME * 1000, 0, relay_timer_callback);
        relay_state = RELAY_STATE_ACTIVATION;
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        closelog();
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RELAY_1, PI_OUTPUT);
    gpioSetMode(RELAY_2, PI_OUTPUT);
    gpioSetMode(RELAY_3, PI_OUTPUT);
    gpioSetMode(RELAY_4, PI_OUTPUT);

    openlog("irrigation_system", LOG_PID, LOG_USER);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetTimerFuncEx(0, RELAY_ACTIVATION_TIME * 1000, 0, relay_timer_callback);

    while (keep_running) {
        sleep(1);
    }

    relay_state_change(RELAY_1, RELAY_OFF);
    relay_state_change(RELAY_2, RELAY_OFF);
    relay_state_change(RELAY_3, RELAY_OFF);
    relay_state_change(RELAY_4, RELAY_OFF);

    gpioTerminate();
    closelog();

    return 0;
}

