#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/timerfd.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c/smbus.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define I2C_TIMEOUT 1000000

#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

#define ACCEL_RANGE_2G 0x00
#define ACCEL_RANGE_4G 0x08
#define ACCEL_RANGE_8G 0x10
#define ACCEL_RANGE_16G 0x18

#define ACCEL_SCALE_2G 16384.0
#define ACCEL_SCALE_4G 8192.0
#define ACCEL_SCALE_8G 4096.0
#define ACCEL_SCALE_16G 2048.0

#define BUF_SIZE 100

struct mpu6050_accel_data {
    double x;
    double y;
    double z;
};

struct mpu6050_accel_data buf[BUF_SIZE];
int buf_head = 0;
int buf_tail = 0;

int i2c_fd;
int timer_fd;

void sigint_handler(int sig) {
    close(i2c_fd);
    close(timer_fd);
    exit(EXIT_SUCCESS);
}

int mpu6050_init(int i2c_fd) {
    int ret;

    // Set power management register to 0x00 (wakes the MPU-6050 up)
    ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_PWR_MGMT_1, 0x00);
    if (ret < 0) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }

    // Set accelerometer range to +-2g
    ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_ACCEL_CONFIG, ACCEL_RANGE_2G);
    if (ret < 0) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }

    return 0;
}

int mpu6050_read_accel(int i2c_fd, struct mpu6050_accel_data *data) {
    int ret;
    uint8_t buf[6];

    // Read 6 bytes starting at ACCEL_XOUT_H
    ret = i2c_smbus_read_i2c_block_data(i2c_fd, MPU6050_ACCEL_XOUT_H, 6, buf);
    if (ret < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }

    // Convert raw values to g
    data->x = (int16_t)((buf[0] << 8) | buf[1]) / ACCEL_SCALE_2G;
    data->y = (int16_t)((buf[2] << 8) | buf[3]) / ACCEL_SCALE_2G;
    data->z = (int16_t)((buf[4] << 8) | buf[5]) / ACCEL_SCALE_2G;

    return 0;
}

void timer_handler(int sig, siginfo_t *si, void *uc) {
    struct mpu6050_accel_data data;
    int ret;

    // Read acceleration data
    ret = mpu6050_read_accel(i2c_fd, &data);
    if (ret < 0) {
        perror("mpu6050_read_accel");
        return;
    }

    // Store data in circular buffer
    buf[buf_head] = data;
    buf_head = (buf_head + 1) % BUF_SIZE;
    if (buf_head == buf_tail) {
        buf_tail = (buf_tail + 1) % BUF_SIZE;
    }
}

int main(int argc, char *argv[]) {
    int ret;
    struct itimerspec ts;
    struct sigaction sa;

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize MPU-6050
    ret = mpu6050_init(i2c_fd);
    if (ret < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Create timer
    timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timer_fd < 0) {
        perror("timerfd_create");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set timer interval to 10ms
    ts.it_interval.tv_sec = 0;
    ts.it_interval.tv_nsec = 10000000;
    ts.it_value.tv_sec = 0;
    ts.it_value.tv_nsec = 10000000;
    ret = timerfd_settime(timer_fd, 0, &ts, NULL);
    if (ret < 0) {
        perror("timerfd_settime");
        close(i2c_fd);
        close(timer_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = sigint_handler;
    sigemptyset(&sa.sa_mask);
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret < 0) {
        perror("sigaction");
        close(i2c_fd);
        close(timer_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler for timer
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    ret = sigaction(SIGALRM, &sa, NULL);
    if (ret < 0) {
        perror("sigaction");
        close(i2c_fd);
        close(timer_fd);
        return EXIT_FAILURE;
    }

    // Wait for timer signal
    while (1) {
        uint64_t exp;
        ret = read(timer_fd, &exp, sizeof(uint64_t));
        if (ret != sizeof(uint64_t)) {
            perror("read");
            close(i2c_fd);
            close(timer_fd);
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

