    sigemptyset(&sa.sa_mask);
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret < 0) {
        perror("sigaction");
        close(i2c_fd);
        close(timer_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler for timer
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    ret = sigaction(SIGALRM, &sa, NULL);
    if (ret < 0) {
        perror("sigaction");
        close(i2c_fd);
        close(timer_fd);
        return EXIT_FAILURE;
    }

    // Wait for timer signal
    while (1) {
        uint64_t exp;
        ret = read(timer_fd, &exp, sizeof(uint64_t));
        if (ret != sizeof(uint64_t)) {
            perror("read");
            close(i2c_fd);
            close(timer_fd);
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}
