#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define GPIO_LINE_COUNT 4
#define GPIO_LINE_FLAGS (GPIOD_LINE_REQUEST_DIRECTION_OUTPUT | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)
#define GPIO_LINE_VALUE_ON 1
#define GPIO_LINE_VALUE_OFF 0

#define INTERVAL_SECONDS_2 2
#define INTERVAL_SECONDS_3 3
#define INTERVAL_SECONDS_5 5
#define INTERVAL_SECONDS_7 7

#define INTERVAL_NANOSECONDS_2 0
#define INTERVAL_NANOSECONDS_3 0
#define INTERVAL_NANOSECONDS_5 0
#define INTERVAL_NANOSECONDS_7 0

#define INTERVAL_COUNT 4

#define ERROR_EXIT_CODE 1

static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_lines[GPIO_LINE_COUNT];
static struct timespec interval_times[INTERVAL_COUNT] = {
    {INTERVAL_SECONDS_2, INTERVAL_NANOSECONDS_2},
    {INTERVAL_SECONDS_3, INTERVAL_NANOSECONDS_3},
    {INTERVAL_SECONDS_5, INTERVAL_NANOSECONDS_5},
    {INTERVAL_SECONDS_7, INTERVAL_NANOSECONDS_7}
};

static void gpio_init(void)
{
    int i;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        exit(ERROR_EXIT_CODE);
    }

    for (i = 0; i < GPIO_LINE_COUNT; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, GPIO_LINE_OFFSET + i);
        if (!gpio_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET + i, strerror(errno));
            exit(ERROR_EXIT_CODE);
        }

        if (gpiod_line_request(gpio_lines[i], NULL, GPIO_LINE_FLAGS) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE_OFFSET + i, strerror(errno));
            exit(ERROR_EXIT_CODE);
        }
    }
}

static void gpio_cleanup(void)
{
    int i;

    for (i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_release(gpio_lines[i]);
    }

    gpiod_chip_close(gpio_chip);
}

static void gpio_set_value(int line, int value)
{
    if (gpiod_line_set_value(gpio_lines[line], value) < 0) {
        fprintf(stderr, "Failed to set GPIO line %d value: %s\n", GPIO_LINE_OFFSET + line, strerror(errno));
        exit(ERROR_EXIT_CODE);
    }
}

static void gpio_toggle_value(int line)
{
    int value;

    value = gpiod_line_get_value(gpio_lines[line]);
    if (value < 0) {
        fprintf(stderr, "Failed to get GPIO line %d value: %s\n", GPIO_LINE_OFFSET + line, strerror(errno));
        exit(ERROR_EXIT_CODE);
    }

    gpio_set_value(line, !value);
}

static void gpio_toggle_values(void)
{
    int i;

    for (i = 0; i < GPIO_LINE_COUNT; i++) {
        gpio_toggle_value(i);
    }
}

static void gpio_toggle_values_interval(int interval)
{
    struct timespec start_time, current_time, elapsed_time;

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        gpio_toggle_values();

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_time.tv_sec = current_time.tv_sec - start_time.tv_sec;
        elapsed_time.tv_nsec = current_time.tv_nsec - start_time.tv_nsec;

        if (elapsed_time.tv_sec >= interval_times[interval].tv_sec && elapsed_time.tv_nsec >= interval_times[interval].tv_nsec) {
            break;
        }

        usleep(100000);
    }
}

static void gpio_toggle_values_intervals(void)
{
    int i;

    for (i = 0; i < INTERVAL_COUNT; i++) {
        gpio_toggle_values_interval(i);
    }
}

static void signal_handler(int signal)
{
    gpio_cleanup();
    exit(0);
}

int main(void)
{
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_init();

    while (1) {
        gpio_toggle_values_intervals();
    }

    return 0;
}

