#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define ALARM_LOG_FILE "alarm_log.txt"
#define ALARM_DURATION_MS 3000
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_MS 500

static volatile int keep_running = 1;

void handle_signal(int signal)
{
    keep_running = 0;
}

int main(int argc, char *argv[])
{
    FILE *alarm_log;
    int sound_sensor_value, relay_state, last_sound_sensor_value, last_relay_state;
    time_t current_time;
    struct tm *time_info;
    char time_string[20];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SOUND_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RELAY_PIN, PI_PUD_OFF);

    gpioWrite(RELAY_PIN, PI_OFF);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    alarm_log = fopen(ALARM_LOG_FILE, "a");
    if (alarm_log == NULL)
    {
        fprintf(stderr, "Failed to open alarm log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    last_sound_sensor_value = gpioRead(SOUND_SENSOR_PIN);
    last_relay_state = PI_OFF;

    while (keep_running)
    {
        sound_sensor_value = gpioRead(SOUND_SENSOR_PIN);
        relay_state = gpioRead(RELAY_PIN);

        if (sound_sensor_value != last_sound_sensor_value)
        {
            if (sound_sensor_value == PI_ON)
            {
                current_time = time(NULL);
                time_info = localtime(&current_time);
                strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);
                fprintf(alarm_log, "%s: Sound detected\n", time_string);
                fflush(alarm_log);

                if (relay_state == PI_OFF)
                {
                    gpioWrite(RELAY_PIN, PI_ON);
                    gpioDelay(ALARM_DURATION_MS);
                    gpioWrite(RELAY_PIN, PI_OFF);
                }
            }

            last_sound_sensor_value = sound_sensor_value;
        }

        if (relay_state != last_relay_state)
        {
            current_time = time(NULL);
            time_info = localtime(&current_time);
            strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

            if (relay_state == PI_ON)
            {
                fprintf(alarm_log, "%s: Relay activated\n", time_string);
            }
            else
            {
                fprintf(alarm_log, "%s: Relay deactivated\n", time_string);
            }

            fflush(alarm_log);
            last_relay_state = relay_state;
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    gpioWrite(RELAY_PIN, PI_OFF);
    gpioTerminate();
    fclose(alarm_log);

    return EXIT_SUCCESS;
}

