            }
            else
            {
                fprintf(alarm_log, "%s: Relay deactivated\n", time_string);
            }

            fflush(alarm_log);
            last_relay_state = relay_state;
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    gpioWrite(RELAY_PIN, PI_OFF);
    gpioTerminate();
    fclose(alarm_log);

    return EXIT_SUCCESS;
