static void i2c_gyro_buffer_push(i2c_gyro_data_t data)
{
    i2c_gyro_buffer.data[i2c_gyro_buffer.head] = data;
    i2c_gyro_buffer.head = (i2c_gyro_buffer.head + 1) % I2C_GYRO_BUFFER_SIZE;
    if (i2c_gyro_buffer.head == i2c_gyro_buffer.tail) {
        i2c_gyro_buffer.tail = (i2c_gyro_buffer.tail + 1) % I2C_GYRO_BUFFER_SIZE;
    }
}

static bool i2c_gyro_buffer_pop(i2c_gyro_data_t *data)
{
    if (i2c_gyro_buffer.head == i2c_gyro_buffer.tail) {
        return false;
    }
    *data = i2c_gyro_buffer.data[i2c_gyro_buffer.tail];
    i2c_gyro_buffer.tail = (i2c_gyro_buffer.tail + 1) % I2C_GYRO_BUFFER_SIZE;
