#define CO2_LOG_FILE "co2_log.json"
#define CO2_ERROR_LOG_FILE "co2_error.log"
#define CO2_READ_CMD {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}
#define CO2_READ_CMD_LEN 9
#define CO2_READ_RESP_LEN 9
#define CO2_READ_TIMEOUT_MS 1000
#define CO2_READ_INTERVAL_S 5

static int co2_log_fd = -1;
static int co2_error_log_fd = -1;
static int co2_uart_fd = -1;

static void co2_log_close(void)
{
    if (co2_log_fd >= 0) {
        close(co2_log_fd);
        co2_log_fd = -1;
    }
}

static void co2_error_log_close(void)
{
    if (co2_error_log_fd >= 0) {
        close(co2_error_log_fd);
        co2_error_log_fd = -1;
    }
}

static void co2_uart_close(void)
{
    if (co2_uart_fd >= 0) {
        serClose(co2_uart_fd);
        co2_uart_fd = -1;
    }
}

static void co2_log_open(void)
{
    co2_log_close();
    co2_log_fd = open(CO2_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (co2_log_fd < 0) {
        fprintf(stderr, "Failed to open %s: %m\n", CO2_LOG_FILE);
        exit(EXIT_FAILURE);
    }
}

static void co2_error_log_open(void)
{
    co2_error_log_close();
    co2_error_log_fd = open(CO2_ERROR_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (co2_error_log_fd < 0) {
        fprintf(stderr, "Failed to open %s: %m\n", CO2_ERROR_LOG_FILE);
        exit(EXIT_FAILURE);
    }
}

static void co2_uart_open(void)
{
    co2_uart_close();
    co2_uart_fd = serOpen("/dev/serial0", 9600, 0);
    if (co2_uart_fd < 0) {
        fprintf(stderr, "Failed to open /dev/serial0: %m\n");
        exit(EXIT_FAILURE);
    }
}

static void co2_log_write(const char *json)
{
    if (co2_log_fd < 0) {
        co2_log_open();
    }
    if (write(co2_log_fd, json, strlen(json)) < 0) {
        fprintf(stderr, "Failed to write to %s: %m\n", CO2_LOG_FILE);
        exit(EXIT_FAILURE);
    }
    if (fsync(co2_log_fd) < 0) {
        fprintf(stderr, "Failed to fsync %s: %m\n", CO2_LOG_FILE);
        exit(EXIT_FAILURE);
    }
}

static void co2_error_log_write(const char *msg)
{
    if (co2_error_log_fd < 0) {
        co2_error_log_open();
    }
    if (write(co2_error_log_fd, msg, strlen(msg)) < 0) {
        fprintf(stderr, "Failed to write to %s: %m\n", CO2_ERROR_LOG_FILE);
        exit(EXIT_FAILURE);
    }
    if (fsync(co2_error_log_fd) < 0) {
        fprintf(stderr, "Failed to fsync %s: %m\n", CO2_ERROR_LOG_FILE);
        exit(EXIT_FAILURE);
    }
}

static void co2_uart_write(const char *buf, size_t len)
{
    if (co2_uart_fd < 0) {
        co2_uart_open();
    }
    if (serWrite(co2_uart_fd, buf, len) < 0) {
        fprintf(stderr, "Failed to write to /dev/serial0: %m\n");
        exit(EXIT_FAILURE);
    }
}

static void co2_uart_read(char *buf, size_t len)
{
    if (co2_uart_fd < 0) {
        co2_uart_open();
    }
    if (serDataAvailable(co2_uart_fd) < 0) {
        fprintf(stderr, "Failed to check /dev/serial0: %m\n");
        exit(EXIT_FAILURE);
    }
    if (serDataAvailable(co2_uart_fd) < len) {
        fprintf(stderr, "Not enough data available on /dev/serial0\n");
        exit(EXIT_FAILURE);
    }
    if (serRead(co2_uart_fd, buf, len) < 0) {
        fprintf(stderr, "Failed to read from /dev/serial0: %m\n");
        exit(EXIT_FAILURE);
    }
}

static void co2_uart_read_timeout(char *buf, size_t len, unsigned timeout_ms)
{
    if (co2_uart_fd < 0) {
        co2_uart_open();
    }
    if (serDataAvailable(co2_uart_fd) < 0) {
        fprintf(stderr, "Failed to check /dev/serial0: %m\n");
        exit(EXIT_FAILURE);
    }
    if (serDataAvailable(co2_uart_fd) < len) {
        if (gpioDelay(timeout_ms * 1000) < 0) {
            fprintf(stderr, "Failed to delay: %m\n");
            exit(EXIT_FAILURE);
        }
        if (serDataAvailable(co2_uart_fd) < 0) {
            fprintf(stderr, "Failed to check /dev/serial0: %m\n");
            exit(EXIT_FAILURE);
        }
        if (serDataAvailable(co2_uart_fd) < len) {
            fprintf(stderr, "Not enough data available on /dev/serial0\n");
            exit(EXIT_FAILURE);
        }
    }
    if (serRead(co2_uart_fd, buf, len) < 0) {
        fprintf(stderr, "Failed to read from /dev/serial0: %m\n");
        exit(EXIT_FAILURE);
    }
}

static void co2_uart_read_cmd(void)
{
    static const char cmd[] = CO2_READ_CMD;
    co2_uart_write(cmd, CO2_READ_CMD_LEN);
}

static void co2_uart_read_resp(char *buf)
{
    co2_uart_read_timeout(buf, CO2_READ_RESP_LEN, CO2_READ_TIMEOUT_MS);
}

static int co2_uart_read_resp_validate(const char *buf)
{
    int i;
    int sum = 0;
    for (i = 1; i < 8; i++) {
        sum += buf[i];
    }
    sum = (sum ^ 0xFF) + 1;
    return sum == buf[8];
}

static int co2_uart_read_ppm(void)
{
    char buf[CO2_READ_RESP_LEN];
    co2_uart_read_cmd();
    co2_uart_read_resp(buf);
    if (!co2_uart_read_resp_validate(buf)) {
        co2_error_log_write("Invalid response from /dev/serial0\n");
        return -1;
    }
    return (buf[2] << 8) | buf[3];
}

static void co2_log_json(int ppm, int error)
{
    char buf[1024];
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Failed to get time: %m\n");
        exit(EXIT_FAILURE);
    }
    snprintf(buf, sizeof(buf), "{\"timestamp\":%ld%09ld,\"ppm\":%d,\"error\":%d}\n", ts.tv_sec, ts.tv_nsec, ppm, error);
    co2_log_write(buf);
}

static void co2_log_json_ppm(int ppm)
{
    co2_log_json(ppm, 0);
}

static void co2_log_json_error(void)
{
    co2_log_json(-1, 1);
}

static void co2_log_json_interval(void)
{
    int ppm = co2_uart_read_ppm();
    if (ppm < 0) {
        co2_log_json_error();
    } else {
        co2_log_json_ppm(ppm);
    }
}

static void co2_log_json_interval_loop(void)
{
    while (1) {
        co2_log_json_interval();
        if (gpioDelay(CO2_READ_INTERVAL_S * 1000000) < 0) {
            fprintf(stderr, "Failed to delay: %m\n");
            exit(EXIT_FAILURE);
        }
    }
}

static void co2_log_json_interval_loop_sigint(int sig)
{
    (void)sig;
    co2_log_close();
    co2_error_log_close();
    co2_uart_close();
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %m\n");
        exit(EXIT_FAILURE);
    }
    signal(SIGINT, co2_log_json_interval_loop_sigint);
    signal(SIGTERM, co2_log_json_interval_loop_sigint);
    co2_log_json_interval_loop();
    return 0;
}

