#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define I2C_CMD 0x10
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LOG_FILE "lighting_log.txt"

int i2c_fd = -1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *red_line = NULL;
struct gpiod_line *green_line = NULL;
struct gpiod_line *blue_line = NULL;
FILE *log_file = NULL;

void cleanup(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;
    char i2c_dev[16];
    uint8_t buf[2];
    uint16_t lux;
    time_t timestamp;
    struct tm *tm;
    char time_str[32];
    int red_state, green_state, blue_state;

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);
    atexit(cleanup);

    // Open I2C bus
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        return EXIT_FAILURE;
    }

    // Set I2C command
    ret = write(i2c_fd, &I2C_CMD, 1);
    if (ret != 1) {
        perror("Failed to write I2C command");
        return EXIT_FAILURE;
    }

    // Wait for conversion
    usleep(120000);

    // Read lux value
    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Failed to read lux value");
        return EXIT_FAILURE;
    }
    lux = (buf[0] << 8) | buf[1];
    lux /= 1.2;

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_GPIO);
    if (!red_line) {
        perror("Failed to request RED GPIO line");
        return EXIT_FAILURE;
    }
    green_line = gpiod_chip_get_line(chip, GREEN_GPIO);
    if (!green_line) {
        perror("Failed to request GREEN GPIO line");
        return EXIT_FAILURE;
    }
    blue_line = gpiod_chip_get_line(chip, BLUE_GPIO);
    if (!blue_line) {
        perror("Failed to request BLUE GPIO line");
        return EXIT_FAILURE;
    }

    // Configure GPIO lines as output
    ret = gpiod_line_request_output(red_line, "red", 0);
    if (ret < 0) {
        perror("Failed to configure RED GPIO line as output");
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(green_line, "green", 0);
    if (ret < 0) {
        perror("Failed to configure GREEN GPIO line as output");
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(blue_line, "blue", 0);
    if (ret < 0) {
        perror("Failed to configure BLUE GPIO line as output");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Get current time
        timestamp = time(NULL);
        tm = localtime(&timestamp);
        if (!tm) {
            perror("Failed to get current time");
            return EXIT_FAILURE;
        }
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

        // Set relay states based on lux
        red_state = (lux < 50) ? 1 : 0;
        green_state = (lux >= 50 && lux < 150) ? 1 : 0;
        blue_state = (lux >= 150 && lux < 300) ? 1 : 0;

        // Write to log file
        fprintf(log_file, "%s, %d, %d, %d, %d\n", time_str, lux, red_state, green_state, blue_state);
        fflush(log_file);

        // Set GPIO line states
        ret = gpiod_line_set_value(red_line, red_state);
        if (ret < 0) {
            perror("Failed to set RED GPIO line state");
            return EXIT_FAILURE;
        }
        ret = gpiod_line_set_value(green_line, green_state);
        if (ret < 0) {
            perror("Failed to set GREEN GPIO line state");
            return EXIT_FAILURE;
        }
        ret = gpiod_line_set_value(blue_line, blue_state);
        if (ret < 0) {
            perror("Failed to set BLUE GPIO line state");
            return EXIT_FAILURE;
        }

        // Wait for 1 second
        sleep(1);
    }

    return EXIT_SUCCESS;
}

