#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQ 1000
#define PWM_RANGE 255

#define DIST_MIN 10
#define DIST_MAX 100

#define DIST_THRESH 50

#define LOOP_DELAY 100

int motor_a_dist;
int motor_b_dist;

void motor_control(int motor_in1, int motor_in2, int dist) {
    int duty;

    if (dist < DIST_MIN) {
        dist = DIST_MIN;
    } else if (dist > DIST_MAX) {
        dist = DIST_MAX;
    }

    duty = (dist - DIST_MIN) * PWM_RANGE / (DIST_MAX - DIST_MIN);

    if (dist < DIST_THRESH) {
        gpioWrite(motor_in1, 1);
        gpioWrite(motor_in2, 0);
    } else {
        gpioWrite(motor_in1, 0);
        gpioWrite(motor_in2, 1);
    }

    gpioPWM(motor_in2, duty);
}

void motor_cleanup() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    gpioPWM(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_B_IN4, 0);

    gpioTerminate();
}

void sig_handler(int sig) {
    motor_cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <motor_a_dist> <motor_b_dist>\n", argv[0]);
        return 1;
    }

    motor_a_dist = atoi(argv[1]);
    motor_b_dist = atoi(argv[2]);

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQ);
    gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQ);
    gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        motor_control(MOTOR_A_IN1, MOTOR_A_IN2, motor_a_dist);
        motor_control(MOTOR_B_IN3, MOTOR_B_IN4, motor_b_dist);

        gpioDelay(LOOP_DELAY * 1000);
    }

    return 0;
}

