### Instruction:
Write a C program for a Raspberry Pi 4 Model B using the pigpio library to implement a simple traffic light controller. A button on GPIO17 (internal pull-up enabled, active-low) toggles the state of the traffic light. The traffic light consists of three LEDs on GPIO18, GPIO23, and GPIO24 (active-high) in the order red, amber, green. The traffic light starts in the red state and cycles through the states in the order red, amber, green, amber, red, amber, green, amber, red, ... The cycle repeats indefinitely. The button toggles the state of the traffic light between the red and amber states. The button must be debounced with a minimum 50 ms gap between presses. Check the return value of every pigpio call, including gpioInitialise, gpioSetMode, gpioSetISRFuncEx, and gpioWrite. The interrupt handler must not block — use a volatile flag checked by the main loop to control the state of the traffic light. On SIGINT or SIGTERM, stop the PWM, release all resources, and call gpioTerminate for a clean shutdown.

### Response:
```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define RED_LED_PIN 18
#define AMBER_LED_PIN 23
#define GREEN_LED_PIN 24
#define DEBOUNCE_TIME 50

typedef enum {
    RED,
    AMBER,
    GREEN
} TrafficLightState;

static volatile int keep_running = 1;
static volatile TrafficLightState traffic_light_state = RED;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

static void button_callback(int gpio, int level, uint32_t tick)
{
    static uint32_t last_press_time = 0;

    if (level == 0) {
        uint32_t current_time = gpioTick();
        if (current_time - last_press_time >= DEBOUNCE_TIME) {
            if (traffic_light_state == RED) {
                traffic_light_state = AMBER;
            } else if (traffic_light_state == AMBER) {
                traffic_light_state = GREEN;
            } else if (traffic_light_state == GREEN) {
                traffic_light_state = AMBER;
            }
            last_press_time = current_time;
        }
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, DEBOUNCE_TIME, button_callback);

    gpioSetMode(RED_LED_PIN, PI_OUTPUT);
    gpioSetMode(AMBER_LED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_LED_PIN, PI_OUTPUT);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (keep_running) {
        if (traffic_light_state == RED) {
            gpioWrite(RED_LED_PIN, 1);
            gpioWrite(AMBER_LED_PIN, 0);
            gpioWrite(GREEN_LED_PIN, 0);
        } else if (traffic_light_state == AMBER) {
            gpioWrite(RED_LED_PIN, 0);
            gpioWrite(AMBER_LED_PIN, 1);
            gpioWrite(GREEN_LED_PIN, 0);
        } else if (traffic_light_state == GREEN) {
            gpioWrite(RED_LED_PIN, 0);
            gpioWrite(AMBER_LED_PIN, 0);
            gpioWrite(GREEN_LED_PIN, 1);
        }
        gpioDelay(1000);
    }

    gpioWrite(RED_LED_PIN, 0);
    gpioWrite(AMBER_LED_PIN, 0);
    gpioWrite(GREEN_LED_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}
