#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define MAX_EVENTS 5
#define MAX_BUF 64

static volatile sig_atomic_t done = 0;

static void term(int signum)
{
    done = 1;
}

int main(int argc, char *argv[])
{
    struct gpiod_line_event event;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config line_config;
    struct gpiod_line_event_poll_status poll_status;
    struct gpiod_line_event_poll poll;
    struct timespec ts;
    char buf[MAX_BUF];
    int timeout = 1000;
    int i, j, k, n, rc;
    FILE *fp;

    if (argc > 1) {
        timeout = atoi(argv[1]);
    }

    if (timeout <= 0) {
        fprintf(stderr, "Invalid timeout %d\n", timeout);
        return 1;
    }

    if (signal(SIGINT, term) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    if (signal(SIGTERM, term) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line_config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    line_config.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN;
    line_config.consumer = "vibration";
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    rc = gpiod_line_request(line, &line_config, 0);
    if (rc < 0) {
        perror("gpiod_line_request");
        return 1;
    }

    fp = fopen("vibration_events.log", "w");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    poll.lineoffsets[0] = 0;
    poll.timeout_ms = timeout;
    poll.flags = GPIOD_LINE_EVENT_POLL_REQUEST_BOTH_EDGES;

    while (!done) {
        rc = gpiod_line_event_poll(line, &poll, &poll_status);
        if (rc < 0) {
            perror("gpiod_line_event_poll");
            return 1;
        }

        if (poll_status.revents & GPIOD_LINE_EVENT_POLL_ERROR) {
            fprintf(stderr, "Error event\n");
            return 1;
        }

        if (poll_status.revents & GPIOD_LINE_EVENT_POLL_TIMEOUT) {
            fprintf(stderr, "Timeout\n");
            return 1;
        }

        if (poll_status.revents & GPIOD_LINE_EVENT_POLL_HUP) {
            fprintf(stderr, "Hangup\n");
            return 1;
        }

        if (poll_status.revents & GPIOD_LINE_EVENT_POLL_NVAL) {
            fprintf(stderr, "Invalid request\n");
            return 1;
        }

        if (poll_status.revents & GPIOD_LINE_EVENT_POLL_LINE_HIGH) {
            fprintf(stderr, "Line high\n");
            return 1;
        }

        if (poll_status.revents & GPIOD_LINE_EVENT_POLL_LINE_LOW) {
            fprintf(stderr, "Line low\n");
            return 1;
        }

        rc = gpiod_line_event_wait(line, &event);
        if (rc < 0) {
            perror("gpiod_line_event_wait");
            return 1;
        }

        rc = clock_gettime(CLOCK_REALTIME, &ts);
        if (rc < 0) {
            perror("clock_gettime");
            return 1;
        }

        rc = gpiod_line_event_read(line, &event);
        if (rc < 0) {
            perror("gpiod_line_event_read");
            return 1;
        }

        strftime(buf, sizeof(buf), "%FT%T%z", gmtime(&ts.tv_sec));
        fprintf(fp, "%s.%09ld %d\n", buf, ts.tv_nsec, event.event_type);
        fflush(fp);

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            printf("EARTHQUAKE ALERT %s.%09ld\n", buf, ts.tv_nsec);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(fp);

    return 0;
}
