#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define I2C_REG_MR_REG_M 0x02
#define I2C_REG_CRA_REG_M 0x00
#define I2C_REG_OUT_X_H_M 0x03
#define I2C_REG_OUT_X_L_M 0x04
#define I2C_REG_OUT_Z_H_M 0x05
#define I2C_REG_OUT_Z_L_M 0x06
#define I2C_REG_OUT_Y_H_M 0x07
#define I2C_REG_OUT_Y_L_M 0x08

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define CSV_FILE "mag_log.csv"

#define DIRECTIONS 8
const char *directions[DIRECTIONS] = { "N", "NE", "E", "SE", "S", "SW", "W", "NW" };

int i2c_fd = -1;
FILE *csv_file = NULL;

void cleanup(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;
    char buf[100];
    uint8_t reg;
    int16_t x, y, z;
    float x_cal, y_cal, z_cal;
    float heading;
    int direction;
    struct tm *tm;
    time_t t;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Configure magnetometer
    reg = 0x00;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    reg = 0x14;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    reg = 0x00;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Write header row if file is empty
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    // Install signal handler
    signal(SIGINT, sigint_handler);

    // Read and process data
    while (true) {
        // Read X value
        reg = I2C_REG_OUT_X_H_M;
        ret = write(i2c_fd, &reg, 1);
        if (ret != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            continue;
        }
        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            continue;
        }
        x = (buf[0] << 8) | buf[1];

        // Read Y value
        reg = I2C_REG_OUT_Y_H_M;
        ret = write(i2c_fd, &reg, 1);
        if (ret != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            continue;
        }
        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            continue;
        }
        y = (buf[0] << 8) | buf[1];

        // Read Z value
        reg = I2C_REG_OUT_Z_H_M;
        ret = write(i2c_fd, &reg, 1);
        if (ret != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            continue;
        }
        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            continue;
        }
        z = (buf[0] << 8) | buf[1];

        // Apply hard-iron calibration offsets
        x_cal = x - X_OFFSET;
        y_cal = y - Y_OFFSET;
        z_cal = z - Z_OFFSET;

        // Compute heading
        heading = atan2f(y_cal, x_cal) * 180.0f / M_PI;
        if (heading < 0) {
            heading += 360.0f;
        }

        // Map heading to compass direction
        direction = (int)(heading / 45.0f) % DIRECTIONS;

        // Print heading and direction
        printf("Heading: %.2f degrees (%s)\n", heading, directions[direction]);

        // Get current time
        t = time(NULL);
        tm = localtime(&t);

        // Write data to CSV file
        fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                x_cal, y_cal, z_cal, heading);
        fflush(csv_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up resources
    cleanup();

    return EXIT_SUCCESS;
}

