        ret = write(i2c_fd, &reg, 1);
        if (ret != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            continue;
        }
        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            continue;
        }
        z = (buf[0] << 8) | buf[1];

        // Apply hard-iron calibration offsets
        x_cal = x - X_OFFSET;
        y_cal = y - Y_OFFSET;
        z_cal = z - Z_OFFSET;

        // Compute heading
        heading = atan2f(y_cal, x_cal) * 180.0f / M_PI;
        if (heading < 0) {
            heading += 360.0f;
        }

        // Map heading to compass direction
        direction = (int)(heading / 45.0f) % DIRECTIONS;

        // Print heading and direction
        printf("Heading: %.2f degrees (%s)\n", heading, directions[direction]);

        // Get current time
        t = time(NULL);
        tm = localtime(&t);

        // Write data to CSV file
        fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                x_cal, y_cal, z_cal, heading);
        fflush(csv_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up resources
    cleanup();

    return EXIT_SUCCESS;
}
