#define LOG_ENTRY_SIZE 128

static int relay_state = 0;
static int last_touch_time = 0;

void toggle_relay(void)
{
    if (relay_state) {
        gpioWrite(RELAY_PIN, 0);
        relay_state = 0;
    } else {
        gpioWrite(RELAY_PIN, 1);
        relay_state = 1;
    }
}

void sensor_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) {
        int now = time(NULL);
        if (now - last_touch_time >= 200) {
            toggle_relay();
            last_touch_time = now;

            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file) {
                char log_entry[LOG_ENTRY_SIZE];
                struct tm *time_info = localtime(&now);
                strftime(log_entry, LOG_ENTRY_SIZE, "{\"timestamp\":\"%FT%T\",\"relay_state\":\"%s\"}\n", time_info, relay_state ? "ON" : "OFF");
                fputs(log_entry, log_file);
                fclose(log_file);
            }
        }
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN);

    if (gpioSetISRFunc(SENSOR_PIN, EITHER_EDGE, 200, sensor_callback) < 0) {
        fprintf(stderr, "Failed to set ISR callback\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Do other tasks here
    }

