#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define RELAY_COUNT 4
#define RELAY_GPIO_PINS {17, 23, 24, 25}
#define RELAY_GPIO_LABELS {"17", "23", "24", "25"}
#define RELAY_GPIO_ACTIVE_STATE 0
#define RELAY_GPIO_INACTIVE_STATE 1
#define RELAY_GPIO_ACTIVE_TIME_MS 5000
#define RELAY_GPIO_INACTIVE_TIME_MS 1000
#define RELAY_GPIO_LOG_FILE "irrigation_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *lines[RELAY_COUNT];
FILE *log_file;

void activate_relay(int relay_index) {
    if (gpiod_line_request_output(lines[relay_index], RELAY_GPIO_LABELS[relay_index], RELAY_GPIO_ACTIVE_STATE) < 0) {
        fprintf(stderr, "Error requesting output for relay %d: %s\n", relay_index, strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(lines[relay_index], RELAY_GPIO_ACTIVE_STATE) < 0) {
        fprintf(stderr, "Error setting active state for relay %d: %s\n", relay_index, strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s, Relay %d, Active\n", gpiod_line_get_name(lines[relay_index]), relay_index);
    fflush(log_file);
    usleep(RELAY_GPIO_ACTIVE_TIME_MS * 1000);
    if (gpiod_line_set_value(lines[relay_index], RELAY_GPIO_INACTIVE_STATE) < 0) {
        fprintf(stderr, "Error setting inactive state for relay %d: %s\n", relay_index, strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s, Relay %d, Inactive\n", gpiod_line_get_name(lines[relay_index]), relay_index);
    fflush(log_file);
    usleep(RELAY_GPIO_INACTIVE_TIME_MS * 1000);
}

void deactivate_relays() {
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpiod_line_set_value(lines[i], RELAY_GPIO_INACTIVE_STATE) < 0) {
            fprintf(stderr, "Error setting inactive state for relay %d: %s\n", i, strerror(errno));
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "%s, Relay %d, Inactive\n", gpiod_line_get_name(lines[i]), i);
        fflush(log_file);
    }
}

void cleanup() {
    deactivate_relays();
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpiod_line_release(lines[i]) < 0) {
            fprintf(stderr, "Error releasing line %d: %s\n", i, strerror(errno));
            exit(EXIT_FAILURE);
        }
    }
    if (gpiod_chip_close(chip) < 0) {
        fprintf(stderr, "Error closing chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fclose(log_file);
}

void signal_handler(int signal) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    srand(time(NULL));
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", i, strerror(errno));
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], RELAY_GPIO_LABELS[i], RELAY_GPIO_INACTIVE_STATE) < 0) {
            fprintf(stderr, "Error requesting output for line %d: %s\n", i, strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    log_file = fopen(RELAY_GPIO_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    while (1) {
        int moisture = rand() % 101;
        fprintf(log_file, "%s, Moisture, %d\n", gpiod_line_get_name(lines[0]), moisture);
        fflush(log_file);
        if (moisture < 30) {
            for (int i = 0; i < RELAY_COUNT; i++) {
                activate_relay(i);
            }
        }
        sleep(10);
    }

    cleanup();
    return 0;
}

