#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define VALVE_PIN 17
#define NOZZLE_PIN 18
#define VALVE_OPEN 90
#define VALVE_CLOSED 0
#define NOZZLE_START 0
#define NOZZLE_END 180
#define NOZZLE_STEP 45
#define NOZZLE_DELAY 2000
#define WATERING_DELAY 5000
#define MOISTURE_THRESHOLD 50
#define RETRIES 3
#define RETRY_DELAY 100

volatile sig_atomic_t stop = 0;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main(void)
{
    int moisture = 0;
    int nozzle_pos = NOZZLE_START;
    int retries = 0;
    int result = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        moisture = rand() % 101;
        printf("Moisture: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Watering...\n");

            // Open valve
            retries = 0;
            do {
                result = gpioServo(VALVE_PIN, VALVE_OPEN);
                if (result < 0) {
                    fprintf(stderr, "Failed to open valve\n");
                    break;
                }
                retries++;
            } while (result < 0 && retries < RETRIES);
            if (result < 0) {
                continue;
            }

            // Sweep nozzle
            nozzle_pos = NOZZLE_START;
            while (nozzle_pos <= NOZZLE_END) {
                retries = 0;
                do {
                    result = gpioServo(NOZZLE_PIN, nozzle_pos);
                    if (result < 0) {
                        fprintf(stderr, "Failed to set nozzle position\n");
                        break;
                    }
                    retries++;
                } while (result < 0 && retries < RETRIES);
                if (result < 0) {
                    break;
                }

                gpioDelay(NOZZLE_DELAY);
                nozzle_pos += NOZZLE_STEP;
            }

            // Hold watering
            gpioDelay(WATERING_DELAY);

            // Close valve
            retries = 0;
            do {
                result = gpioServo(VALVE_PIN, VALVE_CLOSED);
                if (result < 0) {
                    fprintf(stderr, "Failed to close valve\n");
                    break;
                }
                retries++;
            } while (result < 0 && retries < RETRIES);
            if (result < 0) {
                fprintf(stderr, "Critical: failed to close valve\n");
            }
        }

        gpioDelay(WATERING_DELAY);
    }

    gpioServo(VALVE_PIN, 0);
    gpioServo(NOZZLE_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

