#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x68
#define I2C_BUS 1
#define I2C_DEV "/dev/i2c-1"
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

int fd;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        close(fd);
        exit(0);
    }
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return 1;
    }

    uint8_t buf[2];
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to wake sensor");
        close(fd);
        return 1;
    }

    FILE *fp = fopen("gyro_log.txt", "w");
    if (fp == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    struct timespec ts;
    uint8_t data[6];
    int16_t x, y, z;
    double x_deg, y_deg, z_deg;

    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get timestamp");
            break;
        }

        if (read(fd, data, 6) != 6) {
            perror("Failed to read sensor data");
            break;
        }

        x = (data[0] << 8) | data[1];
        y = (data[2] << 8) | data[3];
        z = (data[4] << 8) | data[5];

        x_deg = (double)x / GYRO_SENSITIVITY;
