        close(fd);
        exit(0);
    }
}

int main(void) {
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to select I2C device");
        close(fd);
        return 1;
    }

    // Wake up the sensor from sleep
    char buf[2] = {I2C_REG_PWR_MGMT_1, 0x00};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    // Set the gyroscope full-scale range to ±250 dps
    buf[0] = I2C_REG_GYRO_CONFIG;
    buf[1] = 0x00;
