        if (read(fd, data, 6) != 6) {
            perror("Failed to read from I2C device");
            close(fd);
            return 1;
        }

        // Convert the raw signed 16-bit big-endian values to degrees/second
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        float x_dps = x / I2C_GYRO_SENSITIVITY;
