#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define I2C_ADDR 0x68
#define I2C_BUS 1
#define I2C_HANDLE 0
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define GYRO_CONFIG 0x1B
#define SMPLRT_DIV 0x19
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define LED 17
#define BUFFER_SIZE 100

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    time_t timestamp;
} gyro_data;

gyro_data buffer[BUFFER_SIZE];
int buffer_index = 0;

void init_sensor() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }
    if (i2cOpen(I2C_HANDLE, I2C_ADDR, 0, 0) < 0) {
        fprintf(stderr, "failed to open i2c handle\n");
        exit(1);
    }
    if (i2cWriteByteData(I2C_HANDLE, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "failed to write to PWR_MGMT_1\n");
        exit(1);
    }
    if (i2cWriteByteData(I2C_HANDLE, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "failed to write to SMPLRT_DIV\n");
        exit(1);
    }
    if (i2cWriteByteData(I2C_HANDLE, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "failed to write to GYRO_CONFIG\n");
        exit(1);
    }
    if (i2cReadByteData(I2C_HANDLE, WHO_AM_I) != 0x68) {
        fprintf(stderr, "failed to read WHO_AM_I\n");
        exit(1);
    }
}

void read_sensor() {
    uint8_t data[6];
    if (i2cReadI2CBlockData(I2C_HANDLE, GYRO_XOUT_H, 6, data) < 0) {
        fprintf(stderr, "failed to read gyroscope data\n");
        exit(1);
    }
    buffer[buffer_index].x = (int16_t)((data[0] << 8) | data[1]);
    buffer[buffer_index].y = (int16_t)((data[2] << 8) | data[3]);
    buffer[buffer_index].z = (int16_t)((data[4] << 8) | data[5]);
    buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%d, %d, %d, %ld\n", buffer[i].x, buffer[i].y, buffer[i].z, buffer[i].timestamp);
    }
}

void handle_signal(int signal) {
    gpioWrite(LED, 0);
    gpioTerminate();
    i2cClose(I2C_HANDLE);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    init_sensor();
    gpioSetMode(LED, PI_OUTPUT);
    while (1) {
        read_sensor();
        if (abs(buffer[buffer_index].x) > 250 || abs(buffer[buffer_index].y) > 250 || abs(buffer[buffer_index].z) > 250) {
            gpioWrite(LED, 1);
        } else {
            gpioWrite(LED, 0);
        }
        sleep(50);
    }
    return 0;
}

