#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define I2C_REG_AMBIENT 0x20
#define I2C_REG_PROXIMITY 0x22
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 10
#define LOG_FILE "biometric_log.txt"
#define GPIO_LINE_NAME "gpiochip0"
#define GPIO_LINE_NUM 17

static int i2c_fd = -1;
static int log_fd = -1;
static struct gpiod_line *gpio_line = NULL;

static void cleanup(void)
{
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int i2c_read(uint8_t reg, uint16_t *value)
{
    int ret;
    uint8_t buf[2];

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = write(i2c_fd, &reg, 1);
    if (ret < 0) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, buf, 2);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int i2c_write(uint8_t reg, uint16_t value)
{
    int ret;
    uint8_t buf[3];

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    buf[0] = reg;
    buf[1] = value >> 8;
    buf[2] = value & 0xFF;

    ret = write(i2c_fd, buf, 3);
    if (ret < 0) {
        perror("write");
        return -1;
    }

    return 0;
}

static int i2c_init(void)
{
    int ret;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

static int log_init(void)
{
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_LINE_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(chip, GPIO_LINE_NUM);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    ret = gpiod_line_request_output(gpio_line, "led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }

    return 0;
}

static int gpio_set(int value)
{
