    ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }

    return 0;
}

static int log_write(const char *buf, size_t len)
{
    int ret;

    ret = write(log_fd, buf, len);
    if (ret < 0) {
        perror("write");
        return -1;
    }

    return 0;
}

static int log_printf(const char *fmt, ...)
{
    int ret;
    va_list ap;
    char buf[1024];

    va_start(ap, fmt);
    ret = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    if (ret < 0) {
        perror("vsnprintf");
        return -1;
    }

    return log_write(buf, ret);
}

static int log_timestamp(void)
