#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1 23
#define SENSOR_2 24
#define ALERT_PIN 17
#define ALERT_DURATION 2000
#define EVENT_DURATION 500

FILE *log_file;

void log_event(const char *message)
{
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

void alert_callback(int gpio, int level, uint32_t tick)
{
    gpioWrite(ALERT_PIN, 1);
    log_event("Seismic event detected!");
    gpioDelay(ALERT_DURATION);
    gpioWrite(ALERT_PIN, 0);
}

void init_sensors()
{
    if (gpioSetMode(SENSOR_1, PI_INPUT) != 0)
    {
        fprintf(stderr, "Error setting mode for sensor 1\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(SENSOR_1, PI_PUD_DOWN) != 0)
    {
        fprintf(stderr, "Error setting pull-down for sensor 1\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SENSOR_2, PI_INPUT) != 0)
    {
        fprintf(stderr, "Error setting mode for sensor 2\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(SENSOR_2, PI_PUD_DOWN) != 0)
    {
        fprintf(stderr, "Error setting pull-down for sensor 2\n");
        exit(EXIT_FAILURE);
    }
}

void init_alert_pin()
{
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Error setting mode for alert pin\n");
        exit(EXIT_FAILURE);
    }

    gpioWrite(ALERT_PIN, 0);
}

void init_log_file()
{
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file\n");
        exit(EXIT_FAILURE);
    }
}

void init_callbacks()
{
    if (gpioSetAlertFuncEx(SENSOR_1, alert_callback) != 0)
    {
        fprintf(stderr, "Error setting alert callback for sensor 1\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFuncEx(SENSOR_2, alert_callback) != 0)
    {
        fprintf(stderr, "Error setting alert callback for sensor 2\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup()
{
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
}

void handle_signal(int signal)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[])
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error initializing pigpio\n");
        return EXIT_FAILURE;
    }

    init_sensors();
    init_alert_pin();
    init_log_file();
    init_callbacks();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1)
    {
        gpioDelay(1000);
    }

    return EXIT_SUCCESS;
}

