#include <time.h>
#include <signal.h>
#include <pthread.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define SPI_READ_ADDRESS 0x03
#define SPI_WRITE_ADDRESS 0x02
#define SPI_READ_LENGTH 2
#define SPI_WRITE_LENGTH 1
#define SPI_READ_BUFFER_SIZE 100
#define SPI_READ_THRESHOLD 20.0
#define SPI_READ_LED 17

typedef struct {
    uint8_t buffer[SPI_READ_BUFFER_SIZE][SPI_READ_LENGTH];
    uint8_t head;
    uint8_t tail;
    uint8_t size;
} spi_read_buffer_t;

spi_read_buffer_t spi_read_buffer;

pthread_mutex_t spi_read_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

void spi_read_buffer_init(spi_read_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->size = 0;
}

int spi_read_buffer_is_full(spi_read_buffer_t *buffer) {
    return buffer->size == SPI_READ_BUFFER_SIZE;
}

int spi_read_buffer_is_empty(spi_read_buffer_t *buffer) {
    return buffer->size == 0;
}

int spi_read_buffer_push(spi_read_buffer_t *buffer, uint8_t *data) {
    if (spi_read_buffer_is_full(buffer)) {
        return -1;
    }

    memcpy(buffer->buffer[buffer->head], data, SPI_READ_LENGTH);
    buffer->head = (buffer->head + 1) % SPI_READ_BUFFER_SIZE;
    buffer->size++;
    return 0;
}

int spi_read_buffer_pop(spi_read_buffer_t *buffer, uint8_t *data) {
    if (spi_read_buffer_is_empty(buffer)) {
        return -1;
    }

    memcpy(data, buffer->buffer[buffer->tail], SPI_READ_LENGTH);
    buffer->tail = (buffer->tail + 1) % SPI_READ_BUFFER_SIZE;
    buffer->size--;
    return 0;
}

void spi_read_buffer_clear(spi_read_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->size = 0;
}

void spi_read_buffer_print(spi_read_buffer_t *buffer) {
    printf("SPI Read Buffer:\n");
    printf("  Head: %d\n", buffer->head);
    printf("  Tail: %d\n", buffer->tail);
    printf("  Size: %d\n", buffer->size);
    printf("  Data:\n");
    for (int i = 0; i < SPI_READ_BUFFER_SIZE; i++) {
        printf("    %d: ", i);
        for (int j = 0; j < SPI_READ_LENGTH; j++) {
            printf("%02X ", buffer->buffer[i][j]);
        }
        printf("\n");
    }
}

