#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define RED_LED 17
#define YELLOW_LED 22
#define GREEN_LED 23
#define BLUE_LED 24

#define RED_TIME 10
#define YELLOW_TIME 2
#define GREEN_TIME 10
#define BLUE_TIME 3

#define RED_ON 0
#define YELLOW_ON 0
#define GREEN_ON 1
#define BLUE_ON 0

#define RED_OFF 1
#define YELLOW_OFF 1
#define GREEN_OFF 0
#define BLUE_OFF 1

struct gpiod_chip *chip;
struct gpiod_line *red_line, *yellow_line, *green_line, *blue_line;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main(void)
{
    int ret;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_LED);
    if (!red_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

