        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_output(green_line, "green_led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_LED);
    if (!blue_line) {
        perror("gpiod_chip_get_line");
        return 1;
