#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>

#define SOLENOID_1 17
#define SOLENOID_2 27
#define DISPENSE_DURATION 1000
#define DISPENSE_INTERVAL 5

FILE *log_file;

int init_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialise GPIO\n");
        return 1;
    }
