#define RELAY_1 4
#define RELAY_2 17
#define RELAY_3 27
#define RELAY_4 22

#define LOG_FILE "irrigation_log.txt"

FILE *log_file;

void sig_handler(int signo)
{
    if (signo == SIGINT)
    {
        printf("Received SIGINT, exiting...\n");
        gpioWrite(RELAY_1, 1);
        gpioWrite(RELAY_2, 1);
        gpioWrite(RELAY_3, 1);
        gpioWrite(RELAY_4, 1);
        fclose(log_file);
        gpioTerminate();
        exit(0);
    }
}

int main(void)
{
    int err;
    int moisture_1, moisture_2, moisture_3, moisture_4;
    time_t timestamp;
    char time_str[20];

    if ((err = gpioInitialise()) < 0)
    {
        fprintf(stderr, "pigpio initialisation failed: %s\n", gpioStrerror(err));
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL)
    {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return 1;
    }

    signal(SIGINT, sig_handler);

    gpioSetMode(RELAY_1, PI_OUTPUT);
    gpioSetMode(RELAY_2, PI_OUTPUT);
    gpioSetMode(RELAY_3, PI_OUTPUT);
    gpioSetMode(RELAY_4, PI_OUTPUT);

    while (1)
    {
        srand(time(NULL));
        moisture_1 = rand() % 101;
        moisture_2 = rand() % 101;
        moisture_3 = rand() % 101;
        moisture_4 = rand() % 101;

        timestamp = time(NULL);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

        if (moisture_1 < 30)
        {
            gpioWrite(RELAY_1, 0);
            fprintf(log_file, "%s, Zone 1, Moisture: %d, Relay: ON\n", time_str, moisture_1);
        }
        else
        {
            gpioWrite(RELAY_1, 1);
            fprintf(log_file, "%s, Zone 1, Moisture: %d, Relay: OFF\n", time_str, moisture_1);
        }

        if (moisture_2 < 30)
        {
            gpioWrite(RELAY_2, 0);
            fprintf(log_file, "%s, Zone 2, Moisture: %d, Relay: ON\n", time_str, moisture_2);
        }
        else
        {
            gpioWrite(RELAY_2, 1);
            fprintf(log_file, "%s, Zone 2, Moisture: %d, Relay: OFF\n", time_str, moisture_2);
        }

        if (moisture_3 < 30)
        {
            gpioWrite(RELAY_3, 0);
            fprintf(log_file, "%s, Zone 3, Moisture: %d, Relay: ON\n", time_str, moisture_3);
        }
        else
        {
            gpioWrite(RELAY_3, 1);
            fprintf(log_file, "%s, Zone 3, Moisture: %d, Relay: OFF\n", time_str, moisture_3);
        }

        if (moisture_4 < 30)
