#define I2C_REG_OUT_Z_H 0x2D

#define CTRL_REG1_VALUE 0x77
#define CTRL_REG4_VALUE 0x00

#define SENSITIVITY 16384.0

#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

#define BUZZER_GPIO 17
#define BUZZER_DURATION 1000

#define I2C_RETRIES 3

#define CHECK_ERROR(msg) \
    if (err) { \
        fprintf(stderr, "%s: %s\n", msg, gpioErrMsg(err)); \
        goto cleanup; \
    }

#define CHECK_ERROR_EXIT(msg) \
    if (err) { \
        fprintf(stderr, "%s: %s\n", msg, gpioErrMsg(err)); \
        exit(EXIT_FAILURE); \
    }

static volatile sig_atomic_t interrupted = 0;

static void handle_sigint(int signum)
{
    interrupted = 1;
}

int main(int argc, char *argv[])
{
    int err;
    int i2c_handle;
    int buzzer_gpio;
    double freefall_threshold = FREEFALL_THRESHOLD;
    double impact_threshold = IMPACT_THRESHOLD;
    uint8_t data[6];
    int16_t x, y, z;
    double magnitude;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }

    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    err = gpioInitialise();
    CHECK_ERROR_EXIT("Failed to initialize pigpio");

    err = gpioSetSignalFunc(SIGINT, handle_sigint);
    CHECK_ERROR_EXIT("Failed to set signal handler");

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    CHECK_ERROR_EXIT("Failed to open I2C bus");

    err = i2cWriteByteData(i2c_handle, I2C_REG_CTRL_REG1, CTRL_REG1_VALUE);
    CHECK_ERROR("Failed to write to CTRL_REG1");

    err = i2cWriteByteData(i2c_handle, I2C_REG_CTRL_REG4, CTRL_REG4_VALUE);
    CHECK_ERROR("Failed to write to CTRL_REG4");

    buzzer_gpio = gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    CHECK_ERROR("Failed to set buzzer GPIO mode");

    while (!interrupted) {
        err = i2cReadI2CBlockData(i2c_handle, I2C_REG_OUT_X_L, data, sizeof(data));
        if (err < 0) {
            fprintf(stderr, "Failed to read acceleration data: %s\n", gpioErrMsg(err));
            if (err == PI_I2C_READ_FAILED) {
                // Retry up to 3 times
                for (int i = 0; i < I2C_RETRIES; i++) {
                    err = i2cReadI2CBlockData(i2c_handle, I2C_REG_OUT_X_L, data, sizeof(data));
                    if (err >= 0) {
                        break;
                    }
                }
            }
            if (err < 0) {
                // Give up
                break;
            }
        }

        x = (data[1] << 8) | data[0];
        y = (data[3] << 8) | data[2];
        z = (data[5] << 8) | data[4];

        magnitude = sqrt(x * x + y * y + z * z) / SENSITIVITY;

        if (magnitude < freefall_threshold) {
            printf("Freefall detected\n");
        } else if (magnitude > impact_threshold) {
            printf("Impact detected\n");
            err = gpioWrite(buzzer_gpio, 1);
            CHECK_ERROR("Failed to activate buzzer");
            gpioDelay(BUZZER_DURATION);
            err = gpioWrite(buzzer_gpio, 0);
            CHECK_ERROR("Failed to deactivate buzzer");
        }
    }

cleanup:
    gpioTerminate();
    return err < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}
