#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22
#define BUFFER_SIZE 5

struct gpiod_chip *chip;
struct gpiod_line *left_line, *center_line, *right_line, *alert_line;
struct gpiod_line_request left_req, center_req, right_req, alert_req;

int left_buffer[BUFFER_SIZE], center_buffer[BUFFER_SIZE], right_buffer[BUFFER_SIZE];
int left_buffer_index = 0, center_buffer_index = 0, right_buffer_index = 0;

void init_gpio() {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_config(&left_req, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR);
    if (!left_line) {
        perror("Failed to get left sensor line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(left_line, &left_req, 0) < 0) {
        perror("Failed to request left sensor line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_config(&center_req, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR);
    if (!center_line) {
        perror("Failed to get center sensor line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(center_line, &center_req, 0) < 0) {
        perror("Failed to request center sensor line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_config(&right_req, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR);
    if (!right_line) {
        perror("Failed to get right sensor line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(right_line, &right_req, 0) < 0) {
        perror("Failed to request right sensor line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_config(&alert_req, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert_line) {
        perror("Failed to get alert line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(alert_line, &alert_req, 0) < 0) {
        perror("Failed to request alert line");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpiod_line_release(left_line);
    gpiod_line_release(center_line);
    gpiod_line_release(right_line);
    gpiod_line_release(alert_line);
    gpiod_chip_close(chip);
}

void handle_signal(int signum) {
    cleanup_gpio();
    exit(EXIT_SUCCESS);
}

void log_readings(int left, int center, int right) {
    left_buffer[left_buffer_index] = left;
    left_buffer_index = (left_buffer_index + 1) % BUFFER_SIZE;

    center_buffer[center_buffer_index] = center;
    center_buffer_index = (center_buffer_index + 1) % BUFFER_SIZE;

    right_buffer[right_buffer_index] = right;
    right_buffer_index = (right_buffer_index + 1) % BUFFER_SIZE;
}

void check_alert() {
    int i;
    for (i = 0; i < BUFFER_SIZE; i++) {
        if (center_buffer[i] == 1) {
            return;
        }
    }

    gpiod_line_set_value(alert_line, 1);
    sleep(2);
    gpiod_line_set_value(alert_line, 0);
}

void follow_line() {
    int left, center, right;

    while (1) {
        left = gpiod_line_get_value(left_line);
        center = gpiod_line_get_value(center_line);
        right = gpiod_line_get_value(right_line);

        log_readings(left, center, right);
        check_alert();

        if (center == 0) {
            // Move forward
        } else if (left == 0) {
            // Turn left
        } else if (right == 0) {
            // Turn right
        } else {
            // Stop
        }

        usleep(10000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    follow_line();

    return 0;
}

