static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char buf[128];
    strftime(buf, sizeof(buf), "%FT%T%z", tm);
    fprintf(stderr, "%s: %s\n", buf, msg);
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char buf[128];
    strftime(buf, sizeof(buf), "%FT%T%z", tm);
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", buf, msg);
        fclose(fp);
    }
}

static void log_field(int16_t field_mT_x100)
{
    char buf[128];
    snprintf(buf, sizeof(buf), "field: %d.%02d mT", field_mT_x100 / 100, field_mT_x100 % 100);
    log_event(buf);
}

static void log_relay(bool active)
{
    char buf[128];
    snprintf(buf, sizeof(buf), "relay: %s", active ? "active" : "inactive");
    log_event(buf);
}

static void log_timeout(void)
{
    log_error("timeout");
}

