#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define MAX_LINE 1024
#define RELAY_PIN 18

int main(int argc, char *argv[])
{
    int sockfd, newsockfd, n;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t clilen;
    char buffer[MAX_LINE];
    FILE *fp;

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set relay pin as output\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0)
    {
        fprintf(stderr, "Failed to create socket\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize server address
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0)
    {
        fprintf(stderr, "Failed to bind socket\n");
        close(sockfd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sockfd, 5) < 0)
    {
        fprintf(stderr, "Failed to listen for incoming connections\n");
        close(sockfd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open log file
    fp = fopen("relay_log.txt", "a");
    if (fp == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        close(sockfd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Handle SIGINT and SIGTERM signals
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Accept incoming connections
    while (1)
    {
        clilen = sizeof(cli_addr);
        newsockfd = accept(sockfd, (struct sockaddr *)&cli_addr, &clilen);
        if (newsockfd < 0)
        {
            fprintf(stderr, "Failed to accept incoming connection\n");
            close(sockfd);
            fclose(fp);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        // Read command from client
        memset(buffer, 0, MAX_LINE);
        n = read(newsockfd, buffer, MAX_LINE - 1);
        if (n < 0)
        {
            fprintf(stderr, "Failed to read command from client\n");
            close(newsockfd);
            close(sockfd);
            fclose(fp);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        // Process command
        if (strcmp(buffer, "ON\n") == 0)
        {
            // Turn on relay
            gpioWrite(RELAY_PIN, 1);
            fprintf(fp, "%s", "Relay turned on\n");
        }
        else if (strcmp(buffer, "OFF\n") == 0)
        {
            // Turn off relay
            gpioWrite(RELAY_PIN, 0);
            fprintf(fp, "%s", "Relay turned off\n");
        }
        else
        {
            // Invalid command
            fprintf(fp, "%s", "Invalid command\n");
        }

        // Close connection
        close(newsockfd);
    }

    // Close socket and log file
    close(sockfd);
    fclose(fp);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum)
{
    // Close socket and log file
    close(sockfd);
    fclose(fp);

    // Turn off relay
    gpioWrite(RELAY_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(EXIT_SUCCESS);
}

