#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>

#define RAIN_SENSOR 17
#define MOTOR_ENA 22
#define MOTOR_IN1 23
#define MOTOR_IN2 24

#define MOTOR_RUN_TIME 5000000
#define POLL_INTERVAL 200000
#define RAIN_THRESHOLD 3

static volatile int keep_running = 1;

static void signal_handler(int signum)
{
    syslog(LOG_INFO, "Received signal %d, shutting down", signum);
    keep_running = 0;
}

int main(int argc, char *argv[])
{
    int rain_sensor_state = 0;
    int rain_count = 0;
    int motor_running = 0;

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return EXIT_FAILURE;
    }

    gpioSetMode(RAIN_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR, PI_PUD_UP);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);

    openlog("rain_window", LOG_CONS | LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting up");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int new_rain_sensor_state = gpioRead(RAIN_SENSOR);

        if (new_rain_sensor_state != rain_sensor_state) {
            if (new_rain_sensor_state == 0) {
                syslog(LOG_INFO, "Rain detected");
                rain_count++;
            } else {
                rain_count = 0;
            }

            rain_sensor_state = new_rain_sensor_state;
        }

        if (rain_count >= RAIN_THRESHOLD) {
            if (!motor_running) {
                syslog(LOG_INFO, "Starting motor");
                gpioWrite(MOTOR_ENA, 1);
                gpioWrite(MOTOR_IN1, 1);
                gpioWrite(MOTOR_IN2, 0);
                motor_running = 1;
            }
        } else {
            if (motor_running) {
                syslog(LOG_INFO, "Stopping motor");
                gpioWrite(MOTOR_ENA, 0);
                gpioWrite(MOTOR_IN1, 0);
                gpioWrite(MOTOR_IN2, 0);
                motor_running = 0;
            }
        }

        gpioDelay(POLL_INTERVAL);
    }

    syslog(LOG_INFO, "Shutting down");
    closelog();
    gpioTerminate();

    return EXIT_SUCCESS;
}

