#define PIR_PIN 4
#define RELAY_PIN 17

FILE *log_file;

void log_event(int event, time_t timestamp, int duration)
{
    char time_str[26];
    struct tm *tm_info;

    tm_info = localtime(&timestamp);
    strftime(time_str, 26, "%Y-%m-%dT%H:%M:%S%z", tm_info);

    if (event == 0)
    {
        fprintf(log_file, "%s: Motion detected\n", time_str);
    }
    else
    {
        fprintf(log_file, "%s: Motion ended, duration: %d seconds\n", time_str, duration);
    }

    fflush(log_file);
}

void handle_motion(int gpio, int level, uint32_t tick)
{
    static int motion_detected = 0;
    static time_t start_time;

    if (level == 1)
    {
        if (motion_detected == 0)
        {
            motion_detected = 1;
            start_time = time(NULL);
            gpioWrite(RELAY_PIN, 1);
            log_event(0, start_time, 0);
        }
    }
    else
    {
        if (motion_detected == 1)
        {
            motion_detected = 0;
            time_t end_time = time(NULL);
            int duration = difftime(end_time, start_time);
            gpioWrite(RELAY_PIN, 0);
            log_event(1, end_time, duration);
        }
    }
}

void handle_signal(int signum)
{
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetAlertFunc(PIR_PIN, handle_motion);

    while (1)
    {
        gpioDelay(100000);
    }

    return 0;
}

