#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <gpiod.h>

#define PORT 5000
#define LOG_FILE "security.log"

static int servo_fd = -1;
static int pir_fd = -1;
static int log_fd = -1;
static int sock_fd = -1;
static pthread_t servo_thread;

static void log_message(const char *format, ...)
{
    va_list args;
    char buffer[1024];
    time_t now;
    struct tm *timeinfo;

    time(&now);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%FT%T%z ", timeinfo);

    va_start(args, format);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), format, args);
    va_end(args);

    syslog(LOG_USER | LOG_INFO, "%s", buffer);
    write(log_fd, buffer, strlen(buffer));
}

static void *servo_thread_func(void *arg)
{
    int value = 0;
    int pulse_width = 0;
    int pulse_period = 1000000 / 50;
    struct gpiod_line_request req;

    memset(&req, 0, sizeof(req));
    req.line_offsets[0] = 17;
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE;
    req.default_values[0] = 0;
    req.consumer = "servo";

    servo_fd = gpiod_line_request(&req, 1);
    if (servo_fd < 0) {
        log_message("gpiod_line_request failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpiod_line_set_value(servo_fd, value);
        usleep(pulse_width);
        gpiod_line_set_value(servo_fd, !value);
        usleep(pulse_period - pulse_width);
    }

    return NULL;
}

static void handle_command(const char *command)
{
    if (strncmp(command, "SERVO ", 6) == 0) {
        int angle = atoi(command + 6);
        if (angle < 0 || angle > 180) {
            log_message("Invalid angle: %d", angle);
            return;
        }
        int pulse_width = 1000 + angle * 10;
        pthread_cancel(servo_thread);
        pthread_join(servo_thread, NULL);
        pthread_create(&servo_thread, NULL, servo_thread_func, &pulse_width);
    } else if (strncmp(command, "PIR", 3) == 0) {
        char buffer[16];
        int value = gpiod_line_get_value(pir_fd);
        snprintf(buffer, sizeof(buffer), "PIR:%d\n", value);
        send(sock_fd, buffer, strlen(buffer), 0);
    } else {
        log_message("Invalid command: %s", command);
    }
}

static void handle_connection(int sock_fd)
{
    char buffer[1024];
    int n;

    while ((n = recv(sock_fd, buffer, sizeof(buffer), 0)) > 0) {
        buffer[n] = '\0';
        handle_command(buffer);
    }

    if (n < 0) {
        log_message("recv failed: %s", strerror(errno));
    }
}

static void handle_signal(int signum)
{
    log_message("Received signal: %d", signum);
    if (servo_fd >= 0) {
        gpiod_line_release(servo_fd);
    }
    if (pir_fd >= 0) {
        gpiod_line_release(pir_fd);
    }
    if (sock_fd >= 0) {
        close(sock_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int sock_fd;
    struct sockaddr_in addr;
    struct gpiod_line_request req;

    openlog("security", LOG_PID, LOG_USER);
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_USER | LOG_ERR, "open failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.line_offsets[0] = 4;
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE;
    req.default_values[0] = 0;
    req.consumer = "pir";

    pir_fd = gpiod_line_request(&req, 1);
    if (pir_fd < 0) {
        log_message("gpiod_line_request failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&servo_thread, NULL, servo_thread_func, NULL) != 0) {
        log_message("pthread_create failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        log_message("socket failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(PORT);

    if (bind(sock_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_message("bind failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (listen(sock_fd, 5) < 0) {
        log_message("listen failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_addr_len = sizeof(client_addr);
        int client_sock_fd = accept(sock_fd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_sock_fd < 0) {
            log_message("accept failed: %s", strerror(errno));
            continue;
        }
        log_message("Connection from %s", inet_ntoa(client_addr.sin_addr));
        handle_connection(client_sock_fd);
        close(client_sock_fd);
    }

    return 0;
}
