#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_ONE_TIME_HIGH_RES_MODE 0x20
#define BH1750_CMD_POWER_DOWN 0x00
#define BH1750_CMD_POWER_ON 0x01
#define BH1750_CMD_RESET 0x07
#define RELAY_PIN 23
#define I2C_BUS 1
#define I2C_ADDR BH1750_ADDR
#define I2C_CMD BH1750_CMD_ONE_TIME_HIGH_RES_MODE
#define I2C_DELAY 120
#define LOG_FILE "grow_log.txt"
#define SAMPLING_INTERVAL 2

int i2cHandle;
FILE *logFile;

void logLux(int lux)
{
    time_t now = time(NULL);
    fprintf(logFile, "%ld %d\n", now, lux);
    fflush(logFile);
}

void activateRelay()
{
    gpioWrite(RELAY_PIN, 1);
}

void deactivateRelay()
{
    gpioWrite(RELAY_PIN, 0);
}

void handleError(const char *message)
{
    fprintf(stderr, "%s\n", message);
    if (logFile)
    {
        fprintf(logFile, "%s\n", message);
        fflush(logFile);
    }
    exit(EXIT_FAILURE);
}

void handleSignal(int signal)
{
    if (logFile)
    {
        fclose(logFile);
    }
    if (i2cHandle >= 0)
    {
        i2cClose(i2cHandle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main()
{
    if (gpioInitialise() < 0)
    {
        handleError("Failed to initialize GPIO");
    }
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);
    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0)
    {
        handleError("Failed to open I2C bus");
    }
    logFile = fopen(LOG_FILE, "w");
    if (!logFile)
    {
        handleError("Failed to open log file");
    }
    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);
    while (1)
    {
        if (i2cWriteByte(i2cHandle, I2C_CMD) < 0)
        {
            handleError("Failed to write I2C command");
        }
        sleep(I2C_DELAY / 1000);
        char data[2];
        if (i2cReadDevice(i2cHandle, data, 2) < 0)
        {
            handleError("Failed to read I2C data");
        }
        int lux = (data[0] << 8) | data[1];
        lux /= 1.2;
        logLux(lux);
        if (lux < 150)
        {
            activateRelay();
        }
        else
        {
            deactivateRelay();
        }
        sleep(SAMPLING_INTERVAL);
    }
    return 0;
}

