#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define GPIO_PIN_STR "17"
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define MQTT_KEEPALIVE 60
#define MQTT_RECONNECT_DELAY 5

static struct mosquitto *mosq;
static int running = 1;

static void sig_handler(int signum)
{
    syslog(LOG_INFO, "Received signal %d, shutting down", signum);
    running = 0;
}

static void mosq_log_callback(struct mosquitto *mosq, void *userdata, int level, const char *str)
{
    switch (level) {
        case MOSQ_LOG_INFO:
            syslog(LOG_INFO, "MQTT: %s", str);
            break;
        case MOSQ_LOG_NOTICE:
            syslog(LOG_NOTICE, "MQTT: %s", str);
            break;
        case MOSQ_LOG_WARNING:
            syslog(LOG_WARNING, "MQTT: %s", str);
            break;
        case MOSQ_LOG_ERR:
            syslog(LOG_ERR, "MQTT: %s", str);
            break;
        default:
            syslog(LOG_ERR, "MQTT: unknown log level %d: %s", level, str);
            break;
    }
}

static void mosq_connect_callback(struct mosquitto *mosq, void *userdata, int result)
{
    if (!result) {
        syslog(LOG_INFO, "MQTT: Connected");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    } else {
        syslog(LOG_ERR, "MQTT: Connect failed: %s", mosquitto_connack_string(result));
    }
}

static void mosq_disconnect_callback(struct mosquitto *mosq, void *userdata, int result)
{
    if (result) {
        syslog(LOG_ERR, "MQTT: Disconnected unexpectedly: %s", mosquitto_connack_string(result));
    } else {
        syslog(LOG_INFO, "MQTT: Disconnected");
    }
}

static void mosq_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message)
{
    if (message->payloadlen) {
        syslog(LOG_INFO, "MQTT: Received message on topic %s: %.*s", message->topic, (int)message->payloadlen, (char *)message->payload);
        if (strcmp((char *)message->payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
        } else if (strcmp((char *)message->payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0);
        } else {
            syslog(LOG_ERR, "MQTT: Invalid payload: %.*s", (int)message->payloadlen, (char *)message->payload);
        }
    } else {
        syslog(LOG_ERR, "MQTT: Empty payload");
    }
}

int main(void)
{
    int rc;

    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller");

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO pin %s as output", GPIO_PIN_STR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO pin %s to LOW", GPIO_PIN_STR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, 1, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_log_callback_set(mosq, mosq_log_callback);
    mosquitto_connect_callback_set(mosq, mosq_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mosq_disconnect_callback);
    mosquitto_message_callback_set(mosq, mosq_message_callback);

    while (running) {
        rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
        if (rc) {
            syslog(LOG_ERR, "MQTT: Failed to connect: %s", mosquitto_connack_string(rc));
            sleep(MQTT_RECONNECT_DELAY);
            continue;
        }

        rc = mosquitto_loop_forever(mosq, -1, 1);
        if (rc) {
            syslog(LOG_ERR, "MQTT: Loop failed: %s", mosquitto_strerror(rc));
            mosquitto_disconnect(mosq);
            sleep(MQTT_RECONNECT_DELAY);
            continue;
        }
    }

    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

