Write a robust C program for a Raspberry Pi 4 Model B that uses the pigpio library to implement a smart chicken coop lighting system. Control a 12V relay-connected LED strip via GPIO 17 (active-high) based on ambient light read from a BH1750 sensor on I2C bus 1 at address 0x23. The relay activates at dusk, when lux falls below 50, and deactivates at dawn, when lux exceeds 200, using a hysteresis loop to prevent rapid toggling. Poll the sensor every 5 seconds, waiting at least 180 ms after issuing the One-Time High-Resolution Mode 2 command (0x21) before reading the 2 bytes of lux data, and convert the raw data to lux by dividing by 1.2. Log all sensor readings and relay state changes to chicken_coop_log.txt in the format 'YYYY-MM-DD HH:MM:SS: Lux = XXX, Relay = ON/OFF'. Implement comprehensive error handling for pigpio initialization, I2C bus communication, and file I/O; if the sensor fails to respond, log the error and safely turn off the relay. Ensure clean resource release of the I2C handle, the relay GPIO, and the log file on all exit paths, including graceful shutdown via SIGINT and SIGTERM.

### Response:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define SENSOR_ADDR 0x23
#define SENSOR_CMD 0x21
#define SENSOR_DATA_LEN 2
#define SENSOR_POLL_INTERVAL 5000
#define SENSOR_WAIT_INTERVAL 180
#define LUX_DUSK 50
#define LUX_DAWN 200
#define LUX_HYSTERESIS 10
#define LOG_FILE "chicken_coop_log.txt"

int main(void)
{
    int sensorHandle, relayHandle, lux, relayState, prevRelayState;
    char logLine[100];
    time_t now;
    struct tm *timeInfo;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    sensorHandle = i2cOpen(1, SENSOR_ADDR, 0);
    if (sensorHandle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    relayHandle = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (relayHandle < 0)
    {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        i2cClose(sensorHandle);
        gpioTerminate();
        return 1;
    }

    FILE *logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (1)
    {
        // Read sensor data
        if (i2cWriteByte(sensorHandle, SENSOR_CMD) < 0)
        {
            fprintf(stderr, "Failed to write to sensor\n");
            break;
        }
        sleep(SENSOR_WAIT_INTERVAL / 1000);
        if (i2cReadDevice(sensorHandle, (char *)&lux, SENSOR_DATA_LEN) < 0)
        {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }
        lux /= 1.2;

        // Update relay state
        if (lux < LUX_DUSK - LUX_HYSTERESIS)
        {
            relayState = 1;
        }
        else if (lux > LUX_DAWN + LUX_HYSTERESIS)
        {
            relayState = 0;
        }
        else
        {
            relayState = prevRelayState;
        }
        if (relayState != prevRelayState)
        {
            if (gpioWrite(RELAY_PIN, relayState) < 0)
            {
                fprintf(stderr, "Failed to write to relay\n");
                break;
            }
            prevRelayState = relayState;
        }

        // Log data
        time(&now);
        timeInfo = localtime(&now);
        strftime(logLine, sizeof(logLine), "%Y-%m-%d %H:%M:%S: Lux = %d, Relay = %s\n", timeInfo, lux, relayState ? "ON" : "OFF");
        if (fputs(logLine, logFile) < 0)
        {
            fprintf(stderr, "Failed to write to log file\n");
            break;
        }
        fflush(logFile);

        // Wait for next poll
        sleep(SENSOR_POLL_INTERVAL / 1000);
    }

    // Clean up
    i2cClose(sensorHandle);
    gpioTerminate();
    fclose(logFile);

    return 0;
}
