#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

int main(void)
{
    int touchSensorState = 0;
    int relayState = 0;
    int lastTouchSensorState = 0;
    int lastRelayState = 0;
    int rc = 0;
    int gpio = 0;
    time_t timestamp;
    struct tm *timeInfo;
    char timeString[20];

    // Initialize pigpio
    if ((gpio = gpioInitialise()) < 0)
    {
        fprintf(stderr, "pigpio initialisation failed: %d\n", gpio);
        return 1;
    }

    // Set GPIO 4 as input
    if (gpioSetMode(gpio, TOUCH_SENSOR_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO 4 as input\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    if (gpioSetMode(gpio, RELAY_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO 17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set initial relay state
    if (gpioWrite(gpio, RELAY_PIN, relayState) != 0)
    {
        fprintf(stderr, "Failed to set initial relay state\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1)
    {
        // Read touch sensor state
        touchSensorState = gpioRead(gpio, TOUCH_SENSOR_PIN);

        // Check for edge
        if (touchSensorState != lastTouchSensorState)
        {
            // Debounce
            time_t startTime = time(NULL);
            do
            {
                touchSensorState = gpioRead(gpio, TOUCH_SENSOR_PIN);
            } while (touchSensorState != lastTouchSensorState && difftime(time(NULL), startTime) < 0.05);

            // Toggle relay state
            if (touchSensorState == lastTouchSensorState)
            {
                relayState = !relayState;
                if (gpioWrite(gpio, RELAY_PIN, relayState) != 0)
                {
                    fprintf(stderr, "Failed to toggle relay state\n");
                    gpioTerminate();
                    return 1;
                }

                // Log state change
                timestamp = time(NULL);
                timeInfo = localtime(&timestamp);
                strftime(timeString, sizeof(timeString), "%FT%T%z", timeInfo);
                printf("%s: Relay state changed to %s\n", timeString, relayState ? "ON" : "OFF");
            }
        }

        // Update last states
        lastTouchSensorState = touchSensorState;
        lastRelayState = relayState;

        // Sleep for 10 ms
        gpioDelay(10000);
    }

    // Graceful shutdown
    if (gpioWrite(gpio, RELAY_PIN, 0) != 0)
    {
        fprintf(stderr, "Failed to turn relay OFF\n");
        gpioTerminate();
        return 1;
    }

    gpioTerminate();
    printf("Exiting...\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define FLOW_SENSOR_DEBOUNCE_TIME 1000
#define FLOW_SENSOR_PULSES_PER_LITER 450
#define FLOW_SENSOR_LPM_THRESHOLD 5.0
#define FLOW_SENSOR_LPM_HYSTERESIS 0.5
#define LOG_FILE_NAME "water_flow.log"

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int pulse_count = 0;
static int solenoid_state = 1;
static FILE *log_file = NULL;

static void log_event(const char *event)
{
    pthread_mutex_lock(&mutex);
    fprintf(log_file, "%s\n", event);
    fflush(log_file);
    pthread_mutex_unlock(&mutex);
}

static void log_pulse_count(int count)
{
    char event[128];
    snprintf(event, sizeof(event), "Pulses: %d", count);
    log_event(event);
}

static void log_lpm(double lpm)
{
    char event[128];
    snprintf(event, sizeof(event), "LPM: %.2f", lpm);
    log_event(event);
}

static void log_solenoid_state(int state)
{
    char event[128];
    snprintf(event, sizeof(event), "Solenoid: %s", state ? "Open" : "Closed");
    log_event(event);
}

static void log_timestamp()
{
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove trailing newline
    log_event(timestamp);
}

static void log_init()
{
    log_file = fopen(LOG_FILE_NAME, "w");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    log_timestamp();
    log_event("Log initialized");
}

static void log_cleanup()
{
    if (log_file != NULL)
    {
        log_timestamp();
        log_event("Log closed");
        fclose(log_file);
    }
}

static void flow_sensor_callback(int gpio, int level, uint32_t tick)
{
    pthread_mutex_lock(&mutex);
    pulse_count++;
    pthread_mutex_unlock(&mutex);
}

static void flow_sensor_init()
{
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Error setting flow sensor pin mode: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, EITHER_EDGE, FLOW_SENSOR_DEBOUNCE_TIME, flow_sensor_callback) != 0)
    {
        fprintf(stderr, "Error setting flow sensor ISR: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void solenoid_init()
{
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Error setting solenoid pin mode: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    gpioWrite(SOLENOID_PIN, solenoid_state);
}

static void solenoid_set_state(int state)
{
    solenoid_state = state;
    gpioWrite(SOLENOID_PIN, solenoid_state);
    log_solenoid_state(solenoid_state);
}

static void solenoid_toggle()
{
    solenoid_set_state(!solenoid_state);
}

static void signal_handler(int signal)
{
    log_event("Signal received");
    solenoid_set_state(1);
    log_cleanup();
    pthread_mutex_destroy(&mutex);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

static void signal_init()
{
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
}

static void pigpio_init()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void pigpio_cleanup()
{
    gpioTerminate();
}

static void *pulse_counter_thread(void *arg)
{
    while (1)
    {
        sleep(1);
        pthread_mutex_lock(&mutex);
        int count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&mutex);
        double lpm = (double)count / FLOW_SENSOR_PULSES_PER_LITER * 60.0;
        log_pulse_count(count);
        log_lpm(lpm);
        if (lpm > FLOW_SENSOR_LPM_THRESHOLD)
        {
            solenoid_set_state(0);
        }
        else if (lpm < FLOW_SENSOR_LPM_THRESHOLD - FLOW_SENSOR_LPM_HYSTERESIS)
        {
            solenoid_set_state(1);
        }
    }
    return NULL;
}

int main(int argc, char *argv[])
{
    pigpio_init();
    signal_init();
    log_init();
    flow_sensor_init();
    solenoid_init();
    pthread_t counter_thread;
    pthread_create(&counter_thread, NULL, pulse_counter_thread, NULL);
    pthread_join(counter_thread, NULL);
    pigpio_cleanup();
    return 0;
}

