#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_MS 50

int main(int argc, char *argv[])
{
    int gpio, rc, debounce_ms = DEBOUNCE_MS;
    time_t now;
    struct tm *tm;
    char buf[64];

    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0) {
            if (argc > 2) {
                debounce_ms = atoi(argv[2]);
            }
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);

    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_UP);

    gpioSetAlertFunc(TOUCH_PIN, NULL);

    while (1) {
        gpio = gpioRead(TOUCH_PIN);
        if (gpio == 0) {
            rc = gpioRead_Bits_0_31();
            if (rc & (1 << TOUCH_PIN)) {
                gpioWrite(RELAY_PIN, 1);
                time(&now);
                tm = localtime(&now);
                strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
                printf("%s Relay: ON\n", buf);
                gpioDelay(debounce_ms * 1000);
            }
        } else {
            rc = gpioRead_Bits_0_31();
            if (!(rc & (1 << TOUCH_PIN))) {
                gpioWrite(RELAY_PIN, 0);
                time(&now);
                tm = localtime(&now);
                strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
                printf("%s Relay: OFF\n", buf);
                gpioDelay(debounce_ms * 1000);
            }
        }
    }

    gpioTerminate();

    return 0;
}

