#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_RANGE (SERVO_MAX - SERVO_MIN)
#define SERVO_START 1500
#define SERVO_STEP 10

static struct termios old_termios;
static int servo_angle = 90;

static void servo_quit(int signum)
{
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);
    exit(0);
}

int main(void)
{
    int ch;
    int servo_pulse;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    if (tcgetattr(STDIN_FILENO, &old_termios) < 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        return 1;
    }

    struct termios new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_cc[VMIN] = 1;
    new_termios.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) < 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, servo_quit);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50);
    gpioServo(SERVO_PIN, SERVO_START);

    while ((ch = getchar()) != 'q') {
        if (ch == '+') {
            servo_angle += SERVO_STEP;
            if (servo_angle > 180)
                servo_angle = 180;
        } else if (ch == '-') {
            servo_angle -= SERVO_STEP;
            if (servo_angle < 0)
                servo_angle = 0;
        } else {
            continue;
        }

        servo_pulse = SERVO_MIN + (SERVO_RANGE * servo_angle) / 180;
        if (servo_pulse < SERVO_MIN)
            servo_pulse = SERVO_MIN;
        else if (servo_pulse > SERVO_MAX)
            servo_pulse = SERVO_MAX;

        gpioServo(SERVO_PIN, servo_pulse);
        printf("angle: %d\n", servo_angle);
    }

    servo_quit(0);
}

