#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_PIN_1 17
#define LOCK_PIN_2 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define SPI_BYTES 10
#define SPI_TIMEOUT 1000
#define LOCK_DELAY 5000
#define BUTTON_DELAY 50
#define LOG_FILE "/var/log/door_access.log"

static volatile int keep_running = 1;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

static void log_access(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char time_str[64];
        strftime(time_str, sizeof(time_str), "%FT%TZ", tm);
        fprintf(fp, "%s: %s\n", time_str, message);
        fclose(fp);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LOCK_PIN_1, PI_OUTPUT);
    gpioSetMode(LOCK_PIN_2, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    gpioWrite(LOCK_PIN_1, 1);
    gpioWrite(LOCK_PIN_2, 1);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    uint8_t tag[SPI_BYTES] = {0};
    uint8_t valid_tag[SPI_BYTES] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

    while (keep_running) {
        int button_pressed = 0;
        int tag_read = 0;

        gpioDelay(BUTTON_DELAY);
        if (gpioRead(BUTTON_PIN) == 0) {
            button_pressed = 1;
        }

        if (spiXfer(spi_handle, NULL, tag, SPI_BYTES) == SPI_BYTES) {
            if (memcmp(tag, valid_tag, SPI_BYTES) == 0) {
                tag_read = 1;
            }
        }

        if (tag_read && button_pressed) {
            log_access("Access granted");
            gpioWrite(LOCK_PIN_1, 0);
            gpioWrite(LOCK_PIN_2, 0);
            gpioDelay(LOCK_DELAY);
            gpioWrite(LOCK_PIN_1, 1);
            gpioWrite(LOCK_PIN_2, 1);
        } else if (tag_read) {
            log_access("Button not pressed");
        } else if (button_pressed) {
            log_access("Invalid tag");
        } else {
            log_access("No tag present");
        }
    }

    gpioWrite(LOCK_PIN_1, 1);
    gpioWrite(LOCK_PIN_2, 1);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}
