    if (request_result < 0) {
        fprintf(stderr, "Error requesting output for Valve 2: %s\n", strerror(errno));
        gpiod_line_release(valve_1_line);
        gpiod_line_release(valve_2_line);
        gpiod_chip_close(chip);
        return 1;
