#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define MPR121_ADDR 0x5A
#define MPR121_TOUCH_STATUS 0x00
#define MPR121_RELEASE_STATUS 0x01
#define MPR121_TOUCH_THRESHOLD 0x10
#define MPR121_RELEASE_THRESHOLD 0x0A
#define MPR121_FILTER_CHARGE_TIME 0x20
#define MPR121_ELECTRODE_CURRENT 0x01
#define MPR121_RUN_MODE 0x20
#define MPR121_STOP_MODE 0x00
#define MPR121_ELE_EN 0x80
#define MPR121_ELE_DIS 0x00
#define MPR121_ELE_ALL 0xFF
#define MPR121_ELE_NONE 0x00
#define MPR121_ELE_1 0x01
#define MPR121_ELE_2 0x02
#define MPR121_ELE_3 0x04
#define MPR121_ELE_4 0x08
#define MPR121_ELE_5 0x10
#define MPR121_ELE_6 0x20
#define MPR121_ELE_7 0x40
#define MPR121_ELE_8 0x80
#define MPR121_ELE_9 0x01
#define MPR121_ELE_10 0x02
#define MPR121_ELE_11 0x04
#define MPR121_ELE_12 0x08

static int i2c_handle = -1;
static int relay_pin = -1;

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (relay_pin >= 0) {
        gpioWrite(relay_pin, 0);
        gpioSetMode(relay_pin, PI_INPUT);
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(signum);
}

int main(void)
{
    int ret;
    uint8_t touch_status;
    uint8_t release_status;
    uint8_t touch_threshold;
    uint8_t release_threshold;
    uint8_t filter_charge_time;
    uint8_t electrode_current;
    uint8_t run_mode;
    uint8_t ele_en;
    uint8_t ele_dis;
    uint8_t ele_all;
    uint8_t ele_none;
    uint8_t ele_1;
    uint8_t ele_2;
    uint8_t ele_3;
    uint8_t ele_4;
    uint8_t ele_5;
    uint8_t ele_6;
    uint8_t ele_7;
    uint8_t ele_8;
    uint8_t ele_9;
    uint8_t ele_10;
    uint8_t ele_11;
    uint8_t ele_12;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto error;
    }

    relay_pin = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (relay_pin < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        goto error;
    }

    ret = i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD, 0x10);
    if (ret < 0) {
        fprintf(stderr, "Failed to write touch threshold\n");
        goto error;
    }

    ret = i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD, 0x0A);
    if (ret < 0) {
        fprintf(stderr, "Failed to write release threshold\n");
        goto error;
    }

    ret = i2cWriteByteData(i2c_handle, MPR121_FILTER_CHARGE_TIME, 0x20);
    if (ret < 0) {
        fprintf(stderr, "Failed to write filter/charge time\n");
        goto error;
    }

    ret = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CURRENT, 0x01);
    if (ret < 0) {
        fprintf(stderr, "Failed to write electrode current\n");
        goto error;
    }

    ret = i2cWriteByteData(i2c_handle, MPR121_RUN_MODE, 0x20);
    if (ret < 0) {
        fprintf(stderr, "Failed to write run mode\n");
        goto error;
    }

    usleep(100000);

    ret = i2cWriteByteData(i2c_handle, MPR121_ELE_EN, 0x80);
    if (ret < 0) {
        fprintf(stderr, "Failed to write electrode enable\n");
        goto error;
    }

    while (1) {
        usleep(100000);

        ret = i2cReadByteData(i2c_handle, MPR121_TOUCH_STATUS, &touch_status);
        if (ret < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            goto error;
        }

        ret = i2cReadByteData(i2c_handle, MPR121_RELEASE_STATUS, &release_status);
        if (ret < 0) {
            fprintf(stderr, "Failed to read release status\n");
            goto error;
        }

        if (touch_status > 0) {
            ret = gpioWrite(relay_pin, 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to write relay pin\n");
                goto error;
            }
            printf("Relay on\n");
        } else if (release_status > 0) {
            ret = gpioWrite(relay_pin, 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to write relay pin\n");
                goto error;
            }
            printf("Relay off\n");
        }
    }

error:
    cleanup();
    return EXIT_FAILURE;
}

