5. The program should perform a binary search on the entered numbers and print the result to the console.
6. Compile the program using the `gcc` compiler.
7. Run the compiled program to verify that it performs a binary search correctly.

## Example Solution
```c
#include <stdio.h>

int binarySearch(int arr[], int n, int x)
{
    int low = 0;
    int high = n - 1;
    int mid;

    while (low <= high) {
        mid = (low + high) / 2;

        if (arr[mid] == x) {
            return mid;
        } else if (arr[mid] < x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return -1;
}

int main(void)
{
    int arr[100];
    int n;
    int x;
    int i;
    int result;

    printf("Enter a list of numbers, separated by spaces: ");

    for (i = 0; i < 100; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            break;
        }
    }

    n = i;

    printf("Enter a number to search for: ");
    scanf("%d", &x);

    result = binarySearch(arr, n, x);

    if (result != -1) {
        printf("The number %d was found at index %d.\n", x, result);
    } else {
        printf("The number %d was not found.\n", x);
    }

    return 0;
}
```

## Explanation
The solution to this exercise is a C program that performs a binary search on a given array of numbers. The program uses a binary search algorithm to search for the entered number, and prints the result to the console.

