5. Compile the program using the `gcc` compiler.
6. Run the compiled program to verify that it performs a bubble sort correctly.

## Example Solution
```c
#include <stdio.h>

void bubbleSort(int arr[], int n)
{
    int i;
    int j;
    int temp;

    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

int main(void)
{
    int arr[100];
    int n;
    int i;

    printf("Enter a list of numbers, separated by spaces: ");

    for (i = 0; i < 100; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            break;
        }
    }

    n = i;

    bubbleSort(arr, n);

    printf("The sorted list is: ");

    for (i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}
```

