## Example Solution
```c
#include <stdio.h>

void insertionSort(int arr[], int n)
{
    int i;
    int j;
    int temp;

    for (i = 1; i < n; i++) {
        temp = arr[i];
        j = i - 1;

        while (j >= 0 && arr[j] > temp) {
            arr[j + 1] = arr[j];
            j--;
        }

        arr[j + 1] = temp;
    }
}

int main(void)
{
    int arr[100];
    int n;
    int i;

    printf("Enter a list of numbers, separated by spaces: ");

    for (i = 0; i < 100; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            break;
        }
    }

    n = i;

    insertionSort(arr, n);

    printf("The sorted list is: ");

    for (i = 0; i < n; i++) {
        printf("%d ", arr[i]);
