#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define RATE_LIMIT 2000

FILE *log_file;

void log_event(const char *event)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%03ld %s\n", ts.tv_sec, ts.tv_nsec / 1000000, event);
    fflush(log_file);
}

void motion_detected(int gpio, int level, uint32_t tick)
{
    static uint32_t last_unlock_tick = 0;
    uint32_t now = gpioTick();

    if (level == 1 && now - last_unlock_tick >= RATE_LIMIT) {
        gpioWrite(RELAY_PIN, 1);
        gpioSetTimerFunc(RELAY_PIN, 500, NULL, NULL);
        last_unlock_tick = now;
        log_event("Motion detected, door unlocked");
    } else {
        log_event("Motion detected, rate limited");
    }
}

void cleanup(int signum)
{
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    fclose(log_file);
