#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MOTOR_1 17
#define MOTOR_2 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_DURATION 50
#define MAX_DURATION 200
#define MIN_STEPS 5
#define MAX_STEPS 15

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    gpioSetMode(MOTOR_1, PI_OUTPUT);
    gpioSetMode(MOTOR_2, PI_OUTPUT);

    srand(time(NULL));

    while (1)
    {
        int num_steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;

        for (int i = 0; i < num_steps; i++)
        {
            int duty_cycle_1 = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
            int duty_cycle_2 = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
            int duration = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;

            gpioPWM(MOTOR_1, duty_cycle_1);
            gpioPWM(MOTOR_2, duty_cycle_2);
            gpioDelay(duration);
        }
    }

    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"

#define CALIBRATION_SAMPLES 100
#define CALIBRATION_THRESHOLD 10.0

#define READ_INTERVAL_MS 500
#define READ_TIMEOUT_MS 500

#define LOG_FORMAT "%ld,%.2f\n"

static int running = 1;

static double scale_factor = 1.0;
static double offset = 0.0;

static FILE *calibration_file = NULL;
static FILE *weight_log_file = NULL;

static void sigint_handler(int signum)
{
    running = 0;
}

static int read_calibration_data()
{
    if (calibration_file == NULL) {
        return 0;
    }

    fseek(calibration_file, 0, SEEK_SET);
    if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2) {
        return 0;
    }

    return 1;
}

static int write_calibration_data()
{
    if (calibration_file == NULL) {
        return 0;
    }

    fseek(calibration_file, 0, SEEK_SET);
    if (fprintf(calibration_file, "%.2f %.2f", scale_factor, offset) < 0) {
        return 0;
    }

    return 1;
}

static int calibrate_hx711()
{
    int i;
    double sum = 0.0;

    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        int32_t raw_value = hx711Read(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value < 0) {
            return 0;
        }

        sum += raw_value;
    }

    offset = sum / CALIBRATION_SAMPLES;

    return 1;
}

static int init_hx711()
{
    if (gpioInitialise() < 0) {
        return 0;
    }

    if (hx711Init(HX711_DATA_PIN, HX711_CLOCK_PIN) < 0) {
        return 0;
    }

    return 1;
}

static int init_solenoid()
{
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        return 0;
    }

    return 1;
}

static int init_files()
{
    calibration_file = fopen(CALIBRATION_FILE, "r+");
    if (calibration_file == NULL) {
        return 0;
    }

    if (!read_calibration_data()) {
        fclose(calibration_file);
        calibration_file = NULL;
        return 0;
    }

    weight_log_file = fopen(WEIGHT_LOG_FILE, "a");
    if (weight_log_file == NULL) {
        fclose(calibration_file);
        calibration_file = NULL;
        return 0;
    }

    return 1;
}

static void cleanup()
{
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }

    if (weight_log_file != NULL) {
        fclose(weight_log_file);
    }

    gpioTerminate();
}

static void log_weight(double weight)
{
    if (weight_log_file == NULL) {
        return;
    }

    time_t current_time = time(NULL);
    fprintf(weight_log_file, LOG_FORMAT, current_time, weight);
    fflush(weight_log_file);
}

static void lock_solenoid()
{
    gpioWrite(SOLENOID_PIN, 1);
}

static void unlock_solenoid()
{
    gpioWrite(SOLENOID_PIN, 0);
}

int main()
{
    if (!init_hx711()) {
        fprintf(stderr, "Failed to initialize HX711\n");
        return EXIT_FAILURE;
    }

    if (!init_solenoid()) {
        fprintf(stderr, "Failed to initialize solenoid\n");
        return EXIT_FAILURE;
    }

    if (!init_files()) {
        fprintf(stderr, "Failed to initialize files\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    signal(SIGINT, sigint_handler);

    if (!calibrate_hx711()) {
        fprintf(stderr, "Failed to calibrate HX711\n");
        return EXIT_FAILURE;
    }

    if (!write_calibration_data()) {
        fprintf(stderr, "Failed to write calibration data\n");
        return EXIT_FAILURE;
    }

    while (running) {
        int32_t raw_value = hx711Read(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read HX711\n");
            continue;
        }

        double weight = (raw_value - offset) * scale_factor;
        log_weight(weight);

        if (weight > CALIBRATION_THRESHOLD) {
            lock_solenoid();
        } else {
            unlock_solenoid();
        }

        time_sleep(READ_INTERVAL_MS / 1000.0);
    }

    return EXIT_SUCCESS;
}

