#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define HX711_DATA_HIGH_TIME_US 1
#define HX711_DATA_LOW_TIME_US 1
#define HX711_CLOCK_HIGH_TIME_US 1
#define HX711_CLOCK_LOW_TIME_US 1
#define HX711_TIMEOUT_US 100000

#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"

#define WEIGHT_THRESHOLD_KG 5.0

static int gpiod = -1;
static int solenoid_gpio = -1;
static int calibration_file = -1;
static int security_log_file = -1;
static double calibration_factor = 0.0;

static void cleanup(void)
{
    if (gpiod >= 0)
    {
        gpioTerminate();
    }

    if (solenoid_gpio >= 0)
    {
        gpioWrite(solenoid_gpio, 0);
        gpioSetMode(solenoid_gpio, PI_INPUT);
    }

    if (calibration_file >= 0)
    {
        close(calibration_file);
    }

    if (security_log_file >= 0)
    {
        close(security_log_file);
    }
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_gpiod(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    gpiod = 1;
    return 0;
}

static int init_solenoid(void)
{
    solenoid_gpio = gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    if (solenoid_gpio < 0)
    {
        fprintf(stderr, "Failed to initialize solenoid GPIO\n");
        return -1;
    }

    return 0;
}

static int init_calibration_file(void)
{
    calibration_file = open(CALIBRATION_FILE, O_RDONLY);
    if (calibration_file < 0)
    {
        fprintf(stderr, "Failed to open calibration file\n");
        return -1;
    }

    if (read(calibration_file, &calibration_factor, sizeof(calibration_factor)) != sizeof(calibration_factor))
    {
        fprintf(stderr, "Failed to read calibration factor from file\n");
        return -1;
    }

    return 0;
}

static int init_security_log_file(void)
{
    security_log_file = open(SECURITY_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (security_log_file < 0)
    {
        fprintf(stderr, "Failed to open security log file\n");
        return -1;
    }

    return 0;
}

static int init(void)
{
    if (init_gpiod() < 0)
    {
        return -1;
    }

    if (init_solenoid() < 0)
    {
        return -1;
    }

    if (init_calibration_file() < 0)
    {
        return -1;
    }

    if (init_security_log_file() < 0)
    {
        return -1;
    }

    return 0;
}

static int read_hx711_data(int32_t *data)
{
    int32_t value = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(HX711_CLOCK_LOW_TIME_US);

    for (i = 0; i < 24; i++)
    {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(HX711_CLOCK_HIGH_TIME_US);

        value <<= 1;
        if (gpioRead(HX711_DATA_PIN))
        {
            value |= 1;
        }

        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(HX711_CLOCK_LOW_TIME_US);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(HX711_CLOCK_HIGH_TIME_US);

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(HX711_CLOCK_LOW_TIME_US);

    *data = value;
    return 0;
}

