```
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define BUZZER_GPIO 18
#define PIR_GPIO 17

static struct gpiod_line *pir_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        gpiod_line_set_value(buzzer_line, 0);
        fclose(log_file);
        gpiod_line_release(pir_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(gpiod_line_get_chip(pir_line));
        gpiod_chip_close(gpiod_line_get_chip(buzzer_line));
        exit(0);
    }
}

int main(void)
{
    struct gpiod_chip *chip;
    struct timespec ts;
    char timestamp[20];
    int motion_detected;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        perror("Failed to get PIR GPIO line");
        exit(1);
    }

    if (gpiod_line_request_input(pir_line, "motion_detector")) {
        perror("Failed to request PIR GPIO line");
        exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get buzzer GPIO line");
        exit(1);
    }

    if (gpiod_line_request_output(buzzer_line, "motion_detector", 0)) {
        perror("Failed to request buzzer GPIO line");
        exit(1);
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }

    while (1) {
        motion_detected = gpiod_line_get_value(pir_line);
        if (motion_detected) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%F %T", gmtime(&ts.tv_sec));
            fprintf(log_file, "%s\n", timestamp);
            fflush(log_file);
            gpiod_line_set_value(buzzer_line, 1);
            usleep(2000000);
            gpiod_line_set_value(buzzer_line, 0);
        }
        usleep(100000);
    }

    return 0;
}
