static volatile sig_atomic_t sig_flag = 0;

static void sig_handler(int sig)
{
    sig_flag = 1;
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request req;
    char line_str[MAX_LINE_LEN];
    int duration;
    FILE *fp;
    char *line_ptr;
    size_t line_len;

    /* Install signal handlers */
    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the configuration file */
    fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", CONFIG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Read the duration from the configuration file */
    line_ptr = fgets(line_str, MAX_LINE_LEN, fp);
    if (line_ptr == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", CONFIG_FILE, strerror(errno));
        fclose(fp);
        return EXIT_FAILURE;
    }
    line_len = strlen(line_str);
    if (line_len == 0 || line_str[line_len - 1] != '\n') {
        fprintf(stderr, "Error: %s is empty or too long\n", CONFIG_FILE);
        fclose(fp);
        return EXIT_FAILURE;
    }
    if (sscanf(line_str, "duration=%d", &duration) != 1) {
        fprintf(stderr, "Error: %s is malformed\n", CONFIG_FILE);
        fclose(fp);
        return EXIT_FAILURE;
    }
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: duration must be between 1 and 3600\n");
        fclose(fp);
        return EXIT_FAILURE;
    }
    fclose(fp);

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP, gpiod_strerror(errno));
        return EXIT_FAILURE;
    }

    /* Request the GPIO line */
    memset(&req, 0, sizeof(req));
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE_LOW;
    req.default_values[0] = 0;
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, gpiod_strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(line, &req, "watering") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_LINE, gpiod_strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Turn the valve on */
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error turning valve on: %s\n", gpiod_strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    printf("Valve on\n");

    /* Wait for the configured duration */
    while (duration > 0 && !sig_flag) {
        sleep(1);
        duration--;
    }

    /* Turn the valve off */
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error turning valve off: %s\n", gpiod_strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    printf("Valve off\n");

    /* Release the GPIO line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

