#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LEFT_MOTOR_PWM 22
#define LEFT_MOTOR_DIR 23
#define RIGHT_MOTOR_PWM 24
#define RIGHT_MOTOR_DIR 25
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define BASE_SPEED 150
#define LOG_FILE "trace_log.txt"

FILE *log_file;

void stop_motors(void)
{
    gpioWrite(LEFT_MOTOR_DIR, 0);
    gpioWrite(RIGHT_MOTOR_DIR, 0);
    gpioWrite(LEFT_MOTOR_PWM, 0);
    gpioWrite(RIGHT_MOTOR_PWM, 0);
}

void sigint_handler(int signum)
{
    stop_motors();
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR, PI_OUTPUT);
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    gpioSetPWMfrequency(LEFT_MOTOR_PWM, 1000);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, 1000);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1)
    {
        int left_sensor = gpioRead(LEFT_SENSOR);
        int middle_sensor = gpioRead(MIDDLE_SENSOR);
        int right_sensor = gpioRead(RIGHT_SENSOR);

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle_sensor == 0)
        {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        }
        else if (left_sensor == 0)
        {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        }
        else if (right_sensor == 0)
        {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        }
        else
        {
            left_speed = 0;
            right_speed = 0;
        }

        gpioWrite(LEFT_MOTOR_DIR, 1);
        gpioWrite(RIGHT_MOTOR_DIR, 1);
        gpioPWM(LEFT_MOTOR_PWM, left_speed);
        gpioPWM(RIGHT_MOTOR_PWM, right_speed);

        time_t current_time = time(NULL);
        struct tm *local_time = localtime(&current_time);
        char timestamp[25];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", local_time);

        fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(10000);
    }

    return 0;
}

