#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_PIN 23
#define SENSOR_ADDR 0x23
#define SENSOR_CMD 0x10
#define SENSOR_DELAY 180

static int sensor_handle = -1;
static int relay_state = 0;
static FILE *log_file = NULL;

static void log_lux(int lux)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld %d\n", ts.tv_sec, ts.tv_nsec, lux);
    fflush(log_file);
}

static void log_relay(int state)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld %d\n", ts.tv_sec, ts.tv_nsec, state);
    fflush(log_file);
}

static void sigint_handler(int signum)
{
    if (sensor_handle >= 0) {
        i2cClose(sensor_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    int lux;
    int rc;

    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    sensor_handle = i2cOpen(1, SENSOR_ADDR, 0);
    if (sensor_handle < 0) {
        fprintf(stderr, "i2cOpen failed\n");
        return 1;
    }

    rc = i2cWriteByte(sensor_handle, SENSOR_CMD);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByte failed\n");
        return 1;
    }

    log_file = fopen("grow_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "fopen failed\n");
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    while (1) {
        rc = i2cReadWordData(sensor_handle);
        if (rc < 0) {
            fprintf(stderr, "i2cReadWordData failed\n");
            return 1;
        }
        lux = (rc >> 8) | (rc << 8);
        log_lux(lux);
        if (lux < 150) {
            if (!relay_state) {
                gpioWrite(RELAY_PIN, 1);
                relay_state = 1;
                log_relay(relay_state);
            }
        } else {
            if (relay_state) {
                gpioWrite(RELAY_PIN, 0);
                relay_state = 0;
                log_relay(relay_state);
            }
        }
        sleep(SENSOR_DELAY / 1000);
    }

    return 0;
}

