#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

static struct gpiod_line *motor1_line;
static struct gpiod_line *motor2_line;

static void cleanup(void)
{
    gpiod_line_release(motor1_line);
    gpiod_line_release(motor2_line);
}

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

