#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x28
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "airflow_log.txt"
#define RETRIES 3
#define RETRY_DELAY 100000

int fd;
FILE *log_file;

void sigint_handler(int sig) {
    close(fd);
    fclose(log_file);
    exit(0);
}

int main() {
    int i, ret, raw_flow;
    float flow;
    char buf[2];
    struct timespec ts;

    signal(SIGINT, sigint_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }

    while (1) {
        for (i = 0; i < RETRIES; i++) {
            ret = write(fd, NULL, 0);
            if (ret < 0) {
                perror("write");
                exit(1);
            }

            ret = read(fd, buf, 2);
            if (ret < 0) {
                perror("read");
                exit(1);
            } else if (ret == 0) {
                fprintf(stderr, "Sensor not present\n");
                exit(1);
            } else if (ret != 2) {
                fprintf(stderr, "Unexpected read length\n");
                exit(1);
            }

            raw_flow = (buf[0] << 8) | buf[1];
            if (raw_flow & 0x2000) {
                fprintf(stderr, "Sensor error\n");
                exit(1);
            }

            flow = (raw_flow - 3277) * 0.1;
            break;
        }

        if (i == RETRIES) {
            fprintf(stderr, "Failed to read sensor\n");
            exit(1);
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%f\n", ts.tv_sec, ts.tv_nsec, flow);
        fflush(log_file);

        usleep(1000000);
    }

    return 0;
}

